#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_SINGLE_SHOT 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000  // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000   // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080    // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_ACT_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int ads1115_init(int i2c_handle);
int ads1115_read_current(int i2c_handle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the ADS1115
int ads1115_init(int i2c_handle) {
    uint16_t config = ADS1115_CONFIG_SINGLE_SHOT | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD |
                      ADS1115_CONFIG_COMP_POL_ACT_LOW | ADS1115_CONFIG_COMP_LAT_NON |
                      ADS1115_CONFIG_COMP_QUE_DISABLE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115: %d\n", result);
        return -1;
    }

    return 0;
}

// Read the current from the ADS1115
int ads1115_read_current(int i2c_handle) {
    char buf[1];
    buf[0] = ADS1115_REG_CONFIG;

    // Set the configuration register to start a single conversion
    uint16_t config = ADS1115_CONFIG_SINGLE_SHOT | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD |
                      ADS1115_CONFIG_COMP_POL_ACT_LOW | ADS1115_CONFIG_COMP_LAT_NON |
                      ADS1115_CONFIG_COMP_QUE_DISABLE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF; // MSB
    config_buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, config_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 to start conversion: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    char read_buf[2];
    result = i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];

    // Convert raw value to amperes (assuming 3.3V reference and 16-bit resolution)
    float current = ((float)raw_value / 32768.0) * 3.3;

    return (int)(current * 1000); // Return current in milli-amperes
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init(i2c_handle) != 0) {
        fprintf(stderr, "ADS1115 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int current_mA = ads1115_read_current(i2c_handle);
        if (current_mA >= 0) {
            printf("Current: %d mA\n", current_mA);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }

        gpioDelay(500000); // 500 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

