#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 1000 // Example threshold
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void control_fan(float current);
void signal_handler(int signal);
void cleanup(void);

// Structure for SPI configuration
typedef struct {
    char *device;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// SPI configuration
spi_config_t spi_config = {
    .device = SPI_DEVICE,
    .mode = SPI_MODE,
    .bits_per_word = SPI_BITS_PER_WORD,
    .speed = SPI_SPEED
};

// Function to initialize SPI
int spi_init(void) {
    spi_fd = open(spi_config.device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = spi_config.mode;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = spi_config.bits_per_word;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = spi_config.speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = spi_config.speed;
    transfer[0].bits_per_word = spi_config.bits_per_word;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Check for sensor absence (all zeros or all ones)
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Sensor appears to be absent or out of range.\n");
        return -1; // Indicate sensor absence
    }

    return adc_value;
}

// Function to convert ADC value to current (example conversion)
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and a known ADC range (e.g., 0-1023 for 0-5A).
    float current = (float)adc_value / 1023.0 * 5.0; // Example: 0-5A range
    return current;
}

// Function to log current to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control fan based on current
void control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(FAN_GPIO, 0); // Ensure fan is OFF
    gpioTerminate();

    printf("Cleanup complete.\n");
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue; // Retry
        }

        float current = adc_to_current(adc_value);
        log_current(current);
        control_fan(current);

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

