#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Calibration parameters (example values, replace with your sensor's calibration data)
#define R0 10000.0  // Sensor resistance at 0 ppm CO (example value)
#define A -0.5      // Calibration curve parameter
#define B 1.0       // Calibration curve parameter

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data and configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int co_sensor_channel;
    char *log_file_name;
    int sample_interval_sec;
} sensor_config_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int bus, int address);
int16_t read_co_sensor(int handle, int channel);
float convert_to_ppm(int16_t raw_value);
int log_ppm_value(float ppm_value);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C connection
int open_i2c_connection(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read the CO sensor value from the ADS1115
int16_t read_co_sensor(int handle, int channel) {
    // ADS1115 configuration register settings
    uint8_t config[3];
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC2 | ((channel & 0x07) << 4); // Single-shot mode, AIN0/AIN1, +/-4.096V, 128 SPS
    config[2] = 0x83; // 16-bit, sign extended

    // Write the configuration to the ADS1115
    if (i2cWriteDevice(handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    char buffer[2];
    if (i2cReadDevice(handle, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    int16_t raw_value = (buffer[0] << 8) | buffer[1];

    // Sign extend if necessary (ADS1115 is a 16-bit ADC)
    if (raw_value & 0x8000) {
        raw_value |= 0xFFFF0000; // Sign extend to 32 bits
    }

    return raw_value;
}

// Function to convert the raw ADC value to CO concentration in ppm
