    // Simulate ADC reading (replace with actual ADC reading)
    float sensor_resistance = (float)raw_value / 32768.0 * 10000.0; // Assuming 16-bit ADC and 10k load resistor

    // Calculate CO concentration using logarithmic calibration
    float ppm = pow(10, (log10(sensor_resistance / R0) - A) / B);

    return ppm;
}

// Function to log the CO concentration to a file
int log_ppm_value(float ppm_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm_value);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read CO sensor value
        int16_t raw_value = read_co_sensor(i2c_handle, CO_SENSOR_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read CO sensor value\n");
            // Optionally add retry logic here
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert to ppm
        float ppm_value = convert_to_ppm(raw_value);

        // Log the value
        if (log_ppm_value(ppm_value) != 0) {
            fprintf(stderr, "Failed to log ppm value\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

