#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD_RATE 1000000 // 1 MHz

// Define MCP3008 channel for temperature sensor
#define TEMPERATURE_CHANNEL 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_flame_sensor();
int read_temperature_sensor();
int log_data(int flame_detected, int temperature);
void cleanup();
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int flame_pin;
    int cs_pin;
    int spi_channel;
    int spi_baud_rate;
    int temperature_channel;
} Config;

Config config = {
    FLAME_SENSOR_PIN,
    MCP3008_CS_PIN,
    SPI_CHANNEL,
    SPI_BAUD_RATE,
    TEMPERATURE_CHANNEL
};

int main() {
    // Register signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Error initializing SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flame Detected,Temperature (C)\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();
        int temperature = read_temperature_sensor();

        if (flame_detected == -1 || temperature == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        } else {
            log_data(flame_detected, temperature);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.flame_pin, PI_INPUT);
    gpioSetMode(config.cs_pin, PI_OUTPUT);
    gpioWrite(config.cs_pin, 1); // Ensure CS is initially high

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_baud_rate, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        return 1;
    }
    return 0;
}

// Read flame sensor
int read_flame_sensor() {
    return gpioRead(config.flame_pin);
}

// Read temperature sensor
int read_temperature_sensor() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // MCP3008 command to read channel 0 (single-ended)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | config.temperature_channel) << 4; // Single-ended, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(config.cs_pin, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(config.cs_pin, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Convert ADC value to temperature (Celsius) - Example conversion
    // This is a placeholder; you'll need to calibrate the sensor
    float temperature = (float)adc_value * 0.1; // Example: 0-1023 -> 0-100C

    return (int)temperature;
}

// Log data to file
int log_data(int flame_detected, int temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler for Ctrl-C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl-C pressed. Exiting.\n");
}

