#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
float convert_to_ppm(uint16_t ox_value);
int log_data(float co_ppm);
int check_threshold(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    uint16_t ox_value;
    uint16_t red_value;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-4514
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Convert OX value to CO concentration in ppm
float convert_to_ppm(uint16_t ox_value) {
    // Assuming a linear relationship between OX value and CO concentration
    // and a known baseline OX value (e.g., 0 ppm).
    // This is a placeholder and needs calibration with the actual sensor.
    // You'll need to determine the slope and intercept of the calibration curve.
    // For example, if the OX value at 0 ppm is 1000 and the OX value at 100 ppm is 1100,
    // the slope is (1100 - 1000) / 100 = 10 ppm/unit.
    // Then, the CO concentration in ppm is:
    // CO (ppm) = (OX value - baseline OX value) / slope

    // Placeholder calibration values (replace with your sensor's calibration)
    float baseline_ox = 1000.0; // Example baseline OX value
    float slope = 10.0;        // Example slope (ppm/unit)

    float co_ppm = (ox_value - baseline_ox) / slope;

    return co_ppm;
}

// Log CO concentration to a file
int log_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);

    fclose(fp);
    return 0;
}

// Check if CO concentration exceeds the threshold
int check_threshold(float co_ppm) {
    return (co_ppm > CO_THRESHOLD) ? 1 : 0;
}

// Log alert to a file
int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert file: %s\n", ALERT_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO concentration %.2f ppm exceeds threshold %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm, CO_THRESHOLD);

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("CO Monitoring System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t data[4];

        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Extract OX and RED values (assuming OX is in bytes 0 and 1, RED in 2 and 3)
            uint16_t ox_value = (data[0] << 8) | data[1];
            uint16_t red_value = (data[2] << 8) | data[3];

            // Convert OX value to CO concentration
            float co_ppm = convert_to_ppm(ox_value);

            // Log data
            if (log_data(co_ppm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Check threshold and log alert
            if (check_threshold(co_ppm)) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert\n");
                }
            }

            printf("CO: %.2f ppm, RED: %u\n", co_ppm, red_value);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds...\n", SLEEP_SECONDS);
        }

        sleep(SLEEP_SECONDS);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("CO Monitoring System terminated.\n");

    return 0;
}

