// Define GPIO pins for I2C emulation
#define GPIO_SDA 2
#define GPIO_SCL 3

// Define I2C parameters
#define I2C_BUS 1
#define I2C_ADDR 0x48 // Example address, adjust as needed
#define I2C_FREQ 100000 // 100 kHz

// Define ADC parameters
#define ADC_RESOLUTION 12 // Example resolution
#define ADC_MAX_VALUE (1 << ADC_RESOLUTION) - 1

// Define sampling rate
#define SAMPLING_RATE_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int sda_pin;
    int scl_pin;
    int i2c_bus;
    int i2c_address;
    int i2c_frequency;
    int adc_resolution;
    int sampling_rate_ms;
} Config;

// Function prototypes
int initialize_i2c(int sda_pin, int scl_pin, int i2c_bus, int i2c_address, int i2c_frequency);
int read_adc(int i2c_handle);
double convert_to_db(int adc_value);
double calculate_average(double db1, double db2);
int log_data(double average_db);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c(int sda_pin, int scl_pin, int i2c_bus, int i2c_address, int i2c_frequency) {
    if (gpioSetMode(sda_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d to output\n", sda_pin);
        return -1;
    }
    if (gpioSetMode(scl_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d to output\n", scl_pin);
        return -1;
    }

    i2c_handle = i2cOpen(i2c_bus, i2c_address, 0); // flags = 0
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read ADC value from I2C
int read_adc(int i2c_handle) {
    // Implement I2C read sequence here
    // This is a placeholder, replace with actual I2C communication
    // For example, send command to ADC to start conversion, then read the result
    // This example assumes a simple read of two bytes

    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading ADC: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int adc_value = (buf[0] << 8) | buf[1];

    return adc_value;
}

// Convert ADC value to dB
double convert_to_db(int adc_value) {
    // Implement dB conversion formula here
    // This is a placeholder, replace with the actual formula
    // Example: dB = 20 * log10(adc_value / ADC_MAX_VALUE);
    double db = 20.0 * log10((double)adc_value / ADC_MAX_VALUE);
    return db;
}

// Calculate average dB value
double calculate_average(double db1, double db2) {
    return (db1 + db2) / 2.0;
}

// Log data to file
int log_data(double average_db) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f dB\n", timestamp, average_db);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize configuration
    Config config = {
        .sda_pin = GPIO_SDA,
        .scl_pin = GPIO_SCL,
        .i2c_bus = I2C_BUS,
        .i2c_address = I2C_ADDR,
        .i2c_frequency = I2C_FREQ,
        .adc_resolution = ADC_RESOLUTION,
        .sampling_rate_ms = SAMPLING_RATE_MS
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(config.sda_pin, config.scl_pin, config.i2c_bus, config.i2c_address, config.i2c_frequency) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value1 = read_adc(i2c_handle);
        int adc_value2 = read_adc(i2c_handle);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values, logging error\n");
            log_data(-999.0);
        } else {
            double db1 = convert_to_db(adc_value1);
            double db2 = convert_to_db(adc_value2);
            double average_db = calculate_average(db1, db2);
            log_data(average_db);
        }

        gpioDelay(config.sampling_rate_ms * 1000); // Delay for sampling rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

