#define MIC2_CHANNEL 1
#define LED_GPIO 27
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define HIGH_THRESHOLD 500
#define LED_ON_DURATION_MS 500
#define CSV_FILE "audio_events.csv"

// Global variables
int spi_handle_0 = -1;
int spi_handle_1 = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi(int channel);
int read_mcp3008(int spi_handle, int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Function to initialize SPI
int initialize_spi(int channel) {
    int handle = spiOpen(channel, SPI_SPEED, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
