    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize SPI
    spi_handle_0 = initialize_spi(SPI_CHANNEL_0);
    if (spi_handle_0 < 0) {
        cleanup();
        return 1;
    }

    spi_handle_1 = initialize_spi(SPI_CHANNEL_1);
    if (spi_handle_1 < 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
