#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define A0_CHANNEL 0x00
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define CURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int16_t read_ads1115();
float convert_to_current(int16_t raw_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int gpio_led;
    float current_threshold;
    int buffer_size;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read from ADS1115
int16_t read_ads1115() {
    char config[3];
    char data[2];

    // Configure ADS1115 for single-ended A0, 4.096V, 128 SPS, single conversion
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // OS=1, MUX=000, PGA=000, MODE=0, DR=000
    config[2] = 0x83; // COMP_MODE=0, COMP_POL=0, COMP_LAT=0, COMP_QUE=000

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from conversion register\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    int16_t raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Convert raw value to current (example formula, adjust as needed)
float convert_to_current(int16_t raw_value) {
    // Assuming a sensitivity of 0.1 V/A and a full-scale range of 4.096 V
    float voltage = (float)raw_value * 4.096 / 32768.0; // 32768 is the maximum value
    float current = voltage / 0.1;
    return current;
}

// Update circular buffer
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_LED as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        int16_t raw_value = read_ads1115();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading from ADS1115, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Update circular buffer
        update_circular_buffer(current);

        // Calculate average current
        float average_current = calculate_average_current();

        // Control LED
        control_led(average_current);

        // Print current value (optional)
        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

