#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_GPIO 17
#define OVERCURRENT_THRESHOLD 10.0 // Amperes
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL 1 // Seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int motor_gpio;
    float overcurrent_threshold;
    char *log_file;
    int sample_interval;
} Config;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_amperes(int adc_value);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, adc_value;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    for (count = 0; count < 3; count++) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
            fprintf(stderr, "SPI transfer failed (attempt %d)\n", count + 1);
            if (count < 2) {
                gpioDelay(1000); // Wait 1ms before retrying
                continue;
            } else {
                return -1; // Indicate failure
            }
        }
        break; // Exit the loop if transfer is successful
    }

    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to amperes
float adc_to_amperes(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and a known ADC range (e.g., 0-1023 for 0-5A).
    // This is a placeholder and needs to be calibrated for your specific setup.
    float current = (float)adc_value / 1023.0 * 5.0; // Example: 0-5A range
    return current;
}

// Function to log current to file
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check for overcurrent condition
void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent detected: %.2f A\n", current);
        fprintf(log_file, "Overcurrent detected: %.2f A\n", current);
        fflush(log_file);

        gpioWrite(MOTOR_GPIO, 0); // Disable motor
        gpioDelay(1000);          // Wait 1 second
        gpioWrite(MOTOR_GPIO, 1); // Re-enable motor
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set motor GPIO as output
    gpioSetMode(MOTOR_GPIO, PI_OUTPUT);
    gpioWrite(MOTOR_GPIO, 1); // Initially enable the motor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty or new, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
        fflush(log_file);
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(MOTOR_GPIO, 1); // Ensure motor is enabled on exit
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        float current = adc_to_amperes(adc_value);
        log_current(current);
        check_overcurrent(current);

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for the sample interval
    }

    cleanup();
    return 0;
}

