#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define MLX90817_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register address, adjust as needed
#define LOG_FILE "pressure_log.csv"
#define SENSOR_ABSENT_THRESHOLD 3
#define SLEEP_SECONDS 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    double pressure_kPa;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_pressure(double *pressure_kPa);
int log_data(double pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure data from the sensor
int read_pressure(double *pressure_kPa) {
    char buf[2]; // Assuming 2 bytes for pressure data
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);

    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    // Convert raw data to kPa (example conversion, adjust as needed)
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    *pressure_kPa = (double)raw_pressure * 0.1; // Example scaling

    return 0;
}

// Log data to CSV file
int log_data(double pressure_kPa) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (kPa)\n");
        fflush(log_file);
    }

    int sensor_absent_count = 0;

    // Main loop
    while (!terminate) {
        double pressure_kPa;

        if (read_pressure(&pressure_kPa) == 0) {
            log_data(pressure_kPa);
            sensor_absent_count = 0; // Reset absent count on successful read
        } else {
            fprintf(stderr, "Failed to read pressure. Incrementing absent count.\n");
            sensor_absent_count++;
            if (sensor_absent_count >= SENSOR_ABSENT_THRESHOLD) {
                fprintf(stderr, "Sensor is absent or unresponsive. Stopping logging.\n");
                break; // Exit loop if sensor is consistently absent
            }
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

