#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define OVERCURRENT_THRESHOLD 10.0 // Amperes
#define OVERCURRENT_GPIO 27 // BCM
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float overcurrent_threshold;
    int overcurrent_gpio;
    char log_file[64];
} Config;

// Function prototypes
int initialize_pigpio();
int open_spi(int channel, int speed);
int read_mcp3008(int channel);
float convert_to_current(int adc_value);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open SPI channel
int open_spi(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // SPI mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to current
float convert_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and a sensitivity of 10mV/A (10000 counts/10A)
    float current = (float)adc_value * 10.0 / 1024.0; // 1024 counts for 10-bit ADC
    return current;
}

// Function to log current to file
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file);
}

// Function to check for overcurrent condition
void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        gpioWrite(OVERCURRENT_GPIO, 1); // Set GPIO HIGH
        fprintf(log_file, "OVERCURRENT, %.2f\n", current);
        fflush(log_file);
        fprintf(stderr, "OVERCURRENT: %.2f A\n", current);
        terminate = 1; // Signal termination
    } else {
        gpioWrite(OVERCURRENT_GPIO, 0); // Set GPIO LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(OVERCURRENT_GPIO, 0); // Reset GPIO
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Configuration
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .mcp3008_channel = MCP3008_CHANNEL,
        .overcurrent_threshold = OVERCURRENT_THRESHOLD,
        .overcurrent_gpio = OVERCURRENT_GPIO,
        .log_file = LOG_FILE
    };

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    spi_handle = open_spi(config.spi_channel, config.spi_speed);
    if (spi_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file);
        cleanup();
        return 1;
    }

    // Set GPIO mode for overcurrent indication
    gpioSetMode(config.overcurrent_gpio, PI_OUTPUT);
    gpioWrite(config.overcurrent_gpio, 0); // Initially LOW

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(adc_value);

        // Log current
        log_current(current);

        // Check for overcurrent
        check_overcurrent(current);

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

