#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CE0 8
#define SPI_CE1 7
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define ALARM_PIN 4

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define CO sensor voltage threshold
#define VOLTAGE_THRESHOLD 2.5

// Define CO sensor sensitivity (example value, adjust based on datasheet)
#define SENSOR_SENSITIVITY 0.5 // ppm/V

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
float adc_to_voltage(int adc_value);
void log_data(FILE *log_file, float voltage);
void control_alarm(float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to log data to file
void log_data(FILE *log_file, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the alarm
void control_alarm(float voltage) {
    if (voltage > VOLTAGE_THRESHOLD) {
        gpioWrite(ALARM_PIN, 1); // Turn on alarm
    } else {
        gpioWrite(ALARM_PIN, 0); // Turn off alarm
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("co_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set alarm pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Initially turn off the alarm

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(spi_handle, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            fprintf(log_file, "Error: Failed to read ADC value\n");
        } else {
            // Convert ADC value to voltage
            float voltage = adc_to_voltage(adc_value);

            // Log data
            log_data(log_file, voltage);

            // Control alarm
            control_alarm(voltage);

            printf("Voltage: %.2f V\n", voltage);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is off
    gpioTerminate();

    printf("CO sensor monitoring stopped.\n");

    return 0;
}

