#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define AIN0_CHANNEL 0
#define SAMPLE_RATE_HZ 1
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int ain0_channel;
    int sample_rate_hz;
    float pressure_min;
    float pressure_max;
    char *log_file_name;
} Config;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_ads1115(int handle, int channel);
float convert_to_pressure(int raw_value);
int validate_pressure(float pressure);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from ADS1115
int read_ads1115(int handle, int channel) {
    // Configure ADS1115 for single-ended mode, 4.096V range, 128 SPS
    uint8_t config[3];
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC2; // Single-ended AIN0, 4.096V, 128 SPS, start single conversion
    config[2] = (channel << 1) | 0x80; // Configure channel

    if (i2cWriteDevice(handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion result
    uint8_t data[2];
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    int16_t raw_value = (data[0] << 8) | data[1];

    // Sign extend if necessary
    if (raw_value & 0x8000) {
        raw_value |= 0xFFFF0000;
    }

    return raw_value;
}

// Convert raw value to pressure (kPa)
float convert_to_pressure(int raw_value) {
    // Assuming a linear relationship between raw value and pressure
    // and a full-scale range of 0-4.096V (16-bit ADC)
    float voltage = (float)raw_value / 32768.0 * 4.096; // 32768 is 2^15
    float pressure = (voltage / 4.096) * 100.0; // 0-4V -> 0-100kPa
    return pressure;
}

// Validate pressure reading
int validate_pressure(float pressure) {
    if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
        return 1; // Valid
    } else {
        fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        return 0; // Invalid
    }
}

// Log pressure reading to file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, ADS1115_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl-C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read pressure from sensor
        int raw_value = read_ads1115(i2c_handle, AIN0_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading pressure data\n");
            cleanup();
            return 1;
        }

        // Convert to pressure
        float pressure = convert_to_pressure(raw_value);

        // Validate pressure
        if (validate_pressure(pressure)) {
            // Log pressure
            log_pressure(pressure);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

