#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0 // Channel connected to HIH-4602-A
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define EMAIL_SUBJECT "Humidity Alert"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity, float temperature);
void signal_handler(int signal);

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (12 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A datasheet formula (example, adjust as needed)
    // This is a simplified linear approximation.  A real implementation
    // would use a more complex curve fit or a lookup table.
    float humidity = (float)adc_value / 4095.0 * 100.0; // Example scaling
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    // HIH-4602-A datasheet formula (example, adjust as needed)
    // This is a simplified linear approximation.  A real implementation
    // would use a more complex curve fit or a lookup table.
    float temperature = (float)adc_value / 4095.0 * 50.0 - 25.0; // Example scaling
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float humidity, float temperature) {
    char command[256];
    char body[256];

    snprintf(body, sizeof(body), "Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

    snprintf(command, sizeof(command), "echo \"%s\" | ssmtp -t %s", body, EMAIL_RECIPIENT);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to send email alert\n");
        return;
    }

    // Read the output of the command (optional)
    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        // Optionally log the output
        fprintf(stderr, "%s", buffer);
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: Email command failed with status %d\n", status);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Humidity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Humidity monitoring stopped.\n");

    return 0;
}

