#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FLOW_SENSOR_CHANNEL 0
#define FULL_SCALE_VOLTAGE 5.0 // V
#define MAX_FLOW_RATE 5.0      // L/min
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_device();
int read_mcp3008(int channel);
float convert_to_flow_rate(int adc_value);
int log_flow_rate(float flow_rate);
void handle_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int flow_sensor_channel;
    float full_scale_voltage;
    float max_flow_rate;
    char log_file[64];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    FLOW_SENSOR_CHANNEL,
    FULL_SCALE_VOLTAGE,
    MAX_FLOW_RATE,
    LOG_FILE
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        handle_error("Failed to initialize pigpio");
        return 1;
    }

    // Open SPI device
    if (open_spi_device() != 0) {
        handle_error("Failed to open SPI device");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        handle_error("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.flow_sensor_channel);

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);

        // Log flow rate
        if (log_flow_rate(flow_rate) != 0) {
            handle_error("Failed to log flow rate");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI device
int open_spi_device() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        handle_error("Invalid MCP3008 channel");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to flow rate
float convert_to_flow_rate(int adc_value) {
    if (adc_value == 0 || adc_value == 1023) {
        return -1.0; // Sensor absent
    }

    float voltage = (float)adc_value / 1023.0 * config.full_scale_voltage;
    float flow_rate = (voltage / config.full_scale_voltage) * config.max_flow_rate;

    return flow_rate;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    if (flow_rate < 0.0 || flow_rate > config.max_flow_rate) {
        handle_error("Flow rate out of range");
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    fprintf(log_file, "%s,%.6f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

// Handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

