#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x68 // Or 0x69, check your sensor
#define MEASUREMENT_COMMAND 0x10 // High precision measurement command
#define DATA_LENGTH 6
#define RETRY_DELAY 5 // seconds
#define CSV_FILENAME "environmental_data.csv"

// Global variables
int i2c_handle = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void display_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASUREMENT_COMMAND, 0); // Add register address if needed
    if (result < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion (adjust as needed based on sensor datasheet)
    gpioDelay(10); // 10 ms delay

    // Read data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, DATA_LENGTH); // Read from register 0
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and pressure
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    // Implement calibration formulas from the ICP-10125 datasheet here
    // This is a placeholder; replace with actual conversion logic
    // Example (replace with actual formulas):
    int32_t raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t raw_temperature = (data[3] << 16) | (data[4] << 8) | data[5];

    sensor_data.temperature = (float)raw_temperature / 100.0; // Example scaling
    sensor_data.pressure = (float)raw_pressure / 100.0;      // Example scaling

    return sensor_data;
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILENAME);
        return -1;
    }

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.pressure);
    fclose(csv_file);

    return 0;
}

// Function to display data on the console
void display_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", data.temperature, data.pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

