    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C with retry
    int init_result = -1;
    int retry_count = 0;
    while (init_result != 0 && retry_count < 3) {
        init_result = initialize_i2c();
        if (init_result != 0) {
            fprintf(stderr, "I2C initialization failed, retrying in %d seconds...\n", RETRY_DELAY);
            sleep(RETRY_DELAY);
            retry_count++;
        }
    }

    if (init_result != 0) {
        fprintf(stderr, "I2C initialization failed after multiple retries. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[DATA_LENGTH];
        int read_result = read_sensor_data(data);

        if (read_result == 0) {
            sensor_data_t sensor_data = convert_data(data);
            display_data(sensor_data);
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", RETRY_DELAY);
            sleep(RETRY_DELAY);
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            init_result = initialize_i2c();
            if (init_result != 0) {
                fprintf(stderr, "I2C re-initialization failed. Continuing without I2C.\n");
            }
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

