#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL_0 0
#define SPI_CHANNEL_1 1
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define SAMPLE_RATE 8000
#define BUFFER_SIZE 1024

// Global variables
int spi_handle_0, spi_handle_1;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t left;
    int16_t right;
} AudioSample;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer the SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to apply noise cancellation
int16_t noise_cancellation(int16_t left, int16_t right, float gain) {
    return (int16_t)((left - right) * gain);
}

// Function to print audio samples in CSV format
void print_audio_samples(AudioSample *samples, int num_samples) {
    for (int i = 0; i < num_samples; i++) {
        printf("%d,%d\n", samples[i].left, samples[i].right);
    }
}

int main(int argc, char *argv[]) {
    // Check command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain_left> <gain_right>\n", argv[0]);
        return 1;
    }

    float gain_left = atof(argv[1]);
    float gain_right = atof(argv[2]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI for both channels
    spi_handle_0 = spiOpen(SPI_CHANNEL_0, SPI_SPEED, 0); // CE0
    if (spi_handle_0 < 0) {
        fprintf(stderr, "Error: SPI open failed for channel 0 (CE0)\n");
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, 0); // CE1
    if (spi_handle_1 < 0) {
        fprintf(stderr, "Error: SPI open failed for channel 1 (CE1)\n");
        spiClose(spi_handle_0);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Allocate memory for audio samples
    AudioSample *audio_samples = (AudioSample *)malloc(BUFFER_SIZE * sizeof(AudioSample));
    if (audio_samples == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        spiClose(spi_handle_0);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int sample_count = 0;
    while (!terminate) {
        // Read audio samples from both microphones
        int left_adc = read_mcp3008(spi_handle_0, MCP3008_CHANNEL_0);
        int right_adc = read_mcp3008(spi_handle_1, MCP3008_CHANNEL_1);

        if (left_adc == -1 || right_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to signed 16-bit integers
        int16_t left_sample = (int16_t)left_adc;
        int16_t right_sample = (int16_t)right_adc;

        // Apply noise cancellation
        int16_t filtered_left = noise_cancellation(left_sample, right_sample, gain_left);
        int16_t filtered_right = noise_cancellation(left_sample, right_sample, gain_right);

        // Store the filtered samples
        audio_samples[sample_count].left = filtered_left;
        audio_samples[sample_count].right = filtered_right;

        // Increment the sample count
        sample_count++;

        // Print the samples in CSV format if the buffer is full
        if (sample_count >= BUFFER_SIZE) {
            print_audio_samples(audio_samples, BUFFER_SIZE);
            sample_count = 0; // Reset the sample count
        }

        // Delay to achieve the desired sample rate
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Print any remaining samples in the buffer
    if (sample_count > 0) {
        print_audio_samples(audio_samples, sample_count);
    }

    // Free allocated memory
    free(audio_samples);

    // Close SPI channels
    spiClose(spi_handle_0);
    spiClose(spi_handle_1);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

