#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
double ambient_temperature = 25.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t channel);
double read_temperature(void);
double temperature_compensation(int adc_value, double temperature);
void log_data(int adc_value, double voltage, double compensated_voltage, double temperature, int flame_detected);
void signal_handler(int signal);
int read_ambient_temperature(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message (single-ended, channel selection)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to read ambient temperature from file
int read_ambient_temperature(void) {
    FILE *fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *endptr;
    double temp = strtod(line, &endptr);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error converting temperature to double\n");
        return -1;
    }

    return (int)temp;
}

// Function to read temperature from the sensor
double read_temperature(void) {
    int raw_temp = spi_transfer(1); // Channel 1 for temperature
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature from sensor\n");
        return -1.0;
    }

    // Assuming temperature is a 10-bit value (0-1023)
    // and needs to be converted to Celsius
    double temperature = (double)raw_temp / 1023.0 * 50.0; // Example conversion
    return temperature;
}

// Function to temperature-compensate the ADC value
double temperature_compensation(int adc_value, double temperature) {
    // Simple linear compensation (adjust as needed based on sensor datasheet)
    double compensated_value = adc_value + (temperature - ambient_temperature) * 0.1; // Example compensation
    if (compensated_value < 0) compensated_value = 0;
    if (compensated_value > 1023) compensated_value = 1023;
    return compensated_value;
}

// Function to log data to file
void log_data(int adc_value, double voltage, double compensated_voltage, double temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.2f,%.2f,%.2f,%d\n",
            timestamp, adc_value, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is initially OFF

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read ambient temperature
    int temp_file_temp = read_ambient_temperature();
    if (temp_file_temp != -1) {
        ambient_temperature = (double)temp_file_temp;
    } else {
        fprintf(stderr, "Using default ambient temperature: %.2f\n", ambient_temperature);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;
        while (adc_value < 0 && retries < MAX_RETRIES) {
            adc_value = spi_transfer(0); // Channel 0 for flame sensor
            if (adc_value < 0) {
                fprintf(stderr, "SPI transfer failed, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                usleep(10000); // Wait 10ms before retrying
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            continue; // Skip to the next iteration
        }

        // Read temperature
        double temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue; // Skip to the next iteration
        }

        // Temperature compensation
        double compensated_voltage = temperature_compensation(adc_value, temperature);

        // Flame detection logic
        int flame_detected = (compensated_voltage > 500) ? 1 : 0;

        // Log data
        double voltage = (double)adc_value / 1023.0 * 5.0; // Assuming 5V reference
        log_data(adc_value, voltage, compensated_voltage, temperature, flame_detected);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer OFF
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

