    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Write JSON entry to file
int write_json_entry(const char *timestamp, float water_level) {
    if (json_file == NULL) {
        fprintf(stderr, "JSON file is not open.\n");
        return 1;
    }

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}", timestamp, water_level);
    fprintf(json_file, ",\n");
    fflush(json_file);

    return 0;
}

