int control_led(float water_level) {
    if (water_level > config.high_threshold) {
        gpioWrite(config.led_pin, 1); // Turn LED on
    } else if (water_level < config.low_threshold) {
        gpioWrite(config.led_pin, 0); // Turn LED off
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stdout, "Received signal %d. Terminating.\n", signal);
    terminate = 1;
}

// Close resources before exiting
int close_resources() {
    // Turn off LED
    gpioWrite(config.led_pin, 0);

    // Close SPI channel
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close JSON file
    if (json_file != NULL) {
        // Remove the last comma and newline
        fseek(json_file, -2, SEEK_END);
        fprintf(json_file, "\n]");
        fclose(json_file);
    }

    return 0;
}

