    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_handle, config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(config.logging_interval);
