// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)
#define VREF 3.3          // Reference voltage
#define PRESSURE_MIN 0.0  // Minimum pressure (kPa)
#define PRESSURE_MAX 100.0 // Maximum pressure (kPa)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_pressure(int adc_value);
void get_iso8601_timestamp(char *timestamp);
void log_data(float pressure);
void handle_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to pressure (kPa)
float adc_to_pressure(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    float voltage = (float)adc_value / 1023.0 * VREF;

    // Linear conversion (example, adjust based on sensor datasheet)
    // Assuming 0V = 0 kPa, 3.3V = 100 kPa
    float pressure = (voltage / VREF) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;

    return pressure;
}

// Get ISO 8601 timestamp
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Log data to console
void log_data(float pressure) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp);
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pressure sensor reading started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            handle_error("Failed to read ADC value");
        } else {
            float pressure = adc_to_pressure(adc_value);
            if (pressure >= 0) {
                log_data(pressure);
            } else {
                handle_error("Failed to convert ADC value to pressure");
            }
        }

        gpioDelay(1000); // 1-second interval
    }

    cleanup();
    return 0;
}

