// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define GPIO pins for SPI
#define CE0_PIN 8
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9

// Define sensor channels
#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1
#define SENSOR3_CHANNEL 2

// Define error value for sensor fault
#define SENSOR_FAULT_VALUE 1023

// Global variable for SPI handle
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
void log_data(int sensor_id, int adc_value);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
    int sensor3_value;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log sensor data with timestamp
void log_data(int sensor_id, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor %d: ADC Value = %d\n", timestamp, sensor_id, adc_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code = %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        int sensor1_value = read_mcp3008(SENSOR1_CHANNEL);
        int sensor2_value = read_mcp3008(SENSOR2_CHANNEL);
        int sensor3_value = read_mcp3008(SENSOR3_CHANNEL);

        // Log sensor data
        log_data(1, sensor1_value);
        log_data(2, sensor2_value);
        log_data(3, sensor3_value);

        // Check for sensor faults
        if (sensor1_value == SENSOR_FAULT_VALUE || sensor2_value == SENSOR_FAULT_VALUE || sensor3_value == SENSOR_FAULT_VALUE) {
            fprintf(stderr, "Error: Sensor fault detected!\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup (this part will not be reached in the infinite loop)
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

