#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 4
#define LOG_FILE "environmental_data.csv"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_adc(int channel);
float convert_to_voltage(int adc_value);
int log_data(float voltages[NUM_CHANNELS]);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    char *device;
    uint8_t mode;
    uint32_t speed;
} spi_config_t;

// SPI configuration
spi_config_t spi_config = {
    .device = SPI_DEVICE,
    .mode = SPI_MODE,
    .speed = SPI_SPEED
};

// Function to initialize SPI
int spi_init(void) {
    int ret;

    spi_fd = open(spi_config.device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_config.mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_config.speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = spi_config.speed;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to log data to CSV file
int log_data(float voltages[NUM_CHANNELS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp,
            voltages[0], voltages[1], voltages[2], voltages[3]);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main(void) {
    int i;
    float voltages[NUM_CHANNELS];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel0,Channel1,Channel2,Channel3\n");
    }

    // Main loop
    while (!terminate) {
        // Read ADC values
        for (i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_adc(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC channel %d. Skipping.\n", i);
                voltages[i] = -1.0; // Indicate error
            } else {
                voltages[i] = convert_to_voltage(adc_value);
            }
        }

        // Log data
        log_data(voltages);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(spi_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

