#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define HEALTH_LOG_FILE "health_log.txt"
#define SLEEP_DURATION_MS 1000 // 1 second

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102(int i2c_handle);
int read_max30102_data(int i2c_handle, int *spo2, int *heart_rate);
void log_health_data(int spo2, int heart_rate);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize the MAX30102 sensor
int init_max30102(int i2c_handle) {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, 0x00, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset MAX30102\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure FIFO
    if (i2cWriteByteData(i2c_handle, 0x08, 0x03) < 0) return -1; // Sample Average = 4, FIFO almost full = 17
    if (i2cWriteByteData(i2c_handle, 0x09, 0x03) < 0) return -1; // FIFO almost full = 17

    // Configure Mode
    if (i2cWriteByteData(i2c_handle, 0x06, 0x03) < 0) return -1; // HR only mode

    // Configure SpO2
    if (i2cWriteByteData(i2c_handle, 0x07, 0x21) < 0) return -1; // 100 samples/sec, 1600uA LED current
    if (i2cWriteByteData(i2c_handle, 0x0A, 0x3F) < 0) return -1; // 100 samples/sec, 1600uA LED current

    // Configure LED Pulse Amplitude
    if (i2cWriteByteData(i2c_handle, 0x0C, 0x1F) < 0) return -1; // LED current for red and IR LED
    if (i2cWriteByteData(i2c_handle, 0x0D, 0x1F) < 0) return -1; // LED current for red and IR LED

    // Configure Proximity Mode
    if (i2cWriteByteData(i2c_handle, 0x10, 0x00) < 0) return -1; // Disable proximity mode

    // Configure Part ID
    if (i2cWriteByteData(i2c_handle, 0xFF, 0x01) < 0) return -1; // Reset Part ID

    return 0;
}

// Function to read SpO2 and heart rate data from the MAX30102
int read_max30102_data(int i2c_handle, int *spo2, int *heart_rate) {
    unsigned char data[6];

    // Read 6 bytes of data (SpO2 MSB, SpO2 LSB, HR MSB, HR LSB, RESERVED, CHECKSUM)
    if (i2cReadI2CBlockData(i2c_handle, 0x07, (char*)data, 6) < 0) {
        fprintf(stderr, "Error: Failed to read data from MAX30102\n");
        return -1;
    }

    // Extract SpO2 and heart rate values
    *spo2 = (data[0] << 8) | data[1];
    *heart_rate = (data[2] << 8) | data[3];

    return 0;
}

// Function to log health data to a file
void log_health_data(int spo2, int heart_rate) {
    FILE *fp = fopen(HEALTH_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return;
    }

    char *timestamp = get_iso8601_timestamp();
    fprintf(fp, "%s - SpO2: %d, Heart Rate: %d\n", timestamp, spo2, heart_rate);
    fclose(fp);
    free(timestamp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence by reading Part ID
    int part_id = i2cReadByteData(i2c_handle, 0xFF);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read Part ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x15) {
        fprintf(stderr, "Error: MAX30102 not found (Part ID: 0x%02X)\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102(i2c_handle) < 0) {
        fprintf(stderr, "Error: MAX30102 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spo2, heart_rate;

    // Main loop
    while (!terminate) {
        // Read data from MAX30102
        if (read_max30102_data(i2c_handle, &spo2, &heart_rate) == 0) {
            // Log health data
            log_health_data(spo2, heart_rate);

            // Check for critical values
            if (spo2 < 95 || heart_rate > 100) {
                char *timestamp = get_iso8601_timestamp();
                FILE *fp = fopen(HEALTH_LOG_FILE, "a");
                if (fp != NULL) {
                    fprintf(fp, "%s - CRITICAL: SpO2: %d, Heart Rate: %d\n", timestamp, spo2, heart_rate);
                    fclose(fp);
                } else {
                    fprintf(stderr, "Error: Failed to open log file for critical data\n");
                }
                free(timestamp);
            }
        } else {
            fprintf(stderr, "Error: Failed to read data from MAX30102\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_DURATION_MS);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

