#define NUM_CHANNELS 3
#define READ_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
    int mode;
} spi_config_t;

// Function prototypes
int initialize_spi(spi_config_t config);
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int log_data(FILE *fp, int channel, float voltage);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.baud, config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return (adc_value * 3.3) / 1024.0;
