#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_DEFAULT 0x4003 // Single-shot mode, AIN0, +/-4.096V, 128 SPS
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define NUM_CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define SAMPLING_DELAY_MS 200
#define THRESHOLD_DISTANCE_MM 500
#define RELAY_PULSE_DURATION_MS 3000
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int ads1115_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c(int address);
int16_t read_ads1115(int fd);
float calibrate_sensor(int fd, int num_samples, int delay_ms);
float convert_to_distance(int16_t adc_value);
bool is_door_open(int gpio_pin);
void control_relay(int gpio_pin, int duration_ms);
void log_event(const char *message);
void signal_handler(int signal);

// Function to initialize the I2C interface
int initialize_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read data from the ADS1115
int16_t read_ads1115(int fd) {
    int16_t value = -1;
    int retries = 3;

    while (retries > 0) {
        // Write the configuration register
        if (wiringPiI2CWriteReg16(fd, ADS1115_REG_CONFIG, ADS1115_CONFIG_DEFAULT) == -1) {
            fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
            retries--;
            delay(10); // Small delay before retrying
            continue;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        delay(10);

        // Read the conversion register
        int16_t config_value = wiringPiI2CReadReg16(fd, ADS1115_REG_CONVERT);
        if (config_value == -1) {
            fprintf(stderr, "Error reading from conversion register: %s\n", strerror(errno));
            retries--;
            delay(10);
            continue;
        }

        // Extract the 12-bit value
        value = (config_value >> 4) & 0xFFF; // Shift right by 4 bits and mask to get 12 bits
        if (value & 0x800) {
            value |= 0xF000; // Sign extend if negative
        }

        return value;
    }

    fprintf(stderr, "Failed to read ADS1115 after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to calibrate the sensor
float calibrate_sensor(int fd, int num_samples, int delay_ms) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        int16_t adc_value = read_ads1115(fd);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC during calibration.\n");
            return -1.0; // Indicate calibration failure
        }
        sum += adc_value;
        delay(delay_ms);
    }
    return (float)(sum / num_samples);
}

// Function to convert ADC value to distance (mm)
float convert_to_distance(int16_t adc_value) {
    // This is a placeholder.  A real implementation would use a
    // calibration curve or lookup table specific to the GP2Y0A21YK0F sensor.
    // The relationship between ADC value and distance is non-linear.
    // This example assumes a linear relationship for demonstration purposes.
    // You'll need to determine the appropriate formula based on your sensor's datasheet.
    // Example: distance = 500.0 / (adc_value + 1); // Example inverse relationship

    // For this example, we'll use a simple linear mapping.
    // This is NOT a real-world calibration and should be replaced with a proper one.
    float distance = 500.0 - (float)adc_value * 0.5; // Example linear mapping
    if (distance < 0) distance = 0; // Ensure distance is not negative
    return distance;
}

// Function to check if the door is open
bool is_door_open(int gpio_pin) {
    return !digitalRead(gpio_pin); // Active-low
}

// Function to control the relay
void control_relay(int gpio_pin, int duration_ms) {
    digitalWrite(gpio_pin, HIGH); // Energize relay
    delay(duration_ms);
    digitalWrite(gpio_pin, LOW);  // De-energize relay
}

// Function to log events
void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not initialized.\n");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    ads1115_fd = initialize_i2c(ADS1115_ADDRESS);
    if (ads1115_fd == -1) {
        return 1;
    }

    // Configure GPIO pins
    pinMode(GPIO_RELAY, OUTPUT);
    pinMode(GPIO_DOOR_SENSOR, INPUT);
    pullUpDnControl(GPIO_DOOR_SENSOR, PUD_UP); // Enable pull-up resistor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibrate the sensor
    float baseline_value = calibrate_sensor(ads1115_fd, NUM_CALIBRATION_SAMPLES, CALIBRATION_DELAY_MS);
    if (baseline_value == -1.0) {
        fprintf(stderr, "Sensor calibration failed.\n");
        fclose(log_file);
        return 1;
    }
    printf("Baseline ADC value: %f\n", baseline_value);

    // Main loop
    while (program_running) {
        // Read distance from sensor
        int16_t adc_value = read_ads1115(ads1115_fd);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value.\n");
            log_event("Error reading ADC value.");
            delay(SAMPLING_DELAY_MS);
            continue;
        }

        float distance = convert_to_distance(adc_value);
        printf("Distance: %.2f mm\n", distance);

        // Check if door is open
        bool door_open = is_door_open(GPIO_DOOR_SENSOR);

        // Check if distance is below threshold and door is open
        if (distance < THRESHOLD_DISTANCE_MM && door_open) {
            printf("Releasing door lock!\n");
            log_event("Releasing door lock.");
            control_relay(GPIO_RELAY, RELAY_PULSE_DURATION_MS);
            if (is_door_open(GPIO_DOOR_SENSOR)) {
                log_event("Door opened.");
            } else {
                log_event("Door not opened.");
            }
        }

        delay(SAMPLING_DELAY_MS);
    }

    // Cleanup
    digitalWrite(GPIO_RELAY, LOW); // Ensure relay is de-energized
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

