        int16_t adc_value = read_ads1115(fd);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC during calibration.\n");
            return -1.0; // Indicate calibration failure
        }
        sum += adc_value;
        delay(delay_ms);
    }
    return (float)(sum / num_samples);
