#define CS1_PIN 7
#define CS2_PIN 25

// Define GPIO pins for manual chip select control
#define GPIO_CS0 8
#define GPIO_CS1 7
#define GPIO_CS2 25

// Define GPIO pins for SPI communication
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11

// Define SPI mode
#define SPI_MODE 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define CSV file name
#define CSV_FILE "soil_moisture_log.csv"

// Define sleep interval (seconds)
#define SLEEP_INTERVAL 5

// Global variables
int spi_fd = -1;
FILE *csv_file = NULL;
bool running = true;

// Function prototypes
int spi_init(void);
int spi_read_adc(int chip_select_pin, int channel);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
