    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        if (csv_write_header(csv_file) < 0) {
            fclose(csv_file);
            goto cleanup_spi;
        }
        header_written = true;
