        // Write data to CSV file
        if (csv_write_data(csv_file, sensor1_value, sensor2_value, sensor3_value) < 0) {
            fprintf(stderr, "Error writing data to CSV file.\n");
        }

        // Flush the buffer to ensure data is written to the file
        fflush(csv_file);

        // Sleep for the specified interval
        sleep(SLEEP_INTERVAL);
    }

    // Close CSV file
    fclose(csv_file);

