#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, adc_value = -1;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    for (count = 0; count < 3; count++) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            log_event("SPI read failed, retrying...");
            gpioDelay(1000); // Wait 1ms before retry
        }
    }

    log_event("SPI read failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
int calculate_moisture_percentage(int adc_value) {
    return (int)(((float)adc_value / 1023.0) * 100.0);
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[50];
    snprintf(message, sizeof(message), "Pump turned %s", state ? "ON" : "OFF");
    log_event(message);
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        log_event("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value != -1) {
            int moisture_percentage = calculate_moisture_percentage(adc_value);
            char message[50];
            snprintf(message, sizeof(message), "Moisture level: %d%% (ADC: %d)", moisture_percentage, adc_value);
            log_event(message);

            if (moisture_percentage < threshold) {
                log_event("Moisture level below threshold, activating pump");
                control_pump(1); // Turn on pump
                gpioDelay(duration * 1000); // Wait for specified duration
                control_pump(0); // Turn off pump
                log_event("Pump deactivated");
            }
        } else {
            log_event("Failed to read moisture level");
        }

        gpioDelay(sleep_interval * 1000); // Wait for specified sleep interval
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    log_event("System stopped");

    return 0;
}

