#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl-C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the PCF8591
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Dummy read to trigger conversion
        unsigned char dummy_read = 0x40; // Control byte for AIN0
        if (write(i2c_fd, &dummy_read, 1) != 1) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            return 1;
        }

        // Read the ADC value
        unsigned char adc_value;
        if (read(i2c_fd, &adc_value, 1) != 1) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        // Print the ADC value
        printf("ADC Value: %d\n", adc_value);

        // Wait 100 milliseconds
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close the I2C bus (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

