#define SPI_SPEED 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO 18
#define WATERING_DURATION 10 // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int validate_moisture_level(int moisture_level);
void control_pump(int state);
void log_event(int moisture_level, int pump_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate an error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to validate moisture level
int validate_moisture_level(int moisture_level) {
    if (moisture_level < 0 || moisture_level > 1023) {
        fprintf(stderr, "Error: Invalid moisture level %d\n", moisture_level);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log watering events
void log_event(int moisture_level, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Moisture: %d, Pump: %s\n", timestamp, moisture_level, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            continue; // Skip to the next iteration
        }

        // Validate moisture level
        if (validate_moisture_level(moisture_level) != 0) {
            fprintf(stderr, "Error: Invalid moisture level, skipping watering check\n");
            continue; // Skip watering check
        }

        printf("Moisture level: %d\n", moisture_level);

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating water pump.\n");
            control_pump(1); // Turn pump ON
            log_event(moisture_level, 1); // Log pump activation
            gpioDelay(WATERING_DURATION * 1000000); // Wait for watering duration (microseconds)
            control_pump(0); // Turn pump OFF
            log_event(moisture_level, 0); // Log pump deactivation
            printf("Water pump deactivated.\n");
        }

        gpioDelay(60000000); // Wait 60 seconds (microseconds)
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is OFF
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

