#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define RAIN_SENSOR_CHANNEL 0
#define VDD 3.3
#define FULL_SCALE_ADC 1023.0
#define NUM_INTENSITY_LEVELS 5

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_device();
int read_mcp3008(int channel);
float map_adc_to_intensity(int adc_value);
void log_data(int adc_value, float intensity);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int rain_sensor_channel;
    float vdd;
    float full_scale_adc;
    int num_intensity_levels;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_BAUD,
    RAIN_SENSOR_CHANNEL,
    VDD,
    FULL_SCALE_ADC,
    NUM_INTENSITY_LEVELS
};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI device
    if (open_spi_device() != 0) {
        fprintf(stderr, "Failed to open SPI device. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value from rain sensor
        int adc_value = read_mcp3008(config.rain_sensor_channel);

        // Map ADC value to rainfall intensity
        float intensity = map_adc_to_intensity(adc_value);

        // Log data
        log_data(adc_value, intensity);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI device
int open_spi_device() {
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Map ADC value to rainfall intensity level
float map_adc_to_intensity(int adc_value) {
    if (adc_value < 0) return 0.0; // Handle error case
    if (adc_value > config.full_scale_adc) return (float)config.num_intensity_levels - 1.0; // Cap at max intensity

    return (float)adc_value / config.full_scale_adc * (float)(config.num_intensity_levels - 1);
}

// Log data to stdout
void log_data(int adc_value, float intensity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, %d, %.2f\n", timestamp, adc_value, intensity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

