#define SPI_CE1 7   // GPIO7 (BCM)
#define MOTOR_PIN 18 // GPIO18 (BCM)

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1024

// Global variables
int spi_handle0 = -1;
int spi_handle1 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi(int ce_pin);
int read_adc(int spi_handle, int channel);
void set_motor_speed(int gpio_pin, int duty_cycle);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int spi_handle;
} spi_config_t;

// Function to initialize SPI
int initialize_spi(int ce_pin) {
    int handle = spiOpen(ce_pin, SPI_SPEED, SPI_MODE);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", ce_pin, handle);
        return -1;
    }
    return handle;
}

// Function to read ADC value from MCP3008
int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
