            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate average ADC value
        int average_adc = (adc_value0 + adc_value1) / 2;

        // Map ADC value to PWM duty cycle
        int duty_cycle = average_adc;
        if (duty_cycle > PWM_RANGE) {
            duty_cycle = PWM_RANGE;
        }
        if (duty_cycle < 0) {
            duty_cycle = 0;
        }

        // Set motor speed
        set_motor_speed(MOTOR_PIN, duty_cycle);

        // Print ADC values and PWM duty cycle
        printf("ADC0: %d, ADC1: %d, PWM: %d\n", adc_value0, adc_value1, duty_cycle);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Stop PWM output
    gpioPWM(MOTOR_PIN, 0);

    // Close SPI interfaces
    spiClose(spi_handle0);
    spiClose(spi_handle1);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

