#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define AIN0_CONFIG 0x4003 // Single-ended AIN0, 4.096V PGA, 128 SPS
#define GAUSS_PER_VOLT 0.0001 // Example value, adjust based on sensor datasheet
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int16_t read_ads1115();
double convert_to_gauss(int16_t raw_value);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int ain0_config;
    double gauss_per_volt;
    int led_gpio;
    double default_threshold;
} app_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int16_t read_ads1115() {
    char config[3];
    char data[2];
    int16_t raw_value;

    // Construct configuration register write
    config[0] = 0x01; // Configuration register address
    config[1] = (AIN0_CONFIG >> 8) & 0xFF; // MSB
    config[2] = AIN0_CONFIG & 0xFF; // LSB

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (adjust as needed)
    gpioDelay(10); // 10 ms delay

    // Read conversion register
    config[0] = 0x00; // Conversion register address
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for read\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Convert raw value to Gauss
double convert_to_gauss(int16_t raw_value) {
    return (double)raw_value * GAUSS_PER_VOLT;
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t raw_value = read_ads1115();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        double magnetic_field = convert_to_gauss(raw_value);
        printf("Magnetic Field: %.4f Gauss\n", magnetic_field);

        if (magnetic_field > threshold) {
            printf("Threshold exceeded! Blinking LED...\n");
            for (int i = 0; i < 5; i++) {
                control_led(1);
                gpioDelay(50);
                control_led(0);
                gpioDelay(50);
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

