    char *payload = message->payload;
    syslog(LOG_INFO, "Message arrived: Topic = %s, Payload = %s", topicName, payload);

    if (strcmp(topicName, mqtt_topic_pump) == 0) {
        if (strcmp(payload, MQTT_PUMP_ON) == 0) {
            if (control_pump(1) == 0) {
                syslog(LOG_INFO, "Pump turned ON");
                char payload_response[50];
                snprintf(payload_response, sizeof(payload_response), "{\"%s\": \"%s\", \"%s\": \"%s\"}", MQTT_PUMP_COMMAND, MQTT_PUMP_ON, MQTT_PUMP_RESPONSE, MQTT_PUMP_OK);
