                mqtt_publish(mqtt_topic_status, payload_response);
            }
        } else if (strcmp(payload, MQTT_PUMP_OFF) == 0) {
            if (control_pump(0) == 0) {
                syslog(LOG_INFO, "Pump turned OFF");
                char payload_response[50];
                snprintf(payload_response, sizeof(payload_response), "{\"%s\": \"%s\", \"%s\": \"%s\"}", MQTT_PUMP_COMMAND, MQTT_PUMP_OFF, MQTT_PUMP_RESPONSE, MQTT_PUMP_OK);
