                syslog(LOG_ERR, "Failed to turn pump OFF");
                char payload_response[50];
                snprintf(payload_response, sizeof(payload_response), "{\"%s\": \"%s\", \"%s\": \"%s\"}", MQTT_PUMP_COMMAND, MQTT_PUMP_OFF, MQTT_PUMP_RESPONSE, MQTT_PUMP_ERROR);
                mqtt_publish(mqtt_topic_status, payload_response);
            }
        } else {
            syslog(LOG_WARNING, "Unknown pump command: %s", payload);
            char payload_response[50];
            snprintf(payload_response, sizeof(payload_response), "{\"%s\": \"%s\", \"%s\": \"%s\"}", MQTT_PUMP_COMMAND, payload, MQTT_PUMP_RESPONSE, MQTT_PUMP_ERROR);
            mqtt_publish(mqtt_topic_status, payload_response);
        }
    }

    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

// MQTT connection lost callback
