    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    MQTTClient_create(&mqtt_client, mqtt_broker_address, mqtt_client_id, MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(mqtt_client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker, return code %d", rc);
        return -1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker");
    return 0;
}

// MQTT disconnect function
int mqtt_disconnect(void) {
    MQTTClient_disconnect(mqtt_client, 1000);
