    syslog(LOG_INFO, "Disconnected from MQTT broker");
    return 0;
}

// MQTT publish function
int mqtt_publish(const char *topic, const char *payload) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(mqtt_client, topic, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message, return code %d", rc);
        return -1;
    }

    syslog(LOG_INFO, "Published message to topic %s: %s", topic, payload);
    return 0;
}

// MQTT subscribe function
int mqtt_subscribe(const char *topic) {
    int rc;

    if ((rc = MQTTClient_subscribe(mqtt_client, topic, 1)) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to topic %s, return code %d", topic, rc);
        return -1;
    }

    syslog(LOG_INFO, "Subscribed to topic %s", topic);
    return 0;
}

// MQTT unsubscribe function
int mqtt_unsubscribe(const char *topic) {
