    if ((rc = MQTTClient_unsubscribe(mqtt_client, topic)) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to unsubscribe from topic %s, return code %d", topic, rc);
        return -1;
    }

    syslog(LOG_INFO, "Unsubscribed from topic %s", topic);
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO mode for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (mqtt_connect() != 0) {
        syslog(LOG_ERR, "MQTT connection failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Subscribe to pump control topic
    if (subscribe_pump() != 0) {
        syslog(LOG_ERR, "Failed to subscribe to pump control topic");
        mqtt_disconnect();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        // Read moisture level
        moisture_level = read_mcp3008(MCP3008_CHANNEL);

        if (moisture_level < 0) {
            syslog(LOG_ERR, "Failed to read moisture level");
            sensor_absent = 1;
        } else {
            sensor_absent = 0;
        }

        // Hysteresis control
        if (moisture_level < MOISTURE_THRESHOLD_LOW && pump_state == 0 && sensor_absent == 0) {
            if (control_pump(1) == 0) {
                syslog(LOG_INFO, "Moisture level below threshold. Turning pump ON.");
                char payload[50];
                snprintf(payload, sizeof(payload), "{\"%s\": \"%s\", \"%s\": \"%d\"}", MQTT_PUMP_STATE_CHANGE, MQTT_PUMP_ON, MQTT_PUMP_SENSOR_VALUE, moisture_level);
                mqtt_publish(mqtt_topic_status, payload);
            }
        } else if (moisture_level > MOISTURE_THRESHOLD_HIGH && pump_state == 1 && sensor_absent == 0) {
            if (control_pump(0) == 0) {
                syslog(LOG_INFO, "Moisture level above threshold. Turning pump OFF.");
                char payload[50];
                snprintf(payload, sizeof(payload), "{\"%s\": \"%s\", \"%s\": \"%d\"}", MQTT_PUMP_STATE_CHANGE, MQTT_PUMP_OFF, MQTT_PUMP_SENSOR_VALUE, moisture_level);
                mqtt_publish(mqtt_topic_status, payload);
            }
        }

        // Publish moisture level
        if (publish_moisture(moisture_level) != 0) {
            syslog(LOG_ERR, "Failed to publish moisture level");
        }

        // Sleep for 60 seconds
        sleep(60);

        // Check for pump state change
        if (pump_state != control_pump(pump_state)) {
            syslog(LOG_WARNING, "Pump state changed unexpectedly.");
        }

        // Check for sensor status change
        if (sensor_absent != 0) {
            syslog(LOG_WARNING, "Sensor is absent.");
        }

        // Check for control mode change
        if (control_mode != 0) {
            syslog(LOG_WARNING, "Control mode is manual.");
        }

        // Check for moisture level change
        if (moisture_level != last_moisture_level) {
            syslog(LOG_INFO, "Moisture level changed.");
            last_moisture_level = moisture_level;
        }
    }

    // Cleanup
    mqtt_unsubscribe(mqtt_topic_pump);
    mqtt_disconnect();
    spiClose(spi_handle);
    gpioTerminate();
    closelog();

    return 0;
}

