#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SPI device file descriptor
int spi_fd = -1;

// SPI device path
const char *spi_device_path = "/dev/spidev0.0";

// SPI mode
uint8_t spi_mode = SPI_MODE_0;

// SPI bits per word
uint8_t spi_bits_per_word = 8;

// SPI max speed
uint32_t spi_max_speed = 1000000; // 1 MHz

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to initialize the SPI device
int initialize_spi() {
    int fd;
    uint8_t mode = spi_mode;
    uint8_t bits = spi_bits_per_word;
    uint32_t speed = spi_max_speed;

    fd = open(spi_device_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", spi_device_path, strerror(errno));
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = spi_max_speed;
    transfer[0].bits_per_word = spi_bits_per_word;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to calculate the voltage from the ADC value
float calculate_voltage(int adc_value, float vdd, float vref) {
    return (adc_value / 1023.0) * vref;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the SPI device
    spi_fd = initialize_spi();
    if (spi_fd == -1) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop to read and print ADC values
    while (1) {
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 500ms.\n");
            usleep(500000); // Wait 500ms before retrying
            continue;
        }

        float voltage = calculate_voltage(adc_value, 3.3, 3.3);

        printf("Raw ADC Value: %d, Voltage: %.2f V\n", adc_value, voltage);

        usleep(500000); // Wait 500ms
    }

    return 0;
}

