#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define CSV_FILE "sensor_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int write_to_csv(float voltage0, float voltage1, float voltage2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float voltage0;
    float voltage1;
    float voltage2;
} sensor_data_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to write to CSV file
int write_to_csv(float voltage0, float voltage1, float voltage2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltage0, voltage1, voltage2);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Channel0,Channel1,Channel2\n");
    }
    rewind(fp);

    // Main loop
    while (!terminate) {
        // Read ADC values from channels 0, 1, and 2
        int adc_value0 = read_mcp3008(0);
        int adc_value1 = read_mcp3008(1);
        int adc_value2 = read_mcp3008(2);

        if (adc_value0 == -1 || adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to voltages
        float voltage0 = convert_to_voltage(adc_value0);
        float voltage1 = convert_to_voltage(adc_value1);
        float voltage2 = convert_to_voltage(adc_value2);

        // Write data to CSV file
        if (write_to_csv(voltage0, voltage1, voltage2) != 0) {
            fprintf(stderr, "Error writing to CSV file\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function (milliseconds)
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    // Close CSV file
    fclose(fp);

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

