#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 30.0
#define PUMP_GPIO 17
#define NUM_SENSORS 4
#define SENSOR_CHANNELS {0, 1, 2, 3}

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_data(int sensor_id, float moisture_percentage);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Retry mechanism
    int retries = 3;
    int adc_value = -1;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (channel %d), retrying...\n", channel);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after multiple retries (channel %d)\n", channel);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    printf("Pump set to %s\n", state ? "ON" : "OFF");
}

// Function to log data with timestamp
void log_data(int sensor_id, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor %d: Moisture = %.2f%%\n", timestamp, sensor_id, moisture_percentage);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_channels[] = SENSOR_CHANNELS;

    // Main loop
    while (!terminate) {
        int pump_state = 0; // Assume pump is off initially

        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(sensor_channels[i]);
            if (adc_value >= 0) {
                float moisture_percentage = calculate_moisture_percentage(adc_value);
                log_data(i, moisture_percentage);

                if (moisture_percentage < MOISTURE_THRESHOLD) {
                    pump_state = 1; // Turn pump on if any sensor is below threshold
                }
            } else {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
            }
        }

        control_pump(pump_state);
        sleep(60); // Wait 60 seconds
    }

    // Cleanup before exiting
    control_pump(0); // Turn pump off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

