    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate distance from ADC value (linear approximation)
float calculate_distance(int adc_value) {
    // This is a simplified linear approximation.
    // A more accurate model would be needed for real-world use.
    // The GP2Y0A21YK0F has a non-linear relationship between voltage and distance.
    // You'll need to calibrate the sensor and create a more accurate model.
    // Example linear approximation (adjust based on your sensor's characteristics):
    // Assuming 0V = 20cm, 3.3V = 5cm
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float distance = 20.0 - (voltage / 3.3) * 15.0; // Inverted and scaled

    return distance;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

