        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Monitoring distance sensors... Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(sensor_channels[i]);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
                continue; // Skip to the next sensor
            }

            float distance = calculate_distance(adc_value);

            if (distance < DISTANCE_THRESHOLD) {
                printf("Distance below threshold on sensor %d (%.2f cm)\n", i, distance);
                control_relay(1); // Activate relay
                log_event(i, distance);
                gpioDelay(DEBOUNCE_DELAY * 1000000); // Debounce delay (microseconds)
                control_relay(0); // Deactivate relay
            }
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

