// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL 5 // seconds
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE 10 // milliseconds
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for SPI configuration
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;

// Function to initialize the SPI interface
int initialize_spi(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.speed, config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI command (start bit, single-ended, channel select)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_config_t spi_config = {SPI_CHANNEL, SPI_SPEED, SPI_MODE};
    if (initialize_spi(spi_config) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        for (int i = 0; i < MAX_RETRIES; ++i) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            } else {
                fprintf(stderr, "SPI read failed. Retry %d/%d\n", i + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_BASE * (1 << i)); // Exponential backoff
            }
        }

        if (adc_value >= 0) {
            float moisture_percentage = convert_to_percentage(adc_value);
            if (moisture_percentage >= 0.0) {
                log_data(moisture_percentage);
            } else {
                fprintf(stderr, "Failed to convert ADC value to percentage.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ADC value after multiple retries.\n");
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, ERROR: SPI read failed after multiple retries\n", timestamp);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

