#define CONFIG_FILE "theremin_config.txt"

// Sensor pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// MCP3008 SPI channel
#define SPI_CHANNEL 0

// PWM pin
#define PWM_PIN 18

// Default calibration values
#define DEFAULT_DISTANCE_MIN 10.0
#define DEFAULT_DISTANCE_MAX 100.0
#define DEFAULT_VOLUME_MIN 0
#define DEFAULT_VOLUME_MAX 100

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Calibration parameters
float distance_min = DEFAULT_DISTANCE_MIN;
float distance_max = DEFAULT_DISTANCE_MAX;
int volume_min = DEFAULT_VOLUME_MIN;
int volume_max = DEFAULT_VOLUME_MAX;

// Function prototypes
void signal_handler(int signal);
int initialize();
void cleanup();
int read_mcp3008(int channel);
float measure_distance();
int read_ldr();
void generate_tone(float distance, int volume);
void log_data(float distance, int volume);
void load_calibration();
void save_calibration();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    spi_handle = spiOpen(SPI_CHANNEL, 100000, 0); // SPI channel 0, 100kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, 44100); // Set PWM frequency to 44.1kHz
    gpioSetPWMrange(PWM_PIN, 1000); // Set PWM range to 1000

    log_file = fopen("theremin_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
