    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = gpioTick();
    uint32_t end_tick = start_tick;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0) {
        end_tick = gpioTick();
        if (end_tick - start_tick > 50000) { // Timeout after 50ms
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0;
        }
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > 50000) { // Timeout after 50ms
