    float frequency = distance_min + (distance / (distance_max - distance_min)) * (2000.0 - 20.0);

    // Map volume to duty cycle (0-1000)
    int duty_cycle = volume_min + (volume / (volume_max - volume_min)) * (1000 - 0);

