    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    while (retries < SPI_REINIT_ATTEMPTS) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
