    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            // SPI read failed, but handled in read_mcp3008
            gpioDelay(5000); // Wait 5 seconds before next attempt
            continue;
