    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            log_data(-1, -1); // Log error
        } else {
            // Control pump
            int pump_state = (moisture_level < config.moisture_threshold) ? 1 : 0;
            control_pump(pump_state);

            // Log data
            log_data(moisture_level, pump_state);

            printf("Moisture: %d, Pump: %s\n", moisture_level, pump_state ? "ON" : "OFF");
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    printf("Irrigation system stopped.\n");
    return 0;
}

