#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

// Define motor directions
#define FORWARD 1
#define BACKWARD 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_speed(int adc_value);
void set_motor_speed(int motor_num, int speed);
void set_motor_direction(int motor_num, int direction);
void accelerate(int motor_num, int speed);
void decelerate(int motor_num, int speed);
void reverse_direction(int motor_num);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map ADC value to speed
int map_speed(int adc_value) {
    // Map ADC value (0-1023) to speed (0-1000)
    return (int)(((float)adc_value / 1023.0) * 1000.0);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_num, int speed) {
    int gpio_pin;

    if (motor_num == 1) {
        gpio_pin = MOTOR1_ENABLE;
    } else if (motor_num == 2) {
        gpio_pin = MOTOR2_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
        return;
    }

    gpioPWM(gpio_pin, speed);
}

// Function to set motor direction
void set_motor_direction(int motor_num, int direction) {
    int gpio_pin;

    if (motor_num == 1) {
        gpio_pin = MOTOR1_DIRECTION;
    } else if (motor_num == 2) {
        gpio_pin = MOTOR2_DIRECTION;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
        return;
    }

    gpioWrite(gpio_pin, direction);
}

// Function to accelerate motor
void accelerate(int motor_num, int speed) {
    int current_speed = 0;
    while (current_speed < speed) {
        current_speed += 50; // Increment by 50 each time
        if (current_speed > speed) {
            current_speed = speed;
        }
        set_motor_speed(motor_num, current_speed);
        gpioDelay(10000); // 10 ms delay
    }
}

// Function to decelerate motor
void decelerate(int motor_num, int speed) {
    int current_speed = speed;
    while (current_speed > 0) {
        current_speed -= 50; // Decrement by 50 each time
        if (current_speed < 0) {
            current_speed = 0;
        }
        set_motor_speed(motor_num, current_speed);
        gpioDelay(10000); // 10 ms delay
    }
}

// Function to reverse motor direction
void reverse_direction(int motor_num) {
    int current_direction = gpioRead(MOTOR1_DIRECTION);
    gpioWrite(MOTOR1_DIRECTION, !current_direction);
    gpioDelay(500000); // 0.5 second delay
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from potentiometers
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC values. Exiting.\n");
            break;
        }

        // Map ADC values to motor speeds
        int speed1 = map_speed(pot1_value);
        int speed2 = map_speed(pot2_value);

        // Set motor directions
        set_motor_direction(1, FORWARD);
        set_motor_direction(2, BACKWARD);

        // Accelerate motors
        accelerate(1, speed1);
        accelerate(2, speed2);

        // Hold constant speed
        gpioDelay(2000000); // 2 seconds

        // Decelerate motors
        decelerate(1, speed1);
        decelerate(2, speed2);

        // Reverse motor direction
        reverse_direction(1);

        // Pause
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

