// Define GPIO pins
#define SPI_CE 8
#define LED_PIN 17

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 10

// Global variables
int spi_handle;
volatile int running = 1;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int calibrate_noise_level(int duration_seconds);
int detect_sound_level(int sample, int baseline, int threshold);
void control_led(int state);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int led_pin;
    int spi_ce_pin;
    int spi_channel;
    int spi_speed;
    int debounce_time;
} Config;

Config config = {
    .led_pin = LED_PIN,
    .spi_ce_pin = SPI_CE,
    .spi_channel = SPI_CHANNEL,
    .spi_speed = SPI_SPEED,
    .debounce_time = DEBOUNCE_TIME
};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int baseline = calibrate_noise_level(5);
    printf("Calibrated noise baseline: %d\n", baseline);

    // Main loop
    while (running) {
        // Read sound level from MCP3008 channel 0
        int sound_level = read_mcp3008(0);

        // Detect sound level and control LED
        detect_sound_level(sound_level, baseline, 50); // Threshold = 50

        // Delay to avoid excessive CPU usage
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.led_pin, PI_OUTPUT);
    gpioSetMode(config.spi_ce_pin, PI_OUTPUT);

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        return 1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    gpioWrite(config.spi_ce_pin, 0); // Select the MCP3008
    spiXfer(spi_handle, spi_data, rx_buffer, 3);
    gpioWrite(config.spi_ce_pin, 1); // Deselect the MCP3008

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calibrate noise level
int calibrate_noise_level(int duration_seconds) {
    int sum = 0;
    int num_samples = 0;
    time_t start_time = time(NULL);

    while (time(NULL) - start_time < duration_seconds) {
        int sample = read_mcp3008(0);
        if (sample >= 0) {
            sum += sample;
            num_samples++;
        } else {
            fprintf(stderr, "Error reading ADC during calibration.\n");
        }
        gpioDelay(10000); // 10 ms delay
    }

    if (num_samples > 0) {
        return sum / num_samples;
    } else {
        return 0; // Return 0 if no samples were taken
    }
}

// Detect sound level and control LED
int detect_sound_level(int sample, int baseline, int threshold) {
    static int led_state = 0; // 0 = off, 1 = on
    static uint32_t last_toggle_time = 0;

    if (sample > baseline + threshold) {
        uint32_t current_time = gpioTick();
        if (current_time - last_toggle_time > config.debounce_time * 1000) {
            led_state = !led_state; // Toggle LED state
            control_led(led_state);
            last_toggle_time = current_time;
        }
    }
    return 0;
}

// Control LED
void control_led(int state) {
    gpioWrite(config.led_pin, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    running = 0;
}

