// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

// Calibration data (example, replace with actual values)
#define VOLTAGE_AT_0_CFM 0.5
#define VOLTAGE_AT_20_CFM 4.5

// Global variables
