    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO Set Value
int gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    char buf[2];
    int len = snprintf(buf, sizeof(buf), "%d", value);
    if (write(fd, buf, len) != len) {
        perror("Error writing to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Get Timestamp
int get_timestamp(char *timestamp_str, size_t size) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
        perror("Error getting timestamp");
        return -1;
    }

    long ns = ts.tv_nsec;
    snprintf(timestamp_str, size, "%ld", ns);
    return 0;
}

// Log Data
int log_data(const char *timestamp, int adc_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s|%d\n", timestamp, adc_value);
    fflush(log_file);
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

