    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_export(GPIO_CS) < 0 ||
        gpio_set_direction(GPIO_CS, "out") < 0 ||
        gpio_set_value(GPIO_CS, 1) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpio_unexport(GPIO_CS);
        close(spi_fd);
        return 1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    char timestamp_str[32];

    // Main loop
    while (!terminate) {
        // Toggle CS low
        if (gpio_set_value(GPIO_CS, 0) < 0) {
            fprintf(stderr, "Error setting CS low. Continuing.\n");
        }

        // SPI transfer
        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = 0x80; // Single-ended channel 0
        tx_buf[2] = 0x00; // Dummy byte

        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed. Continuing.\n");
        }

        // Toggle CS high
        if (gpio_set_value(GPIO_CS, 1) < 0) {
            fprintf(stderr, "Error setting CS high. Continuing.\n");
        }

        // Get timestamp
        if (get_timestamp(timestamp_str, sizeof(timestamp_str)) < 0) {
            fprintf(stderr, "Error getting timestamp. Continuing.\n");
        }

        // Log data
        int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
        if (log_data(timestamp_str, adc_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        // Sleep
        struct timespec req = {0};
        req.tv_sec = 0;
        req.tv_nsec = SLEEP_NS;
        nanosleep(&req, NULL);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_unexport(GPIO_CS) < 0) {
        fprintf(stderr, "Error unexporting GPIO. Continuing.\n");
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

