float convert_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float acceleration = (voltage - (3.3 / 2.0)) / SENSITIVITY;
    return acceleration;
}

// Kalman filter implementation
void kalman_filter(float *x, float *x_estimate, float *x_error_covariance, float measurement) {
    // Prediction step
    float predicted_state = *x_estimate;
    float predicted_error_covariance = *x_error_covariance + PROCESS_NOISE;

    // Update step
    float kalman_gain = predicted_error_covariance / (predicted_error_covariance + MEASUREMENT_NOISE);
    *x_estimate = predicted_state + kalman_gain * (measurement - predicted_state);
    *x_error_covariance = (1 - kalman_gain) * predicted_error_covariance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ADXL335 Accelerometer Reader\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to g
        float x_g = convert_to_g(x_adc);
        float y_g = convert_to_g(y_adc);
        float z_g = convert_to_g(z_adc);

        // Apply Kalman filter
        kalman_filter(&x_g, &x_estimate, &x_error_covariance, x_g);
        kalman_filter(&y_g, &y_estimate, &y_error_covariance, y_g);
        kalman_filter(&z_g, &z_estimate, &z_error_covariance, z_g);

        // Print smoothed values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_estimate, y_estimate, z_estimate);

        // Delay
        gpioDelay(100); // 10 Hz
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

