#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL 100

// Define the voltage range for the DRV5055VA sensors
#define MIN_VOLTAGE 0.0
#define MAX_VOLTAGE 3.3

// Define the magnetic field range for the DRV5055VA sensors
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the digital state of a sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to convert the digital state to a voltage
float voltage_from_state(int state) {
    return (float)state * MAX_VOLTAGE;
}

// Function to convert the voltage to a magnetic field strength in mT
float magnetic_field_from_voltage(float voltage) {
    return (voltage / MAX_VOLTAGE) * (MAX_MAGNETIC_FIELD - MIN_MAGNETIC_FIELD) + MIN_MAGNETIC_FIELD;
}

// Function to log the magnetic field strengths to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Flush the buffer to ensure data is written to the file
    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);
        int sensor3_state = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1) {
            fprintf(stderr, "Error reading sensors, skipping logging.\n");
            gpioDelay(SAMPLING_INTERVAL * 1000); // Delay for the sampling interval
            continue; // Skip to the next iteration
        }

        // Convert the sensor states to voltages
        float sensor1_voltage = voltage_from_state(sensor1_state);
        float sensor2_voltage = voltage_from_state(sensor2_state);
        float sensor3_voltage = voltage_from_state(sensor3_state);

        // Convert the voltages to magnetic field strengths
        float sensor1_mT = magnetic_field_from_voltage(sensor1_voltage);
        float sensor2_mT = magnetic_field_from_voltage(sensor2_voltage);
        float sensor3_mT = magnetic_field_from_voltage(sensor3_voltage);

        // Check for out-of-range magnetic field values
        if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD ||
            sensor2_mT < MIN_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD ||
            sensor3_mT < MIN_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field value out of range. Sensor1: %.2f mT, Sensor2: %.2f mT, Sensor3: %.2f mT\n", sensor1_mT, sensor2_mT, sensor3_mT);
        }

        // Log the data to the file
        if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Delay for the sampling interval
        gpioDelay(SAMPLING_INTERVAL * 1000);
    }

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

