#define CHANNEL_0 0
#define CHANNEL_1 1
#define CHANNEL_2 2

// Global variables
int spi_fd = -1; // SPI file descriptor
FILE *csv_file = NULL; // CSV file pointer

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
int log_data(int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int signal);

// Structure to hold SPI configuration
struct spi_config {
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed_hz;
};

// Initialize SPI interface
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    struct spi_config config = {
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed_hz = SPI_SPEED
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed_hz) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read analog value from MCP3008 channel
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

