#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17

// Global variables for signal handling
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int connect_mqtt(struct mosquitto **mosq);
int subscribe_mqtt(struct mosquitto *mosq);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, bool *led_state);
int set_gpio_output(int gpio, int value);
void signal_handler(int signum);

// Function to connect to MQTT broker with exponential backoff
int connect_mqtt(struct mosquitto **mosq) {
    int rc = 0;
    int reconnect_delay = 1; // Initial delay in seconds

    while (running) {
        rc = mosquitto_connect(*mosq, MQTT_HOST, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Connected to MQTT broker.\n");
            return MOSQ_ERR_SUCCESS;
        } else {
            fprintf(stderr, "%s: Error connecting to MQTT broker: %s\n", __func__, mosquitto_strerror(rc));
            // Log the error to stderr with timestamp
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            fprintf(stderr, "%s: %s: Error connecting to MQTT broker: %s\n", buf, __func__, mosquitto_strerror(rc));

            sleep(reconnect_delay);
            reconnect_delay *= 2; // Exponential backoff
            if (reconnect_delay > 60) {
                reconnect_delay = 60; // Maximum delay
            }
        }
    }

    return MOSQ_ERR_SUCCESS; // Return success to exit the loop
}

// Function to subscribe to an MQTT topic
int subscribe_mqtt(struct mosquitto *mosq) {
    int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "%s: Error subscribing to topic: %s\n", __func__, mosquitto_strerror(rc));
        return rc;
    }
    printf("Subscribed to topic: %s\n", MQTT_TOPIC);
    return MOSQ_ERR_SUCCESS;
}

// Callback function for handling incoming MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        bool led_state;
        if (parse_json_payload(message->payload, &led_state) == 0) {
            if (set_gpio_output(GPIO_PIN, led_state ? 1 : 0) != 0) {
                fprintf(stderr, "%s: Error setting GPIO output.\n", __func__);
            }
        } else {
            fprintf(stderr, "%s: Error parsing JSON payload.\n", __func__);
        }
    } else {
        fprintf(stderr, "%s: Empty message received.\n", __func__);
    }
}

// Function to parse JSON payload and extract LED state
int parse_json_payload(const char *payload, bool *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        fprintf(stderr, "%s: JSON parse error: %s\n", __func__, error.text);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        fprintf(stderr, "%s: Missing 'led_state' key in JSON.\n", __func__);
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        fprintf(stderr, "%s: 'led_state' is not a boolean.\n", __func__);
        json_decref(root);
        return -1;
    }

    *led_state = json_is_true(led_state_json);
    json_decref(root);
    return 0;
}

// Function to set GPIO output using pigpio
int set_gpio_output(int gpio, int value) {
    if (gpioWrite(gpio, value) != 0) {
        fprintf(stderr, "%s: Error writing to GPIO %d.\n", __func__, gpio);
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize MQTT library
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Set callback functions
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to MQTT broker with exponential backoff
    if (connect_mqtt(&mosq) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker after multiple retries.\n");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Subscribe to the MQTT topic
    if (subscribe_mqtt(mosq) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to MQTT topic.\n");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start the MQTT client loop
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1); // -1 means loop forever, 1 means max 1 message processed per loop
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "%s: Error in mosquitto_loop: %s\n", __func__, mosquitto_strerror(rc));
            // Log the error to stderr with timestamp
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            fprintf(stderr, "%s: %s: Error in mosquitto_loop: %s\n", buf, __func__, mosquitto_strerror(rc));

            mosquitto_reconnect(mosq);
        }
    }

    // Clean up and disconnect from MQTT broker
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    // Turn off the LED
    set_gpio_output(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

