        fprintf(stderr, "%s: Error writing to GPIO %d.\n", __func__, gpio);
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize MQTT library
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Set callback functions
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to MQTT broker with exponential backoff
    if (connect_mqtt(&mosq) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker after multiple retries.\n");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Subscribe to the MQTT topic
    if (subscribe_mqtt(mosq) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to MQTT topic.\n");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start the MQTT client loop
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1); // -1 means loop forever, 1 means max 1 message processed per loop
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "%s: Error in mosquitto_loop: %s\n", __func__, mosquitto_strerror(rc));
            // Log the error to stderr with timestamp
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            fprintf(stderr, "%s: %s: Error in mosquitto_loop: %s\n", buf, __func__, mosquitto_strerror(rc));

            mosquitto_reconnect(mosq);
        }
    }

    // Clean up and disconnect from MQTT broker
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    // Turn off the LED
    set_gpio_output(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

