#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

// Define GPIO pin and log file path
#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_edge(int pin, const char *edge);
int gpio_get_value(int pin);
int log_message(const char *message);
void signal_handler(int signal);

// Helper function to construct the GPIO path
char* get_gpio_path(int pin, char* path_buffer, size_t buffer_size) {
    snprintf(path_buffer, buffer_size, "/sys/class/gpio/gpio%d", pin);
    return path_buffer;
}

// Exports the specified GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to /sys/class/gpio/export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to /sys/class/gpio/unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Sets the direction of the specified GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    get_gpio_path(pin, path, sizeof(path));
    strcat(path, "/direction");

    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        perror("Failed to write to GPIO direction file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Sets the edge trigger for the specified GPIO pin (rising, falling, both, none)
int gpio_set_edge(int pin, const char *edge) {
    char path[64];
    int fd;

    get_gpio_path(pin, path, sizeof(path));
    strcat(path, "/edge");

    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO edge file");
        return -1;
    }
    if (write(fd, edge, strlen(edge)) < 0) {
        perror("Failed to write to GPIO edge file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Reads the value of the specified GPIO pin (0 or 1)
int gpio_get_value(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    get_gpio_path(pin, path, sizeof(path));
    strcat(path, "/value");

    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file");
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        perror("Failed to read GPIO value file");
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Appends a timestamped message to the log file
int log_message(const char *message) {
    FILE *fp;
    time_t t;
    struct tm *tm_info;
    char timestamp[20];

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time(&t);
    tm_info = localtime(&t);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler to catch SIGINT and SIGTERM signals
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO pin %d\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO direction for pin %d\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Set GPIO edge to falling
    if (gpio_set_edge(GPIO_PIN, "falling") < 0) {
        fprintf(stderr, "Failed to set GPIO edge for pin %d\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read GPIO value
        int value = gpio_get_value(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO value for pin %d\n", GPIO_PIN);
            break; // Exit loop on error
        }

        // Check for falling edge (low to high transition)
        if (value == 0) {
            // Get current time
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

            // Create log message
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Vibration detected at %s", timestamp);

            // Log the message
            if (log_message(log_message_buffer) < 0) {
                fprintf(stderr, "Failed to log message\n");
            }

            // Print to stdout
            printf("%s\n", log_message_buffer);

            // Shutdown the system
            system("sudo shutdown -h now");
            break; // Exit loop after shutdown command
        }

        // Small delay to avoid busy-waiting
        usleep(100000); // 100ms
    }

    // Unexport GPIO pin
    if (gpio_unexport(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to unexport GPIO pin %d\n", GPIO_PIN);
    }

    printf("Vibration monitoring stopped.\n");

    return 0;
}

