    size_t elements_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to log file: wrote %zu elements, expected %d\n", elements_written, BUFFER_SIZE);
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI device
    if (open_spi_device() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Store temperature
        store_temperature(temperature);

        // Print temperature
        print_temperature(temperature);

        // Log temperature to file
        log_temperature_to_file();

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

