#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus);
int init_spi(const char *device);
int read_bh1750(int fd);
int read_mcp3008(int fd, int channel);
void log_data(FILE *fp, int light_level, int sound_level);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// I2C initialization function
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int init_spi(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    unsigned int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 reading function
int read_bh1750(int fd) {
    unsigned char buf[2];
    int lux;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-resolution mode
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read two bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert data to lux
    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// MCP3008 reading function
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Logging function
void log_data(FILE *fp, int light_level, int sound_level) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Light: %d, Sound: %d\n", timestamp, light_level, sound_level);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int light_level = read_bh1750(i2c_fd);
        int sound_level = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        if (light_level >= 0 && sound_level >= 0) {
            log_data(log_file, light_level, sound_level);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log entry.\n");
        }

        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    close(spi_fd);
    fclose(log_file);

    return 0;
}

