#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

static volatile int keepRunning = 1;

// Signal handler for graceful shutdown
void signalHandler(int signum) {
    keepRunning = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to read the flame sensor
int readFlameSensor(int gpioPin) {
    return gpioRead(gpioPin);
}

// Function to log the event to a CSV file
void logEvent(const char *filename, int gpioPin, int state) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", filename);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, gpioPin, state);
    fclose(fp);
}

// Function to print an alarm message to stdout
void printAlarmMessage(int gpioPin, int state) {
    if (state == 1) {
        printf("ALARM: Flame detected on GPIO %d!\n", gpioPin);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_DOWN);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        int sensorValue = readFlameSensor(FLAME_SENSOR_GPIO);
        logEvent(LOG_FILE, FLAME_SENSOR_GPIO, sensorValue);
        printAlarmMessage(FLAME_SENSOR_GPIO, sensorValue);
        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");
    return 0;
}

