#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP4725_ADDR 0x60
#define LOG_FILE "temperature_log.txt"
#define SLEEP_DURATION_SEC 0.5
#define MAX_RETRIES 3

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int mcp3008_read(int spi_fd, int channel);
float tmp36_to_celsius(int adc_value);
int i2c_init(const char *device);
int i2c_write(int fd, uint8_t reg, uint16_t value);
int dac_set_voltage(int i2c_fd, float voltage);
int log_data(FILE *fp, int adc_value, float temperature, float voltage);
void signal_handler(int sig);

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = 500000; // 500 kHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 500000, // 500 kHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MCP3008 Read
int mcp3008_read(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int adc_value = -1;
    int retries = 0;

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00;

    while (retries < MAX_RETRIES) {
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == 0) {
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries.\n", MAX_RETRIES);
    return -1;
}

// TMP36 to Celsius
float tmp36_to_celsius(int adc_value) {
    float voltage = (adc_value * 3.3) / 1024.0;
    float temperature = (voltage - 0.5) / 0.01;
    return temperature;
}

// I2C Initialization
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C Write
int i2c_write(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 4) & 0xFF; // Upper 8 bits
    buf[2] = (value << 4) & 0xF0; // Lower 4 bits

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// DAC Set Voltage
int dac_set_voltage(int i2c_fd, float voltage) {
    uint16_t dac_value = (uint16_t)((voltage / 3.3) * 4095.0);
    return i2c_write(i2c_fd, 0x40, dac_value); // Write to DAC register
}

// Log Data
int log_data(FILE *fp, int adc_value, float temperature, float voltage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = mcp3008_read(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping.\n");
            sleep(1);
            continue;
        }

        // Convert to Celsius
        float temperature = tmp36_to_celsius(adc_value);

        // Set DAC voltage
        if (dac_set_voltage(i2c_fd, temperature * 3.3) < 0) {
            fprintf(stderr, "Failed to set DAC voltage. Skipping.\n");
        }

        // Log data
        if (log_data(log_file, adc_value, temperature, temperature * 3.3) < 0) {
            fprintf(stderr, "Failed to log data. Skipping.\n");
        }

        // Print to stdout
        printf("ADC: %d, Temperature: %.2f °C, DAC Voltage: %.2f V\n", adc_value, temperature, temperature * 3.3);

        // Sleep
        sleep(SLEEP_DURATION_SEC);
    }

    // Cleanup
    close(spi_fd);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

