// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to sequence through the relays
    while (program_running) {
        activate_relay(RELAY1_PIN);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(RELAY1_PIN);

        activate_relay(RELAY2_PIN);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(RELAY2_PIN);

        activate_relay(RELAY3_PIN);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(RELAY3_PIN);

        activate_relay(RELAY4_PIN);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(RELAY4_PIN);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially deactivated
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    return 0;
}

// Function to activate a relay by setting the GPIO pin HIGH
void activate_relay(int pin) {
    gpioWrite(pin, 1); // Set pin HIGH to activate relay
}

// Function to deactivate a relay by setting the GPIO pin LOW
void deactivate_relay(int pin) {
    gpioWrite(pin, 0); // Set pin LOW to deactivate relay
}

// Function to cleanup GPIO resources and terminate the pigpio library
void cleanup_gpio() {
    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Terminate the pigpio library
    gpioTerminate();
}

// Signal handler function to catch SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0; // Set flag to exit main loop
}

