#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define THRESHOLD 500
#define LED_GPIO 16
#define DEBOUNCE_DELAY 1000 // 1 second
#define SAMPLE_INTERVAL 10 // 10 ms

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
int check_threshold(int adc_value, int threshold);
void control_led(int gpio, int state, int duration_ms);
void log_event(const char *timestamp);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to check if ADC value exceeds threshold
int check_threshold(int adc_value, int threshold) {
    return (adc_value > threshold) ? 1 : 0;
}

// Function to control LED
void control_led(int gpio, int state, int duration_ms) {
    gpioWrite(gpio, state);
    gpioDelay(duration_ms);
    gpioWrite(gpio, 0); // Turn off LED after duration
}

// Function to log event to file
void log_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure data is written to disk
}

