void control_motor(int direction, int duration) {
    if (direction == 1) { // Forward
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 150); // Set PWM duty cycle
    } else if (direction == 0) { // Reverse
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, 150); // Set PWM duty cycle
    } else { // Stop
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 0); // Set PWM duty cycle to 0
