void cleanup() {
    // Stop the motor
    control_motor(0, 0); // Stop the motor

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int rain_level = read_rain_sensor();
        if (rain_level < 0) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        log_data(rain_level);

        if (rain_level > config.rain_threshold) {
            printf("Rain detected, closing window\n");
            control_motor(1, config.motor_duration); // Close window
        } else {
            printf("No rain, opening window\n");
            control_motor(0, config.motor_duration); // Open window
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

