#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define ADC_PIN 26
#define LED_PIN 16

// Define clap detection parameters
#define CLAP_THRESHOLD 500
#define DEBOUNCE_DELAY 50 // milliseconds

// Global variables
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void turn_on_led();
void turn_off_led();
void print_timestamped_message();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int last_clap_time;
} ProgramState;

ProgramState state = {0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ADC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    // Set ADC_PIN as output and drive it low
    gpioSetMode(ADC_PIN, PI_OUTPUT);
    gpioWrite(ADC_PIN, 0);
    gpioDelay(2); // Charge capacitor

    // Set ADC_PIN as input
    gpioSetMode(ADC_PIN, PI_INPUT);

    // Read 10 bits
    for (int i = 0; i < 10; i++) {
        gpioDelay(1); // Short delay for sampling
        if (gpioRead(ADC_PIN)) {
            adc_value |= (1 << i);
        }
    }

    return adc_value;
}

// Function to detect clap
int detect_clap(int adc_value) {
    if (adc_value > CLAP_THRESHOLD) {
        return 1; // Clap detected
    }
    return 0; // No clap detected
}

// Function to turn on LED
void turn_on_led() {
    gpioWrite(LED_PIN, 1);
}

// Function to turn off LED
void turn_off_led() {
    gpioWrite(LED_PIN, 0);
}

// Function to print timestamped message
void print_timestamped_message() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s: Clap detected!\n", timestamp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    turn_off_led();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    printf("Clap detection program started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc();
        int clap_detected = detect_clap(adc_value);

        if (clap_detected) {
            // Debounce check
            if (gpioTime(PI_TIME_RELATIVE, NULL, NULL) - state.last_clap_time > DEBOUNCE_DELAY * 1000) {
                turn_on_led();
                print_timestamped_message();
                gpioDelay(500); // LED on for 500ms
                turn_off_led();
                state.last_clap_time = gpioTime(PI_TIME_RELATIVE, NULL, NULL);
            }
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

