#include <pigpio.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200 // mm
#define LOG_FILE "distance_log.txt"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to read the distance sensor
int read_distance() {
    return gpioRead(GPIO_PIN);
}

// Function to log the distance to a file
void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d\n", timestamp, distance);
    fclose(fp);
}

// Function to determine feeder status
void determine_feeder_status(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Distance sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance();
        log_distance(distance);
        determine_feeder_status(distance);

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    gpioTerminate();

    return 0;
}

