#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_moisture.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void control_pump(int state);
void log_data(float moisture_percentage, int pump_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int pump_gpio;
    float moisture_threshold;
    char log_file[64];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    PUMP_GPIO,
    MOISTURE_THRESHOLD,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 60 seconds.\n");
            log_data(-1.0, -1); // Log error
            gpioDelay(60000000); // Wait 60 seconds
            continue;
        }

        float moisture_percentage = convert_to_percentage(adc_value);

        if (moisture_percentage < config.moisture_threshold) {
            control_pump(1); // Turn pump ON
        } else {
            control_pump(0); // Turn pump OFF
        }

        log_data(moisture_percentage, gpioRead(config.pump_gpio));

        gpioDelay(60000000); // Wait 60 seconds
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(config.pump_gpio, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

float convert_to_percentage(int adc_value) {
    // Assuming ADC range is 0-1023
    return ((float)adc_value / 1023.0) * 100.0;
}

void control_pump(int state) {
    gpioWrite(config.pump_gpio, state);
}

void log_data(float moisture_percentage, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (moisture_percentage >= 0) {
        fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n", timestamp, moisture_percentage, pump_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(log_file, "%s, ERROR: Invalid moisture reading, Pump: %s\n", timestamp, pump_state ? "ON" : "OFF");
        fflush(log_file);
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    control_pump(0); // Turn pump OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

