#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_POWER_ENABLE 17
#define VREF 3.3 // Reference voltage for MCP3008
#define SENSOR_SENSITIVITY 0.1 // 100mV/A
#define SENSOR_OFFSET 0.5 // 500mV offset
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int log_init(void);
void cleanup(int signal);
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
int log_data(float current);

// Structure for configuration (optional)
typedef struct {
    char spi_device[20];
    int spi_mode;
    int spi_bits_per_word;
    int spi_speed;
    int gpio_power_enable;
    float vref;
    float sensor_sensitivity;
    float sensor_offset;
    char log_file[20];
} config_t;

config_t config = {
    .spi_device = SPI_DEVICE,
    .spi_mode = SPI_MODE,
    .spi_bits_per_word = SPI_BITS_PER_WORD,
    .spi_speed = SPI_SPEED,
    .gpio_power_enable = GPIO_POWER_ENABLE,
    .vref = VREF,
    .sensor_sensitivity = SENSOR_SENSITIVITY,
    .sensor_offset = SENSOR_OFFSET,
    .log_file = LOG_FILE
};

// SPI initialization function
int spi_init(void) {
    spi_fd = open(config.spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = config.spi_mode;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = config.spi_bits_per_word;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = config.spi_speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config.gpio_power_enable, PI_OUTPUT);
    gpioWrite(config.gpio_power_enable, 1); // Enable sensor power

    return 0;
}

// Log file initialization function
int log_init(void) {
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,current_A\n");
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = config.spi_speed;
    transfer[0].bits_per_word = config.spi_bits_per_word;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to current
float adc_to_current(int adc_value) {
    float voltage = (adc_value / 1023.0) * config.vref;
    float current = (voltage - config.sensor_offset) / config.sensor_sensitivity;
    return current;
}

// Function to log data to CSV file
int log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    terminate = 1;

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(config.gpio_power_enable, 0); // Disable sensor power
    gpioTerminate();

    exit(0);
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize hardware
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    if (log_init() != 0) {
        fprintf(stderr, "Log file initialization failed. Exiting.\n");
        gpioWrite(config.gpio_power_enable, 0);
        gpioTerminate();
        close(spi_fd);
        return 1;
    }

    printf("Current sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_data(current) != 0) {
            fprintf(stderr, "Error logging data. Retrying in 1 second.\n");
        }

        sleep(1);
    }

    return 0;
}

