#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 2

// Number of readings for debouncing
#define NUM_READINGS 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read sensor with debouncing
int read_sensor(int gpio_pin) {
    int readings[NUM_READINGS];
    int i;

    for (i = 0; i < NUM_READINGS; i++) {
        readings[i] = gpioRead(gpio_pin);
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }

    // Determine the majority value
    int count_low = 0;
    int count_high = 0;
    for (i = 0; i < NUM_READINGS; i++) {
        if (readings[i] == 0) {
            count_low++;
        } else {
            count_high++;
        }
    }

    return (count_low > count_high) ? 0 : 1; // Return the majority value
}

// Function to log sensor state
void log_sensor_state(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_state, sensor2_state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensors
        int sensor1_state = read_sensor(SENSOR_1_PIN);
        int sensor2_state = read_sensor(SENSOR_2_PIN);

        // Log sensor state
        log_sensor_state(sensor1_state, sensor2_state);

        // Check for alert condition
        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

