#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/security_cam.log"

static volatile int running = 1;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_buffer;
}

// Function to create the capture directory if it doesn't exist
int create_capture_directory() {
    struct stat st = {0};

    if (stat(CAPTURE_DIR, &st) == -1) {
        if (mkdir(CAPTURE_DIR, 0777) == -1) {
            syslog(LOG_ERR, "Failed to create directory: %s, error: %s", CAPTURE_DIR, strerror(errno));
            return -1;
        }
        syslog(LOG_INFO, "Created directory: %s", CAPTURE_DIR);
    }
    return 0;
}

// Function to capture an image using libcamera-still
int capture_image(const char* filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s", filename);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execlp("libcamera-still", "libcamera-still", "-o", filename, NULL);
        syslog(LOG_ERR, "Failed to execute libcamera-still: %s", strerror(errno));
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            syslog(LOG_INFO, "Captured image: %s", filename);
            return 0; // Success
        } else {
            syslog(LOG_ERR, "libcamera-still failed with status: %d", status);
            return -1; // Failure
        }
    } else {
        syslog(LOG_ERR, "Failed to fork process: %s", strerror(errno));
        return -1; // Fork error
    }
}

// Function to read the PIR sensor with debouncing
int read_pir_sensor() {
    int value = gpioRead(GPIO_PIN);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    return value;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

int main() {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera program");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Create capture directory
    if (create_capture_directory() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            char timestamp[32];
            get_iso8601_timestamp(timestamp, sizeof(timestamp));

            char filename[256];
            snprintf(filename, sizeof(filename), "%s%s_%s.jpg", CAPTURE_DIR, timestamp, "motion");

            if (capture_image(filename) == 0) {
                syslog(LOG_INFO, "Motion detected at %s, image captured: %s", timestamp, filename);
            } else {
                syslog(LOG_ERR, "Failed to capture image after motion detection at %s", timestamp);
            }
        }

        gpioDelay(50 * 1000); // Polling interval
    }

    // Cleanup
    gpioTerminate();
    syslog(LOG_INFO, "Security camera program stopped");
    closelog();

    return 0;
}

