        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (write_pgm_header(fp, width, height) != 0) {
        fclose(fp);
        return -1;
    }

    if (fwrite(data, 1, width * height, fp) != width * height) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to enqueue a buffer
int enqueue_buffer(int fd, void *buffer, unsigned int buffer_size)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.m.offset = (unsigned long)buffer;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to dequeue a buffer with timeout
int dequeue_buffer(int fd, void **buffer, unsigned int *buffer_size)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1; // Timeout
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    *buffer = buffers[buf.index];
    *buffer_size = buffer_size;

    return 0;
}

int main(int argc, char *argv[]) {
    int i;
    char filename[20];

    // Parse command-line arguments
    if (argc > 1) {
        video_device = argv[1];
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open video device
    fd = open(video_device, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", video_device, strerror(errno));
        return EXIT_FAILURE;
    }

    // Query capabilities
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", video_device);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", video_device);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set image format
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = MAX_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    for (i = 0; i < MAX_BUFFERS; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            fprintf(stderr, "mmap failed: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
        buffer_size = buf.length;
    }

    // Queue buffers
    for (i = 0; i < MAX_BUFFERS; ++i) {
        if (enqueue_buffer(fd, buffers[i], buffer_size) == -1) {
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture loop
    while (!stop) {
        void *buffer;
        unsigned int buffer_size;

        if (dequeue_buffer(fd, &buffer, &buffer_size) == -1) {
            // Timeout or error, continue to next iteration
            continue;
        }

        // Save image to PGM file
        snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_count + 1);
        if (save_image_to_pgm(filename, buffer, IMAGE_WIDTH, IMAGE_HEIGHT) == -1) {
            fprintf(stderr, "Failed to save image %s\n", filename);
        }

        frame_count++;

        // Requeue buffer
        if (enqueue_buffer(fd, buffer, buffer_size) == -1) {
            break;
        }
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
    }

    // Unmap buffers
    for (i = 0; i < MAX_BUFFERS; ++i) {
        if (munmap(buffers[i], buffer_size) == -1) {
            fprintf(stderr, "munmap failed: %s\n", strerror(errno));
        }
    }

    // Close device
    close(fd);

    fprintf(stderr, "Captured %d frames\n", frame_count);

    return EXIT_SUCCESS;
}

