        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize video device
    if (open_device(&dev) < 0 ||
        init_device(&dev) < 0 ||
        set_format(&dev) < 0 ||
        request_buffers(&dev) < 0 ||
