        fprintf(stderr, "Failed to initialize video device\n");
        goto cleanup;
    }

    printf("Video device initialized.  Capturing frames...\n");

    fd_set fds;
    struct timeval tv;
    int r;

    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(dev.fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(dev.fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            perror("select()");
            break;
        } else if (r == 0) {
            // Timeout occurred
            continue;
        } else {
            // Data is available
            memset(&dev.buf, 0, sizeof(dev.buf));
            dev.buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            dev.buf.memory = V4L2_MEMORY_MMAP;

            if (ioctl(dev.fd, VIDIOC_DQBUF, &dev.buf) < 0) {
                perror("Error dequeuing buffer");
                break;
            }

            // Get timestamp
            struct timeval tv;
            gettimeofday(&tv, NULL);
            char timestamp[30];
            snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv.tv_sec, tv.tv_usec);

            // Write to log file
            if (write_log(timestamp) < 0) {
                fprintf(stderr, "Failed to write log entry\n");
            }

            // Requeue the buffer
            if (ioctl(dev.fd, VIDIOC_QBUF, &dev.buf) < 0) {
                perror("Error queuing buffer");
                break;
            }
        }
    }

    // Cleanup resources
    stop_capturing(&dev);
    unmap_buffers(&dev);
    release_buffers(&dev);
    uninit_device(&dev);
    close_device(&dev);

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

