        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Function to send a UDP datagram
int send_datagram(int sockfd, const void *buffer, size_t buffer_size, const struct sockaddr_in *server_addr) {
    ssize_t bytes_sent = sendto(sockfd, buffer, buffer_size, 0, (struct sockaddr *)server_addr, sizeof(*server_addr));
    if (bytes_sent < 0) {
