    while (state.running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(state.video_fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        // Frame index (simulated)
        uint32_t frame_index = 0; // Replace with actual frame index if available

        // Calculate number of fragments
        int num_fragments = (state.buffer_size - HEADER_SIZE) / FRAGMENT_SIZE + 1;

        // Send fragments
        for (int fragment_index = 0; fragment_index < num_fragments; ++fragment_index) {
