            // Prepare datagram
            uint8_t *datagram = (uint8_t *)malloc(HEADER_SIZE + payload_size);
            if (datagram == NULL) {
                perror("Error allocating memory for datagram");
                break;
            }
            memcpy(datagram, header, HEADER_SIZE);
            memcpy(datagram + HEADER_SIZE, (uint8_t *)state.buffers[buf.index] + fragment_index * FRAGMENT_SIZE, payload_size);

