#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define PWM range (1000)
#define PWM_RANGE 1000

// Define servo mid-position (75)
#define SERVO_MID_POSITION 75

// Define servo range (25-125)
#define SERVO_MIN_POSITION 25
#define SERVO_MAX_POSITION 125

// Define PWM pulse width limits (1ms - 2ms)
#define PWM_MIN_PULSE_WIDTH 1000 // 1ms
#define PWM_MAX_PULSE_WIDTH 2000 // 2ms

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_position(int pin, int position);
int adjust_servo_position(int pin, int adjustment);
int read_button(int pin);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, cleaning up...\n");
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Initialize servos to mid-position
    if (set_servo_position(PAN_SERVO_PIN, SERVO_MID_POSITION) != 0) {
        fprintf(stderr, "Failed to initialize pan servo\n");
        return -1;
    }
    if (set_servo_position(TILT_SERVO_PIN, SERVO_MID_POSITION) != 0) {
        fprintf(stderr, "Failed to initialize tilt servo\n");
        return -1;
    }

    return 0;
}

// Set servo position
int set_servo_position(int pin, int position) {
    if (position < SERVO_MIN_POSITION || position > SERVO_MAX_POSITION) {
        fprintf(stderr, "Invalid servo position: %d\n", position);
        return -1;
    }

    // Calculate pulse width (1ms - 2ms)
    int pulse_width = PWM_MIN_PULSE_WIDTH + (position - SERVO_MIN_POSITION) * (PWM_MAX_PULSE_WIDTH - PWM_MIN_PULSE_WIDTH) / (SERVO_MAX_POSITION - SERVO_MIN_POSITION);

    gpioPWM(pin, pulse_width);
    return 0;
}

// Adjust servo position
int adjust_servo_position(int pin, int adjustment) {
    int current_position = gpioGetPWMdutycycle(pin) * (SERVO_MAX_POSITION - SERVO_MIN_POSITION) / PWM_RANGE + SERVO_MIN_POSITION;
    int new_position = current_position + adjustment;

    // Clamp position to valid range
    if (new_position < SERVO_MIN_POSITION) {
        new_position = SERVO_MIN_POSITION;
    } else if (new_position > SERVO_MAX_POSITION) {
        new_position = SERVO_MAX_POSITION;
    }

    return set_servo_position(pin, new_position);
}

// Read button state
int read_button(int pin) {
    return gpioRead(pin);
}

// Cleanup GPIO
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("Camera pan-tilt mount control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int tilt_up_pressed = read_button(TILT_UP_BUTTON);
        int tilt_down_pressed = read_button(TILT_DOWN_BUTTON);
        int pan_left_pressed = read_button(PAN_LEFT_BUTTON);
        int pan_right_pressed = read_button(PAN_RIGHT_BUTTON);

        // Adjust servo positions
        if (tilt_up_pressed) {
            adjust_servo_position(TILT_SERVO_PIN, 5);
        }
        if (tilt_down_pressed) {
            adjust_servo_position(TILT_SERVO_PIN, -5);
        }
        if (pan_left_pressed) {
            adjust_servo_position(PAN_SERVO_PIN, -5);
        }
        if (pan_right_pressed) {
            adjust_servo_position(PAN_SERVO_PIN, 5);
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms
    }

    return 0;
}

