#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BUFFER_COUNT 4
#define JPEG_QUALITY 75

// Structure to hold image data
typedef struct {
    unsigned char *data;
    size_t size;
} ImageData;

// Global variables for signal handling
volatile sig_atomic_t stop_flag = 0;
int fd = -1;
struct buffer {
    void   *start;
    size_t length;
};
struct buffer *buffers = NULL;
unsigned int n_buffers = 0;

// Error handling function
void error_exit(const char *format, ...) {
    va_list args;
    va_start(args, format);
    fprintf(stderr, "Error: ");
    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");
    va_end(args);
    exit(EXIT_FAILURE);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to close the video device
void close_device(int fd) {
    if (close(fd) == -1) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
    }
}

// Function to query camera capabilities
int query_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n", (cap.version >> 16) & 0xff, (cap.version >> 8) & 0xff, cap.version & 0xff);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    return 0;
}

// Function to set the video format
int set_format(int fd, int width, int height, const char *format) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;

    if (strcmp(format, "YUYV") == 0) {
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    } else if (strcmp(format, "MJPEG") == 0) {
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    } else {
        fprintf(stderr, "Invalid format: %s\n", format);
        return -1;
    }

    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    printf("Format set to %s, %dx%d\n", format, fmt.fmt.pix.width, fmt.fmt.pix.height);
    return 0;
}

// Function to request buffers
int request_buffers(int fd, unsigned int count) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < count) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    printf("Requested %u buffers\n", count);
    return 0;
}

// Function to map buffers
int map_buffers(int fd, struct buffer **buffers, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer %u: %s\n", i, strerror(errno));
            return -1;
        }

        (*buffers)[i].length = buf.length;
        (*buffers)[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if ((*buffers)[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %u: %s\n", i, strerror(errno));
            return -1;
        }

        printf("Mapped buffer %u to address %p, length %u\n", i, (*buffers)[i].start, buf.length);
    }
    return 0;
}

// Function to unmap buffers
int unmap_buffers(struct buffer *buffers, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            fprintf(stderr, "Error unmapping buffer %u: %s\n", i, strerror(errno));
            return -1;
        }
        printf("Unmapped buffer %u\n", i);
    }
    return 0;
}

// Function to free buffers
int free_buffers(int fd, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer %u for freeing: %s\n", i, strerror(errno));
            return -1;
        }
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 0; // Release all buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error freeing buffers: %s\n", strerror(errno));
        return -1;
    }

    printf("Freed %u buffers\n", count);
    return 0;
}

// Function to queue a buffer
int queue_buffer(int fd, unsigned int index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer %u: %s\n", index, strerror(errno));
        return -1;
    }

    printf("Queued buffer %u\n", index);
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, unsigned int *index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *index = buf.index;
    printf("Dequeued buffer %u\n", *index);
    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }

    printf("Streaming started\n");
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
        return -1;
    }

    printf("Streaming stopped\n");
    return 0;
}

// Function to convert YUYV to RGB24
ImageData convert_yuyv_to_rgb24(const unsigned char *yuyv_data, size_t yuyv_size, size_t *rgb_size) {
    size_t rgb_length = yuyv_size * 2 / 3; // Estimate RGB size
    ImageData rgb_data = {NULL, 0};

    rgb_data.data = (unsigned char *)malloc(rgb_length);
    if (rgb_data.data == NULL) {
        fprintf(stderr, "Error allocating memory for RGB data\n");
        *rgb_size = 0;
        return rgb_data;
    }

    size_t i, j;
    for (i = 0, j = 0; i < yuyv_size - 1; i += 2, j += 3) {
        unsigned char y1 = yuyv_data[i];
        unsigned char u = yuyv_data[i + 1];
        unsigned char y2 = yuyv_data[i + 2];
        unsigned char v = yuyv_data[i + 3];

        int r1 = y1 + 1.13983 * (v - 128);
        int g1 = y1 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
        int b1 = y1 + 2.03211 * (u - 128);

        int r2 = y2 + 1.13983 * (v - 128);
        int g2 = y2 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
        int b2 = y2 + 2.03211 * (u - 128);

        r1 = (r1 < 0) ? 0 : ((r1 > 255) ? 255 : r1);
        g1 = (g1 < 0) ? 0 : ((g1 > 255) ? 255 : g1);
        b1 = (b1 < 0) ? 0 : ((b1 > 255) ? 255 : b1);

        r2 = (r2 < 0) ? 0 : ((r2 > 255) ? 255 : r2);
        g2 = (g2 < 0) ? 0 : ((g2 > 255) ? 255 : g2);
        b2 = (b2 < 0) ? 0 : ((b2 > 255) ? 255 : b2);

        rgb_data.data[j] = (unsigned char)r1;
        rgb_data.data[j + 1] = (unsigned char)g1;
        rgb_data.data[j + 2] = (unsigned char)b1;

        rgb_data.data[j + 3] = (unsigned char)r2;
        rgb_data.data[j + 4] = (unsigned char)g2;
        rgb_data.data[j + 5] = (unsigned char)b2;
    }

    rgb_data.size = rgb_length;
    *rgb_size = rgb_length;
    return rgb_data;
}

// Function to apply a simple blur filter (3x3 kernel)
ImageData apply_blur_filter(const unsigned char *rgb_data, size_t rgb_size, size_t *blurred_size) {
    ImageData blurred_data = {NULL, 0};
    blurred_data.data = (unsigned char *)malloc(rgb_size);
    if (blurred_data.data == NULL) {
        fprintf(stderr, "Error allocating memory for blurred data\n");
        *blurred_size = 0;
        return blurred_data;
    }

    size_t width = IMAGE_WIDTH;
    size_t height = IMAGE_HEIGHT;

    for (size_t i = 0; i < height; ++i) {
        for (size_t j = 0; j < width; ++j) {
            unsigned char r = 0, g = 0, b = 0;
            for (int k = -1; k <= 1; ++k) {
                for (int l = -1; l <= 1; ++l) {
                    size_t x = j + l;
                    size_t y = i + k;

                    if (x < 0) x = 0;
                    if (x >= width) x = width - 1;
                    if (y < 0) y = 0;
                    if (y >= height) y = height - 1;

                    size_t index = y * width * 3 + x * 3;
                    r += rgb_data[index];
                    g += rgb_data[index + 1];
                    b += rgb_data[index + 2];
                }
            }
            size_t blurred_index = i * width * 3 + j * 3;
            blurred_data.data[blurred_index] = r / 9;
            blurred_data.data[blurred_index + 1] = g / 9;
            blurred_data.data[blurred_index + 2] = b / 9;
        }
    }

    blurred_data.size = rgb_size;
    *blurred_size = rgb_size;
    return blurred_data;
}

// Function to encode RGB24 data to JPEG
int encode_to_jpeg(const unsigned char *rgb_data, size_t rgb_size, const char *filename, int quality) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Error opening output file %s: %s\n", filename, strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = IMAGE_WIDTH;
    cinfo.image_height = IMAGE_HEIGHT;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = IMAGE_WIDTH * 3; // RGB

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (unsigned char *)&rgb_data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    printf("JPEG image saved to %s\n", filename);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the video device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (query_capabilities(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Set format
    if (set_format(fd, IMAGE_WIDTH, IMAGE_HEIGHT, "YUYV") == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(fd, BUFFER_COUNT) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Allocate buffers
    buffers = (struct buffer *)calloc(BUFFER_COUNT, sizeof(struct buffer));
    if (!buffers) {
        fprintf(stderr, "Error allocating buffers\n");
        close_device(fd);
        return EXIT_FAILURE;
    }
    n_buffers = BUFFER_COUNT;

    // Map buffers
    if (map_buffers(fd, &buffers, BUFFER_COUNT) == -1) {
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Queue all buffers
    for (unsigned int i = 0; i < BUFFER_COUNT; ++i) {
        if (queue_buffer(fd, i) == -1) {
            unmap_buffers(buffers, BUFFER_COUNT);
            free(buffers);
            close_device(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        unmap_buffers(buffers, BUFFER_COUNT);
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    unsigned int buffer_index;
    ImageData rgb_data, blurred_data;
    size_t rgb_size, blurred_size;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;

    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        int ret = select(fd + 1, &fds, NULL, NULL, &tv);

        if (ret == -1) {
            if (errno == EINTR) {
                fprintf(stderr, "select() interrupted by signal\n");
                break;
            }
            fprintf(stderr, "Error in select(): %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            continue;
        } else {
            if (dequeue_buffer(fd, &buffer_index) == -1) {
                break;
            }

            // Process the captured frame
            rgb_data = convert_yuyv_to_rgb24((unsigned char *)buffers[buffer_index].start, buffers[buffer_index].length, &rgb_size);
            blurred_data = apply_blur_filter(rgb_data.data, rgb_size, &blurred_size);

            // Get current timestamp for filename
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

            // Encode to JPEG
            if (encode_to_jpeg(blurred_data.data, blurred_size, filename, JPEG_QUALITY) == -1) {
                fprintf(stderr, "Error encoding to JPEG\n");
            }

            // Free allocated memory
            free(rgb_data.data);
            free(blurred_data.data);

            // Requeue the buffer
            if (queue_buffer(fd, buffer_index) == -1) {
                break;
            }
        }
    }

    // Stop streaming
    if (stop_streaming(fd) == -1) {
        // Non-fatal error, continue cleanup
    }

    // Unmap buffers
    if (unmap_buffers(buffers, BUFFER_COUNT) == -1) {
        // Non-fatal error, continue cleanup
    }

    // Free buffers
    if (free_buffers(fd, BUFFER_COUNT) == -1) {
        // Non-fatal error, continue cleanup
    }

    // Close device
    close_device(fd);

    // Free buffers structure
    free(buffers);

    printf("Exiting cleanly\n");
    return EXIT_SUCCESS;
}

