#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

// Structure to hold camera capabilities
typedef struct {
    char device_name[256];
    int width;
    int height;
    float frame_rate;
    int autofocus_supported;
} camera_capabilities_t;

// Function to check if the device node exists
int device_exists(const char *device_name) {
    if (access(device_name, F_OK) == 0) {
        return 1; // Device exists
    } else {
        return 0; // Device does not exist
    }
}

// Function to open the device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR); // Open in read/write mode
    if (fd < 0) {
        perror("Error opening device");
        return -1; // Error opening device
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("Error querying capabilities");
        return -1; // Error querying capabilities
    }
    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, struct v4l2_frmsizeenum *frmsize) {
    frmsize->index = 0; // Start from the first frame size
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, frmsize) == 0) {
        printf("  Supported frame size: %d x %d\n", frmsize->discrete.width, frmsize->discrete.height);
        frmsize->index++; // Move to the next frame size
    }
    if (errno != EINVAL) {
        perror("Error enumerating frame sizes");
        return -1; // Error enumerating frame sizes
    }
    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd, struct v4l2_frmivalenum *frmival) {
    frmival->index = 0; // Start from the first frame interval
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, frmival) == 0) {
        printf("    Supported frame interval: %d/%d\n", frmival->discrete.numerator, frmival->discrete.denominator);
        frmival->index++; // Move to the next frame interval
    }
    if (errno != EINVAL) {
        perror("Error enumerating frame intervals");
        return -1; // Error enumerating frame intervals
    }
    return 0;
}

// Function to query autofocus support
int query_autofocus(int fd, struct v4l2_queryctrl *queryctrl) {
    queryctrl->id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, queryctrl) < 0) {
        if (errno == EINVAL) {
            printf("  Autofocus not supported\n");
            return 0; // Autofocus not supported
        } else {
            perror("Error querying autofocus");
            return -1; // Error querying autofocus
        }
    }

    if (queryctrl->flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("  Autofocus disabled\n");
        return 0;
    }

    printf("  Autofocus supported\n");
    return 1;
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl queryctrl;

    // Check if the device exists
    if (!device_exists(DEVICE_NAME)) {
        fprintf(stderr, "Error: Device %s does not exist.\n", DEVICE_NAME);
        return 1;
    }

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    // Query device capabilities
    if (query_capabilities(fd, &cap) < 0) {
        close(fd);
        return 1;
    }

    printf("Device: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n", (cap.version >> 16) & 0xff, (cap.version >> 8) & 0xff, cap.version & 0xff);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    // Enumerate frame sizes
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Example format
    printf("Supported frame sizes for V4L2_PIX_FMT_YUYV:\n");
    if (enumerate_frame_sizes(fd, &frmsize) < 0) {
        close(fd);
        return 1;
    }

    // Enumerate frame intervals for each frame size
    memset(&frmival, 0, sizeof(frmival));
    frmival.pixel_format = V4L2_PIX_FMT_YUYV; // Example format
    frmsize.index = 0; // Reset index for frame size enumeration
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV;
    frmsize.type = V4L2_FRMSIZE_TYPE_DISCRETE;
    frmsize.discrete.width = 640; // Example width
    frmsize.discrete.height = 480; // Example height

    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("Supported frame intervals for %d x %d:\n", frmsize.discrete.width, frmsize.discrete.height);
        frmival.width = frmsize.discrete.width;
        frmival.height = frmsize.discrete.height;
        frmival.type = V4L2_FRMIVAL_TYPE_DISCRETE;
        if (enumerate_frame_intervals(fd, &frmival) < 0) {
            close(fd);
            return 1;
        }
    } else {
        perror("Error enumerating frame sizes");
        close(fd);
        return 1;
    }

    // Query autofocus support
    if (query_autofocus(fd, &queryctrl) < 0) {
        close(fd);
        return 1;
    }

    close(fd);
    return 0;
}

