    printf("DOWN: GPIO %d\n", DOWN_BUTTON_PIN);
    printf(" LEFT: GPIO %d\n", LEFT_BUTTON_PIN);
    printf("RIGHT: GPIO %d\n", RIGHT_BUTTON_PIN);
    printf("Center Position: Pan=%d, Tilt=%d\n", SERVO_CENTER_PULSE_WIDTH, SERVO_CENTER_PULSE_WIDTH);
}

// Function to set servo pulse width
void set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    gpioPWM(gpio_pin, 128); // 50% duty cycle
    gpioDelay(pulse_width);
    gpioPWM(gpio_pin, 0);   // Stop PWM
    gpioDelay(SERVO_MAX_PULSE_WIDTH - pulse_width);
}

// Function to update servo position based on button presses
void update_servo_position() {
    if (gpioRead(UP_BUTTON_PIN) == 0) {
        tilt_pulse_width += 10;
        if (tilt_pulse_width > SERVO_MAX_PULSE_WIDTH) {
            tilt_pulse_width = SERVO_MAX_PULSE_WIDTH;
        }
    } else if (gpioRead(DOWN_BUTTON_PIN) == 0) {
        tilt_pulse_width -= 10;
        if (tilt_pulse_width < SERVO_MIN_PULSE_WIDTH) {
            tilt_pulse_width = SERVO_MIN_PULSE_WIDTH;
        }
    } else if (gpioRead(LEFT_BUTTON_PIN) == 0) {
