        pan_pulse_width += 10;
        if (pan_pulse_width > SERVO_MAX_PULSE_WIDTH) {
            pan_pulse_width = SERVO_MAX_PULSE_WIDTH;
        }
    }

    set_servo_pulse_width(PAN_SERVO_PIN, pan_pulse_width);
    set_servo_pulse_width(TILT_SERVO_PIN, tilt_pulse_width);
}

// Function to handle button press
void handle_button_press(int button_pin) {
    if (gpioRead(button_pin) == 0) { // Button is pressed (active low)
        if (button_pin == UP_BUTTON_PIN) {
            tilt_pulse_width += 10;
            if (tilt_pulse_width > SERVO_MAX_PULSE_WIDTH) {
                tilt_pulse_width = SERVO_MAX_PULSE_WIDTH;
            }
        } else if (button_pin == DOWN_BUTTON_PIN) {
            tilt_pulse_width -= 10;
            if (tilt_pulse_width < SERVO_MIN_PULSE_WIDTH) {
                tilt_pulse_width = SERVO_MIN_PULSE_WIDTH;
            }
        } else if (button_pin == LEFT_BUTTON_PIN) {
            pan_pulse_width -= 10;
            if (pan_pulse_width < SERVO_MIN_PULSE_WIDTH) {
                pan_pulse_width = SERVO_MIN_PULSE_WIDTH;
            }
        } else if (button_pin == RIGHT_BUTTON_PIN) {
            pan_pulse_width += 10;
            if (pan_pulse_width > SERVO_MAX_PULSE_WIDTH) {
                pan_pulse_width = SERVO_MAX_PULSE_WIDTH;
            }
        }

        set_servo_pulse_width(PAN_SERVO_PIN, pan_pulse_width);
        set_servo_pulse_width(TILT_SERVO_PIN, tilt_pulse_width);
    }
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("GPIO terminated\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Main loop
    while (1) {
        handle_button_press(UP_BUTTON_PIN);
        handle_button_press(DOWN_BUTTON_PIN);
        handle_button_press(LEFT_BUTTON_PIN);
        handle_button_press(RIGHT_BUTTON_PIN);

        gpioDelay(50); // Delay for 50 milliseconds
    }

    return 0;
}

