#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <pigpio.h>
#include <jpeglib.h>
#include <setjmp.h>

// Configuration
#define PIR_GPIO 17
#define DEBOUNCE_TIME 2000 // milliseconds
#define POLL_INTERVAL 100 // milliseconds
#define JPEG_QUALITY 85
#define MOTION_CAPTURE_DIR "motion_captures"
#define HTTP_TIMEOUT 5 // seconds

// Global variables
static int running = 1;
static int socket_fd = -1;
static char *server_ip = NULL;
static int server_port = 0;
static pthread_mutex_t socket_mutex = PTHREAD_MUTEX_INITIALIZER;

// Structure to hold image data
struct my_error_mgr {
  struct jpeg_error_mgr pub;
  jmp_buf setjmp_buffer;
};

typedef struct my_error_mgr * my_error_ptr;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_jpeg();
void capture_motion();
int capture_image(char *filename);
int encode_jpeg(unsigned char *image_data, int width, int height, unsigned char **jpeg_data, unsigned long *jpeg_size);
int decode_jpeg(unsigned char *jpeg_data, unsigned long jpeg_size, unsigned char **image_data, int *width, int *height);
int post_data(const char *filename, const char *timestamp, const char *motion_status, int gpio_pin);
void *http_thread(void *arg);
void error_exit(const char *message);
void my_error_exit(j_common_ptr cinfo);

// Signal handler
void signal_handler(int signal) {
  fprintf(stderr, "Signal received: %d. Shutting down...\n", signal);
  running = 0;
}

// Initialize GPIO
int init_gpio() {
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return -1;
  }

  gpioSetMode(PIR_GPIO, PI_INPUT);
  gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);
  return 0;
}

// Initialize JPEG library
int init_jpeg() {
  // No specific initialization needed for jpeglib in this example
  return 0;
}

// Capture motion event
void capture_motion() {
  static int last_motion_time = 0;
  int current_time = gpioTick();

  if (gpioRead(PIR_GPIO) == 1) {
    if (current_time - last_motion_time > DEBOUNCE_TIME * 1000) {
      last_motion_time = current_time;

      // Generate filename
      time_t rawtime;
      struct tm *timeinfo;
      char filename[80];
      time(&rawtime);
      timeinfo = localtime(&rawtime);
      strftime(filename, sizeof(filename), MOTION_CAPTURE_DIR "/%Y%m%d_%H%M%S.jpg", timeinfo);

      // Create directory if it doesn't exist
      char command[128];
      snprintf(command, sizeof(command), "mkdir -p %s", MOTION_CAPTURE_DIR);
      int result = system(command);
      if (result != 0) {
        fprintf(stderr, "Error creating directory: %s\n", MOTION_CAPTURE_DIR);
        return;
      }

      // Capture image
      if (capture_image(filename) != 0) {
        fprintf(stderr, "Error capturing image\n");
        return;
      }

      // Get timestamp
      time_t now = time(NULL);
      struct tm *tstruct = localtime(&now);
      char timestamp[80];
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%3Z", tstruct);

      // Post data
      if (post_data(filename, timestamp, "MOTION", PIR_GPIO) != 0) {
        fprintf(stderr, "Error posting data\n");
      }
    }
  }
}

// Capture image using libcamera
int capture_image(char *filename) {
  char command[256];
  snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 --quality %d", filename, JPEG_QUALITY);
  int result = system(command);
  if (result != 0) {
    fprintf(stderr, "Error capturing image using libcamera-still: %d\n", result);
    return -1;
  }
  return 0;
}

// Encode image to JPEG (Placeholder - requires actual implementation)
int encode_jpeg(unsigned char *image_data, int width, int height, unsigned char **jpeg_data, unsigned long *jpeg_size) {
  // This is a placeholder.  A real implementation would use libjpeg
  // to encode the raw image data into a JPEG stream.
  // For simplicity, we'll just return a dummy JPEG.

  // Allocate memory for the JPEG data
  *jpeg_size = width * height * 3; // Assuming 24-bit RGB
  *jpeg_data = (unsigned char *)malloc(*jpeg_size);
  if (*jpeg_data == NULL) {
    fprintf(stderr, "Failed to allocate memory for JPEG data\n");
    return -1;
  }

  // Fill the JPEG data with dummy data (e.g., all zeros)
  memset(*jpeg_data, 0, *jpeg_size);

  return 0;
}

// Decode JPEG (Placeholder - requires actual implementation)
int decode_jpeg(unsigned char *jpeg_data, unsigned long jpeg_size, unsigned char **image_data, int *width, int *height) {
    // This is a placeholder.  A real implementation would use libjpeg
    // to decode the JPEG data and extract the image width, height, and RGB data.
    // For simplicity, we'll just return a dummy image.

    // Allocate memory for the image data
    *width = 640;  // Example width
    *height = 480; // Example height
    *image_data = (unsigned char *)malloc(*width * *height * 3);
    if (*image_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for image data\n");
        return -1;
    }

    // Fill the image data with dummy data (e.g., all zeros)
    memset(*image_data, 0, *width * *height * 3);

    return 0;
}

// Post data to HTTP endpoint
int post_data(const char *filename, const char *timestamp, const char *motion_status, int gpio_pin) {
  pthread_mutex_lock(&socket_mutex);
  if (socket_fd == -1) {
    fprintf(stderr, "HTTP socket not initialized\n");
    pthread_mutex_unlock(&socket_mutex);
    return -1;
  }

  char payload[512];
  snprintf(payload, sizeof(payload), "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": \"%s\", \"gpio_pin\": %d}", filename, timestamp, motion_status, gpio_pin);

  char request[1024];
  snprintf(request, sizeof(request), "POST /upload HTTP/1.1\r\nHost: %s:%d\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", server_ip, server_port, strlen(payload), payload);

  if (send(socket_fd, request, strlen(request), 0) < 0) {
    fprintf(stderr, "Error sending data to server\n");
    pthread_mutex_unlock(&socket_mutex);
    return -1;
  }

  // Receive response (basic implementation - needs improvement for real-world use)
  char buffer[1024];
  memset(buffer, 0, sizeof(buffer));
  ssize_t bytes_received = recv(socket_fd, buffer, sizeof(buffer) - 1, 0);
  if (bytes_received < 0) {
    fprintf(stderr, "Error receiving data from server\n");
    pthread_mutex_unlock(&socket_mutex);
    return -1;
  }

  printf("Received response: %s\n", buffer);

  pthread_mutex_unlock(&socket_mutex);
  return 0;
}

// HTTP thread function
void *http_thread(void *arg) {
  struct sockaddr_in server_addr;

  // Create socket
  socket_fd = socket(AF_INET, SOCK_STREAM, 0);
  if (socket_fd < 0) {
    fprintf(stderr, "Error creating socket\n");
    pthread_exit(NULL);
  }

  // Configure server address
  memset(&server_addr, 0, sizeof(server_addr));
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(server_port);
  if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
    fprintf(stderr, "Invalid address/ Address not supported \n");
    close(socket_fd);
    pthread_exit(NULL);
  }

  // Connect to server
  if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    fprintf(stderr, "Error connecting to server\n");
    close(socket_fd);
    pthread_exit(NULL);
  }

  printf("HTTP thread connected to server\n");

  // Main loop
  while (running) {
    // Check for motion (this is done in the main thread)
    // The HTTP thread just waits for data to be posted
    sleep(1); // Reduce CPU usage
  }

  // Cleanup
  close(socket_fd);
  socket_fd = -1;
  printf("HTTP thread exiting\n");
  pthread_exit(NULL);
}

// Error exit function
void error_exit(const char *message) {
  fprintf(stderr, "%s\n", message);
  gpioTerminate();
  exit(EXIT_FAILURE);
}

// JPEG error exit function
void my_error_exit(j_common_ptr cinfo) {
  my_error_ptr myerr = (my_error_ptr)cinfo->err;
  (*cinfo->err->output_message) (cinfo);
  longjmp(myerr->setjmp_buffer, 1);
}

int main(int argc, char *argv[]) {
  // Parse command-line arguments
  if (argc != 3) {
    fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
    return EXIT_FAILURE;
  }

  server_ip = argv[1];
  server_port = atoi(argv[2]);

  // Initialize signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize GPIO
  if (init_gpio() != 0) {
    error_exit("GPIO initialization failed");
  }

  // Initialize JPEG
  if (init_jpeg() != 0) {
    error_exit("JPEG initialization failed");
  }

  // Create HTTP thread
  pthread_t http_thread_id;
  if (pthread_create(&http_thread_id, NULL, http_thread, NULL) != 0) {
    fprintf(stderr, "Error creating HTTP thread\n");
    gpioTerminate();
    return EXIT_FAILURE;
  }

  // Main loop
  while (running) {
    capture_motion();
    gpioDelay(POLL_INTERVAL * 1000); // Convert milliseconds to microseconds
  }

  // Cleanup
  pthread_join(http_thread_id, NULL);
  gpioTerminate();

  return EXIT_SUCCESS;
}

