// Capture motion event
void capture_motion() {
  static int last_motion_time = 0;
  int current_time = gpioTick();

  if (gpioRead(PIR_GPIO) == 1) {
    if (current_time - last_motion_time > DEBOUNCE_TIME * 1000) {
      last_motion_time = current_time;

      // Generate filename
      time_t rawtime;
      struct tm *timeinfo;
      char filename[80];
      time(&rawtime);
      timeinfo = localtime(&rawtime);
      strftime(filename, sizeof(filename), MOTION_CAPTURE_DIR "/%Y%m%d_%H%M%S.jpg", timeinfo);

      // Create directory if it doesn't exist
      char command[128];
      snprintf(command, sizeof(command), "mkdir -p %s", MOTION_CAPTURE_DIR);
      int result = system(command);
      if (result != 0) {
        fprintf(stderr, "Error creating directory: %s\n", MOTION_CAPTURE_DIR);
        return;
      }

      // Capture image
      if (capture_image(filename) != 0) {
        fprintf(stderr, "Error capturing image\n");
        return;
      }

      // Get timestamp
      time_t now = time(NULL);
      struct tm *tstruct = localtime(&now);
      char timestamp[80];
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%3Z", tstruct);

      // Post data
      if (post_data(filename, timestamp, "MOTION", PIR_GPIO) != 0) {
        fprintf(stderr, "Error posting data\n");
      }
    }
  }
}

