#define CAPTURE_COMMAND "libcamera-still -o %s --width 640 --height 480 --quality 85 --timeout 2000 --no-preview"
#define DEBOUNCE_DELAY_MS 50

static volatile int running = 1;
static int log_fd = -1;

// Function to get current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // YYYYMMDD_HHMMSS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
    return timestamp;
}

// Function to generate filename with timestamp
char* generate_filename() {
    char* timestamp = get_timestamp();
    static char filename[100]; // /home/pi/images/YYYYMMDD_HHMMSS_mmm.jpg
    snprintf(filename, sizeof(filename), "%s/%s_mmm.jpg", IMAGES_DIR, timestamp);
    return filename;
}

// Function to execute the camera capture command
int capture_image(const char* filename) {
    char command[256];
    snprintf(command, sizeof(command), CAPTURE_COMMAND, filename);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        log_message("Error: Failed to execute capture command.");
        return -1;
    }

    int status = pclose(fp);
    if (status != 0) {
        log_message("Error: Capture command failed with status %d.", status);
        return -1;
    }

    return 0;
}

// Function to log messages to a file
void log_message(const char* format, ...) {
    if (log_fd == -1) return;

    char* timestamp = get_timestamp();
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: ", timestamp);

    va_list args;
    va_start(args, format);
    int len = strlen(log_entry);
    vsnprintf(log_entry + len, sizeof(log_entry) - len, format, args);
    va_end(args);

    dprintf(log_fd, "%s\n", log_entry);
    fsync(log_fd);
}

// Function to handle GPIO interrupt
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected
        char* filename = generate_filename();
        log_message("Motion detected! Capturing image: %s", filename);
        if (capture_image(filename) != 0) {
            log_message("Error: Image capture failed.");
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received: %d. Shutting down...", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set interrupt handler
    gpioSetAlertFuncEx(GPIO_PIN, motion_detected_callback, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Motion capture service started.");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt
    gpioTerminate(); // Terminate pigpio

    if (log_fd != -1) {
        close(log_fd);
    }

    log_message("Motion capture service stopped.");

    return 0;
}

