#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define BUFFER_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2)

static int fd = -1;
static void *buffer = MAP_FAILED;
static FILE *output_file = NULL;

// Structure to hold camera capabilities
typedef struct {
    char card[32];
    char bus_info[32];
    char version[32];
    char capabilities[32];
    char device_caps[32];
} camera_capabilities_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Signal received (%d). Cleaning up...\n", signum);
    if (fd != -1) {
        if (buffer != MAP_FAILED) {
            if (munmap(buffer, BUFFER_SIZE) == -1) {
                perror("munmap");
            }
        }
        if (close(fd) == -1) {
            perror("close");
        }
    }
    if (output_file != NULL) {
        if (fclose(output_file) == EOF) {
            perror("fclose");
        }
    }
    exit(EXIT_SUCCESS);
}

// Function to query camera capabilities
int query_camera_capabilities(int fd, camera_capabilities_t *capabilities) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    strncpy(capabilities->card, cap.card, sizeof(capabilities->card) - 1);
    capabilities->card[sizeof(capabilities->card) - 1] = '\0';
    strncpy(capabilities->bus_info, cap.bus_info, sizeof(capabilities->bus_info) - 1);
    capabilities->bus_info[sizeof(capabilities->bus_info) - 1] = '\0';
    strncpy(capabilities->version, cap.version, sizeof(capabilities->version) - 1);
    capabilities->version[sizeof(capabilities->version) - 1] = '\0';
    snprintf(capabilities->capabilities, sizeof(capabilities->capabilities), "0x%08x", cap.capabilities);
    snprintf(capabilities->device_caps, sizeof(capabilities->device_caps), "0x%08x", cap.device_caps);

    printf("Camera Capabilities:\n");
    printf("  Card: %s\n", capabilities->card);
    printf("  Bus Info: %s\n", capabilities->bus_info);
    printf("  Version: %s\n", capabilities->version);
    printf("  Capabilities: %s\n", capabilities->capabilities);
    printf("  Device Capabilities: %s\n", capabilities->device_caps);

    return 0;
}

// Function to configure the camera
int configure_camera(int fd) {
    struct v4l2_format format;
    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = IMAGE_WIDTH;
    format.fmt.pix.height = IMAGE_HEIGHT;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    format.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &format) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    printf("Camera configured: %dx%d %s\n", format.fmt.pix.width, format.fmt.pix.height, (format.fmt.pix.pixelformat == V4L2_PIX_FMT_YUYV) ? "YUYV" : "Unknown");

    return 0;
}

// Function to request a buffer
int request_buffer(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    printf("Buffer requested: %d\n", req.count);

    return 0;
}

// Function to map the buffer
int map_buffer(int fd, void **buffer) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    printf("Buffer mapped at address: %p\n", *buffer);

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    printf("Streaming started\n");

    return 0;
}

// Function to capture a frame
int capture_frame(int fd, void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    printf("Frame captured\n");

    return 0;
}

// Function to process the captured frame
int process_frame(void *buffer, size_t buffer_size, size_t crop_width, size_t crop_height) {
    unsigned char *yuyv_data = (unsigned char *)buffer;
    unsigned char *cropped_data = (unsigned char *)malloc(crop_width * crop_height * 2);
    if (cropped_data == NULL) {
        perror("malloc");
        return -1;
    }

    // Crop and copy YUYV data
    for (size_t y = 0; y < crop_height; y++) {
        for (size_t x = 0; x < crop_width; x++) {
            size_t src_index = (y * IMAGE_WIDTH + x) * 2;
            size_t dst_index = (y * crop_width + x) * 2;
            cropped_data[dst_index] = yuyv_data[src_index];
            cropped_data[dst_index + 1] = yuyv_data[src_index + 1];
        }
    }

    // Write cropped data to file
    output_file = fopen("cropped.yuv", "wb");
    if (output_file == NULL) {
        perror("fopen");
        free(cropped_data);
        return -1;
    }

    size_t bytes_written = fwrite(cropped_data, 1, crop_width * crop_height * 2, output_file);
    if (bytes_written != crop_width * crop_height * 2) {
        perror("fwrite");
        fclose(output_file);
        free(cropped_data);
        return -1;
    }

    printf("Cropped frame written to cropped.yuv\n");

    fclose(output_file);
    free(cropped_data);

    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }

    printf("Streaming stopped\n");

    return 0;
}

// Function to unmap the buffer
int unmap_buffer(void *buffer) {
    if (munmap(buffer, BUFFER_SIZE) == -1) {
        perror("munmap");
        return -1;
    }

    printf("Buffer unmapped\n");

    return 0;
}

int main() {
