#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servo motors
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define neutral servo angle (90 degrees)
#define NEUTRAL_ANGLE 90

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define angle increment/decrement step
#define ANGLE_STEP 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set servo angle
int set_servo_angle(int gpio, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate error
    }

    // Calculate pulse width (in microseconds)
    int pulse_width = 500 + (angle * 2000 / 180); // SG90 servo pulse width range: 500-2500 us

    // Set PWM duty cycle
    int result = gpioPWM(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set PWM for GPIO %d. Error code: %d\n", gpio, result);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO modes for servo control
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(PAN_SERVO_PIN, 255);
    gpioSetPWMrange(TILT_SERVO_PIN, 255);

    // Initialize servos to neutral position
    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        fprintf(stderr, "Error: Failed to set pan servo to neutral position.\n");
        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        fprintf(stderr, "Error: Failed to set tilt servo to neutral position.\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;
    char input;

    printf("Press arrow keys (up/down/left/right) to move servos, or 'q' to quit.\n");

    while (program_running) {
        // Read input from stdin
        input = getchar();

        // Process input
        switch (input) {
            case 'q':
                printf("Quitting...\n");
                program_running = 0;
                break;
            case 'w': // Up arrow
                tilt_angle += ANGLE_STEP;
                if (tilt_angle > MAX_ANGLE) {
                    tilt_angle = MAX_ANGLE;
                }
                if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set tilt servo angle.\n");
                    program_running = 0;
                }
                break;
            case 's': // Down arrow
                tilt_angle -= ANGLE_STEP;
                if (tilt_angle < MIN_ANGLE) {
                    tilt_angle = MIN_ANGLE;
                }
                if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set tilt servo angle.\n");
                    program_running = 0;
                }
                break;
            case 'a': // Left arrow
                pan_angle -= ANGLE_STEP;
                if (pan_angle < MIN_ANGLE) {
                    pan_angle = MIN_ANGLE;
                }
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set pan servo angle.\n");
                    program_running = 0;
                }
                break;
            case 'd': // Right arrow
                pan_angle += ANGLE_STEP;
                if (pan_angle > MAX_ANGLE) {
                    pan_angle = MAX_ANGLE;
                }
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set pan servo angle.\n");
                    program_running = 0;
                }
                break;
            default:
                // Ignore other characters
                break;
        }

        // Delay to prevent excessive servo movement
        usleep(100000); // 100 ms
    }

    // Cleanup: Set servos to neutral position before exiting
    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

