    {0x00, 0x08, 0x36, 0x41, 0x00}, // {
    {0x00, 0x00, 0x00, 0x7F, 0x00}, // |
    {0x00, 0x41, 0x36, 0x08, 0x00}, // }
    {0x00, 0x02, 0x01, 0x02, 0x04}  // ~
};

// Function prototypes
int read_cpu_temp();
float read_cpu_usage();
void oled_init();
void oled_clear();
void oled_write_string(int x, int y, const char *str);
void oled_write_char(int x, int y, char c);
void oled_display_text(const char *cpu_temp_str, const char *cpu_usage_str);
void signal_handler(int signal);

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer);
    } else {
        fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to Celsius
}

// Function to read CPU usage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1.0;
    }

    // Read the first line (CPU stats)
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    sleep(1);

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1.0;
    }

    // Read the first line (CPU stats)
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal;

    unsigned long long prev_idle_all = prev_idle + prev_iowait;
    unsigned long long idle_all = idle + iowait;

    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle_all - prev_idle_all;

    usage = (float)(delta_total - delta_idle) / (float)delta_total * 100.0;

    return usage;
}

// Function to initialize the OLED display
void oled_init() {
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        exit(1);
    }

    // Initialization sequence (SSD1306)
    char init_sequence[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100 fps)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode
        0xA1,       // Segment remap
        0xC8,       // COM output scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Precharge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Normal/Inverse display
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_sequence); i++) {
        if (i2cWriteByteData(i2c_handle, 0x00, init_sequence[i]) < 0) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            exit(1);
        }
    }
}

// Function to clear the OLED display
void oled_clear() {
    char buffer[OLED_WIDTH * (OLED_HEIGHT / 8)];
    memset(buffer, 0, sizeof(buffer));

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer, sizeof(buffer)) < 0) {
        fprintf(stderr, "Error clearing OLED display: %s\n", strerror(errno));
    }
}

// Function to write a string to the OLED display
void oled_write_string(int x, int y, const char *str) {
    int i;
    for (i = 0; str[i] != '\0'; i++) {
        oled_write_char(x + i * 6, y, str[i]);
    }
}

// Function to write a character to the OLED display
void oled_write_char(int x, int y, char c) {
    if (c < 32 || c > 126) c = 0; // Handle out-of-range characters
    c -= 32;

    char buffer[8];
    for (int i = 0; i < 5; i++) {
        buffer[i] = font[c][i];
    }
    buffer[5] = 0x00; // Add a null byte for padding
    buffer[6] = 0x00;
    buffer[7] = 0x00;

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer, 8) < 0) {
        fprintf(stderr, "Error writing character to OLED: %s\n", strerror(errno));
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40 + 8, buffer, 8) < 0) {
        fprintf(stderr, "Error writing character to OLED: %s\n", strerror(errno));
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40 + 16, buffer, 8) < 0) {
        fprintf(stderr, "Error writing character to OLED: %s\n", strerror(errno));
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40 + 24, buffer, 8) < 0) {
        fprintf(stderr, "Error writing character to OLED: %s\n", strerror(errno));
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40 + 32, buffer, 8) < 0) {
        fprintf(stderr, "Error writing character to OLED: %s\n", strerror(errno));
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40 + 40, buffer, 8) < 0) {
        fprintf(stderr, "Error writing character to OLED: %s\n", strerror(errno));
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40 + 48, buffer, 8) < 0) {
        fprintf(stderr, "Error writing character to OLED: %s\n", strerror(errno));
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40 + 56, buffer, 8) < 0) {
        fprintf(stderr, "Error writing character to OLED: %s\n", strerror(errno));
    }

}

// Function to display text on the OLED
void oled_display_text(const char *cpu_temp_str, const char *cpu_usage_str) {
    oled_clear();
    oled_write_string(0, 0, cpu_temp_str);
    oled_write_string(0, 16, cpu_usage_str);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize OLED display
    oled_init();

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature and CPU usage
        int cpu_temp = read_cpu_temp();
        float cpu_usage = read_cpu_usage();

        // Format strings
        char cpu_temp_str[20];
        char cpu_usage_str[20];

        if (cpu_temp == -1) {
            strcpy(cpu_temp_str, "Temp Err");
        } else {
            snprintf(cpu_temp_str, sizeof(cpu_temp_str), "Temp: %dC", cpu_temp);
        }

        if (cpu_usage == -1.0) {
            strcpy(cpu_usage_str, "Usage Err");
        } else {
            snprintf(cpu_usage_str, sizeof(cpu_usage_str), "Usage: %.2f%%", cpu_usage);
        }

        // Display text on OLED
        oled_display_text(cpu_temp_str, cpu_usage_str);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

