#define LCD_D4 23
#define LCD_D5 22
#define LCD_D6 21
#define LCD_D7 14

// Define I2C address for LCD
#define LCD_ADDR 0x27

// Define LCD constants
#define LCD_CHR 1
#define LCD_CMD 0

#define LCD_LINE_1 0x80 // 1st line
#define LCD_LINE_2 0xC0 // 2nd line

#define LCD_BACKLIGHT 0x08  // On
// #define LCD_BACKLIGHT 0x00  // Off

#define ENABLE 0b00000100 // Enable bit

// Global variables
volatile int pulse_count = 0;
volatile double flow_rate = 0.0;
double total_volume = 0.0;
int i2c_handle;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulses);
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);

// Function to handle pulses from the water flow sensor
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in liters per minute
double calculate_flow_rate(int pulses)
{
    // Calibration factor: Adjust this based on your sensor's datasheet
    // and experimental calibration.
    // Example: 7.5 pulses per liter
    double calibration_factor = 7.5;
    return (double)pulses / calibration_factor * 60.0; // Liters per minute
}

// Function to update the LCD display
void update_lcd(double flow_rate, double total_volume)
{
    char buffer[17];

    // Clear LCD
    i2cWriteByteData(i2c_handle, LCD_CMD, 0x01); // Clear display
    gpioDelay(2000); // Delay 2ms

    // Set cursor to the first line
    i2cWriteByteData(i2c_handle, LCD_CMD, 0x80); // Set cursor to line 1, position 0
    gpioDelay(1000); // Delay 1ms

    // Flow Rate
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow_rate);
    for (int i = 0; buffer[i] != '\0'; i++)
    {
        i2cWriteByteData(i2c_handle, LCD_CHR, buffer[i]);
    }

    // Set cursor to the second line
    i2cWriteByteData(i2c_handle, LCD_CMD, 0xC0); // Set cursor to line 2, position 0
    gpioDelay(1000); // Delay 1ms

    // Total Volume
    snprintf(buffer, sizeof(buffer), "Total: %.2f L", total_volume);
    for (int i = 0; buffer[i] != '\0'; i++)
    {
        i2cWriteByteData(i2c_handle, LCD_CHR, buffer[i]);
    }
}

