{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set up interrupt on GPIO17 (rising edge)
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter, NULL);

    // Initialize I2C communication
    i2c_handle = i2cOpen(1, LCD_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0)
    {
        fprintf(stderr, "I2C initialisation failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD (Simplified 4-bit mode)
    i2cWriteByteData(i2c_handle, LCD_CMD, 0x33); // Initialize
    i2cWriteByteData(i2c_handle, LCD_CMD, 0x32); // Initialize
    i2cWriteByteData(i2c_handle, LCD_CMD, 0x28); // 4-bit mode, 2 lines, 5x8 font
    i2cWriteByteData(i2c_handle, LCD_CMD, 0x0C); // Display on, cursor off, blink off
    i2cWriteByteData(i2c_handle, LCD_CMD, 0x06); // Increment cursor, no shift
    i2cWriteByteData(i2c_handle, LCD_CMD, 0x01); // Clear display
    gpioDelay(2000); // Delay 2ms

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        // Read pulse count
        int current_pulses = pulse_count;
        pulse_count = 0; // Reset pulse count

        // Calculate flow rate
        flow_rate = calculate_flow_rate(current_pulses);

        // Accumulate total volume
        total_volume += (double)current_pulses / 7.5 * 0.1; // Assuming 7.5 pulses/liter

        // Log data to console
        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);

        // Update LCD every 10 seconds
        update_lcd(flow_rate, total_volume);
        gpioDelay(10000000); // Delay 10 seconds (10000000 microseconds)
    }

    return 0;
}

