#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define WIND_DIRECTION_CHANNEL 0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSES_PER_METER 1000 // Example value, adjust based on anemometer
#define SAMPLE_WINDOW_MS 500
#define LOG_FILE "wind_data.log"

// Global variables
volatile int pulse_count = 0;
int spi_fd;
int lcd_fd;
FILE *log_file;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
float calculate_wind_speed(int pulse_count, int sample_window_ms);
int read_wind_direction(int spi_channel, int spi_speed);
void lcd_init(int i2c_address);
void lcd_clear(int fd);
void lcd_print(int fd, int row, int col, const char *text);
void log_data(float wind_speed, int wind_direction);
void signal_handler(int signal);

// LCD commands
const unsigned char lcd_init_cmds[] = {
    0x33, // Initialize
    0x32, // Set to 4-bit mode
    0x06, // Cursor move direction
    0x0C, // Turn on display, cursor blinking
    0x28  // Data length, number of lines, font size
};

const unsigned char lcd_clear_cmd = 0x01;

// Function to initialize the LCD
void lcd_init(int i2c_address) {
    lcd_fd = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (lcd_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", lcd_fd);
        perror("i2cOpen");
        exit(1);
    }

    // Initialize LCD
    for (size_t i = 0; i < sizeof(lcd_init_cmds); ++i) {
        unsigned char cmd = lcd_init_cmds[i];
        unsigned char data_u, data_l;
        data_u = (cmd & 0xF0);
        data_l = ((cmd << 4) & 0xF0);

        i2cWriteByteData(lcd_fd, data_u | 0x0C, data_u | 0x08); // Enable pulse
        i2cWriteByteData(lcd_fd, data_u | 0x08, data_u | 0x08); // Disable pulse
        i2cWriteByteData(lcd_fd, data_l | 0x0C, data_l | 0x08); // Enable pulse
        i2cWriteByteData(lcd_fd, data_l | 0x08, data_l | 0x08); // Disable pulse
        gpioDelay(5); // Delay
    }
}

// Function to clear the LCD
void lcd_clear(int fd) {
    i2cWriteByteData(fd, lcd_clear_cmd, lcd_clear_cmd);
    gpioDelay(2); // Delay
}

// Function to print text to the LCD
void lcd_print(int fd, int row, int col, const char *text) {
    unsigned char addr;
    if (row == 0) {
        addr = 0x80 + col;
    } else {
        addr = 0xC0 + col;
    }

    i2cWriteByte(fd, addr);

    for (size_t i = 0; i < strlen(text); ++i) {
        i2cWriteByte(fd, text[i]);
    }
}

// Interrupt handler for anemometer pulses
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate wind speed in m/s
float calculate_wind_speed(int pulse_count, int sample_window_ms) {
    float wind_speed = (float)pulse_count / ((float)sample_window_ms / 1000.0) * (3.6 / PULSES_PER_METER); // m/s
    return wind_speed;
}

// Function to read wind direction from MCP3008 ADC
int read_wind_direction(int spi_channel, int spi_speed) {
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | WIND_DIRECTION_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to log data to file
void log_data(float wind_speed, int wind_direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

