// LCD1602 functions implementation
void lcd_init() {
    // Initialization sequence (simplified)
    gpioDelay(50000); // Wait 50ms
    char init_sequence[] = {0x33, 0x32, 0x28, 0x0C, 0x06};
    for (int i = 0; i < sizeof(init_sequence); i++) {
        char buf[2];
        buf[0] = 0x80; // Control byte: command
        buf[1] = init_sequence[i];
        i2cWriteDevice(i2c_handle, buf, 2);
        gpioDelay(5000); // Delay 5ms
    }
}

void lcd_clear() {
    char buf[2];
    buf[0] = 0x80; // Control byte: command
    buf[1] = 0x01; // Clear display command
    i2cWriteDevice(i2c_handle, buf, 2);
    gpioDelay(2000); // Delay 2ms
}

void lcd_set_cursor(int row, int col) {
    char buf[2];
    buf[0] = 0x80; // Control byte: command
    buf[1] = 0x80 + (row * 0x40) + col; // Set cursor position
    i2cWriteDevice(i2c_handle, buf, 2);
    gpioDelay(2000); // Delay 2ms
}

void lcd_print(const char *str) {
    char buf[32];
    buf[0] = 0x40; // Control byte: data
    strcpy(buf + 1, str);
    i2cWriteDevice(i2c_handle, buf, strlen(str) + 1);
    gpioDelay(2000); // Delay 2ms
}

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

