    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    lcd_init();
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioSetAlertFuncEx(SENSOR_GPIO, NULL, NULL); // Disable callback
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (initialize_lcd() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for sensor input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Set alert function for pulse counting
    if (gpioSetAlertFuncEx(SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_pulse_time = time(NULL);
    int sensor_absent = 0;

    // Main loop
    while (running) {
        gpioDelay(1000); // Wait for 1 second

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate
        display_flow_rate(flow_rate);

        // Log flow rate
        log_flow_rate(flow_rate);

        // Reset pulse count
        pulse_count = 0;

        // Check for sensor absence
        if (pulse_count == 0) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_pulse_time) > SENSOR_ABSENT_TIMEOUT) {
                if (!sensor_absent) {
                    printf("Sensor appears to be absent!\n");
                    lcd_clear();
                    lcd_set_cursor(0, 0);
                    lcd_print("Sensor Absent!");
                    sensor_absent = 1;
                }
            } else {
                sensor_absent = 0; // Reset if pulses are detected
            }
        } else {
            last_pulse_time = time(NULL);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

