#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};
const int num_rows = 8;
const int num_cols = 8;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to clear all rows and columns
int clear_matrix() {
    for (int i = 0; i < num_rows; i++) {
        if (set_gpio_state(row_pins[i], 0) != 0) return -1;
    }
    for (int i = 0; i < num_cols; i++) {
        if (set_gpio_state(col_pins[i], 1) != 0) return -1;
    }
    return 0;
}

// Function to display a single frame of the left-to-right animation
int left_to_right_animation() {
    for (int col = 0; col < num_cols; col++) {
        if (clear_matrix() != 0) return -1;
        for (int row = 0; row < num_rows; row++) {
            if (set_gpio_state(row_pins[row], 1) != 0) return -1;
            if (set_gpio_state(col_pins[col], 0) != 0) return -1;
            gpioDelay(800); // Delay for 800 microseconds
        }
    }
    return 0;
