#include <unistd.h>

// VL53L3CX I2C address
#define VL53L3CX_ADDR 0x29

// Register definitions (example, adjust based on datasheet)
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L3CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L3CX_REG_SYSTEM_START 0x0010
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_SPAD_NB 0x0022
#define VL53L3CX_REG_RESULT_SIGNAL_RATE 0x001E
#define VL53L3CX_REG_RESULT_AMBIENT_RATE 0x0020
#define VL53L3CX_REG_RESULT_DISTANCE 0x001A
#define VL53L3CX_REG_RESULT_TARGET_STATUS 0x0024

// Number of targets to read
#define NUM_TARGETS 4

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint8_t status;
    uint16_t distance;
} sensor_data_t;

// Function prototypes
int init_vl53l3cx();
int read_sensor_data(sensor_data_t *data);
void print_data(sensor_data_t *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L3CX sensor
int init_vl53l3cx() {
    // Check sensor ID
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, buf, 2) != 2) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    uint16_t model_id = (buf[0] << 8) | buf[1];
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor model ID: 0x%04X\n", model_id);
        return -1;
    }

    // Example initialization sequence (replace with actual sequence from datasheet)
    // This is a placeholder, actual initialization requires specific register writes
    char init_data[] = {0x01, 0x02, 0x03, 0x04};
    for (int i = 0; i < sizeof(init_data); i++) {
        if (i2cWriteByteData(i2c_handle, 0x2000 + i, init_data[i]) != 0) {
            fprintf(stderr, "Error writing initialization data\n");
            return -1;
        }
    }

    // Start the sensor (replace with actual register and value)
    if (i2cWriteByteData(i2c_handle, VL53L3CX_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error starting sensor\n");
        return -1;
    }

    return 0;
}

// Read distance data from the VL53L3CX sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[6]; // 2 bytes status + 4 bytes distance

    if (i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_RESULT_RANGE_STATUS, buf, 6) != 6) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    data->status = buf[0];
    data->distance = (buf[1] << 8) | buf[2];

    return 0;
}

// Print the sensor data with timestamp
void print_data(sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s,", timestamp);
    for (int i = 0; i < NUM_TARGETS; i++) {
        printf("%d", data[i].distance);
        if (i < NUM_TARGETS - 1) {
            printf(",");
        }
    }
    printf("\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_vl53l3cx() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data[NUM_TARGETS];
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Print the data
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

