#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PROXIMITY_SENSOR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_proximity_sensor();
int detect_falling_edge(int current_state, int previous_state);
int log_event(const char *timestamp);
int blink_led();
void cleanup();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int previous_sensor_state;
} ProgramState;

ProgramState state = {1}; // Initialize previous sensor state to HIGH (no object detected)

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read proximity sensor
        int sensor_value = read_proximity_sensor();

        // Detect falling edge
        if (detect_falling_edge(sensor_value, state.previous_sensor_state)) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30]; // Increased size to accommodate ISO 8601 format

            time(&rawtime);
            timeinfo = gmtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log event
            if (log_event(timestamp) != 0) {
                fprintf(stderr, "Failed to log event.\n");
            }

            // Blink LED
            if (blink_led() != 0) {
                fprintf(stderr, "Failed to blink LED.\n");
            }
        }

        // Update previous sensor state
        state.previous_sensor_state = sensor_value;

        // Wait 100 milliseconds
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PROXIMITY_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read proximity sensor value
int read_proximity_sensor() {
    return gpioRead(PROXIMITY_SENSOR_PIN);
}

// Detect falling edge
int detect_falling_edge(int current_state, int previous_state) {
    return (previous_state == 1 && current_state == 0);
}

// Log event to file
int log_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s Object detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        perror("Log file is not open");
        return 1;
    }
}

// Blink LED
int blink_led() {
