typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function to initialize the Si1145 sensor
int init_si1145() {
    // Reset the device (example initialization sequence, adjust as needed)
    if (i2cWriteByteData(i2c_handle, 0x17, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
    }
    gpioDelay(10); // Delay for reset to complete

    // Configure the sensor (example configuration, adjust as needed)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x7B) < 0) {
        fprintf(stderr, "Error: Failed to configure Si1145\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(int *proximity, int *ambient_light) {
    int prox, als;

    // Read proximity data
    prox = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    if (prox < 0) {
        fprintf(stderr, "Error: Failed to read proximity data\n");
        return -1;
    }

    // Read ambient light data
    als = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (als < 0) {
        fprintf(stderr, "Error: Failed to read ambient light data\n");
        return -1;
    }

    *proximity = prox;
    *ambient_light = als;

    return 0;
}

