#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define MAX_DISTANCE 400         // centimeters
#define MIN_DISTANCE 2           // centimeters
#define TIMEOUT_US 30000          // microseconds (30 milliseconds)
#define LOG_INTERVAL_SEC 60       // seconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long long getPulseWidth();
float calculateDistance(long long pulse_width);
void logDistance(float distance);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set TRIGGER pin HIGH
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set TRIGGER pin LOW
}

// Function to measure the echo pulse width
long long getPulseWidth() {
    long long start_tick, end_tick, pulse_width;

    // Wait for the ECHO pin to go HIGH (start of the pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout: ECHO pin never went HIGH
    }

    start_tick = gpioTick();

    // Wait for the ECHO pin to go LOW (end of the pulse)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        return -2; // Timeout: ECHO pin never went LOW
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Error: Invalid pulse width
    }

    // Speed of sound in air (cm/us) = 0.0343 cm/us
    // Distance (cm) = (pulse_width * 0.0343) / 2
    float distance = (float)pulse_width * 0.0343 / 2.0;

    return distance;
}

// Function to log the distance to a file
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately

        if (distance < 15.0) {
            fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
            fflush(log_file);
        }
    } else {
        fprintf(log_file, "%s, Error: Distance out of range (%.2f cm)\n", timestamp, distance);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long long pulse_width = getPulseWidth();

        if (pulse_width < 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            if (pulse_width == -1) {
                fprintf(log_file, "%s, Error: Timeout waiting for ECHO HIGH\n", timestamp);
                fflush(log_file);
            } else if (pulse_width == -2) {
                fprintf(log_file, "%s, Error: Timeout waiting for ECHO LOW\n", timestamp);
                fflush(log_file);
            }
        } else {
            float distance = calculateDistance(pulse_width);

            if (distance >= 0) {
                logDistance(distance);
            } else {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

                fprintf(log_file, "%s, Error: Invalid pulse width\n", timestamp);
                fflush(log_file);
            }
        }

        sleep(LOG_INTERVAL_SEC);
    }

    // Close the log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

