#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_proximity(uint16_t *proximity);
int apds9960_read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t proximity, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the APDS9960 sensor
int apds9960_init() {
    // Enable proximity sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x02) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set proximity pulse length and number of pulses
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Set gain
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set proximity time
    if (i2cWriteByteData(i2c_handle, APDS9960_PTIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to PTIME register\n");
        return -1;
    }

    // Set wait time
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to WTIME register\n");
        return -1;
    }

    return 0;
}

// Read proximity value from the sensor
int apds9960_read_proximity(uint16_t *proximity) {
    int retries = 3;
    while (retries > 0) {
        int data = i2cReadWordData(i2c_handle, APDS9960_PDATA);
        if (data >= 0) {
            *proximity = (uint16_t)data;
            return 0;
        } else {
            fprintf(stderr, "Error reading proximity data, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read proximity data after multiple retries\n");
    return -1;
}

// Read RGB color values from the sensor
int apds9960_read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int retries = 3;
    while (retries > 0) {
        int r_low = i2cReadByteData(i2c_handle, APDS9960_RDATAL);
        int r_high = i2cReadByteData(i2c_handle, APDS9960_RDATAH);
        int g_low = i2cReadByteData(i2c_handle, APDS9960_GDATAL);
        int g_high = i2cReadByteData(i2c_handle, APDS9960_GDATAH);
        int b_low = i2cReadByteData(i2c_handle, APDS9960_BDATAL);
        int b_high = i2cReadByteData(i2c_handle, APDS9960_BDATAH);

        if (r_low >= 0 && r_high >= 0 && g_low >= 0 && g_high >= 0 && b_low >= 0 && b_high >= 0) {
            *red = (uint16_t)((r_high << 8) | r_low);
            *green = (uint16_t)((g_high << 8) | g_low);
            *blue = (uint16_t)((b_high << 8) | b_low);
            return 0;
        } else {
            fprintf(stderr, "Error reading RGB data, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read RGB data after multiple retries\n");
    return -1;
}

// Log data to CSV file
void log_data(uint16_t proximity, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

