#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// CH101 I2C address
#define CH101_ADDR 0x70

// CH101 register addresses
#define CH101_REG_CONFIG 0x00
#define CH101_REG_TRIGGER 0x01
#define CH101_REG_DISTANCE_HIGH 0x02
#define CH101_REG_DISTANCE_LOW 0x03

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_ch101();
int read_distance(int *distance);
int log_distance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize CH101 sensor
int init_ch101() {
    // Configure the sensor (example: continuous mode, 100ms measurement period)
    // Refer to the CH101 datasheet for the correct configuration values
    char config_data[2] = {0x01, 0x00}; // Example: Continuous mode, 100ms
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to CH101 configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance from CH101 sensor
int read_distance(int *distance) {
    char trigger_data[1] = {0x01}; // Trigger measurement
    int result;

    // Trigger measurement
    result = i2cWriteDevice(i2c_handle, trigger_data, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to CH101 trigger register: %d\n", result);
        return -1;
    }

    // Wait for measurement (adjust as needed based on sensor datasheet)
    gpioDelay(50000); // 50 ms

    // Read distance data (high byte and low byte)
    char distance_data[2];
    result = i2cReadDevice(i2c_handle, distance_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from CH101 distance registers: %d\n", result);
        return -1;
    }

    // Combine high and low bytes to get the distance
    *distance = (distance_data[0] << 8) | distance_data[1];

    return 0;
}

// Log distance to file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, %d\n", timestamp, distance);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize CH101 sensor
    if (init_ch101() != 0) {
        fprintf(stderr, "CH101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;
    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(200000); // 200 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

