#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define COMMAND_FRAME_SIZE 4
#define RESPONSE_FRAME_SIZE 15
#define NUM_SAMPLES 10
#define SAMPLE_DELAY_MS 100
#define INTRUSION_THRESHOLD_MM 1000
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(const uint8_t *command, int length);
int read_response(uint8_t *response, int length);
int verify_header(const uint8_t *response);
int extract_distance(const uint8_t *response);
float calculate_average_distance(int *distances, int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command frame to the sensor
int send_command(const uint8_t *command, int length) {
    int result = i2cWriteDevice(i2c_handle, (char *)command, length);
    if (result != length) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read response frame from the sensor
int read_response(uint8_t *response, int length) {
    int result = i2cReadDevice(i2c_handle, (char *)response, length);
    if (result != length) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify the header byte of the response frame
int verify_header(const uint8_t *response) {
    if (response[0] != 0x01) {
        fprintf(stderr, "Error: Invalid header byte: 0x%02X\n", response[0]);
        return -1;
    }
    return 0;
}

// Extract the distance from the response frame
int extract_distance(const uint8_t *response) {
    int distance = (response[11] << 8) | response[12];
    return distance;
}

// Calculate the average distance from multiple samples
float calculate_average_distance(int *distances, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return (float)(sum / num_samples);
}

// Log intrusion event to file
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fclose(log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Command frame (B5L-LD50-07050 specific)
    uint8_t command_frame[COMMAND_FRAME_SIZE] = {0x01, 0x02, 0x03, 0x04};

    // Response frame
    uint8_t response_frame[RESPONSE_FRAME_SIZE];

    // Intrusion detection loop
    while (!terminate) {
        int distances[NUM_SAMPLES];

        // Take multiple samples
        for (int i = 0; i < NUM_SAMPLES; i++) {
            // Send command
            if (send_command(command_frame, COMMAND_FRAME_SIZE) != 0) {
                fprintf(stderr, "Error sending command, retrying...\n");
                gpioDelay(100); // Wait before retrying
                continue; // Retry the sample
            }

            gpioDelay(10); // Wait for 10 ms

            // Read response
            if (read_response(response_frame, RESPONSE_FRAME_SIZE) != 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                gpioDelay(100); // Wait before retrying
                continue; // Retry the sample
            }

            // Verify header
            if (verify_header(response_frame) != 0) {
                fprintf(stderr, "Error verifying header, retrying...\n");
                gpioDelay(100); // Wait before retrying
                continue; // Retry the sample
            }

            // Extract distance
            int distance = extract_distance(response_frame);
            distances[i] = distance;

            gpioDelay(SAMPLE_DELAY_MS); // Delay between samples
        }

        // Calculate average distance
        float average_distance = calculate_average_distance(distances, NUM_SAMPLES);

        // Log intrusion event
        if (average_distance < INTRUSION_THRESHOLD_MM) {
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion event\n");
            }
        }

        gpioDelay(SAMPLE_DELAY_MS * 10); // Delay between cycles
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

