#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L0X_REG_RESULT_RANGE_STATUS       0x0014
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L0X_REG_INTERRUPT_CLEAR           0x0086
#define VL53L0X_REG_START_STOP_CONTROL        0x0400
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS   0x0089

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l0x();
int read_distance();
void signal_handler(int signal);

// Structure to hold sensor configuration (optional)
typedef struct {
    int io_timeout_ms;
    int inter_measurement_period_ms;
} sensor_config_t;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x() {
    // Check sensor ID
    int model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X). Expected 0xEA.\n", model_id);
        return -1;
    }

    // Initialize sensor (example: set to short-range mode)
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_START_STOP_CONTROL, 0x04) < 0) {
        fprintf(stderr, "Error writing to start/stop control register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance() {
    int distance = -1;
    int status;
    int timeout_count = 0;

    // Poll RESULT_INTERRUPT_STATUS with timeout
    while (timeout_count < 10) {
        status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading RESULT_INTERRUPT_STATUS: %s\n", strerror(errno));
            return -1;
        }
        if (status & 0x01) {
            break; // Data ready
        }
        gpioDelay(10000); // 10ms delay
        timeout_count++;
    }

    if (timeout_count >= 10) {
        fprintf(stderr, "Timeout waiting for data ready.\n");
        return -1;
    }

    // Read distance
    distance = i2cReadWordData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error writing to interrupt clear register: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x() != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
