#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4A

// Define the register address for distance data (example, adjust as needed)
#define DISTANCE_REG 0x00 // Example register address

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl-C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read distance data from the sensor
int read_distance(int fd) {
    unsigned char buf[2]; // Assuming distance data is 2 bytes
    int bytes_read = read(fd, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Convert the received bytes to an integer (adjust based on sensor data format)
    int distance = (buf[0] << 8) | buf[1];

    return distance;
}

int main() {
    // Install signal handler for Ctrl-C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MLX75030_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Verify sensor presence by reading a register
    unsigned char test_buf[1];
    test_buf[0] = DISTANCE_REG; // Assuming DISTANCE_REG is the register to read
    if (write(i2c_fd, test_buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device. Sensor might not be present. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance. Continuing...\n");
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

