    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance from channel 0
        int16_t distance = read_opt3101_value(i2c_handle, REG_DISTANCE_CH0);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Read ambient light value
