// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(TRIGGER_PULSE_US); // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to measure the echo pulse duration
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go HIGH (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Wait 1 microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go LOW (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Wait 1 microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo falling edge timeout\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    if (pulse_width <= 0) {
        fprintf(stderr, "Error: Invalid pulse width (%ld)\n", pulse_width);
        return -1; // Invalid pulse width
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND_CM_US / 2.0;
}

// Function to log the distance with a timestamp
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor(); // Trigger the sensor
        long pulse_width = measurePulseWidth(); // Measure the echo pulse width

        if (pulse_width > 0) {
            float distance = calculateDistance(pulse_width); // Calculate the distance
            logDistance(distance); // Log the distance
        } else {
            fprintf(stderr, "Error: Failed to measure distance\n");
        }

        gpioDelay(1000000); // Wait for 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

