#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

// Constants
#define UART_PORT "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_PIN 17
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define NUM_BINS 64
#define TARGET_THRESHOLD 1.0 // meters
#define ALERT_DURATION 2 // seconds

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure for UART configuration
typedef struct {
    char *port;
    int baud_rate;
} uart_config_t;

// Structure for GPIO configuration
typedef struct {
    int pin;
} gpio_config_t;

// Function prototypes
int initialize_uart(uart_config_t config);
void close_uart(int fd);
int initialize_gpio(gpio_config_t config);
void cleanup_gpio(int pin);
int read_range_profile(int fd, uint8_t *buffer, size_t size);
int decode_range_profile(const uint8_t *buffer, int16_t *range_profile);
int check_for_target(const int16_t *range_profile, int num_bins, float threshold);
int log_intrusion(const char *timestamp, float distance);
void activate_alert(int pin, int duration);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize UART
int initialize_uart(uart_config_t config) {
    int fd = open(config.port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, config.baud_rate);
    cfsetispeed(&tty, config.baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_iflag = 0;

    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to close UART
void close_uart(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

// Function to initialize GPIO
int initialize_gpio(gpio_config_t config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config.pin, PI_OUTPUT);
    gpioWrite(config.pin, 0); // Ensure LED is off initially
    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio(int pin) {
    gpioWrite(pin, 0); // Turn off LED
    gpioTerminate();
}

// Function to read range profile from UART
int read_range_profile(int fd, uint8_t *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != size) {
        fprintf(stderr, "Incomplete read: expected %zu bytes, got %zd\n", size, bytes_read);
        return -1;
    }
    return 0;
}

// Function to decode range profile data
int decode_range_profile(const uint8_t *buffer, int16_t *range_profile) {
    // Assuming little-endian format
    for (int i = 0; i < NUM_BINS; i++) {
        range_profile[i] = (int16_t)((buffer[i * 2] << 8) | buffer[i * 2 + 1]);
    }
    return 0;
}

// Function to check for target within threshold
int check_for_target(const int16_t *range_profile, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (range_profile[i] <= threshold * 1000) { // Convert meters to mm
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Function to log intrusion event
int log_intrusion(const char *timestamp, float distance) {
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Function to activate alert (LED)
void activate_alert(int pin, int duration) {
    gpioWrite(pin, 1); // Turn on LED
    gpioDelay(duration * 1000000); // Delay for specified duration (microseconds)
    gpioWrite(pin, 0); // Turn off LED
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int main() {
    // UART configuration
    uart_config_t uart_config = {
        .port = UART_PORT,
        .baud_rate = BAUD_RATE
    };

    // GPIO configuration
    gpio_config_t gpio_config = {
        .pin = GPIO_PIN
    };

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = initialize_uart(uart_config);
    if (uart_fd == -1) {
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(gpio_config) == -1) {
        close_uart(uart_fd);
        return 1;
    }

    uint8_t buffer[RANGE_PROFILE_SIZE];
    int16_t range_profile[NUM_BINS];
    char *timestamp;

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read range profile data
        if (read_range_profile(uart_fd, buffer, RANGE_PROFILE_SIZE) == 0) {
            // Decode range profile
            if (decode_range_profile(buffer, range_profile) == 0) {
                // Check for target
                if (check_for_target(range_profile, NUM_BINS, TARGET_THRESHOLD)) {
                    // Get timestamp
                    timestamp = get_iso8601_timestamp();

                    // Log intrusion
                    if (log_intrusion(timestamp, TARGET_THRESHOLD) == 0) {
                        printf("Intrusion detected at %s, distance: %.2f meters\n", timestamp, TARGET_THRESHOLD);
                    } else {
                        fprintf(stderr, "Error logging intrusion event\n");
                    }

                    // Activate alert
                    activate_alert(GPIO_PIN, ALERT_DURATION);

                    free(timestamp); // Free the allocated memory
                }
            } else {
                fprintf(stderr, "Error decoding range profile\n");
            }
        } else {
            fprintf(stderr, "Error reading range profile\n");
        }

        gpioDelay(10000); // Delay for 10ms (adjust as needed)
    }

    // Cleanup
    close_uart(uart_fd);
    cleanup_gpio(GPIO_PIN);

    printf("Exiting.\n");
    return 0;
}

