// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x64 // Replace with the actual I2C address
#define DISTANCE_REG 0x00 // Replace with the actual register address
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
int log_data(float distance);
int set_alert(int state);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance: %d\n", bytes_read);
        return -1;
    }

    // Assuming the sensor returns distance in millimeters
    int16_t raw_distance = (buf[0] << 8) | buf[1];
    *distance = (float)raw_distance / 10.0; // Convert to cm

    return 0;
}

// Log data to file
int log_data(float distance) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        free(timestamp);
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fclose(log_file);
    free(timestamp);
    return 0;
}

// Set alert GPIO pin
int set_alert(int state) {
    gpioWrite(ALERT_GPIO, state);
    return 0;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;
    int alert_active = 0;

    printf("Starting distance monitoring...\n");

    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);

            if (log_data(distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            if (distance < DISTANCE_THRESHOLD && !alert_active) {
                set_alert(1);
                alert_active = 1;
                printf("Alert activated!\n");
            } else if (distance >= DISTANCE_THRESHOLD && alert_active) {
                set_alert(0);
                alert_active = 0;
                printf("Alert deactivated.\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Turn off alert
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

