#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define DISTANCE_REG 0x00 // Example register address, adjust as needed
#define MAX_DISTANCE 2000 // Maximum expected distance in mm
#define MIN_DISTANCE 100  // Minimum expected distance in mm

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
void control_led(int distance);
void log_data(int distance, int led_frequency);
void signal_handler(int signal);

// Structure for CH201 configuration (example)
typedef struct {
    uint8_t integration_time;
    uint8_t modulation_frequency;
} ch201_config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];

    // Validate distance reading
    if (*distance < MIN_DISTANCE || *distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance reading: %d\n", *distance);
        return -1;
    }

    return 0;
}

// Control LED blinking frequency based on distance
void control_led(int distance) {
    // Map distance to blink frequency (example: inverse relationship)
    int frequency = 1000000 / (distance * 2); // Calculate period in microseconds

    // Blink the LED
    gpioWrite(LED_GPIO, 1); // LED on
    gpioDelay(frequency / 2); // Half period on
    gpioWrite(LED_GPIO, 0); // LED off
    gpioDelay(frequency / 2); // Half period off
}

// Log timestamped distance and LED blink frequency to stdout
void log_data(int distance, int led_frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

