    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t distance;
        int retries = 0;

        // Retry mechanism for I2C communication
        while (retries < MAX_RETRIES) {
            if (trigger_measurement() == 0) {
                gpioDelay(10); // Wait for measurement to complete (adjust as needed)
                if (read_distance(&distance) == 0) {
                    log_data(distance);
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "Read failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "Trigger failed, retrying...\n");
            }
            retries++;
            gpioDelay(RETRY_DELAY_MS);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, skipping measurement.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

