#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_MS 50

static volatile int running = 1;
FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to a file
void log_event(int sensor_id, const char *event_type) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s Sensor %d %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
    free(timestamp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int sensor1_state = 0;
    int sensor2_state = 0;
    int prev_sensor1_state = 0;
    int prev_sensor2_state = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    printf("Starting sensor monitoring...\n");

    while (running) {
        // Read sensor states
        sensor1_state = gpioRead(SENSOR_1_GPIO);
        sensor2_state = gpioRead(SENSOR_2_GPIO);

        // Debounce sensor 1
        if (sensor1_state != prev_sensor1_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
            if (sensor1_state != gpioRead(SENSOR_1_GPIO)) {
                prev_sensor1_state = sensor1_state;
                if (sensor1_state == 0) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
            }
        }

        // Debounce sensor 2
        if (sensor2_state != prev_sensor2_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
            if (sensor2_state != gpioRead(SENSOR_2_GPIO)) {
                prev_sensor2_state = sensor2_state;
                if (sensor2_state == 0) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
            }
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

