#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_MSB_REG 0x01
#define DISTANCE_LSB_REG 0x02
#define MEAS_STATUS_READY 0x01
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave_address(int fd, int addr);
int i2c_write_read(int fd, uint8_t *write_data, int write_len, uint8_t *read_data, int read_len);
int read_distance(int fd, uint16_t *distance);
int log_data(FILE *fp, const char *timestamp, uint16_t distance);
void signal_handler(int sig);
char* get_iso8601_timestamp();

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave_address(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write and read function
int i2c_write_read(int fd, uint8_t *write_data, int write_len, uint8_t *read_data, int read_len) {
    if (write_len > 0) {
        if (write(fd, write_data, write_len) != write_len) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            return -1;
        }
    }

    if (read_len > 0) {
        if (read(fd, read_data, read_len) != read_len) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Read distance function
int read_distance(int fd, uint16_t *distance) {
    uint8_t write_data[1] = {MEAS_STATUS_REG};
    uint8_t read_data[2];
    int retries = TIMEOUT_MS / 10; // Number of retries based on timeout

    // Poll MEAS_STATUS register until it's ready
    while (retries > 0) {
        if (i2c_write_read(fd, write_data, 1, read_data, 1) == 0) {
            if ((read_data[0] & MEAS_STATUS_READY) == MEAS_STATUS_READY) {
                break; // Measurement ready
            }
        } else {
            fprintf(stderr, "Error reading MEAS_STATUS, retrying...\n");
        }
        usleep(10000); // 10ms delay
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Timeout waiting for MEAS_STATUS ready\n");
        return -1;
    }

    // Read distance data
    write_data[0] = DISTANCE_MSB_REG;
    if (i2c_write_read(fd, write_data, 1, read_data, 2) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    *distance = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Log data function
int log_data(FILE *fp, const char *timestamp, uint16_t distance) {
    if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
