// Function to read the distance data for all zones
int read_zone_data(int fd, uint16_t *zone_data) {
    uint8_t data[DATA_BYTES];

    if (read_block(fd, DATA_REG, data, DATA_BYTES) != 0) {
        fprintf(stderr, "Failed to read zone data\n");
        return -1;
    }

    // Convert the byte data to uint16_t (assuming little-endian)
    for (int i = 0; i < NUM_ZONES; i++) {
        zone_data[i] = (uint16_t)data[i * ZONE_BYTES] | ((uint16_t)data[i * ZONE_BYTES + 1] << 8);
    }

    return 0;
}

// Function to log the distance data for all zones
void log_zone_data(uint16_t *zone_data) {
    for (int i = 0; i < NUM_ZONES; i++) {
        printf("Zone %d: %d mm, ", i, zone_data[i]);
        if ((i + 1) % 8 == 0) {
            printf("\n");
        }
    }
    printf("\n");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Allocate memory for the zone data
    uint16_t *zone_data = (uint16_t *)malloc(NUM_ZONES * sizeof(uint16_t));
    if (zone_data == NULL) {
        perror("Failed to allocate memory for zone data");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the zone data
        if (read_zone_data(i2c_fd, zone_data) == 0) {
            // Log the zone data
            log_zone_data(zone_data);
        } else {
            fprintf(stderr, "Failed to read or log zone data\n");
        }

        // Wait for 500 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Free the allocated memory (this will never be reached in the current loop)
    free(zone_data);

    // Close the I2C bus (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

