#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A

// Define the register address for distance data (example, adjust as needed)
#define DISTANCE_REG 0x00

// Global variables for graceful shutdown
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl-C
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle, uint16_t *distance)
{
    char buf[2];
    int result;

    // Read two bytes from the DISTANCE_REG register
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1; // Indicate failure
    }

    // Combine the two bytes into a 16-bit distance value
    *distance = (buf[0] << 8) | buf[1];

    return 0; // Indicate success
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl-C
    signal(SIGINT, sigint_handler);

    // Main loop to read and log distance measurements
    while (!terminate) {
        uint16_t distance;
        int retries = 3;
        int result;

        // Retry loop for I2C read
        do {
            result = read_distance(i2c_handle, &distance);
            if (result == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d retries left)...\n", retries - 1);
                gpioDelay(10000); // 10 ms delay
            }
        } while (retries-- > 0 && !terminate);

        if (result == 0) {
            // Get current timestamp in milliseconds
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

            // Log the distance and timestamp to the console
            printf("Distance: %u mm, Timestamp: %ld ms\n", distance, timestamp_ms);
        } else {
            fprintf(stderr, "Failed to read distance after multiple retries.\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Close the I2C bus and terminate the pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

