// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the VL53L4CX sensor
int init_vl53l4cx() {
    // Example initialization sequence (adjust based on datasheet)
    uint8_t data;
    int status;

    // Check sensor ID (Example)
    status = i2cReadByteData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    if (status != 0xEA) { // Expected value for VL53L4CX
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", status);
        return -1;
    }

    // Configure ROI (Example)
    data = 0x0A; // Example value
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD, data);
    if (status < 0) {
        fprintf(stderr, "Error writing to ROI centre spad register: %d\n", status);
        return -1;
    }

    data = 0x07; // Example value
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE, data);
    if (status < 0) {
        fprintf(stderr, "Error writing to ROI global size register: %d\n", status);
        return -1;
    }

    // Configure interrupt (Example)
    data = 0x04; // Example value
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_CONFIG_GPIO_CONFIG, data);
    if (status < 0) {
        fprintf(stderr, "Error writing to interrupt config register: %d\n", status);
        return -1;
    }

    // Clear interrupt (Example)
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_CLEAR, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to interrupt clear register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read distance data from the VL53L4CX sensor
int read_distance(int *distance) {
    uint8_t status;
    int result;

    // Read range status
    result = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS);
    if (result < 0) {
        fprintf(stderr, "Error reading range status: %d\n", result);
        return -1;
    }
    status = (uint8_t)result;

    // Check for valid measurement (Example - adjust based on datasheet)
    if ((status & 0x07) != 0) { // Example: Check for specific status bits
        fprintf(stderr, "Invalid range status: 0x%02X\n", status);
        return -1;
    }

    // Read distance (Example - adjust based on datasheet)
    result = i2cReadWordData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (result < 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }
    *distance = result;

    return 0;
}

// Function to log the distance data with a timestamp
void log_data(int distance) {
    struct timespec ts;
    char timestamp[30];

    clock_gettime(CLOCK_REALTIME, &ts);

    // Format timestamp
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%06ld",
             ts.tv_sec / 31536000 + 1970, // Approximate years since 1970
             (ts.tv_sec % 31536000) / 2628000 + 1, // Approximate months since January
             ((ts.tv_sec % 2628000) % 604800) / 86400 + 1, // Approximate days since January
             (ts.tv_sec % 86400) / 3600,
             (ts.tv_sec % 3600) / 60,
             ts.tv_sec % 60,
             ts.tv_nsec / 1000); // Microseconds

    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (init_vl53l4cx() != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    int status;

    // Main loop
    while (program_running) {
        // Read distance
        status = read_distance(&distance);
        if (status == 0) {
            // Log data
            log_data(distance);
        } else {
            fprintf(stderr, "Failed to read distance data\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

