            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Timeout error
        }
    }

    // Wait for echo to end
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        timeout_count++;
        if (timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Timeout error
        }
    }

    // Calculate the pulse duration
    diff_tick = end_tick - start_tick;

    // Calculate the distance
    double distance = (double)diff_tick * SPEED_OF_SOUND / 2000000.0; // in cm

    return distance;
}

// Map distance to servo angle
double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Set the servo angle
void set_servo_angle(double angle) {
    // Map angle to pulse width (us)
    double pulse_width = SERVO_MIN_US + (angle + 90.0) * (SERVO_MAX_US - SERVO_MIN_US) / 180.0;

    // Set the servo pulse width
    gpioServo(SERVO_PIN, (int)pulse_width);
}

// Log data to file
void log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            double angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(SAMPLE_PERIOD_MS); // Sample every 200ms
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Parking assist system stopped.\n");
    return 0;
}

