#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds
#define DISTANCE_MIN 2.0       // Minimum valid distance in cm
#define DISTANCE_MAX 400.0     // Maximum valid distance in cm
#define BUZZER_THRESHOLD 30.0   // Distance threshold for buzzer activation in cm

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Function to generate a 10 microsecond HIGH pulse on the trigger pin
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 2; // Indicate that the falling edge has been received
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        trigger_pulse(); // Send trigger pulse

        // Wait for echo pulse with timeout
        int timeout_count = 0;
        while (echo_received < 2 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Wait 1 microsecond
            timeout_count++;
        }

        if (echo_received == 2) {
            // Calculate pulse width
            unsigned int pulse_width = end_tick - start_tick;

            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Validate distance
            if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                printf("Distance: %.2f cm\n", distance);
                control_buzzer(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
        }

        echo_received = 0; // Reset echo received flag
        gpioDelay(100);     // Wait 100 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

