#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define DISTANCE_THRESHOLD 200 // mm
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
int socket_desc;
FILE *log_file;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance();
void set_servo_angle(int angle);
void log_event(const char *event);
void handle_remote_command(int command);
void signal_handler(int signal);

// VL53L1X Register Addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_SYSTEM_START              0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS       0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (refer to VL53L1X datasheet)
    char data[2];
    int retries = 3;

    // Check sensor ID (example)
    while (retries > 0) {
        data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
        if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
            fprintf(stderr, "Error writing to I2C (ID check): %d\n", i2c_handle);
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }
        data[0] = 0x00; // Dummy data for reading
        if (i2cReadDevice(i2c_handle, data, 1) != 0) {
            fprintf(stderr, "Error reading from I2C (ID check): %d\n", i2c_handle);
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }
        if (data[0] != 0xEA) {
            fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", data[0]);
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }
        break; // Success
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read sensor ID after multiple retries.\n");
        return -1;
    }

    // Reset the sensor
    data[0] = 0x00; // Soft reset command
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C (reset): %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(10000); // Wait for reset (10ms)

    // Configure for short-range mode (example)
    data[0] = 0x02D8; // Example register address
    data[1] = 0x01;   // Example value
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C (config): %d\n", i2c_handle);
        return -1;
    }

    // Start ranging
    data[0] = VL53L1X_REG_SYSTEM_START;
    data[1] = 0x01; // Start ranging
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C (start ranging): %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X sensor
