#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TIMEOUT_DURATION 60       // milliseconds
#define MIN_PULSE_WIDTH 100       // microseconds
#define MAX_PULSE_WIDTH 30000     // microseconds

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate the trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 1;
    } else if (level == 0) {
        falling_tick = tick;
        echo_received = 0;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (pulse_width * 0.0343) / 2.0;
}

// Function to log the distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
    printf("%s Distance: %.2f cm\n", timestamp, distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        gpioDelay(TIMEOUT_DURATION * 1000); // Wait for timeout duration

        if (echo_received) {
            if (falling_tick > rising_tick) {
                uint32_t pulse_width = falling_tick - rising_tick;

                if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
                    fprintf(log_file, "Warning: Invalid pulse width: %u us\n", pulse_width);
                    fflush(log_file);
                    printf("Warning: Invalid pulse width: %u us\n", pulse_width);
                } else {
                    double distance = calculate_distance(pulse_width);
                    log_distance(distance);
                }
            } else {
                fprintf(log_file, "Warning: Tick wraparound occurred!\n");
                fflush(log_file);
                printf("Warning: Tick wraparound occurred!\n");
            }
        } else {
            fprintf(log_file, "Warning: Timeout waiting for echo.\n");
            fflush(log_file);
            printf("Warning: Timeout waiting for echo.\n");
        }

        gpioDelay(100000); // Delay between measurements (100ms)
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    return 0;
}

