#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTIONS_ENABLES 0x001E
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Define distance thresholds
#define OPEN_THRESHOLD 50  // cm
#define CLOSE_THRESHOLD 60 // cm

// Define servo pulse widths
#define SERVO_OPEN_PULSE 1500
#define SERVO_CLOSED_PULSE 1000

// Define sensor states
typedef enum {
    SENSOR_ABSENT,
    SENSOR_PRESENT,
    SENSOR_ERROR
} sensor_state_t;

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor(int i2c_bus, int shutdown_pin, int interrupt_pin);
sensor_state_t read_distance(int i2c_handle, int *distance);
void control_servo(int gpio_pin, int pulse_width);
void log_event(const char *event, int distance1, int distance2);
void signal_handler(int signal);

// Function to initialize a VL53L1X sensor
int initialize_sensor(int i2c_bus, int shutdown_pin, int interrupt_pin) {
    int handle = i2cOpen(i2c_bus, 0x29, 0); // Open I2C device
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device on bus %d: %d\n", i2c_bus, handle);
        return -1;
    }

    // Check sensor model ID
    char data[2];
    int result = i2cReadI2CBlockData(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, data, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading model ID from bus %d: %d\n", i2c_bus, result);
        i2cClose(handle);
        return -1;
    }

    if (data[0] != 0xEA) {
        fprintf(stderr, "Incorrect model ID 0x%02X on bus %d, expected 0xEA\n", data[0], i2c_bus);
        i2cClose(handle);
        return -1;
    }

    // Configure sensor for short-range mode (example configuration)
    char config_data[2];
    config_data[0] = VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTIONS_ENABLES;
    config_data[1] = 0x01; // Example value, adjust as needed
    result = i2cWriteI2CBlockData(handle, config_data[0], &config_data[1], 1);
    if (result != 1) {
        fprintf(stderr, "Error writing configuration to bus %d: %d\n", i2c_bus, result);
        i2cClose(handle);
        return -1;
    }

    // Start the sensor
    config_data[0] = VL53L1X_REG_SYSTEM_START;
    config_data[1] = 0x01;
    result = i2cWriteI2CBlockData(handle, config_data[0], &config_data[1], 1);
    if (result != 1) {
        fprintf(stderr, "Error starting sensor on bus %d: %d\n", i2c_bus, result);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Function to read distance from a VL53L1X sensor
sensor_state_t read_distance(int i2c_handle, int *distance) {
    char data[2];
    int result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return SENSOR_ERROR;
    }

    *distance = (data[0] << 8) | data[1];
    return SENSOR_PRESENT;
}

// Function to control the servo motor
void control_servo(int gpio_pin, int pulse_width) {
    gpioServo(gpio_pin, pulse_width);
}

// Function to log events to a file
void log_event(const char *event, int distance1, int distance2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d - %s - Sensor1: %d cm, Sensor2: %d cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            event, distance1, distance2);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(SENSOR1_SHUTDOWN, PI_OUTPUT);
    gpioSetMode(SENSOR1_INTERRUPT, PI_INPUT);
    gpioSetMode(SENSOR2_SHUTDOWN, PI_OUTPUT);
    gpioSetMode(SENSOR2_INTERRUPT, PI_INPUT);

    // Initialize I2C sensors
    i2c_handle1 = initialize_sensor(I2C_BUS1, SENSOR1_SHUTDOWN, SENSOR1_INTERRUPT);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize sensor on I2C bus 1\n");
    }

    i2c_handle2 = initialize_sensor(I2C_BUS2, SENSOR2_SHUTDOWN, SENSOR2_INTERRUPT);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize sensor on I2C bus 2\n");
    }

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int gate_open = 0; // 0 = closed, 1 = open
    int distance1, distance2;
    sensor_state_t sensor1_state, sensor2_state;

    // Main loop
    while (program_running) {
        sensor1_state = SENSOR_ABSENT;
        sensor2_state = SENSOR_ABSENT;

        if (i2c_handle1 >= 0) {
            sensor1_state = read_distance(i2c_handle1, &distance1);
        }

        if (i2c_handle2 >= 0) {
            sensor2_state = read_distance(i2c_handle2, &distance2);
        }

        if (sensor1_state == SENSOR_ERROR || sensor2_state == SENSOR_ERROR) {
            log_event("Error reading sensor data", distance1, distance2);
        } else {
            // Determine gate state based on distances
            if ((sensor1_state == SENSOR_PRESENT && distance1 < OPEN_THRESHOLD) ||
                (sensor2_state == SENSOR_PRESENT && distance2 < OPEN_THRESHOLD)) {
                if (!gate_open) {
                    control_servo(SERVO_PIN, SERVO_OPEN_PULSE);
                    log_event("Gate opened", distance1, distance2);
                    gate_open = 1;
                }
            } else if ((sensor1_state == SENSOR_PRESENT && distance1 > CLOSE_THRESHOLD) &&
                       (sensor2_state == SENSOR_PRESENT && distance2 > CLOSE_THRESHOLD)) {
                if (gate_open) {
                    control_servo(SERVO_PIN, SERVO_CLOSED_PULSE);
                    log_event("Gate closed", distance1, distance2);
                    gate_open = 0;
                }
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    fclose(log_file);
    gpioTerminate();

    return 0;
}

