#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD 200 // mm
#define TIMING_BUDGET 33000 // us
#define POLLING_INTERVAL 500 // ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_SYSTEM_START              0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS       0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            if (distance < DISTANCE_THRESHOLD) {
                open_gate();
            } else {
                close_gate();
            }
        }
        gpioDelay(POLLING_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Soft reset
    if (write_register(i2c_handle, 0x0000, 0x01) != 0) {
        fprintf(stderr, "Error resetting VL53L1X\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure timing budget (example: 33ms)
    if (write_register(i2c_handle, 0x0080, TIMING_BUDGET >> 8) != 0) return -1;
    if (write_register(i2c_handle, 0x0081, TIMING_BUDGET & 0xFF) != 0) return -1;

    // Start ranging
    if (write_register(i2c_handle, 0x0000, 0x04) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;
    int distance;

    // Read range status
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance (MSB and LSB)
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_msb) != 0) {
        fprintf(stderr, "Error reading distance MSB\n");
        return -1;
    }

    if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &distance_lsb) != 0) {
        fprintf(stderr, "Error reading distance LSB\n");
        return -1;
    }

    distance = (distance_msb << 8) | distance_lsb;

    return distance;
}

// Open the gate
void open_gate() {
    gpioWrite(GPIO_OPEN, 1);
    gpioWrite(GPIO_CLOSE, 0);
    log_event("Gate Opened");
}

// Close the gate
void close_gate() {
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 1);
    log_event("Gate Closed");
}

// Log an event to the log file
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

