#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define DISTANCE_TRIGGER_PIN 24

// Define I2C bus and address
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

// Define distance thresholds
#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300

// Define VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void control_motor(int distance);
void distance_trigger_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// VL53L1X Initialization Sequence (Simplified - refer to datasheet for full sequence)
int vl53l1x_init() {
    // Example: Reset the sensor
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X reset failed\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Example: Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X start failed\n");
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X sensor
int vl53l1x_read_distance() {
    int distance = -1; // Default to error value
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        // Read range status
        int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (range_status < 0) {
            fprintf(stderr, "Error: I2C read failed (range status)\n");
            retries--;
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        // Check for data ready (adjust based on datasheet)
        if ((range_status & 0x01) == 0) {
            fprintf(stderr, "Error: Data not ready\n");
            retries--;
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        // Read distance
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance < 0) {
            fprintf(stderr, "Error: I2C read failed (distance)\n");
            retries--;
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        // Success, break out of retry loop
        break;
    }

    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance after multiple retries\n");
        return -1; // Indicate error
    }

    return distance;
}

// Function to control the motor based on distance
void control_motor(int distance) {
    if (distance < DISTANCE_THRESHOLD_FORWARD) {
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        printf("Motor: Forward\n");
    } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 1);
        printf("Motor: Backward\n");
    } else {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        printf("Motor: Stop\n");
    }
}

// Interrupt service routine for distance trigger
void distance_trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            control_motor(distance);
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(DISTANCE_TRIGGER_PIN, PI_INPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on rising edge of GPIO24
    if (gpioSetISRFuncEx(DISTANCE_TRIGGER_PIN, RISING_EDGE, 0, distance_trigger_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    gpioTerminate();

    return 0;
}

