#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define sensor addresses
#define MPR121_ADDR_1 0x5A
#define MPR121_ADDR_2 0x5B

// Define GPIO pins for LEDs
#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

// Define proximity threshold
#define PROXIMITY_THRESHOLD 50

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 200

// Structure to hold sensor data
typedef struct {
    int fd;
    int address;
    bool present;
    unsigned long last_proximity_time;
} sensor_t;

// Global variables
sensor_t sensors[2];
int led_pins[4] = {LED_PIN_0, LED_PIN_1, LED_PIN_2, LED_PIN_3};
bool running = true;

// Function prototypes
int init_sensor(sensor_t *sensor);
int read_touch_status(sensor_t *sensor);
void set_led_pattern(int pattern);
void log_event(int sensor_id, int electrode);
void signal_handler(int signal);

// Function to initialize a sensor
int init_sensor(sensor_t *sensor) {
    int fd = wiringPiI2CSetup(sensor->address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C for sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        return -1;
    }
    sensor->fd = fd;
    sensor->present = true;

    // Soft reset the sensor
    if (wiringPiI2CWriteReg8(fd, 0x80, 0x63) == -1) {
        fprintf(stderr, "Error writing to reset register for sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        sensor->present = false;
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (wiringPiI2CWriteReg8(fd, 0x5E, 0xC0) == -1) { // Set Electrode Configuration
        fprintf(stderr, "Error writing to electrode config register for sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        sensor->present = false;
        return -1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x5B, 0x05) == -1) { // Set Touch Threshold
        fprintf(stderr, "Error writing to touch threshold register for sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        sensor->present = false;
        return -1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x5C, 0x05) == -1) { // Set Release Threshold
        fprintf(stderr, "Error writing to release threshold register for sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        sensor->present = false;
        return -1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x5D, 0x01) == -1) { // Set Filter Configuration
        fprintf(stderr, "Error writing to filter config register for sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        sensor->present = false;
        return -1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x5F, 0x01) == -1) { // Set Debounce Configuration
        fprintf(stderr, "Error writing to debounce config register for sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        sensor->present = false;
        return -1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x2B, 0x01) == -1) { // Enable all electrodes
        fprintf(stderr, "Error writing to electrode enable register for sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        sensor->present = false;
        return -1;
    }

    return 0;
}

// Function to read touch status from a sensor
int read_touch_status(sensor_t *sensor) {
    int touch_status = wiringPiI2CReadReg16(sensor->fd, 0x00);
    if (touch_status == -1) {
        fprintf(stderr, "Error reading touch status from sensor 0x%02X: %s\n", sensor->address, strerror(errno));
        sensor->present = false;
        return -1;
    }
    return touch_status;
}

// Function to set the LED pattern
void set_led_pattern(int pattern) {
    for (int i = 0; i < 4; i++) {
        digitalWrite(led_pins[i], (pattern >> i) & 1);
    }
}

// Function to log an event
void log_event(int sensor_id, int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor %d - Electrode %d - Proximity detected\n", timestamp, sensor_id, electrode);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;

    // Turn off all LEDs
    for (int i = 0; i < 4; i++) {
        digitalWrite(led_pins[i], LOW);
    }

    // Close I2C file descriptors
    for (int i = 0; i < 2; i++) {
        if (sensors[i].fd != -1) {
            close(sensors[i].fd);
        }
    }

    // Reset GPIO pins to input mode
    for (int i = 0; i < 4; i++) {
        pinMode(led_pins[i], INPUT);
    }

    exit(0);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize sensors
    sensors[0].address = MPR121_ADDR_1;
    sensors[0].present = false;
    sensors[0].last_proximity_time = 0;
    sensors[1].address = MPR121_ADDR_2;
    sensors[1].present = false;
