int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
int mpr121_is_proximity(uint16_t touch_status);
void led_on();
void led_off();
void log_proximity_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize MPR121
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MPR121_ELECTRODECONFIG\n");
        return -1;
    }

    // Recommended settings from datasheet
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error writing to MPR121_CONFIG1\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x01) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error writing to MPR121_CONFIG2\n");
        return -1;
    }

    // Set filter threshold
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_L, 0x10) < 0) {
        fprintf(stderr, "Error writing to MPR121_FILTERTH_L\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_H, 0x00) < 0) {
        fprintf(stderr, "Error writing to MPR121_FILTERTH_H\n");
        return -1;
    }

    // Set baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_L, 0x05) < 0) {
        fprintf(stderr, "Error writing to MPR121_BASELINE_L\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_H, 0x00) < 0) {
        fprintf(stderr, "Error writing to MPR121_BASELINE_H\n");
        return -1;
    }

    // Start mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error writing to MPR121_ELECTRODECONFIG\n");
        return -1;
    }

    return 0;
}

