#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 30000       // Timeout in microseconds (30ms)
#define MIN_DISTANCE 2.0       // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0     // Maximum measurable distance (cm)

// Global variables
static volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long long get_pulse_width();
double calculate_distance(long long pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioDelay(100);             // Allow sensor to settle

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width
long long get_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Calculate distance from pulse width
double calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
