#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define MIN_PULSE_WIDTH 58 // Minimum pulse width in microseconds (1 cm)
#define MAX_PULSE_WIDTH 25000 // Maximum pulse width in microseconds (4 m)

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt service routine for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag on rising edge
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1; // Set validity flag on falling edge
    }
}

// Function to calculate distance in meters
double calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate invalid reading
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Terminate pigpio before exiting
        return 1;
    }

    // Register ISR callback
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(100000); // Wait 100 ms

        if (echo_valid) {
            int pulse_width = echo_end_tick - echo_start_tick;

            // Handle tick wrap-around
            if (echo_end_tick < echo_start_tick) {
                pulse_width = (0xFFFFFFFF - echo_start_tick) + echo_end_tick;
            } else {
                pulse_width = echo_end_tick - echo_start_tick;
            }

            if (pulse_width > MIN_PULSE_WIDTH && pulse_width < MAX_PULSE_WIDTH) {
                double distance = calculate_distance(pulse_width);
                if (distance >= 0.0) {
                    log_distance(distance);
                } else {
                    fprintf(stderr, "Invalid distance reading.\n");
                }
            } else {
                fprintf(stderr, "Pulse width out of range: %d us\n", pulse_width);
            }
        } else {
            fprintf(stderr, "No valid echo pulse received.\n");
        }

        echo_valid = 0; // Reset validity flag
    }

    return 0;
}

