void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);

    // Disable sensor (set XSHUT high)
    gpioWrite(XSHUT_PIN, 1);

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

