#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define DISTANCE_THRESHOLD 200 // mm

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void update_circular_buffer(circular_buffer_t *cb, int distance);
void control_led(int distance);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void circular_buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add data to circular buffer
void circular_buffer_add(circular_buffer_t *cb, int data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get data from circular buffer (not used in this example, but included for completeness)
int circular_buffer_get(circular_buffer_t *cb, int index) {
    if (index < 0 || index >= cb->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return -1; // Indicate error
    }
    int real_index = (cb->head - cb->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[real_index];
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    circular_buffer_t distance_buffer;
    circular_buffer_init(&distance_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int distance;
    while (!terminate) {
        // Read distance from VL53L1X sensor
        if (read_distance(&distance) == 0) {
            // Update circular buffer
            update_circular_buffer(&distance_buffer, distance);

            // Control LED based on distance
            control_led(distance);

            // Print distance (for debugging)
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C interface: %d\n", i2c_handle);
        return -1;
    }

    // Basic initialization sequence (refer to VL53L1X datasheet)
    // Example: Check sensor ID (replace with actual initialization sequence)
    char data[2];
    int status;

    // Check sensor ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    data[0] = 0x00; // Dummy data for reading
    status = i2cReadDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    if (data[0] != 0xEA) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Start ranging (example)
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01; // Start ranging
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char data[2];
    int status;

    // Read range status
    data[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    status = i2cReadDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    // Read distance (example - adjust register address as needed)
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    char distance_data[2];
    status = i2cReadDevice(i2c_handle, distance_data, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    *distance = (distance_data[0] << 8) | distance_data[1];

    return 0;
}

// Update circular buffer with new distance reading
void update_circular_buffer(circular_buffer_t *cb, int distance) {
    circular_buffer_add(cb, distance);
}

// Control LED based on distance
void control_led(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioWrite(GPIO_LED, 0);

    // Close I2C interface
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();
}

