    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    *distance = (distance_data[0] << 8) | distance_data[1];

    return 0;
}

// Update circular buffer with new distance reading
void update_circular_buffer(circular_buffer_t *cb, int distance) {
    circular_buffer_add(cb, distance);
}

// Control LED based on distance
void control_led(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioWrite(GPIO_LED, 0);

    // Close I2C interface
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();
}

