#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"
#define MAX_LOG_LENGTH 256

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static volatile int interrupt_flag = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int init_i2c(int bus, int address);
int init_gpio(int pin);
int configure_interrupt(int pin, int edge);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
