int log_data(int proximity_value, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to initialize GPIO
int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO pull-up\n");
        return -1;
    }
    return 0;
}

// Function to configure interrupt
int configure_interrupt(int pin, int edge) {
    if (gpioSetISRFuncEx(pin, edge, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        return -1;
    }
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    interrupt_flag = 1;
}

