        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure interrupt
    if (configure_interrupt(GPIO_PIN, RISING_EDGE) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Proximity sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (interrupt_flag) {
            int proximity_value = read_proximity(i2c_handle);
            if (proximity_value >= 0) {
                const char *status = (proximity_value <= threshold) ? "SAFE" : "ALERT";
                log_data(proximity_value, status);
            }
            interrupt_flag = 0;
        }
        gpioDelay(100); // Check every 100ms
    }

    return 0;
}

