#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)
#define MIN_DISTANCE 2.0       // Minimum distance in cm
#define MAX_DISTANCE 200.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0    // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0   // Maximum frequency in Hz

// Global variable for the current frequency
float current_frequency = 1000.0; // Initial frequency

// Function prototypes
void trigger_sensor();
long get_pulse_width();
float calculate_distance(long pulse_width);
float map_distance_to_frequency(float distance);
void set_speaker_frequency(float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long get_pulse_width() {
    long start_time = 0, end_time = 0;
    long pulse_width = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_time = gpioTick();

    pulse_width = end_time - start_time;

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate an error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Function to map the distance to a frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MAX_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MIN_FREQUENCY;
    } else {
        // Logarithmic mapping
        return MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * log10(distance / MIN_DISTANCE) / log10(MAX_DISTANCE / MIN_DISTANCE);
    }
}

// Function to set the speaker frequency using PWM
void set_speaker_frequency(float frequency) {
    if (frequency < 0) {
        fprintf(stderr, "Invalid frequency: %f\n", frequency);
        return;
    }

    gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency); // Set PWM frequency
    gpioPWM(SPEAKER_PIN, 128);                       // Set duty cycle (50%)
    current_frequency = frequency;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(SPEAKER_PIN, 255);

    // Set PWM frequency (initial value)
    gpioSetPWMfrequency(SPEAKER_PIN, (int)current_frequency);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_sensor();
        long pulse_width = get_pulse_width();

        if (pulse_width < 0) {
            fprintf(stderr, "Error: Timeout or error reading pulse width\n");
        } else {
            float distance = calculate_distance(pulse_width);

            if (distance < 0) {
                fprintf(stderr, "Error: Invalid distance reading\n");
            } else {
                float frequency = map_distance_to_frequency(distance);
                set_speaker_frequency(frequency);
                printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
            }
        }

        gpioDelay(50); // Delay between readings
    }

    return 0;
}

