// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 100000      // 100 ms
#define MIN_DISTANCE 5.0      // cm
#define MAX_DISTANCE 50.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz

// Global variable for pulse start time
static volatile uint32_t pulse_start = 0;

// Function prototypes
void triggerSensor();
float getDistance();
float mapDistanceToFrequency(float distance);
void generateTone(float frequency);
