void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Callback function for echo pin changes
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        uint32_t pulse_end = tick;
        uint32_t pulse_width = pulse_end - pulse_start;

        // Check for timeout
        if (pulse_width > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout\n");
            return; // Skip the rest of the function
        }

        // Calculate distance in centimeters
        float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance

        // Map distance to frequency
        float frequency = mapDistanceToFrequency(distance);

        // Generate tone
        generateTone(frequency);

        // Print distance and frequency
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

