    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Install signal handler
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_duration = measurePulse();

        if (pulse_duration < 0) {
            fprintf(stderr, "Timeout occurred\n");
        } else {
            float distance = calculateDistance(pulse_duration);

            if (distance >= 2.0 && distance <= 400.0) {
                printf("Distance: %.2f cm", distance);
                if (distance < 10.0) {
                    printf(" - Too close!\n");
                } else {
                    printf("\n");
                }
            } else {
                fprintf(stderr, "Invalid reading: %.2f cm\n", distance);
            }
        }

        gpioDelay(500); // Wait 500ms
    }

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

