#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (BCM)
#define DISTANCE_MIN 200  // Minimum distance in mm
#define DISTANCE_MAX 5000 // Maximum distance in mm
#define LOG_FILE "distance_log.csv"

// ICU-20201 Register Addresses (Example - Adjust based on datasheet)
#define WHO_AM_I 0x0F
#define DISTANCE_REG_L 0x5A
#define DISTANCE_REG_H 0x5B

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_distance(uint16_t *distance);
void log_data(uint16_t distance);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    uint8_t who_am_i_value;
    uint8_t operating_mode;
} sensor_config_t;

// Function to initialize the sensor
int initialize_sensor() {
    char tx_buf[2], rx_buf[2];
    int result;

    // Example: Check WHO_AM_I register (replace with actual value from datasheet)
    tx_buf[0] = WHO_AM_I | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", result);
        return -1;
    }

    // Replace 0xXX with the expected WHO_AM_I value
    if (rx_buf[1] != 0xXX) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", 0xXX, rx_buf[1]);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read distance from the sensor
int read_distance(uint16_t *distance) {
    char tx_buf[2], rx_buf[2];
    int result;

    // Read distance registers (LSB and MSB)
    tx_buf[0] = DISTANCE_REG_L | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading distance LSB: %d\n", result);
        return -1;
    }

    uint8_t distance_lsb = rx_buf[1];

    tx_buf[0] = DISTANCE_REG_H | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading distance MSB: %d\n", result);
        return -1;
    }

    uint8_t distance_msb = rx_buf[1];

    // Combine LSB and MSB to get the distance
    *distance = (uint16_t)((distance_msb << 8) | distance_lsb);

    return 0;
}

// Function to log data to a file
void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s, Distance: %u mm\n", timestamp, distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t distance;
    while (program_running) {
        if (read_distance(&distance) == 0) {
            // Validate distance
            if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                log_data(distance);
            } else {
                fprintf(stderr, "Distance out of range: %u\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

