#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_PART_ID_REG 0x00
#define SI1120_PART_ID_VALUE 0x50
#define SI1120_RESET_CMD 0x01
#define SI1120_ALS_DATA_REG 0x22
#define SI1120_PS_DATA_REG 0x24
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000 // 10 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1120();
int read_si1120_data(uint16_t *als_data, uint16_t *ps_data);
int log_data(uint16_t als_data, uint16_t ps_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1120 sensor
int init_si1120() {
    int retries = 0;
    int result;

    // Reset the sensor
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, SI1120_RESET_CMD, SI1120_RESET_CMD);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error resetting Si1120 (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to reset Si1120 after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Verify Part ID
    retries = 0;
    uint8_t part_id;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, SI1120_PART_ID_REG);
        if (result >= 0) {
            part_id = (uint8_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading Part ID (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read Part ID after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    if (part_id != SI1120_PART_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect Part ID (0x%02X, expected 0x%02X)\n", part_id, SI1120_PART_ID_VALUE);
        return -1;
    }

    return 0;
}

// Read ALS and proximity data from the Si1120 sensor
int read_si1120_data(uint16_t *als_data, uint16_t *ps_data) {
    int retries = 0;
    int result;
    uint8_t als_low, als_high, ps_low, ps_high;

    // Read ALS data
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, SI1120_ALS_DATA_REG);
        if (result >= 0) {
            als_low = (uint8_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading ALS low byte (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ALS low byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, SI1120_ALS_DATA_REG + 1);
        if (result >= 0) {
            als_high = (uint8_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading ALS high byte (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ALS high byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Read Proximity data
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, SI1120_PS_DATA_REG);
        if (result >= 0) {
            ps_low = (uint8_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading PS low byte (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read PS low byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, SI1120_PS_DATA_REG + 1);
        if (result >= 0) {
            ps_high = (uint8_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading PS high byte (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read PS high byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Combine bytes into 16-bit values
    *als_data = (uint16_t)((als_high << 8) | als_low);
    *ps_data = (uint16_t)((ps_high << 8) | ps_low);

    return 0;
}

// Log data to file
int log_data(uint16_t als_data, uint16_t ps_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als_data, ps_data);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1120 sensor
    if (init_si1120() != 0) {
        fprintf(stderr, "Si1120 initialization failed!\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t als_data, ps_data;

    // Main loop
    while (!terminate) {
        if (read_si1120_data(&als_data, &ps_data) == 0) {
            log_data(als_data, ps_data);
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

