#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define ALS_VIS_DATA0 0x22
#define PS1_DATA0 0x18

#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_register(int reg);
int write_register(int reg, int value);
int configure_sensor();
int read_sensor_data(float *lux, int *proximity);
void log_data(float lux, int proximity);
void print_data(float lux, int proximity);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    int measurement_rate;
    int als_integration_time;
    int ps_integration_time;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read a register
int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a register
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor() {
    // Example configuration (adjust as needed based on datasheet)
    if (write_register(MEAS_RATE_REG, 0x0A) < 0) return -1; // Example rate

    // Add more configuration registers as needed

    return 0;
}

// Read sensor data
int read_sensor_data(float *lux, int *proximity) {
    int als_low, als_high, ps_low, ps_high;

    als_low = read_register(ALS_VIS_DATA0);
    als_high = read_register(ALS_VIS_DATA0 + 1);
    ps_low = read_register(PS1_DATA0);
    ps_high = read_register(PS1_DATA0 + 1);

    if (als_low < 0 || als_high < 0 || ps_low < 0 || ps_high < 0) {
        return -1;
    }

    *lux = (float)((als_high << 8) | als_low); // Example conversion
    *proximity = (ps_high << 8) | ps_low; // Example conversion

    return 0;
}

// Log data to file
void log_data(float lux, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(log_file); // Ensure data is written immediately
}

// Print data to stdout
void print_data(float lux, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s,%.2f,%d\n", timestamp, lux, proximity);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int part_id = read_register(PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Sensor not found or I2C error. Check connection.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("Sensor Part ID: 0x%02X\n", part_id);

    // Configure sensor
    if (configure_sensor() < 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float lux;
    int proximity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&lux, &proximity) == 0) {
            log_data(lux, proximity);
            print_data(lux, proximity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

