#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout for echo pulse in microseconds

// Global variable for pigpio initialization status
int pigpio_initialized = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");

    // Stop the servo motor
    gpioServo(SERVO_PIN, 0);

    // Terminate the pigpio library
    if (pigpio_initialized) {
        gpioTerminate();
    }

    exit(0);
}

// Function to measure distance using HC-SR04 sensor
float getDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse duration
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance

    return distance;
}

// Function to set the servo angle based on distance
void setServoAngle(float distance) {
    // Map distance to servo pulse width (500us - 2500us)
    int pulse_width = 500 + (int)((distance / 200.0) * 2000); // Assuming distance range of 200cm to 20cm

    // Limit the pulse width to the valid range
    if (pulse_width < 500) {
        pulse_width = 500;
    } else if (pulse_width > 2500) {
        pulse_width = 2500;
    }

    // Set the servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        float distance = getDistance();

        if (distance < 0) {
            fprintf(stderr, "Error: Timeout or sensor error. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        setServoAngle(distance);

        gpioDelay(100); // Delay for 100ms
    }

    return 0;
}

