#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define TIMEOUT_DURATION 50      // Timeout duration in milliseconds
#define SERVO_MIN_PULSE_WIDTH 500 // Minimum pulse width for 0 degrees (microseconds)
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum pulse width for 180 degrees (microseconds)
#define MIN_DISTANCE 2.0          // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0        // Maximum measurable distance (cm)
#define MIN_ANGLE 0.0             // Minimum servo angle (degrees)
#define MAX_ANGLE 180.0           // Maximum servo angle (degrees)

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
double measure_distance();
double calculate_distance(long start_time, long end_time);
double map_distance_to_angle(double distance);
int set_servo_angle(double angle);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
    int servo_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100); // Allow sensor to settle

    return 0; // Indicate success
}

// Measure distance using the HC-SR04 sensor
double measure_distance() {
    long start_time, end_time;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_DURATION * 1000) {
        gpioDelay(1); // Check every microsecond
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_DURATION * 1000) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate timeout
    }

    start_time = gpioTick();

    // Wait for echo to end
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_DURATION * 1000) {
        gpioDelay(1); // Check every microsecond
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_DURATION * 1000) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate timeout
    }

    end_time = gpioTick();

    return calculate_distance(start_time, end_time);
}

// Calculate distance from pulse duration
double calculate_distance(long start_time, long end_time) {
    double pulse_duration = (double)(end_time - start_time) / 1000000.0; // in seconds
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2.0;

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0; // Indicate invalid distance
    }

    return distance;
}

// Map distance to servo angle
double map_distance_to_angle(double distance) {
    if (distance < 20.0) {
        return MIN_ANGLE;
    } else if (distance > 200.0) {
        return MAX_ANGLE;
    } else {
        return (distance - 20.0) * (MAX_ANGLE - MIN_ANGLE) / (200.0 - 20.0) + MIN_ANGLE;
    }
}

// Set servo angle using pigpio
int set_servo_angle(double angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Angle out of range: %.2f degrees\n", angle);
        return 1; // Indicate error
    }

    // Map angle to pulse width
    double pulse_width = (angle - MIN_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE) + SERVO_MIN_PULSE_WIDTH;

    gpioServo(SERVO_PIN, (int)pulse_width);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("HC-SR04 Distance Sensor and Servo Control\n");

    while (program_running) {
        double distance = measure_distance();

        if (distance > 0) {
            double angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Failed to measure distance\n");
        }

        gpioDelay(100); // Pause for 100 milliseconds
    }

    // Stop the servo
    set_servo_angle(MIN_ANGLE);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

