    }

    // Map angle to pulse width
    double pulse_width = (angle - MIN_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE) + SERVO_MIN_PULSE_WIDTH;

    gpioServo(SERVO_PIN, (int)pulse_width);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("HC-SR04 Distance Sensor and Servo Control\n");

    while (program_running) {
        double distance = measure_distance();

        if (distance > 0) {
            double angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Failed to measure distance\n");
        }

        gpioDelay(100); // Pause for 100 milliseconds
    }

    // Stop the servo
    set_servo_angle(MIN_ANGLE);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

