    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = CONFIG_VALUE;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    return 0;
}

