    cmd = TEMP_MEASURE_CMD;
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    // Read temperature data
    cmd = 0x00; // Dummy register address
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write temperature read command: %d\n", result);
        return -1;
