    if (result != 2) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }
    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

