#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 command for high repeatability measurement
#define SHT40_MEASURE_HIGH 0xFD

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable for I2C handle
int i2c_handle = -1;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C bus
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t sensor_data[6];
        sensor_data_t data;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Retry
        }

        // Wait for measurement to complete (at least 10 ms)
        gpioDelay(10000); // 10 ms

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Retry
        }

        // Validate CRC checksums
        if (validate_crc(sensor_data, 6) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Retry
        }

        // Convert raw data to temperature and humidity
        uint16_t raw_temperature = (sensor_data[0] << 8) | sensor_data[1];
        uint16_t raw_humidity = (sensor_data[3] << 8) | sensor_data[4];

        data.temperature = convert_temperature(raw_temperature);
        data.humidity = convert_humidity(raw_humidity);

        // Log data to console
        log_data(data.temperature, data.humidity);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Open I2C bus 1 with SHT40 address
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

