#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold temperature data
typedef struct {
    float ambient_temp;
    float object_temp;
} TemperatureData;

// Function prototypes
int init_i2c();
TemperatureData read_temperatures();
int log_temperatures(TemperatureData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperatures from the sensor
TemperatureData read_temperatures() {
    TemperatureData data;
    int raw_ambient, raw_object;

    raw_ambient = i2cReadWordData(i2c_handle, AMBIENT_TEMP_REG);
    if (raw_ambient < 0) {
        fprintf(stderr, "Error reading ambient temperature: %s\n", strerror(errno));
        data.ambient_temp = -273.15; // Return absolute zero on error
    } else {
        data.ambient_temp = (float)raw_ambient * 0.02 - 273.15;
    }

    raw_object = i2cReadWordData(i2c_handle, OBJECT_TEMP_REG);
    if (raw_object < 0) {
        fprintf(stderr, "Error reading object temperature: %s\n", strerror(errno));
        data.object_temp = -273.15; // Return absolute zero on error
    } else {
        data.object_temp = (float)raw_object * 0.02 - 273.15;
    }

    return data;
}

// Log temperatures to a file
int log_temperatures(TemperatureData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.ambient_temp, data.object_temp);
    fclose(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        TemperatureData temperatures = read_temperatures();

        if (temperatures.ambient_temp != -273.15 && temperatures.object_temp != -273.15) {
            if (log_temperatures(temperatures) != 0) {
                fprintf(stderr, "Error logging temperatures.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperatures, skipping logging.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

