#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_HIGH_REP 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for grouping I2C configuration
typedef struct {
    int bus;
    int addr;
} i2c_config_t;

// Initialize I2C bus
int init_i2c() {
    i2c_config_t config = {I2C_BUS, STS30_ADDR};
    i2c_handle = i2cOpen(config.bus, config.addr, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        return -1;
    }
    return 0;
}

// Read temperature from STS30-DIS sensor
int read_temperature(float *temperature) {
    char cmd[2] = {(MEASURE_HIGH_REP >> 8) & 0xFF, MEASURE_HIGH_REP & 0xFF};
    char buf[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write to I2C device.");
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 12.1ms for high repeatability)

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        log_error("Failed to read from I2C device.");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * temp_raw / 65535.0);

    return 0;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file.");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fclose(log_file);
    return 0;
}

// Log error messages to file
