    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_FRAME_LENGTH);
    if (result != DATA_FRAME_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

