// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0x240B
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "sht40_log.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sht40(float *temperature, float *humidity);
uint8_t calculate_crc(const uint8_t *data, size_t length);
int validate_crc(const uint8_t *data, size_t length, uint8_t checksum);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_HIGH_REPEATABILITY >> 8) & 0xFF, MEASURE_HIGH_REPEATABILITY & 0xFF};
    uint8_t buffer[6];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(10); // Wait at least 10 ms

    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Validate CRC for temperature
    if (validate_crc(buffer, 2, buffer[2]) != 0) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Validate CRC for humidity
    if (validate_crc(buffer + 3, 2, buffer[5]) != 0) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temp_raw = (buffer[0] << 8) | buffer[1];
    uint16_t humidity_raw = (buffer[3] << 8) | buffer[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, size_t length, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, length);
    return (calculated_crc == checksum) ? 0 : -1;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sht40(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

