#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x21
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define BACKOFF_BASE_MS 1

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger continuous measurement
int trigger_measurement() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error triggering measurement (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_BASE_MS * (1 << retries)); // Exponential backoff
        }
    }
    fprintf(stderr, "Failed to trigger measurement after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
