    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7015_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting sensor data logging...\n");

    // Main loop
    while (!terminate) {
        uint8_t data[2];
        uint16_t raw_temp, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (write_i2c_command(i2c_handle, TEMP_CMD) != 0) {
            fprintf(stderr, "Error writing temperature command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }
        gpioDelay(20); // Wait for measurement (at least 20ms)
        if (read_i2c_data(i2c_handle, data, 2) != 0) {
            fprintf(stderr, "Error reading temperature data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }
        raw_temp = (data[0] << 8) | data[1];
        temperature = convert_temperature(raw_temp);

        // Read humidity
        if (write_i2c_command(i2c_handle, HUMID_CMD) != 0) {
            fprintf(stderr, "Error writing humidity command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }
        gpioDelay(20); // Wait for measurement
        if (read_i2c_data(i2c_handle, data, 2) != 0) {
            fprintf(stderr, "Error reading humidity data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }
        raw_humidity = (data[0] << 8) | data[1];
        humidity = convert_humidity(raw_humidity);

        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

