#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0x240B
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define LOG_FILE "sht40_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sht40(float *temperature, float *humidity);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_crc(uint8_t data[], int nbrOfBytes);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_HIGH_REPEATABILITY >> 8) & 0xFF, MEASURE_HIGH_REPEATABILITY & 0xFF};
    uint8_t buffer[6];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(8500); // Wait at least 8.5 ms

    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Validate CRC for temperature
    if (validate_crc(buffer, 2) != 0) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Validate CRC for humidity
    if (validate_crc(buffer + 3, 2) != 0) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temp_raw = (buffer[0] << 8) | buffer[1];
    uint16_t hum_raw = (buffer[3] << 8) | buffer[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

// Calculate CRC checksum
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = CRC_INITIAL;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= (data[i]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = calculate_crc(data, nbrOfBytes);
    return (crc == data[nbrOfBytes]);
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
