#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_HIGH 28.0
#define TEMP_LOW 27.0
#define MAX_RETRIES 3

// Structure for storing temperature readings and timestamps
typedef struct {
    float temperature;
    time_t timestamp;
} Reading;

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer
Reading temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature(float *temperature);
void control_fan(float temperature);
void buffer_add(float temperature);
void buffer_print();
void signal_handler(int signal);

// Function to read temperature from Si7021
int read_temperature(float *temperature) {
    int retries = 0;
    int status;
    uint8_t data[2];

    while (retries < MAX_RETRIES) {
        status = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (status != 0) {
            fprintf(stderr, "Error writing temperature command: %d. Retry %d\n", status, retries + 1);
            gpioDelay(10); // Small delay before retry
            retries++;
            continue;
        }

        gpioDelay(25); // Wait for conversion (datasheet specifies 12.5ms for high accuracy)

        status = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (status != 2) {
            fprintf(stderr, "Error reading temperature data: %d. Retry %d\n", status, retries + 1);
            gpioDelay(10); // Small delay before retry
            retries++;
            continue;
        }

        // Convert raw data to temperature (Celsius)
        *temperature = (175.72 * (float)((data[0] << 8) | data[1])) / 65536.0 - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON (Temperature: %.2f°C)\n", temperature);
    } else if (temperature < TEMP_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF (Temperature: %.2f°C)\n", temperature);
    }
}

// Function to add temperature reading to the circular buffer
void buffer_add(float temperature) {
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void buffer_print() {
    printf("\n--- Temperature Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        printf("[%s] Temperature: %.2f°C\n", ctime(&temperature_buffer[index].timestamp), temperature_buffer[index].temperature);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    float temperature;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f°C\n", temperature);
            buffer_add(temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup before exiting
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

