#define CO2_THRESHOLD 1000

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_READ_MEASUREMENT 0xec05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86

// Data Structure for SCD40 Readings
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    time_t timestamp;
} scd40_reading_t;

// Circular Buffer Structure
typedef struct {
    scd40_reading_t readings[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global Variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_i2c();
int init_scd40();
int read_scd40_data(scd40_reading_t *reading);
uint8_t crc8(const uint8_t *data, int len);
void add_reading_to_buffer(circular_buffer_t *buffer, scd40_reading_t reading);
scd40_reading_t get_latest_reading(circular_buffer_t *buffer);
void control_led(int co2_ppm);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the SCD40 sensor
int init_scd40() {
    char cmd[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for the sensor to start
    return 0;
}

// Function to read data from the SCD40 sensor
int read_scd40_data(scd40_reading_t *reading) {
    char cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    char buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }

    // Extract data and perform CRC validation
    uint16_t co2_raw = (buffer[0] << 8) | buffer[1];
    uint8_t co2_crc = buffer[2];
    uint16_t temperature_raw = (buffer[3] << 8) | buffer[4];
    uint8_t temperature_crc = buffer[5];
    uint16_t humidity_raw = (buffer[6] << 8) | buffer[7];
    uint8_t humidity_crc = buffer[8];

    if (crc8((uint8_t *)&co2_raw, 2) != co2_crc) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }
    if (crc8((uint8_t *)&temperature_raw, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    if (crc8((uint8_t *)&humidity_raw, 2) != humidity_crc) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    reading->co2 = co2_raw;
    reading->temperature = temperature_raw;
    reading->humidity = humidity_raw;
    reading->timestamp = time(NULL);

    return 0;
}

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to add a reading to the circular buffer
void add_reading_to_buffer(circular_buffer_t *buffer, scd40_reading_t reading) {
    buffer->readings[buffer->head] = reading;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to get the latest reading from the circular buffer
scd40_reading_t get_latest_reading(circular_buffer_t *buffer) {
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->readings[index];
}

// Function to control the LED based on CO2 concentration
void control_led(int co2_ppm) {
    if (co2_ppm > CO2_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    // Stop periodic measurement
    char cmd[2] = {(CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    i2cWriteDevice(i2c_handle, cmd, 2);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set back to input

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40
    if (init_scd40() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Initially turn LED off

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    scd40_reading_t reading;
    while (!terminate) {
        if (read_scd40_data(&reading) == 0) {
            add_reading_to_buffer(&buffer, reading);
            printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
                   reading.co2,
                   -45 + 175 * (reading.temperature / 65535.0),
                   100 * (reading.humidity / 65535.0));
            control_led(reading.co2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

