#define GPIO_PIN 4
#define PWM_FREQUENCY 1000 // Hz
#define TIMEOUT_US 50000    // 50 ms
#define SAMPLE_INTERVAL_S 5
#define TEMP_MIN -40.0
#define TEMP_MAX 150.0
#define MALFUNCTION_THRESHOLD 3

static volatile int running = 1;
static FILE *log_file = NULL;
static int malfunction_count = 0;

// Structure to hold PWM pulse width data
typedef struct {
    uint32_t high_time;
    uint32_t total_time;
} PWMPulse;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_buffer;
}

// Function to read PWM pulse width
PWMPulse read_pwm_pulse(int gpio_pin, int timeout_us) {
    PWMPulse pulse;
    uint32_t start_tick, end_tick, high_start_tick, high_end_tick;

    // Wait for the pin to go high
    start_tick = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - start_tick > timeout_us) {
            pulse.high_time = 0;
            pulse.total_time = 0;
            return pulse; // Timeout
        }
    }
    high_start_tick = gpioTick();

    // Wait for the pin to go low
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - high_start_tick > timeout_us) {
            pulse.high_time = 0;
            pulse.total_time = 0;
            return pulse; // Timeout
        }
    }
    high_end_tick = gpioTick();
    end_tick = gpioTick();

    pulse.high_time = high_end_tick - high_start_tick;
    pulse.total_time = end_tick - start_tick;

    return pulse;
}

// Function to calculate temperature from pulse width
double calculate_temperature(uint32_t high_time, uint32_t total_time) {
    if (total_time == 0) {
        return -999.0; // Indicate error
    }

    double temperature = (double)high_time / (double)total_time * 100.0 - 50.0;
    return temperature;
}

// Function to log temperature data
void log_temperature(double temperature, const char* timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f °C\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to log error message
void log_error(const char* message, const char* timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int result;
    char timestamp_buffer[32];
    PWMPulse pulse;
    double temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read PWM pulse width
        pulse = read_pwm_pulse(GPIO_PIN, TIMEOUT_US);

        // Calculate temperature
        temperature = calculate_temperature(pulse.high_time, pulse.total_time);

        // Get timestamp
        get_iso8601_timestamp(timestamp_buffer, sizeof(timestamp_buffer));

        // Validate temperature
        if (temperature >= TEMP_MIN && temperature <= TEMP_MAX) {
            log_temperature(temperature, timestamp_buffer);
            malfunction_count = 0; // Reset malfunction count
        } else {
            char error_message[64];
            snprintf(error_message, sizeof(error_message), "Temperature out of range: %.2f °C", temperature);
            log_error(error_message, timestamp_buffer);
            malfunction_count++;

            if (malfunction_count >= MALFUNCTION_THRESHOLD) {
                log_error("SENSOR MALFUNCTION", timestamp_buffer);
                malfunction_count = 0; // Reset after logging
            }
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Delay for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

