#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CRC_POLYNOMIAL 0x31
#define SLEEP_DURATION_SEC 5
#define SINUSOID_PERIOD_HOURS 1
#define SINUSOID_AMPLITUDE_TEMP 2.0
#define SINUSOID_AMPLITUDE_HUMIDITY 5.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
SensorData convert_raw_data(uint8_t data[]);
SensorData apply_sinusoidal_offset(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);

// CRC check function
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= (data[i]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, (MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(1000); // Wait 1 second
            retries--;
            continue;
        }

        gpioDelay(15000); // Wait 15 ms

        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(1000); // Wait 1 second
            retries--;
            continue;
        }
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Convert raw data to temperature and humidity
SensorData convert_raw_data(uint8_t data[]) {
    SensorData sensor_data;
    int32_t raw_temperature = (data[0] << 8) | data[1];
    int32_t raw_humidity = (data[3] << 8) | data[4];

    // CRC Check
    if (calculate_crc(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        sensor_data.temperature = NAN;
    } else {
        sensor_data.temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    }

    if (calculate_crc(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        sensor_data.humidity = NAN;
    } else {
        sensor_data.humidity = 100.0 * (float)raw_humidity / 65535.0;
    }

    return sensor_data;
}

// Apply sinusoidal offset
SensorData apply_sinusoidal_offset(SensorData data) {
    time_t now = time(NULL);
    double time_elapsed = difftime(now, 1483228800); // Start at 2017-01-01 00:00:00 UTC
    double offset_temp = SINUSOID_AMPLITUDE_TEMP * sin(2 * M_PI * time_elapsed / (SINUSOID_PERIOD_HOURS * 3600));
    double offset_humidity = SINUSOID_AMPLITUDE_HUMIDITY * sin(2 * M_PI * time_elapsed / (SINUSOID_PERIOD_HOURS * 3600));

    data.temperature += offset_temp;
    data.humidity += offset_humidity;

    return data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (isnan(data.temperature) || isnan(data.humidity)) {
        fprintf(log_file, "%s,NaN,NaN\n", timestamp);
        fprintf(stderr, "%s,NaN,NaN\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
        printf("%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    }
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data_raw[6];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data_raw) == 0) {
            sensor_data = convert_raw_data(sensor_data_raw);
            sensor_data = apply_sinusoidal_offset(sensor_data);
            log_data(sensor_data);
        } else {
            // Log NaN values if read failed
            sensor_data.temperature = NAN;
            sensor_data.humidity = NAN;
            log_data(sensor_data);
        }

        gpioDelay(SLEEP_DURATION_SEC * 1000); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

