        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return 1;
    }

    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->crc = buf[8];

    return 0;
}

