#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SHT35 I2C address
#define SHT35_ADDR 0x44

// Measurement command (Single Shot, High Repeatability, Clock Stretching Disabled)
#define MEASURE_CMD 0x2400

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the SHT35 sensor
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait 15 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate the CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len);
    return (crc == data[len]);
}

// Function to convert raw data to temperature and humidity
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract raw temperature and humidity values
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    // Convert to Celsius and percentage
    sensor_data->temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    sensor_data->humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

// Function to log data to a CSV file
int log_data(const sensor_data_t *sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data->temperature, sensor_data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and file handles
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("environment.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty or doesn't exist, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Humidity (%%)\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    uint8_t data[6];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 2) && validate_crc(data + 3, 2)) {
                // Convert data
                if (convert_data(data, &sensor_data) == 0) {
                    // Log data
                    if (log_data(&sensor_data) != 0) {
                        fprintf(stderr, "Error logging data!\n");
                    }
                } else {
                    fprintf(stderr, "Error converting data!\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed!\n");
