#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define CONVERSION_TIME_US 50000 // 50ms
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define SCALE_FACTOR_PRESSURE 60.0
#define SCALE_FACTOR_TEMPERATURE 200.0
#define SCALE_FACTOR_HUMIDITY 100.0

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len, uint8_t crc);
sensor_data_t convert_data(const char *buffer);
int log_data(FILE *file, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a command to the sensor
int write_command(int handle, uint16_t command) {
    char buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC-8 checksum
int validate_crc(const char *data, int len, uint8_t crc) {
    return (calculate_crc(data, len) == crc);
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(const char *buffer) {
    sensor_data_t data;
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data.pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE;
    data.temperature = (float)raw_temperature / SCALE_FACTOR_TEMPERATURE;

    return data;
}

// Function to log data to a file
int log_data(FILE *file, sensor_data_t data) {
    if (fwrite(&data.pressure, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&data.temperature, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen("airflow.dat", "wb");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[9];

        // Write measurement command
        if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to write measurement command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_US);

        // Read data
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(buffer, 2, buffer[2])) {
            fprintf(stderr, "CRC validation failed for pressure\n");
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(buffer + 3, 2, buffer[5])) {
            fprintf(stderr, "CRC validation failed for temperature\n");
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(buffer);

        // Log data
        if (log_data(data_file, data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

