int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, float *pressure);
float calculate_flow_rate(float pressure);
void set_fan_speed(int gpio, int duty_cycle);
void log_data(FILE *log_file, float pressure);
void signal_handler(int signal);

// Function to read the sensor data
int read_sensor(int i2c_handle, float *pressure) {
    char buffer[2];
    int result;

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate failure
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (buffer[0] << 8) | buffer[1];

    // Convert the raw value to pressure (Pa)
    *pressure = (float)raw_value / 100.0; // Example conversion, adjust as needed

    return 0; // Indicate success
}

// Function to calculate the flow rate
float calculate_flow_rate(float pressure) {
    // Linear mapping from pressure to flow rate
    return (pressure - PRESSURE_MIN) / (PRESSURE_MAX - PRESSURE_MIN) * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;
}

// Function to set the fan speed using PWM
void set_fan_speed(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to log the data to a file
void log_data(FILE *log_file, float pressure) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.2f\n", now, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float pressure, flow_rate;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(i2c_handle, &pressure) == 0) {
            // Calculate flow rate
            flow_rate = calculate_flow_rate(pressure);

            // Map flow rate to duty cycle (0-255)
            duty_cycle = (int)(flow_rate / FLOW_MAX * 255.0);
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > 255) duty_cycle = 255;

            // Set fan speed
            set_fan_speed(FAN_GPIO, duty_cycle);

            // Log data
            log_data(log_file, pressure);

            // Print to console for debugging
            printf("Pressure: %.2f Pa, Flow Rate: %.2f, Duty Cycle: %d\n", pressure, flow_rate, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    set_fan_speed(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

