#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define GPIO_LED 17
#define TEMP_THRESHOLD 28.0
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int read_temperature(float *temperature);
void update_circular_buffer(float temperature);
float calculate_running_average();
void control_led(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int stlm75_address;
    int gpio_led;
    float temp_threshold;
    int buffer_size;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .stlm75_address = STLM75_ADDR,
    .gpio_led = GPIO_LED,
    .temp_threshold = TEMP_THRESHOLD,
    .buffer_size = BUFFER_SIZE
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    float temperature;
    float average_temperature;
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Update circular buffer
            update_circular_buffer(temperature);

            // Calculate running average
            average_temperature = calculate_running_average();

            // Control LED
            control_led(average_temperature);

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping iteration.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(config.i2c_bus, config.stlm75_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from STLM75
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return 1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    *temperature = raw_temp * 0.125;

    return 0;
}

// Update circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % config.buffer_size;
}

// Calculate running average
float calculate_running_average() {
    float sum = 0.0;
    for (int i = 0; i < config.buffer_size; i++) {
        sum += temperature_buffer[i];
    }
    return sum / config.buffer_size;
}

// Control LED
void control_led(float average_temperature) {
    if (average_temperature > config.temp_threshold) {
        gpioWrite(config.gpio_led, 1); // Turn LED on
    } else {
        gpioWrite(config.gpio_led, 0); // Turn LED off
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    gpioWrite(config.gpio_led, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
}

