// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_SET_MEASUREMENT_INTERVAL 0x4600

// Ventilation states
typedef enum {
    OFF,
    LOW,
    HIGH
} VentilationState;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_scd30();
int read_scd30_data(float *co2, float *temperature, float *humidity);
VentilationState determine_ventilation_state(float co2);
int log_data(float co2, float temperature, float humidity, VentilationState state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} SensorData;

// Function to write a command to the SCD30
int write_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
