        fprintf(stderr, "Error writing command 0x%04X: %s\n", command, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from the SCD30
int read_data(int handle, char *buf, int count) {
    int result = i2cReadDevice(handle, buf, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the SCD30 sensor
int init_scd30() {
    // Set measurement interval to 5 seconds
    if (write_command(i2c_handle, SCD30_CMD_SET_MEASUREMENT_INTERVAL) != 0) {
        fprintf(stderr, "Error setting measurement interval\n");
        return -1;
    }
    char interval_data[2] = {0x00, 0x05}; // 5 seconds
    if (i2cWriteDevice(i2c_handle, interval_data, 2) != 0) {
        fprintf(stderr, "Error setting measurement interval data\n");
        return -1;
    }

    // Start periodic measurement
    if (write_command(i2c_handle, SCD30_CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error starting periodic measurement\n");
        return -1;
    }

    return 0;
}

