#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SDP32 I2C address
#define SDP32_ADDR 0x21

// I2C bus
#define I2C_BUS 1

// Measurement command (continuous, no averaging)
#define MEASURE_CMD 0x2190

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sdp32(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SDP32 sensor
int read_sdp32(sensor_data_t *data) {
    char buf[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (adjust as needed based on SDP32 datasheet)
    gpioDelay(50); // 50 ms delay

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Extract data
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    // CRC validation
    uint8_t pressure_crc = crc8((uint8_t *)buf, 2);
    uint8_t temperature_crc = crc8((uint8_t *)buf + 3, 2);
    uint8_t scale_factor_crc = crc8((uint8_t *)buf + 6, 2);

    if (pressure_crc != buf[2]) {
        fprintf(stderr, "Pressure CRC error!\n");
        return -1;
    }
    if (temperature_crc != buf[5]) {
        fprintf(stderr, "Temperature CRC error!\n");
        return -1;
    }
    if (scale_factor_crc != buf[8]) {
        fprintf(stderr, "Scale Factor CRC error!\n");
        return -1;
    }

    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Print sensor data with timestamp
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Pressure: %d Pa, Temperature: %d deg C, Scale Factor: %d\n",
           timestamp, data.pressure, data.temperature, data.scale_factor);
}

int main(int argc, char *argv[]) {
    int interval_ms = 1000; // Default interval
    sensor_data_t sensor_data;
    int result;

    // Parse command-line argument
    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval. Using default: 1000 ms\n");
            interval_ms = 1000;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("SDP32 sensor reader started. Interval: %d ms\n", interval_ms);

    // Main loop
    while (!terminate) {
        result = read_sdp32(&sensor_data);
        if (result == 0) {
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in %d ms...\n", interval_ms);
        }

        gpioDelay(interval_ms);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

