// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x25

// Define the trigger command
#define TRIGGER_COMMAND 0x362F

// Define the CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Global variable for I2C handle
int i2c_handle = -1;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len);
sensor_data_t convert_data(uint8_t *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads data from the sensor
int read_sensor_data(uint8_t *data) {
    uint8_t buffer[9];
    int result;

    // Send trigger command
    result = i2cWriteByteData(i2c_handle, TRIGGER_COMMAND >> 8, TRIGGER_COMMAND & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        return -1;
    }

    // Wait for conversion (45 ms)
    gpioDelay(45000);

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Copy the data to the provided buffer
    for (int i = 0; i < 9; i++) {
        data[i] = buffer[i];
    }

    return 0;
}

// Calculates the CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validates the CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = calculate_crc(data, len);
    return (crc == data[len]);
}

// Converts raw data to pressure and temperature
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Scale factors (from datasheet)
    float pressure_scale = 60.0; // Pa
    float temperature_scale = 200.0; // °C

    sensor_data.pressure = (float)raw_pressure / pressure_scale;
    sensor_data.temperature = (float)raw_temperature / temperature_scale;

    return sensor_data;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    uint8_t data[9];
    sensor_data_t sensor_values;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 2) && validate_crc(data + 3, 2)) {
                // Convert data
                sensor_values = convert_data(data);

                // Print data
                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", sensor_values.pressure, sensor_values.temperature);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

