#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from HDC1000
int read_hdc1000(int i2c_fd, float *temperature, float *humidity) {
    unsigned char buf[4];
    int result;

    // Trigger temperature and humidity conversion
    result = i2cWriteByteData(i2c_fd, CONFIGURATION_REG, 0x00); // Reset
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    gpioDelay(15); // Wait for conversion (at least 15ms)

    // Read temperature and humidity registers
    result = i2cReadI2CBlockData(i2c_fd, TEMPERATURE_REG, (char *)buf, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature and humidity registers: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    uint16_t raw_humidity = (buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, HDC1000_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log data to console
            printf("%s Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000); // 5000 ms = 5 seconds
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

