#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define SLEEP_TIME_US 5000000 // 5 seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read temperature from Si7051
float read_temperature() {
    char buf[2];
    int result;

    // Send temperature measurement command
    result = i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Wait for measurement (datasheet recommends at least 20ms)
    gpioDelay(20000); // 20ms

    // Read two bytes of temperature data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    return temperature;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in 5 seconds.\n");
        }

        gpioDelay(SLEEP_TIME_US);
    }

    // Cleanup and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

