#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define MLX90821_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register address, adjust as needed
#define LOG_FILE "pressure_log.csv"
#define SAFE_PRESSURE_MIN 200.0
#define SAFE_PRESSURE_MAX 250.0

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
float read_pressure();
void log_pressure(float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    int i2c_address;
    int i2c_bus;
} sensor_config_t;

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from MLX90821
float read_pressure() {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1.0; // Indicate error
    }

    // Convert raw data to pressure (kPa) - Example conversion
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    float pressure = (float)raw_pressure / 100.0; // Adjust scaling factor as needed

    return pressure;
}

// Log pressure to CSV file
void log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fclose(log_file);
}

// Check pressure range and log warning
void check_pressure_range(float pressure) {
    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        fprintf(stderr, "Warning: Pressure out of safe range: %.2f kPa\n", pressure);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float pressure = read_pressure();
        if (pressure >= 0) {
            log_pressure(pressure);
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before retrying
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break; // Exit loop if re-initialization fails
            }
            continue; // Skip logging and range check if read failed
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (in case the loop breaks)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

