#define LOG_FILE_OLD "environmental_data.log.old"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB
#define TRIGGER_MEASUREMENT 0x00
#define DATA_LENGTH 4
#define SENSOR_ABSENT_RETRIES 3
#define SENSOR_ABSENT_DELAY 1 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_sensor_data(const uint8_t *data);
int log_data(float temperature, float humidity);
void roll_log_file();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cWriteByte(i2c_handle, TRIGGER_MEASUREMENT);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    gpioDelay(40); // Wait 40 ms

    result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate sensor data
int validate_sensor_data(const uint8_t *data) {
    // Check status bits (bits 6 and 7 of the first byte)
    int status = (data[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Invalid sensor status: %d\n", status);
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Function to roll log file
void roll_log_file() {
    remove(LOG_FILE_OLD);
    rename(LOG_FILE, LOG_FILE_OLD);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[DATA_LENGTH];
    sensor_data_t processed_data;

    while (program_running) {
        // Check if log file exceeds size limit
        FILE *fp = fopen(LOG_FILE, "r");
        if (fp != NULL) {
            fseek(fp, 0, SEEK_END);
            long file_size = ftell(fp);
            fclose(fp);

            if (file_size > LOG_FILE_SIZE_LIMIT) {
                roll_log_file();
            }
        }

        // Read sensor data with retries
        int sensor_present = 0;
        for (int i = 0; i < SENSOR_ABSENT_RETRIES; ++i) {
            if (read_sensor_data(sensor_data) == 0) {
                if (validate_sensor_data(sensor_data) == 0) {
                    sensor_present = 1;
                    break;
                }
            }
            gpioDelay(SENSOR_ABSENT_DELAY * 1000); // Delay in milliseconds
        }

        if (sensor_present) {
            // Convert raw data to temperature and humidity
            int humidity_raw = ((sensor_data[0] & 0x3F) << 8) | sensor_data[1];
            int temperature_raw = (sensor_data[2] << 6) | (sensor_data[3] >> 2);

            processed_data.humidity = (float)humidity_raw / 16383 * 100;
            processed_data.temperature = (float)temperature_raw / 16383 * 165 - 40;

            // Log data
            if (log_data(processed_data.temperature, processed_data.humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Sensor not present after multiple retries\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

