#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define GPIO_PIN 4
#define TICK_TIME_US 3 // 3 microseconds
#define SYNC_PULSE_TICKS 56 // 56 ticks = 189 us
#define MIN_PULSE_WIDTH_TICKS 12 // 36 us
#define MAX_PULSE_WIDTH_TICKS 271 // 813 us
#define MAX_TIMEOUT_US 100000 // 100ms timeout
#define LOG_FILE "pressure_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    unsigned int status;
    unsigned int data1;
    unsigned int data2;
    unsigned int data3;
    unsigned int checksum;
} SensorData;

// Function prototypes
int initialize_gpio();
int read_sent_data(unsigned int *pulse_widths, int *num_pulses);
int decode_sent_data(const unsigned int *pulse_widths, int num_pulses, SensorData *data);
int validate_checksum(const SensorData *data);
int log_pressure_data(const SensorData *data);
void handle_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor
    return 0;
}

// Function to read SENT data
int read_sent_data(unsigned int *pulse_widths, int *num_pulses) {
    int i = 0;
    unsigned int start_time, end_time, pulse_width;

    // Wait for the start of the SENT frame (falling edge)
    while (gpioRead(GPIO_PIN) == 1 && running) {
        // Timeout check
        if (i > MAX_TIMEOUT_US) {
            handle_error("Timeout waiting for start of SENT frame");
            return -1;
        }
        gpioDelay(1); // Wait 1 us
        i++;
    }

    start_time = gpioTick();

    // Read pulse widths
    while (running) {
        // Wait for the pin to go high
        while (gpioRead(GPIO_PIN) == 0 && running) {
            gpioDelay(1);
        }

        end_time = gpioTick();
        pulse_width = end_time - start_time;
        start_time = end_time;

        // Validate pulse width
        if (pulse_width < MIN_PULSE_WIDTH_TICKS * TICK_TIME_US || pulse_width > MAX_PULSE_WIDTH_TICKS * TICK_TIME_US) {
            handle_error("Invalid pulse width");
            return -1;
        }

        pulse_widths[i] = pulse_width;
        i++;

        // Wait for the pin to go low
        while (gpioRead(GPIO_PIN) == 1 && running) {
            gpioDelay(1);
        }

        // Check for end of frame (rising edge after sync pulse)
        if (i > SYNC_PULSE_TICKS && gpioRead(GPIO_PIN) == 1) {
            *num_pulses = i;
            return 0;
        }
    }

    return -1; // Indicate program termination
}

// Function to decode SENT data
int decode_sent_data(const unsigned int *pulse_widths, int num_pulses, SensorData *data) {
    if (num_pulses < 16) {
        handle_error("Too few pulses received");
        return -1;
    }

    // Extract status nibble
    data->status = (pulse_widths[1] - 12) / 12; // Assuming 12us tick

    // Extract data nibbles
    data->data1 = (pulse_widths[3] - 12) / 12;
    data->data2 = (pulse_widths[5] - 12) / 12;
    data->data3 = (pulse_widths[7] - 12) / 12;

    // Extract checksum nibble
    data->checksum = (pulse_widths[9] - 12) / 12;

    return 0;
}

// Function to validate checksum
int validate_checksum(const SensorData *data) {
    unsigned int checksum = (data->status << 12) | (data->data1 << 8) | (data->data2 << 4) | data->data3;
    unsigned int received_checksum = (data->checksum << 12) | (data->data1 << 8) | (data->data2 << 4) | data->data3;

    if (checksum != received_checksum) {
        handle_error("Checksum mismatch");
        return -1;
    }

    return 0;
}

// Function to log pressure data
int log_pressure_data(const SensorData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    float pressure = (float)data->data1 * 0.1; // Example conversion

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    if (log_file != NULL) {
        fprintf(log_file, "Error: %s\n", message);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    unsigned int pulse_widths[256]; // Assuming max 256 pulses
    int num_pulses;
    SensorData data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Starting pressure sensor data logging...\n");

    while (running) {
        // Read SENT data
        if (read_sent_data(pulse_widths, &num_pulses) == 0) {
            // Decode SENT data
            if (decode_sent_data(pulse_widths, num_pulses, &data) == 0) {
                // Validate checksum
                if (validate_checksum(&data) == 0) {
                    // Log pressure data
                    log_pressure_data(&data);
                }
            }
        }

        gpioDelay(100); // Delay between readings
    }

    cleanup();
    return 0;
}

