#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define DEVICE_ID 0x5000
#define LOG_FILE "greenhouse_temps.dat"
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
float read_temperature();
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%X (expected 0x%X)\n", device_id, DEVICE_ID);
        return -1;
    }

    printf("Device ID verified: 0x%X\n", device_id);
    return 0;
}

// Read temperature
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius (see TMP117 datasheet)
    float temperature = (float)raw_temp * 0.0078125;
    return temperature;
}

// Log temperature to file
int log_temperature(float temperature) {
    uint8_t buffer[4];
    float *temp_ptr = (float *)buffer;
    *temp_ptr = temperature;

    size_t bytes_written = fwrite(buffer, 1, 4, log_file);
    if (bytes_written != 4) {
        fprintf(stderr, "Error writing temperature to file: %zu bytes written\n", bytes_written);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Greenhouse temperature monitoring started. Logging to %s\n", LOG_FILE);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping logging.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

