#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 commands
#define SHT40_MEASURE_HIGH_PRECISION 0xFD

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40(uint8_t *data) {
    if (i2cWriteByte(i2c_handle, SHT40_MEASURE_HIGH_PRECISION) != 0) {
        fprintf(stderr, "Error writing to I2C\n");
        return -1;
    }
    gpioDelay(8500); // Wait 8.5 ms

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C\n");
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len);
    return (crc == 0);
}

// Convert raw data to temperature and humidity
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract raw temperature and humidity values
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    // Convert to Celsius and percentage relative humidity
    sensor_data->temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
    sensor_data->humidity = 100.0 * (raw_humidity / 65535.0);

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *sensor_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data->temperature, sensor_data->humidity);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint8_t data[6];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sht40(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 2) && validate_crc(data + 3, 2)) {
                // Convert data
                if (convert_data(data, &sensor_data) == 0) {
                    // Log data
                    log_data(&sensor_data);
                } else {
                    fprintf(stderr, "Error converting data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

