#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(float temperature);
void write_buffer_to_file();
void signal_handler(int signal);
void init_circular_buffer();

// Initialize circular buffer
void init_circular_buffer() {
    temp_buffer.head = 0;
    temp_buffer.count = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
float read_temperature() {
    int raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_data);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to Celsius (see TMP117 datasheet)
    float temperature = (float)((int16_t)raw_data) * 0.0078125;
    return temperature;
}

// Add temperature to circular buffer
void add_to_buffer(float temperature) {
    temp_buffer.buffer[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

// Write buffer to file
void write_buffer_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file for writing!\n");
        return;
    }

    size_t elements_written = fwrite(temp_buffer.buffer, sizeof(float), temp_buffer.count, fp);
    if (elements_written != temp_buffer.count) {
        fprintf(stderr, "Error writing to log file! Wrote %zu elements, expected %d\n", elements_written, temp_buffer.count);
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            add_to_buffer(temperature);
        }
        sleep(SAMPLE_INTERVAL);
    }

    // Write buffer to file before exiting
    write_buffer_to_file();

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

