    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, SHTC3_MEASURE_NORMAL) != 0) {
            fprintf(stderr, "Error sending measurement command\n");
            cleanup();
            return 1;
        }

        // Wait for measurement to complete (at least 12.4 ms)
        gpioDelay(15000); // 15 ms

        // Read data
        if (read_data(i2c_handle, data, 6) != 0) {
            fprintf(stderr, "Error reading data\n");
            cleanup();
            return 1;
        }

        // Validate data
        if (validate_data(data) != 0) {
            fprintf(stderr, "Data validation failed\n");
            cleanup();
            return 1;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Validate sensor readings
        if (sensor_data.temperature < -40.0 || sensor_data.temperature > 125.0 ||
            sensor_data.humidity < 0.0 || sensor_data.humidity > 100.0) {
            fprintf(stderr, "Sensor readings out of range: Temperature=%.2f, Humidity=%.2f\n",
                    sensor_data.temperature, sensor_data.humidity);
