#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"
#define SLEEP_SECONDS 1

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
float read_temperature();
char* format_timestamp();
int log_temperature(char* timestamp, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    int retries = 0;
    while (retries < 3) {
        i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
        if (i2c_handle >= 0) {
            printf("I2C initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error opening I2C device: %d. Retry %d/%d\n", i2c_handle, retries + 1, 3);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }
    fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
    return -1; // Failure
}

// Read temperature from TMP117
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes_read);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = raw_temp * 0.0078125;

    return temperature;
}

// Format timestamp
char* format_timestamp() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    static char timestamp[20]; // Static to persist across calls
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);
    return timestamp;
}

