#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FLOW_LOG_FILE "flow_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define START_BYTE 0x01
#define STOP_BYTE 0x02
#define NUM_INIT_READS 2
#define RETRY_COUNT 3

// Global variables
int i2c_handle = -1;
FILE *flow_log_fp = NULL;
FILE *error_log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float flow_slpm;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(sensor_data_t data);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        log_error("Failed to read sensor data");
        return -1;
    }
    return 0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract flow data (14 bits)
    int flow_raw = ((data[0] & 0x3F) << 6) | (data[1] >> 2);
    sensor_data.flow_slpm = (float)flow_raw / 10.0; // SLPM

    // Extract temperature data (12 bits)
    int temperature_raw = ((data[1] & 0x03) << 8) | data[2];
    sensor_data.temperature_c = (float)temperature_raw / 10.0; // °C

    return sensor_data;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(flow_log_fp, "%s, %.2f SLPM, %.2f °C\n", timestamp, data.flow_slpm, data.temperature_c);
    fflush(flow_log_fp); // Ensure data is written to disk immediately

    return 0;
}

// Function to log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_fp, "%s, %s\n", timestamp, message);
    fflush(error_log_fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (flow_log_fp != NULL) {
        fclose(flow_log_fp);
    }
    if (error_log_fp != NULL) {
        fclose(error_log_fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    flow_log_fp = fopen(FLOW_LOG_FILE, "a");
    if (flow_log_fp == NULL) {
        fprintf(stderr, "Failed to open flow log file\n");
        gpioTerminate();
        return 1;
    }

    error_log_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_log_fp == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(flow_log_fp);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Read sensor data and log it
    uint8_t sensor_data[4];
    int init_reads_remaining = NUM_INIT_READS;
    int retry;

    while (!terminate) {
        // Read sensor data with retries
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(sensor_data) == 0) {
                break; // Success, exit retry loop
            } else {
                retry++;
                gpioDelay(100); // Wait 100ms before retrying
            }
        }

        if (retry == RETRY_COUNT) {
            log_error("Failed to read sensor data after multiple retries");
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        // Process sensor data
        sensor_data_t data = process_sensor_data(sensor_data);

        // Log data
        log_data(data);

        // Wait for 1 second
        gpioDelay(1000);

        // Initialization reads
        if (init_reads_remaining > 0) {
            init_reads_remaining--;
            log_error("Initialization read, discarding data.");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

