#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 100000 // 100ms timeout
#define RETRY_COUNT 3

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
} DHT11Data;

// Function prototypes
int readDHT11(DHT11Data *data);
int validateChecksum(const unsigned char *data);
int logError(const char *message, int statusCode);
int logData(int humidity, int temperature);
void signalHandler(int signal);

// Global variable for program termination
volatile sig_atomic_t programRunning = 1;

// Signal handler function
void signalHandler(int signal) {
    programRunning = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to read data from DHT11 sensor
int readDHT11(DHT11Data *data) {
    unsigned char data_buffer[5] = {0, 0, 0, 0, 0};
    int i, j;

    // Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for response (low pulse)
    int start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            logError("Timeout waiting for DHT11 response", 1);
            return 1;
        }
    }

    // Wait for response (high pulse)
    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            logError("Timeout waiting for DHT11 response", 1);
            return 1;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for low pulse
            start_time = gpioTick();
            while (gpioRead(DHT11_GPIO) == 1) {
                if (gpioTick() - start_time > TIMEOUT_US) {
                    logError("Timeout waiting for DHT11 data bit", 2);
                    return 1;
                }
            }

            // Measure high pulse duration
            start_time = gpioTick();
            while (gpioRead(DHT11_GPIO) == 0) {
                if (gpioTick() - start_time > TIMEOUT_US) {
                    logError("Timeout waiting for DHT11 data bit", 2);
                    return 1;
                }
            }
            int pulse_duration = gpioTick() - start_time;

            // Determine if bit is 0 or 1 based on pulse duration
            if (pulse_duration > 40) {
                data_buffer[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    if (!validateChecksum(data_buffer)) {
        logError("Checksum validation failed", 3);
        return 1;
    }

    // Extract humidity and temperature
    data->humidity = data_buffer[0];
    data->temperature = data_buffer[2];

    return 0;
}

// Function to validate the checksum
int validateChecksum(const unsigned char *data) {
    return ((data[0] + data[1] + data[2] + data[3]) & 0xFF) == data[4];
}

// Function to log errors to a file
int logError(const char *message, int statusCode) {
    FILE *fp = fopen("dht11_errors.txt", "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - %s - Status Code: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message, statusCode);
    fclose(fp);
    return 0;
}

// Function to log data to a file
int logData(int humidity, int temperature) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (fp == NULL) {
        perror("Error opening data log file");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Humidity: %d%%, Temperature: %d°C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, humidity, temperature);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    DHT11Data data;
    int retries = 0;

    while (programRunning) {
        if (readDHT11(&data) == 0) {
            if (logData(data.humidity, data.temperature) != 0) {
                logError("Failed to log data", 4);
            }
            retries = 0; // Reset retry count on success
        } else {
            retries++;
            if (retries >= RETRY_COUNT) {
                logError("Max retries reached, exiting", 5);
                programRunning = 0; // Exit loop after max retries
            }
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    gpioTerminate();
    return 0;
}

