    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    DHT11Data data;
    int retries = 0;

    while (programRunning) {
        if (readDHT11(&data) == 0) {
            if (logData(data.humidity, data.temperature) != 0) {
                logError("Failed to log data", 4);
            }
            retries = 0; // Reset retry count on success
        } else {
            retries++;
            if (retries >= RETRY_COUNT) {
                logError("Max retries reached, exiting", 5);
                programRunning = 0; // Exit loop after max retries
            }
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    gpioTerminate();
    return 0;
}

