#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06 // High repeatability, clock stretching disabled
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define DATA_LENGTH 6
#define RETRY_COUNT 3
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int write_command(int handle, uint16_t command);
int read_data(int handle, char *data, int count);
uint8_t calculate_crc(const char *data, int length);
int validate_crc(const char *data, int length);
int convert_temperature(uint16_t raw_temp);
int convert_humidity(uint16_t raw_humidity);
int log_data(FILE *file, int temperature, int humidity);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data
typedef struct {
    int temperature;
    int humidity;
} SensorData;

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection();
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        gpioTerminate();
        return 1;
    }

