    log_file = fopen("sht31d_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data[DATA_LENGTH];
        SensorData sensor_data;

        // Write measurement command
        if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to write measurement command. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement (at least 15 ms)
        gpioDelay(15000); // 15 ms

        // Read data
        if (read_data(i2c_handle, data, DATA_LENGTH) != 0) {
            fprintf(stderr, "Failed to read data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(data, DATA_LENGTH) != 0) {
            fprintf(stderr, "CRC validation failed. Discarding data.\n");
            continue;
        }

        // Convert data
        uint16_t raw_temp = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[3] << 8) | data[4];

        sensor_data.temperature = convert_temperature(raw_temp);
        sensor_data.humidity = convert_humidity(raw_humidity);

