// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    int handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write command to SHT31-D
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SHT31-D
int read_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const char *data, int length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const char *data, int length) {
    uint8_t crc_calculated = calculate_crc(data, length - 1);
    uint8_t crc_received = data[length - 1];
    return (crc_calculated == crc_received) ? 0 : -1;
}

// Convert raw temperature to Celsius
int convert_temperature(uint16_t raw_temp) {
    return (int)(175.0 * (float)raw_temp / 65535.0 - 45.0);
}

// Convert raw humidity to percentage
int convert_humidity(uint16_t raw_humidity) {
    return (int)(100.0 * (float)raw_humidity / 65535.0);
}

// Log data to file
int log_data(FILE *file, int temperature, int humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(file, "%s,%d,%d\n", timestamp, temperature, humidity);
    fflush(file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

