#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor I2C addresses
#define SENSOR1_ADDR 0x38
#define SENSOR2_ADDR 0x39

// Define register addresses (replace with actual values from datasheet)
#define REG_PART_ID 0x00
#define REG_CONFIG 0x01
#define REG_DATA_HIGH 0x02
#define REG_DATA_LOW 0x03

// Define CCT range
#define MIN_CCT 1000
#define MAX_CCT 15000

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
    int part_id;
} sensor_t;

// Function prototypes
int initialize_sensor(sensor_t *sensor);
int read_sensor_data(sensor_t *sensor, uint16_t *data);
float calculate_cct(uint16_t data);
int log_cct(float cct1, float cct2, float avg_cct);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize a sensor
int initialize_sensor(sensor_t *sensor) {
    int retries = 3;
    while (retries > 0) {
        sensor->handle = i2cOpen(1, sensor->address, 0); // Bus 1
        if (sensor->handle >= 0) {
            // Verify Part ID (replace with actual Part ID from datasheet)
            char part_id;
            if (i2cReadI2CBlockData(sensor->handle, REG_PART_ID, &part_id, 1) == 1) {
                sensor->part_id = part_id; // Store the Part ID
                // Configure the sensor (replace with actual configuration)
                if (i2cWriteByteData(sensor->handle, REG_CONFIG, 0x01) == 0) {
                    fprintf(stderr, "Sensor %x initialized successfully.\n", sensor->address);
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error configuring sensor %x.\n", sensor->address);
                }
            } else {
                fprintf(stderr, "Error reading Part ID from sensor %x.\n", sensor->address);
            }
            i2cClose(sensor->handle);
            sensor->handle = -1;
        } else {
            fprintf(stderr, "Error opening I2C device for sensor %x.\n", sensor->address);
        }
        retries--;
        gpioDelay(100000); // Wait 100ms before retrying
    }
    fprintf(stderr, "Failed to initialize sensor %x after multiple retries.\n", sensor->address);
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(sensor_t *sensor, uint16_t *data) {
    char buffer[2];
    if (i2cReadI2CBlockData(sensor->handle, REG_DATA_HIGH, buffer, 2) == 2) {
        *data = (buffer[0] << 8) | buffer[1];
        return 0; // Success
    } else {
        fprintf(stderr, "Error reading data from sensor %x.\n", sensor->address);
        return -1; // Failure
    }
}

// Function to calculate CCT (replace with actual formula from datasheet)
float calculate_cct(uint16_t data) {
    // Example formula (replace with actual formula)
    float cct = MIN_CCT + (float)data * (MAX_CCT - MIN_CCT) / 65535.0;
    return cct;
}

// Function to log CCT data to a file
int log_cct(float cct1, float cct2, float avg_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, cct1, cct2, avg_cct);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Define sensors
    sensor_t sensor1 = { .address = SENSOR1_ADDR };
    sensor_t sensor2 = { .address = SENSOR2_ADDR };

    // Initialize sensors
    if (initialize_sensor(&sensor1) != 0 || initialize_sensor(&sensor2) != 0) {
        fprintf(stderr, "Failed to initialize sensors. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(sensor1.handle);
        i2cClose(sensor2.handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sensor1_CCT,Sensor2_CCT,Average_CCT\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint16_t data1, data2;
        float cct1, cct2, avg_cct;

        // Read data from sensor 1
        if (read_sensor_data(&sensor1, &data1) == 0) {
            cct1 = calculate_cct(data1);
        } else {
            cct1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_sensor_data(&sensor2, &data2) == 0) {
            cct2 = calculate_cct(data2);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Calculate average CCT
        if (cct1 >= 0 && cct2 >= 0) {
            avg_cct = (cct1 + cct2) / 2.0;
        } else {
            avg_cct = -1.0; // Indicate error
        }

        // Log data
        if (avg_cct >= 0) {
            log_cct(cct1, cct2, avg_cct);
        } else {
            fprintf(stderr, "Error: Could not calculate average CCT.\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    i2cClose(sensor1.handle);
    i2cClose(sensor2.handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

