// Function to log CCT data to a file
int log_cct(float cct1, float cct2, float avg_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, cct1, cct2, avg_cct);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Define sensors
    sensor_t sensor1 = { .address = SENSOR1_ADDR };
    sensor_t sensor2 = { .address = SENSOR2_ADDR };

    // Initialize sensors
    if (initialize_sensor(&sensor1) != 0 || initialize_sensor(&sensor2) != 0) {
        fprintf(stderr, "Failed to initialize sensors. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(sensor1.handle);
        i2cClose(sensor2.handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sensor1_CCT,Sensor2_CCT,Average_CCT\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint16_t data1, data2;
        float cct1, cct2, avg_cct;

        // Read data from sensor 1
        if (read_sensor_data(&sensor1, &data1) == 0) {
            cct1 = calculate_cct(data1);
        } else {
            cct1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_sensor_data(&sensor2, &data2) == 0) {
            cct2 = calculate_cct(data2);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Calculate average CCT
        if (cct1 >= 0 && cct2 >= 0) {
            avg_cct = (cct1 + cct2) / 2.0;
        } else {
            avg_cct = -1.0; // Indicate error
        }

        // Log data
        if (avg_cct >= 0) {
            log_cct(cct1, cct2, avg_cct);
        } else {
            fprintf(stderr, "Error: Could not calculate average CCT.\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    i2cClose(sensor1.handle);
    i2cClose(sensor2.handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

