#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define PRESSURE_THRESHOLD 5.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len, uint8_t checksum);
sensor_data_t convert_data(const char *buffer);
void log_data(FILE *fp, sensor_data_t data);
void check_pressure_threshold(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC checksum
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(const char *data, int len, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == checksum);
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(const char *buffer) {
    sensor_data_t data;
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data.pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    data.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return data;
}

// Function to log data to a file
void log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.pressure, data.temperature);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to check pressure threshold
void check_pressure_threshold(sensor_data_t data) {
    if (data.pressure > PRESSURE_THRESHOLD) {
        fprintf(stderr, "Warning: Pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", data.pressure, PRESSURE_THRESHOLD);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    char buffer[9];
    sensor_data_t data;
    while (!terminate) {
        // Wait for 45 ms
        gpioDelay(45000); // Delay in microseconds

        // Read data
        if (read_data(i2c_handle, buffer, 9) == 0) {
