#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define HIGH_THRESHOLD 28.0
#define LOW_THRESHOLD 27.0
#define MAX_I2C_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read temperature from STTS2004
float read_temperature() {
    int retries = 0;
    int raw_temp;
    float temperature;

    while (retries < MAX_I2C_RETRIES) {
        raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp >= 0) {
            // Convert raw temperature to Celsius (refer to STTS2004 datasheet)
            raw_temp = ((raw_temp >> 8) & 0xFF) | ((raw_temp << 8) & 0xFF00); // Swap bytes
            temperature = (float)((int16_t)raw_temp) * 0.0078125; // Resolution of 0.0078125 degrees Celsius
            return temperature;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_I2C_RETRIES);
    return -1000.0; // Indicate error with a very low temperature
}

// Function to control the LED based on temperature
void control_led(float temperature) {
    if (temperature > HIGH_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (temperature < LOW_THRESHOLD) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            control_led(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping LED control.\n");
        }

        gpioDelay(1000000); // Delay for 1 second (in microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

