int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize HDC1080 sensor
int init_hdc1080() {
    // Configure for temperature and humidity measurement, 14-bit resolution, 1 Hz conversion rate
    if (i2cWriteByteData(i2c_handle, CONFIGURATION_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing to configuration register\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC1080
int read_hdc1080(sensor_data_t *data) {
    uint8_t buf[4];
    int result;

    // Trigger measurement
    if (i2cWriteByte(i2c_handle, TEMPERATURE_REG) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for conversion (at least 20 ms)
    gpioDelay(20000);

    // Read 4 bytes of data (temp MSB, temp LSB, humidity MSB, humidity LSB)
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, (char *)buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    int raw_temperature = (buf[0] << 8) | buf[1];
    int raw_humidity = (buf[2] << 8) | buf[3];

    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

