    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_hdc1080(&sensor_data) == 0) {
            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
