#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "hvac_pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_logging();
void close_resources();
void signal_handler(int signal);
uint8_t calculate_crc(const uint8_t *data, int len);
int read_sdp810(sensor_data_t *data);
int log_data(const sensor_data_t *data);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }
    return 0;
}

// Close resources
void close_resources() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Read data from SDP810
int read_sdp810(sensor_data_t *data) {
    char buf[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASUREMENT_COMMAND >> 8, MEASUREMENT_COMMAND & 0xFF);
    if (result < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for at least 50 ms
    gpioDelay(50000); // 50 ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // CRC validation
    uint8_t pressure_crc = calculate_crc((uint8_t *)buf, 2);
    uint8_t temperature_crc = calculate_crc((uint8_t *)buf + 3, 2);
    uint8_t scale_factor_crc = calculate_crc((uint8_t *)buf + 5, 3);

    if (pressure_crc != buf[2]) {
        fprintf(stderr, "Pressure CRC error\n");
        return -1;
    }

    if (temperature_crc != buf[5]) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }

    if (scale_factor_crc != buf[8]) {
        fprintf(stderr, "Scale Factor CRC error\n");
        return -1;
    }

    // Convert data
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];
    int32_t raw_scale_factor = (buf[6] << 16) | (buf[7] << 8) | buf[8];

    data->pressure_Pa = (float)raw_pressure / 10.0; // Scale factor from datasheet
    data->temperature_C = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure_Pa, data->temperature_C);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    if (init_logging() != 0) {
        fprintf(stderr, "Logging initialization failed\n");
        close_resources();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sdp810(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,ERROR,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    close_resources();

    return 0;
}

