#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define BUFFER_CAPACITY 100
#define CSV_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define MEASUREMENT_INTERVAL_SEC 5
#define FLUSH_INTERVAL_SEC 60

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86
#define CMD_READ_MEASUREMENT 0xec05

// Data Structure
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} scd40_data_t;

// Circular Buffer Structure
typedef struct {
    scd40_data_t data[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global Variables
static int i2c_handle;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

// Function Prototypes
int init_i2c();
int init_circular_buffer(circular_buffer_t *buffer);
int add_to_buffer(circular_buffer_t *buffer, scd40_data_t data);
int read_scd40_data(scd40_data_t *data);
int validate_crc(unsigned char data[], int len, unsigned char crc);
int start_periodic_measurement();
int stop_periodic_measurement();
void *logging_thread_func(void *arg);
void signal_handler(int signal);
void log_error(const char *message);
void create_csv_dir();

// CRC-8 Checksum Calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize Circular Buffer
int init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    if (pthread_mutex_init(&buffer->mutex, NULL) != 0) {
        log_error("Mutex initialization failed");
        return -1;
    }
    return 0;
}

// Add Data to Circular Buffer
int add_to_buffer(circular_buffer_t *buffer, scd40_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count == BUFFER_CAPACITY) {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Read Data from SCD40
int read_scd40_data(scd40_data_t *data) {
    unsigned char cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    unsigned char buffer[9];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        log_error("Failed to write read measurement command");
        return -1;
    }

    gpioDelay(1); // Small delay after writing the command

    if (i2cReadDevice(i2c_handle, buffer, 9) != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // Validate CRC for CO2
    if (!validate_crc(buffer, 2, buffer[2])) {
        log_error("CO2 CRC validation failed");
        return -1;
    }

    // Validate CRC for Temperature
    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        log_error("Temperature CRC validation failed");
        return -1;
    }

    // Validate CRC for Humidity
    if (!validate_crc(buffer + 6, 2, buffer[8])) {
        log_error("Humidity CRC validation failed");
        return -1;
    }

    data->co2 = (float)((buffer[0] << 8) | buffer[1]);
