    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t raw_data[9];
        sensor_data_t sensor_data;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Continue to the next iteration
        }

        // Wait for measurement to complete
        gpioDelay(45000); // 45 ms

        // Read sensor data
        if (read_sensor_data(raw_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Continue to the next iteration
        }

        // Validate CRC
        if (validate_crc(raw_data, 6) != 0 || validate_crc(raw_data + 6, 3) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Continue to the next iteration
        }

        // Convert data
        if (convert_data(raw_data, &sensor_data) != 0) {
            fprintf(stderr, "Failed to convert sensor data\n");
            continue; // Continue to the next iteration
        }

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    char buf[2];
    buf[0] = (TRIGGER_MEASUREMENT >> 8) & 0xFF;
    buf[1] = TRIGGER_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return 1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        crc = crc_table[crc & 0x0F] ^ (crc_table[16 + (crc >> 4)] << 4);
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len);
    if (crc != data[len]) {
        fprintf(stderr, "CRC validation failed\n");
        return 1;
    }
    return 0;
}

// Convert data
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    sensor_data->pressure = (int16_t)((data[0] << 8) | data[1]);
    sensor_data->temperature = (int16_t)((data[3] << 8) | data[4]);
    sensor_data->scale_factor = (uint16_t)((data[6] << 8) | data[7]);

    // Basic data validation
    if (sensor_data->pressure > 500 || sensor_data->pressure < -500) {
        fprintf(stderr, "Pressure out of range\n");
        return 1;
    }

    return 0;
}

// Log data
int log_data(const sensor_data_t *sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp,
            (float)sensor_data->pressure / sensor_data->scale_factor,
            (float)sensor_data->temperature / 200.0);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

