                processed_data.temperature = convert_temperature(((uint16_t)sensor_data[2] << 8) | sensor_data[3]);

                // Control LED based on pressure
                control_led(processed_data.pressure);

                // Print sensor data (for debugging)
                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", processed_data.pressure, processed_data.temperature);
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

