    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read 6 bytes from I2C: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Calculate CRC
uint16_t calculate_crc(const uint8_t *data, int len) {
    uint16_t crc = 0xFFFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x0001) {
                crc >>= 1;
                crc ^= 0xA001;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Convert raw pressure to Pascals
float convert_pressure(uint16_t raw_pressure) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (float)raw_pressure * 0.1f; // Example conversion
