    if (pressure < PRESSURE_THRESHOLD) {
        // Blink at 5 Hz
        gpioWrite(LED_GPIO, 1);
        gpioDelay(100000); // 100 ms
        gpioWrite(LED_GPIO, 0);
        gpioDelay(100000); // 100 ms
    } else {
        // Blink at 1 Hz
        gpioWrite(LED_GPIO, 1);
        gpioDelay(500000); // 500 ms
        gpioWrite(LED_GPIO, 0);
        gpioDelay(500000); // 500 ms
    }
}

