#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define AMBIENT_THRESHOLD_HIGH 30.0
#define AMBIENT_THRESHOLD_LOW 28.0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_US 10000 // 10ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature(int reg);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from the sensor
float read_temperature(int reg) {
    int raw_data;
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        raw_data = i2cReadWordData(i2c_handle, reg);
        if (raw_data >= 0) {
            // Convert raw data to Celsius (refer to MLX90614 datasheet)
            float temp = (float)raw_data * 0.02 - 273.15;
            return temp;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X), retry %d/%d\n", reg, retries + 1, I2C_RETRY_COUNT);
            gpioDelay(I2C_RETRY_DELAY_US);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries\n", reg, I2C_RETRY_COUNT);
    return -1000.0; // Indicate an error
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (ambient_temp > -273.0 && object_temp > -273.0) {
        FILE *fp = fopen("temperature_log.txt", "a");
        if (fp != NULL) {
            fprintf(fp, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
            fclose(fp);
        } else {
            fprintf(stderr, "Error opening log file!\n");
        }
    } else {
        fprintf(stderr, "Invalid temperature reading, skipping log.\n");
    }
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > AMBIENT_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON (Object Temp: %.2f°C)\n", object_temp);
    } else if (object_temp < AMBIENT_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF (Object Temp: %.2f°C)\n", object_temp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperatures
        float ambient_temp = read_temperature(AMBIENT_TEMP_REG);
        float object_temp = read_temperature(OBJECT_TEMP_REG);

        // Log temperatures
        if (ambient_temp > -273.0 && object_temp > -273.0) {
            log_temperature(ambient_temp, object_temp);
        }

        // Control fan
        control_fan(object_temp);

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

