#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;

// Function to calculate CRC8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
            fprintf(stderr, "Error writing to I2C device. Retry %d\n", retries + 1);
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(10000); // Wait for measurement (at least 10ms)

        if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device. Retry %d\n", retries + 1);
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // CRC Check
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC check failed. Retry %d\n", retries + 1);
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Convert data to temperature and humidity
        unsigned short temperature_raw = (data[0] << 8) | data[1];
        unsigned short humidity_raw = (data[3] << 8) | data[4];

        *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
        *humidity = 100.0 * (float)humidity_raw / 65535.0;

        // Clamp humidity to 0-100%
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to handle HTTP requests
void handle_http_request(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';

    // Basic request parsing (looking for GET /)
    if (strstr(buffer, "GET /") != NULL) {
        float temperature, humidity;
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            char response[1024];
            snprintf(response, sizeof(response), 
                     "HTTP/1.1 200 OK\r\n" \
                     "Content-Type: text/html\r\n" \
                     "\r\n" \
                     "<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>Temperature: %.2f &deg;C</h1><h1>Humidity: %.2f %%</h1></body></html>",
                     temperature, humidity);
            send(client_socket, response, strlen(response), 0);
        } else {
            const char *error_response = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\n\r\nSHT40 read failed";
            send(client_socket, error_response, strlen(error_response), 0);
        }
    } else {
        const char *not_found_response = "HTTP/1.1 404 Not Found\r\nContent-Type: text/plain\r\n\r\nNot Found";
        send(client_socket, not_found_response, strlen(not_found_response), 0);
    }

    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("bind failed");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_socket, 3) < 0) {
        perror("listen failed");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Main loop
    while (1) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        handle_http_request(client_socket);
    }

    // Cleanup (should not reach here in normal operation due to the while(1) loop)
    close(server_socket);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

