#include <pigpio.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02
#define MEASUREMENT_CONFIG 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity);
void output_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the HDC2010 sensor
int configure_sensor() {
    // Configure for temperature and humidity measurement, single measurement mode
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char buf[4];

    // Read temperature and humidity registers (2 bytes each)
    if (i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 4) != 4) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    *humidity = (buf[2] << 8) | buf[3];

    return 0;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    sensor_data_t data;
    data.temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data.humidity = ((float)raw_humidity / 65536.0) * 100.0;
    return data;
}

// Output temperature and humidity data to the console
void output_data(sensor_data_t data) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            // Convert data
            sensor_data = convert_data(raw_temperature, raw_humidity);

            // Output data
            output_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

