// Define the I2C address of the SDP800-500Pa sensor
#define SDP800_I2C_ADDR 0x25

// Define the measurement command (continuous measurement without averaging)
#define MEASURE_CMD 0x362F

// Define the I2C bus number
#define I2C_BUS 1

// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate the CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, int16_t *pressure, int16_t *temperature) {
    uint8_t buffer[6];
    int result;

    // Send the measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for the measurement to complete (45 ms)
    gpioDelay(45000);

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Extract pressure and temperature values
    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    // Validate CRC checksums
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC checksum error\n");
        return -1;
    }
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC checksum error\n");
        return -1;
    }

    return 0;
}

int main() {
    int16_t pressure, temperature;
    int result;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from the sensor
        result = read_sdp800(i2c_handle, &pressure, &temperature);
        if (result == 0) {
            // Log the raw values to the console
            printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 500 ms
        gpioDelay(500000);
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

