// Function to read temperature from MAX6675
double read_temperature(int spi_channel) {
    char buffer[4];
    int result;
    double temperature = -1.0; // Default to error value

    if (spi_channel == SPI_CHANNEL_0) {
        result = spiRead(spi_handle_0, buffer, 4);
    } else {
        result = spiRead(spi_handle_1, buffer, 4);
    }

    if (result == 4) {
        // Extract temperature data (ignoring fault bit)
        int raw_temp = ((buffer[0] << 8) | buffer[1]) >> 3;
        temperature = raw_temp * 0.25;
    } else {
        fprintf(stderr, "SPI read error on channel %d: %d\n", spi_channel, result);
        log_data(-1.0, -1.0, -1.0); // Log error
    }

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Clamp the output to the range [0.0, 1.0]
    if (output < 0.0) {
        output = 0.0;
    } else if (output > 1.0) {
        output = 1.0;
    }

    return output;
}

// Function to set SSR duty cycle
void set_ssr_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 255.0); // pigpio uses 0-255 for PWM
    gpioPWM(SSR_GPIO, pwm_value);
}

// Function to log data to file
void log_data(double temp0, double temp1, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temp0, temp1, duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to load temperature profile from file
int load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening profile file");
        return -1;
    }

    char line[256];
    num_profile_points = 0;
    while (fgets(line, sizeof(line), fp) != NULL && num_profile_points < MAX_PROFILE_LINES) {
        if (sscanf(line, "%lf", &target_temperatures[num_profile_points]) == 1) {
            num_profile_points++;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:p:k:i:d:")) != -1) {
        switch (opt) {
            case 's':
                setpoint = atof(optarg);
                break;
            case 'p':
                strncpy(PROFILE_FILE, optarg, sizeof(PROFILE_FILE) - 1);
                PROFILE_FILE[sizeof(PROFILE_FILE) - 1] = '\0'; // Ensure null termination
                break;
            case 'k':
                Kp = atof(optarg);
                break;
            case 'i':
                Ki = atof(optarg);
                break;
            case 'd':
                Kd = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s setpoint] [-p profile_file] [-k Kp] [-i Ki] [-d Kd]\n", argv[0]);
                return 1;
        }
    }

