    spi_handle_0 = spiOpen(SPI_CHANNEL_0, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle_0 < 0) {
        fprintf(stderr, "SPI open failed on channel 0: %d\n", spi_handle_0);
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, 0); // CE1, 1MHz, Mode 0
    if (spi_handle_1 < 0) {
        fprintf(stderr, "SPI open failed on channel 1: %d\n", spi_handle_1);
        spiClose(spi_handle_0);
        gpioTerminate();
        return 1;
    }

    // Set SSR GPIO as output
    gpioSetMode(SSR_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SSR_GPIO, PWM_FREQUENCY);

    // Load temperature profile
    if (load_profile(PROFILE_FILE) != 0) {
        fprintf(stderr, "Failed to load temperature profile.\n");
        spiClose(spi_handle_0);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle_0);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    double integral = 0.0;
    double previous_error = 0.0;
    int profile_index = 0;
    time_t start_time = time(NULL);

    // Main loop
    while (!terminate) {
        // Read temperatures
        double temp0 = read_temperature(SPI_CHANNEL_0);
        double temp1 = read_temperature(SPI_CHANNEL_1);

        // Calculate PID output
        double pid_output = calculate_pid(target_temperatures[profile_index], (temp0 + temp1) / 2.0, &integral, &previous_error);

        // Set SSR duty cycle
        set_ssr_duty_cycle(pid_output);

        // Log data
        log_data(temp0, temp1, pid_output);

        // Update profile index
        time_t current_time = time(NULL);
        if (difftime(current_time, start_time) >= target_temperatures[profile_index]) {
            profile_index = (profile_index + 1) % num_profile_points;
            start_time = current_time;
        }

        // Sleep for 1 second
        gpioDelay(1000); // pigpioDelay is in milliseconds
    }

    // Cleanup
    spiClose(spi_handle_0);
    spiClose(spi_handle_1);
    fclose(log_file);
    gpioWrite(SSR_GPIO, 0); // Turn off SSR
    gpioTerminate();

    return 0;
}

