#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <stdbool.h>

// Configuration
#define DS18B20_GPIO 4
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "greenhouse.log"
#define TEMP_ERROR_VALUE -999.0
#define PWM_FREQUENCY 1000 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)

// PID Gains
double Kp, Ki, Kd;

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function Prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_heater_state(int state);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(double temperature, double setpoint, double pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data);

// PID Variables
double integral = 0.0;
double previous_error = 0.0;

// Function to read temperature from DS18B20 sensor
double read_temperature() {
    int fd;
    uint8_t data[9];
    int16_t raw_temperature;
    double temperature;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return TEMP_ERROR_VALUE;
    }

    // Set the I2C slave address for the DS18B20
    if (ioctl(fd, I2C_SLAVE, 0x50) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return TEMP_ERROR_VALUE;
    }

    // Write to the DS18B20 to initiate a temperature conversion
    if (i2c_write_byte(fd, 0x44, 0x44) < 0) {
        perror("Error writing to DS18B20");
        close(fd);
        return TEMP_ERROR_VALUE;
    }

    // Wait for the conversion to complete (at least 750ms)
    usleep(750000);

    // Read the temperature data from the DS18B20
    if (i2c_read_bytes(fd, 0x00, data, 9) < 0) {
        perror("Error reading from DS18B20");
        close(fd);
        return TEMP_ERROR_VALUE;
    }

    close(fd);

    // Check CRC
    uint8_t crc = 0;
    for (int i = 0; i < 8; i++) {
        crc = crc ^ data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ 0x8C;
            } else {
                crc = (crc >> 1);
            }
        }
    }

    if (crc != data[8]) {
        fprintf(stderr, "CRC check failed!\n");
        return TEMP_ERROR_VALUE;
    }

    // Extract raw temperature data
    raw_temperature = (data[1] << 8) | data[0];

    // Convert to Celsius
    temperature = (double)raw_temperature / 16.0;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set the heater state (ON/OFF)
void set_heater_state(int state) {
    int fd;
    char value_str[3];

    fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return;
    }

    snprintf(value_str, sizeof(value_str), "%d", state);
    if (write(fd, value_str, strlen(value_str)) < 0) {
        perror("Error writing to GPIO value file");
    }

    close(fd);
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    int fd;
    char period_str[11];
    char duty_cycle_str[11];

    // Set PWM period
    fd = open("/sys/class/pwm/pwmchip0/pwm0/period", O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM period file");
        return;
    }
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD_US);
    if (write(fd, period_str, strlen(period_str)) < 0) {
        perror("Error writing to PWM period file");
    }
    close(fd);

    // Set PWM duty cycle
    fd = open("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM duty_cycle file");
        return;
    }
    snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);
    if (write(fd, duty_cycle_str, strlen(duty_cycle_str)) < 0) {
        perror("Error writing to PWM duty_cycle file");
    }
    close(fd);

    // Enable PWM
    fd = open("/sys/class/pwm/pwmchip0/pwm0/enable", O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM enable file");
        return;
    }
    if (write(fd, "1", 1) < 0) {
        perror("Error writing to PWM enable file");
    }
    close(fd);
}

// Function to log data to file
void log_data(double temperature, double setpoint, double pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %d\n", timestamp, temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }
    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing data");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    double setpoint, temperature, pid_output;
    int pwm_duty_cycle;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:k:i:d:")) != -1) {
        switch (opt) {
            case 's':
                setpoint = atof(optarg);
                break;
            case 'k':
                Kp = atof(optarg);
                break;
            case 'i':
                Ki = atof(optarg);
                break;
            case 'd':
                Kd = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -s <setpoint> -k <Kp> -i <Ki> -d <Kd>\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (optind != argc) {
        fprintf(stderr, "Usage: %s -s <setpoint> -k <Kp> -i <Ki> -d <Kd>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for heater control
    int fd;
    char buffer[64];

    // Export GPIO17
    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return 1;
    }
    snprintf(buffer, sizeof(buffer), "%d", HEATER_GPIO);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        return 1;
    }
    close(fd);

    // Set GPIO17 direction to output
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", HEATER_GPIO);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return 1;
    }
    if (write(fd, "out", 3) < 0) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return 1;
    }
    close(fd);

    // Export PWM channel 0
    fd = open("/sys/class/pwm/pwmchip0/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/pwm/pwmchip0/export");
        return 1;
    }
    if (write(fd, "0", 1) < 0) {
        perror("Error writing to /sys/class/pwm/pwmchip0/export");
        close(fd);
        return 1;
    }
    close(fd);

    // Set PWM channel 0 period
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/period");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM period file");
        return 1;
    }
    snprintf(buffer, sizeof(buffer), "%d", PWM_PERIOD_US);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to PWM period file");
        close(fd);
        return 1;
    }
    close(fd);

    // Set PWM channel 0 enable
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM enable file");
        return 1;
    }
    if (write(fd, "0", 1) < 0) {
        perror("Error writing to PWM enable file");
        close(fd);
        return 1;
    }
    close(fd);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
