        perror("Error opening /sys/class/pwm/pwmchip0/export");
        return 1;
    }
    if (write(fd, "0", 1) < 0) {
        perror("Error writing to /sys/class/pwm/pwmchip0/export");
        close(fd);
        return 1;
    }
    close(fd);

    // Set PWM channel 0 period
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/period");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM period file");
        return 1;
    }
    snprintf(buffer, sizeof(buffer), "%d", PWM_PERIOD_US);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to PWM period file");
        close(fd);
        return 1;
    }
    close(fd);

    // Set PWM channel 0 enable
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM enable file");
        return 1;
    }
    if (write(fd, "0", 1) < 0) {
        perror("Error writing to PWM enable file");
        close(fd);
        return 1;
    }
    close(fd);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
