#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_HIGH_THRESHOLD 60.0
#define HUMIDITY_LOW_THRESHOLD 55.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_aht20(float *humidity);
void control_relay(float humidity);
void log_humidity(float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data
typedef struct {
    uint8_t status;
    uint8_t humidity_msb;
    uint8_t humidity_lsb;
    uint8_t temperature_msb;
    uint8_t temperature_lsb;
} aht20_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity;

    // Main loop
    while (!terminate) {
        if (read_aht20(&humidity) == 0) {
            log_humidity(humidity);
            control_relay(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read humidity from AHT20 sensor
int read_aht20(float *humidity) {
    aht20_data_t data;
    uint8_t cmd[3] = {0xAC, 0x33, 0x00};
    int retries = 0;

    // Trigger measurement
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 3) == 0) {
            break;
        } else {
            fprintf(stderr, "I2C write failed (trigger), retry %d\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to trigger measurement after %d retries\n", MAX_RETRIES);
        return 1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement (80ms)

    // Read 6 bytes of data
    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cReadDevice(i2c_handle, (char *)&data, 6) == 6) {
            break;
        } else {
            fprintf(stderr, "I2C read failed, retry %d\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read data after %d retries\n", MAX_RETRIES);
        return 1;
    }

    // Check status byte
    if ((data.status & 0x80) != 0) {
        fprintf(stderr, "Sensor not calibrated\n");
        return 1;
    }
    if ((data.status & 0x08) != 0) {
        fprintf(stderr, "Sensor is busy\n");
        return 1;
    }

    // Convert humidity data
    uint16_t raw_humidity = ((uint16_t)data.humidity_msb << 8) | data.humidity_lsb;
    *humidity = ((float)raw_humidity / 0x100000) * 100;

    return 0;
}

// Control the dehumidifier relay
void control_relay(float humidity) {
    if (humidity > HUMIDITY_HIGH_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // Activate relay
        printf("Dehumidifier ON\n");
    } else if (humidity < HUMIDITY_LOW_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 0); // Deactivate relay
        printf("Dehumidifier OFF\n");
    }
}

// Log humidity reading with timestamp
void log_humidity(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Humidity: %.2f %%\n", timestamp, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

