    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

// Function to read humidity from HTU21D sensor
int read_htu21d(int i2c_handle, float *humidity) {
    unsigned char cmd[1] = {0xE5}; // Trigger humidity measurement
    unsigned char buffer[3];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        syslog(LOG_ERR, "I2C write failed: %d", result);
        return -1;
    }

    gpioDelay(50); // Wait for measurement (datasheet specifies 50ms)

    result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        syslog(LOG_ERR, "I2C read failed: %d", result);
        return -1;
    }

    // Check CRC (simplified, assumes no error)
    unsigned short raw_humidity = (buffer[0] << 8) | buffer[1];
    unsigned char checksum = buffer[2];

    // CRC calculation (simplified, using polynomial 0x131)
    unsigned short polynomial = 0x131;
    unsigned short crc = 0xFF;
    unsigned char data;
    unsigned char bit;

    for (int i = 0; i < 2; i++) {
        data = (i == 0) ? buffer[0] : buffer[1];
        for (int j = 0; j < 8; j++) {
            bit = (data >> (7 - j)) & 1;
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
            if (bit) {
                crc ^= polynomial;
            }
        }
    }

    if (crc != checksum) {
        syslog(LOG_ERR, "CRC check failed!");
        return -1;
    }

    // Convert raw humidity to percentage
    *humidity = ((float)raw_humidity / 65535.0) * 100.0;

    return 0;
}

