int post_humidity(float humidity, const char *api_endpoint) {
    int sock = 0, valread;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};
    char json_data[256];

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation error: %s", strerror(errno));
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80); // Assuming port 80 for HTTP

    // Convert URL to IP address (simplified)
    if (inet_pton(AF_INET, api_endpoint, &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address or address not supported: %s", api_endpoint);
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char post_data[256];
    snprintf(post_data, sizeof(post_data), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", api_endpoint, api_endpoint, strlen(json_data), json_data);

    if (send(sock, post_data, strlen(post_data), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    valread = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
        close(sock);
        return -1;
    }
    buffer[valread] = '\0';

    syslog(LOG_INFO, "Response from server: %s", buffer);

    close(sock);
    return 0;
}

