                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        // Wait for the next poll interval
        sleep(POLL_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

