#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define LOG_FILE_NAME "sensor_log.csv"
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS 10

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_tmp117(int handle, float *temperature);
int read_aht20(int handle, float *humidity);
int read_pir_sensor(int gpio);
int log_data(FILE *fp, float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
int check_sensor_presence(int gpio);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read temperature from TMP117
int read_tmp117(int handle, float *temperature) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (Celsius)
            int raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (float)raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (TMP117) attempt %d: %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read humidity from AHT20
int read_aht20(int handle, float *humidity) {
    char buf[6];
    int retries = 0;
    int result;

    // Trigger measurement
    char init_buf[3] = {0xAC, 0x33, 0x00};
    result = i2cWriteDevice(handle, init_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error triggering AHT20 measurement: %d\n", result);
        return -1;
    }
    gpioDelay(80); // Wait for measurement (at least 75ms)

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 6);
        if (result == 6) {
            // Check status bit (bit 7 of byte 0)
            if (buf[0] & 0x80) {
                fprintf(stderr, "AHT20 busy\n");
                retries++;
                gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
                continue;
            }

            // Convert raw data to humidity (%RH)
            unsigned long raw_humidity = ((unsigned long)buf[1] << 12) | ((unsigned long)buf[2] << 4) | (buf[3] >> 4);
            *humidity = ((float)raw_humidity / 0x100000) * 100;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (AHT20) attempt %d: %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read PIR sensor
int read_pir_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to check if a sensor is present
int check_sensor_presence(int gpio) {
    int value = gpioRead(gpio);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return 0; // Assume not present on error
    }
    gpioDelay(100); // Small delay to allow sensor to stabilize
    if (gpioRead(gpio) == value) {
        return 1; // Sensor is present if reading is stable
    } else {
        return 0; // Sensor is not present if reading is unstable
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C for TMP117 and AHT20
    i2c_handle_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Failed to initialize TMP117 I2C. Continuing without TMP117.\n");
    }

    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Failed to initialize AHT20 I2C. Continuing without AHT20.\n");
    }

    // Check for sensor presence
    if (!check_sensor_presence(PIR_GPIO)) {
        fprintf(stderr, "PIR sensor not detected. Continuing without PIR.\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        float temperature = -999.0; // Default value in case of error
        float humidity = -999.0;    // Default value in case of error
        int motion_detected = -1;   // Default value in case of error

        // Read temperature from TMP117
        if (i2c_handle_tmp117 >= 0) {
            if (read_tmp117(i2c_handle_tmp117, &temperature) != 0) {
                fprintf(stderr, "Error reading TMP117 temperature.\n");
            }
        }

        // Read humidity from AHT20
        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(i2c_handle_aht20, &humidity) != 0) {
                fprintf(stderr, "Error reading AHT20 humidity.\n");
            }
        }

        // Read motion from PIR sensor
        if (check_sensor_presence(PIR_GPIO)) {
            motion_detected = read_pir_sensor(PIR_GPIO);
        }

        // Log the data
        log_data(log_file, temperature, humidity, motion_detected);

        // Check if it's midnight and create a new log file
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        if (tm.tm_hour == 0 && tm.tm_min == 0 && tm.tm_sec == 0) {
            fclose(log_file);
            log_file = fopen(LOG_FILE_NAME, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file!\n");
                terminate = 1; // Exit if we can't open the log file
            } else {
                fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
            }
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

