    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Failed to initialize AHT20 I2C. Continuing without AHT20.\n");
    }

    // Check for sensor presence
    if (!check_sensor_presence(PIR_GPIO)) {
        fprintf(stderr, "PIR sensor not detected. Continuing without PIR.\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        float temperature = -999.0; // Default value in case of error
        float humidity = -999.0;    // Default value in case of error
        int motion_detected = -1;   // Default value in case of error

        // Read temperature from TMP117
        if (i2c_handle_tmp117 >= 0) {
            if (read_tmp117(i2c_handle_tmp117, &temperature) != 0) {
                fprintf(stderr, "Error reading TMP117 temperature.\n");
            }
        }

        // Read humidity from AHT20
        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(i2c_handle_aht20, &humidity) != 0) {
                fprintf(stderr, "Error reading AHT20 humidity.\n");
            }
        }

        // Read motion from PIR sensor
        if (check_sensor_presence(PIR_GPIO)) {
            motion_detected = read_pir_sensor(PIR_GPIO);
        }

        // Log the data
        log_data(log_file, temperature, humidity, motion_detected);

        // Check if it's midnight and create a new log file
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        if (tm.tm_hour == 0 && tm.tm_min == 0 && tm.tm_sec == 0) {
            fclose(log_file);
            log_file = fopen(LOG_FILE_NAME, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file!\n");
                terminate = 1; // Exit if we can't open the log file
            } else {
                fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
            }
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

