// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run time
#define MOTOR_RUN_TIME 5 // seconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message("Received signal, stopping motor and exiting...");
        stop_motor();
        gpioTerminate();
        program_running = 0;
        exit(0);
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = gpioRead(RAIN_SENSOR_PIN);
    if (rain_detected < 0) {
        log_message("Error reading rain sensor");
        return -1; // Indicate error
    }
    return rain_detected;
}

// Function to close the window
void close_window() {
    log_message("Closing window...");

    // Set motor direction to close (IN1 high, IN2 low)
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);

    // Enable the motor
    gpioWrite(MOTOR_ENA_PIN, 1);

    // Wait for the specified run time
    gpioDelay(MOTOR_RUN_TIME * 1000000); // Convert seconds to microseconds

    // Stop the motor
    stop_motor();

    log_message("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    log_message("Stopping motor...");

    // Disable the motor
    gpioWrite(MOTOR_ENA_PIN, 0);

    // Set IN1 and IN2 to low (safe state)
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    log_message("Motor stopped.");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up/down resistor for rain sensor pin (optional, adjust as needed)
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP); // Or PI_PUD_DOWN if needed

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Rain sensor monitoring started...");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 0) {
            log_message("Rain detected!");
            close_window();
        } else if (rain_detected < 0) {
            // Error already logged in read_rain_sensor
        }

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();

    return 0;
}

