#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define CPU load file path
#define CPU_LOAD_FILE "/proc/stat"

// Global variables for CPU load samples
static unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest;

// Function prototypes
int read_cpu_load(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle, unsigned long long *iowait, unsigned long long *irq, unsigned long long *softirq, unsigned long long *steal, unsigned long long *guest);
float calculate_cpu_usage(unsigned long long prev_total, unsigned long long prev_idle, unsigned long long total, unsigned long long idle);
void map_cpu_to_color(float cpu_usage, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read CPU load from /proc/stat
int read_cpu_load(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle, unsigned long long *iowait, unsigned long long *irq, unsigned long long *softirq, unsigned long long *steal, unsigned long long *guest) {
    FILE *fp;
    char line[256];

    fp = fopen(CPU_LOAD_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open %s for reading\n", CPU_LOAD_FILE);
        return -1;
    }

    // Read the first line (CPU stats)
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from %s\n", CPU_LOAD_FILE);
        fclose(fp);
        return -1;
    }

    // Parse the line
    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               user, nice, system, idle, iowait, irq, softirq, steal, guest) != 9) {
        fprintf(stderr, "Error: Could not parse CPU stats from %s\n", CPU_LOAD_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU usage percentage
float calculate_cpu_usage(unsigned long long prev_total, unsigned long long prev_idle, unsigned long long total, unsigned long long idle) {
    unsigned long long diff_total = total - prev_total;
    unsigned long long diff_idle = idle - prev_idle;

    if (diff_total == 0) {
        return 0.0;
    }

    float usage = 100.0 * (float)(diff_total - diff_idle) / (float)diff_total;
    return usage;
}

// Function to map CPU usage to RGB color values
void map_cpu_to_color(float cpu_usage, int *red, int *green, int *blue) {
    if (cpu_usage < 50.0) {
        *green = 255;
        *red = 0;
        *blue = 0;
    } else {
        *green = 255 - (int)((cpu_usage - 50.0) * 512.0 / 50.0);
        *red = (int)((cpu_usage - 50.0) * 512.0 / 50.0);
        *blue = 0;
    }

    // Clamp values to 0-255 range
    if (*green > 255) *green = 255;
    if (*green < 0) *green = 0;
    if (*red > 255) *red = 255;
    if (*red < 0) *red = 0;
    if (*blue > 255) *blue = 255;
    if (*blue < 0) *blue = 0;
}

// Function to set the RGB LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the value
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the value
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the value
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read initial CPU load
    if (read_cpu_load(&prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest) != 0) {
        fprintf(stderr, "Error reading initial CPU load, exiting\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest;

        // Read CPU load
        if (read_cpu_load(&user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest) != 0) {
            fprintf(stderr, "Error reading CPU load, continuing...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate CPU usage
        float cpu_usage = calculate_cpu_usage(prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest,
                                              prev_idle,
                                              user + nice + system + idle + iowait + irq + softirq + steal + guest,
                                              idle);

        // Map CPU usage to color
        int red, green, blue;
        map_cpu_to_color(cpu_usage, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous CPU load values
        prev_user = user;
        prev_nice = nice;
        prev_system = system;
        prev_idle = idle;
        prev_iowait = iowait;
        prev_irq = irq;
        prev_softirq = softirq;
        prev_steal = steal;
        prev_guest = guest;

        // Wait for 500 milliseconds
        usleep(500000); // 500 ms
    }

    return 0;
}

