#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20

// Temperature thresholds
#define TEMP_LOW 25.0
#define TEMP_MED 40.0
#define TEMP_HIGH 60.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for the circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
int calculate_duty_cycle(float temperature);
void update_fan(int duty_cycle);
void signal_handler(int signal);
void log_data(float temperature, int duty_cycle);
void print_log_buffer();

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char spi_data[4];
    int i2c_handle;
    float temperature = -1000.0; // Initialize to an invalid value

    i2c_handle = i2cOpen(SPI_CHANNEL, 0x00, 0); // Open I2C device (CE0 is I2C)
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1000.0; // Indicate error
    }

    if (i2cReadDevice(i2c_handle, (char *)spi_data, 4) != 4) {
        fprintf(stderr, "Error reading from I2C device\n");
        i2cClose(i2c_handle);
        return -1000.0; // Indicate error
    }

    i2cClose(i2c_handle);

    // Check for fault bits
    if (spi_data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1000.0;
    }
    if (spi_data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (spi_data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((spi_data[0] << 8) | spi_data[1]) >> 2;

    // Convert to Celsius
    temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature >= TEMP_LOW && temperature < TEMP_MED) {
        duty_cycle = (int)((temperature - TEMP_LOW) / (TEMP_MED - TEMP_LOW) * 50.0);
    } else if (temperature >= TEMP_MED && temperature < TEMP_HIGH) {
        duty_cycle = 50 + (int)((temperature - TEMP_MED) / (TEMP_HIGH - TEMP_MED) * 150.0);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to update the fan PWM duty cycle
void update_fan(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[i].timestamp));
        printf("Timestamp: %s, Temperature: %.2f C, Duty Cycle: %d\n", time_str, log_buffer[i].temperature, log_buffer[i].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Set PWM duty cycle to 0 initially
    gpioPWM(FAN_GPIO, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            int duty_cycle = calculate_duty_cycle(temperature);
            update_fan(duty_cycle);
            log_data(temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Stop the PWM
    gpioPWM(FAN_GPIO, 0);

    // Print the log buffer
    print_log_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

