    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature >= TEMP_LOW && temperature < TEMP_MED) {
        duty_cycle = (int)((temperature - TEMP_LOW) / (TEMP_MED - TEMP_LOW) * 50.0);
    } else if (temperature >= TEMP_MED && temperature < TEMP_HIGH) {
        duty_cycle = 50 + (int)((temperature - TEMP_MED) / (TEMP_HIGH - TEMP_MED) * 150.0);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to update the fan PWM duty cycle
void update_fan(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[i].timestamp));
        printf("Timestamp: %s, Temperature: %.2f C, Duty Cycle: %d\n", time_str, log_buffer[i].temperature, log_buffer[i].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Set PWM duty cycle to 0 initially
    gpioPWM(FAN_GPIO, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            int duty_cycle = calculate_duty_cycle(temperature);
            update_fan(duty_cycle);
            log_data(temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Stop the PWM
    gpioPWM(FAN_GPIO, 0);

    // Print the log buffer
    print_log_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

