#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // SPI_MODE0
#define CE0_GPIO 8
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int read_max31865(uint32_t *raw_data);
uint8_t check_fault(uint32_t raw_data);
float calculate_temperature(uint32_t raw_data);
int log_data(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int spi_flags;
    int ce0_gpio;
    char *log_file;
    int sample_interval;
} config_t;

// Function to initialize SPI
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from MAX31865
int read_max31865(uint32_t *raw_data) {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1;
    }

    *raw_data = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
    return 0;
}

// Function to check for fault conditions
uint8_t check_fault(uint32_t raw_data) {
    return (raw_data >> 31) & 0x07;
}

// Function to calculate temperature using Callendar-Van Dusen equation
float calculate_temperature(uint32_t raw_data) {
    // Extract RTD resistance from the data (assuming 3-wire mode)
    uint16_t rtd_resistance = (raw_data >> 18) & 0x3FFF; // Extract 14 bits

    // Convert RTD resistance to ohms (example, adjust based on your RTD)
    float rtd_resistance_ohms = (float)rtd_resistance * 400.0 / 32768.0; // Example scaling

    // Callendar-Van Dusen equation (example, adjust based on your RTD)
    float temperature = (rtd_resistance_ohms - 100.0) / 0.39; // Example equation

    return temperature;
}

// Function to log data to file
int log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close SPI and log file
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
