#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUMIDITY 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int init_bme280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure);
double compensate_humidity(int32_t raw_humidity);
void log_data(double temperature, double humidity, double pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize the BME280 sensor
int init_bme280() {
    // Check the sensor ID
    char chip_id;
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_ID, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUMIDITY, 0x01) != 0) {
        fprintf(stderr, "Error writing to CTRL_HUMIDITY register\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set the config register (t_sb = 0.5ms, filter = off)
    if (i2cWriteByteData(i2c_handle, BME280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
int read_calibration_data() {
    uint8_t buffer[26];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)buffer, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib.dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib.dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib.dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib.dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib.dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib.dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib.dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib.dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib.dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib.dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib.dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);
    calib.dig_H1 = buffer[25];

    uint8_t buffer_h[7];
    if (i2cReadI2CBlockData(i2c_handle, 0xE1, (char *)buffer_h, 7) != 7) {
        fprintf(stderr, "Error reading humidity calibration data\n");
        return -1;
    }

    calib.dig_H2 = (int16_t)buffer_h[0] | ((int16_t)buffer_h[1] << 8);
    calib.dig_H3 = buffer_h[2];
    calib.dig_H4 = (int16_t)((buffer_h[3] << 4) | (buffer_h[4] & 0x0F));
    calib.dig_H5 = (int16_t)((buffer_h[5] << 4) | (buffer_h[4] >> 4));
    calib.dig_H6 = (int8_t)buffer_h[6];

    return 0;
}

// Read raw temperature, pressure, and humidity data from the sensor
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t buffer[8];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_PRESSURE_MSB, (char *)buffer, 8) != 8) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (int32_t)buffer[0] << 12 | (int32_t)buffer[1] << 4 | (int32_t)(buffer[2] >> 4);
    *temperature = (int32_t)buffer[3] << 12 | (int32_t)buffer[4] << 4 | (int32_t)(buffer[5] >> 4);
    *humidity = (int32_t)buffer[6] << 8 | (int32_t)buffer[7];

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double adc_T = (double)raw_temperature;

    var1 = (adc_T / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    var2 = ((adc_T / 131072.0 - calib.dig_T1 / 8192.0) * (adc_T / 131072.0 - calib.dig_T1 / 8192.0)) * calib.dig_T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data
double compensate_pressure(int32_t raw_pressure) {
    double var1, var2, p;
    double adc_P = (double)raw_pressure;

    double t_fine; // Needs to be calculated in compensate_temperature first
    int32_t raw_temperature;
    if (read_raw_data(&raw_temperature, &raw_pressure, NULL) != 0) {
        fprintf(stderr, "Error reading raw temperature during pressure compensation\n");
        return -1.0;
    }
    double adc_T = (double)raw_temperature;

    var1 = (adc_T / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    var2 = ((adc_T / 131072.0 - calib.dig_T1 / 8192.0) * (adc_T / 131072.0 - calib.dig_T1 / 8192.0)) * calib.dig_T3;
    t_fine = var1 + var2;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (calib.dig_P4 * 65536.0);
    var1 = (calib.dig_P3 * var1 * var1 / 524288.0 + calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * calib.dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + calib.dig_P7) / 16.0;

    return p;
}

// Compensate humidity using calibration data
double compensate_humidity(int32_t raw_humidity) {
    double var_H;
    double adc_H = (double)raw_humidity;

    double t_fine; // Needs to be calculated in compensate_temperature first
    int32_t raw_temperature;
    if (read_raw_data(&raw_temperature, NULL, &raw_humidity) != 0) {
        fprintf(stderr, "Error reading raw temperature during humidity compensation\n");
        return -1.0;
    }
    double adc_T = (double)raw_temperature;

    var_H = t_fine - 76800.0;
    var_H = (adc_H - (calib.dig_H4 * 64.0 + calib.dig_H5 / 16384.0 * var_H)) * (calib.dig_H2 / 65536.0 * (1.0 + calib.dig_H6 / 67108864.0 * var_H * (1.0 + calib.dig_H3 / 67108864.0 * var_H)));
    var_H = var_H * (1.0 - calib.dig_H1 * var_H / 524288.0);

    if (var_H > 100.0)
        var_H = 100.0;
    else if (var_H < 0.0)
        var_H = 0.0;

    return var_H;
}

// Log data to a CSV file
void log_data(double temperature, double humidity, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

