        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bme280_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),Pressure(hPa)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure, raw_humidity;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure, &raw_humidity) == 0) {
            // Compensate data
            double temperature = compensate_temperature(raw_temperature);
            double pressure = compensate_pressure(raw_pressure);
            double humidity = compensate_humidity(raw_humidity);

            // Log data
            log_data(temperature, humidity, pressure);

            printf("Temperature: %.2f C, Humidity: %.2f %%, Pressure: %.2f hPa\n", temperature, humidity, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

