#include <math.h>

#include <wiringPi.h>
#include <wiringPiI2C.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_PIN 24

// Circular buffer size (60 seconds * 10 readings/second)
#define BUFFER_SIZE 600

// Structure to hold pressure reading and timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

// Circular buffer
PressureReading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// I2C file descriptor
int i2c_fd;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_pressure(int raw_temperature, int raw_pressure);
void add_reading(float pressure);
float calculate_rolling_average();
void assert_alert();
void deassert_alert();
void signal_handler(int signal);
void log_error(const char *message);

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

int main()
{
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        fprintf(stderr, "Error initializing I2C. Exiting.\n");
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() == -1) {
        fprintf(stderr, "Error reading calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Set GPIO24 as output
    pinMode(ALERT_PIN, OUTPUT);
    deassert_alert(); // Ensure alert is initially off

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int raw_temperature, raw_pressure;
        float pressure;

        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temperature) == -1 || read_raw_pressure(&raw_pressure) == -1) {
            log_error("Error reading temperature or pressure.");
            delay(50); // Wait before retrying
            continue;
        }

        // Calculate pressure
        pressure = calculate_pressure(raw_temperature, raw_pressure);

        // Add reading to circular buffer
        add_reading(pressure);

        // Calculate rolling average
        float rolling_average = calculate_rolling_average();

        // Check for pressure deviation
        float deviation = fabs(pressure - rolling_average);
        if (deviation > 5.0) {
            assert_alert();
            fprintf(stderr, "Alert: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa\n", pressure, rolling_average);
        } else {
            deassert_alert();
        }

        // Wait 50 milliseconds
        delay(50);
    }

    // Cleanup
    close(i2c_fd);
    deassert_alert();

    return 0;
}

// Initialize I2C
int init_i2c()
{
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read calibration data from BMP180
int read_calibration_data()
{
    ac1 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC1);
    ac2 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC2);
    ac3 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC3);
    ac4 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC4);
    ac5 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC5);
    ac6 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC6);
    b1 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B1);
    b2 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B2);
    mb = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MB);
    mc = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MC);
    md = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MD);

    return 0;
}

// Read raw temperature value from BMP180
int read_raw_temperature(int *raw_temperature)
{
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x2E); // Request temperature reading
    delay(5); // Wait for conversion (at least 4.5ms)

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);

    if (msb == -1 || lsb == -1) {
        log_error("Error reading raw temperature data.");
        return -1;
    }

    *raw_temperature = (msb << 8) + lsb;
    return 0;
}

// Read raw pressure value from BMP180
int read_raw_pressure(int *raw_pressure)
{
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)); // Request pressure reading
    delay(2 + (3 << BMP180_OSS)); // Wait for conversion

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        log_error("Error reading raw pressure data.");
        return -1;
    }

    *raw_pressure = ((msb << 16) + (lsb << 8) + xlsb) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate pressure in hPa
float calculate_pressure(int raw_temperature, int raw_pressure)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    x1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((ac1 * 4 + x3) << BMP180_OSS) + 2) / 4;

    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / pow(2, 2);
    b4 = ac4 * (unsigned long)(x3 + 32768) / pow(2, 15);
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    p = p + (x1 + x2 + 3791) / pow(2, 4);

    return p / 100.0; // Convert to hPa
}

// Add pressure reading to circular buffer
void add_reading(float pressure)
{
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].pressure = pressure;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Calculate rolling average of pressure readings
float calculate_rolling_average()
{
    if (buffer_count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += buffer[i].pressure;
    }

    return sum / buffer_count;
}

// Assert alert (set GPIO high)
void assert_alert()
{
    digitalWrite(ALERT_PIN, HIGH);
}

// Deassert alert (set GPIO low)
void deassert_alert()
{
    digitalWrite(ALERT_PIN, LOW);
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// Log error messages to stderr
void log_error(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%04d-%02d-%02d %02d:%02d:%02d: ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

