#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C addresses
#define BMP280_I2C_ADDR_1 0x76
#define BMP280_I2C_ADDR_2 0x77

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

bmp280_calib_data calib_1, calib_2;

// Function prototypes
int init_i2c(int i2c_bus, int i2c_address);
int read_calibration_data(int i2c_handle, bmp280_calib_data *calib);
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, double t_fine, bmp280_calib_data calib);
int write_data_to_file(double temperature1, double pressure1, double temperature2, double pressure2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_address, handle);
        return -1;
    }
    return handle;
}

// Read calibration data from BMP280
int read_calibration_data(int i2c_handle, bmp280_calib_data *calib) {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from BMP280
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESSURE_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using BMP280 formula
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, T;
    double dig_T1 = (double)calib.dig_T1;
    double dig_T2 = (double)calib.dig_T2;
    double dig_T3 = (double)calib.dig_T3;

    var1 = (((double)raw_temperature / 16384.0) - dig_T1 / 1024.0) * dig_T2;
    var2 = ((((double)raw_temperature / 131072.0) - dig_T1 / 8192.0) * (((double)raw_temperature / 131072.0) - dig_T1 / 8192.0)) * dig_T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using BMP280 formula
double compensate_pressure(int32_t raw_pressure, double t_fine, bmp280_calib_data calib) {
    double var1, var2, p;
    double dig_P1 = (double)calib.dig_P1;
    double dig_P2 = (double)calib.dig_P2;
    double dig_P3 = (double)calib.dig_P3;
    double dig_P4 = (double)calib.dig_P4;
    double dig_P5 = (double)calib.dig_P5;
    double dig_P6 = (double)calib.dig_P6;
    double dig_P7 = (double)calib.dig_P7;
    double dig_P8 = (double)calib.dig_P8;
    double dig_P9 = (double)calib.dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = dig_P9 * p * p / 2147483648.0;
    var2 = p * dig_P8 / 32768.0;
    p = p + (var1 + var2 + dig_P7) / 16.0;

    return p;
}

// Write data to file
int write_data_to_file(double temperature1, double pressure1, double temperature2, double pressure2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature1: %.2f °C, Pressure1: %.2f hPa, Temperature2: %.2f °C, Pressure2: %.2f hPa\n",
            timestamp, temperature1, pressure1, temperature2, pressure2);

    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle_1 = init_i2c(1, BMP280_I2C_ADDR_1);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1, trying alternative address...\n");
        i2c_handle_1 = init_i2c(1, BMP280_I2C_ADDR_2);
        if (i2c_handle_1 < 0) {
            fprintf(stderr, "Failed to initialize I2C for sensor 1 on both addresses.\n");
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
    }

    i2c_handle_2 = init_i2c(1, BMP280_I2C_ADDR_2);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2, trying alternative address...\n");
        i2c_handle_2 = init_i2c(1, BMP280_I2C_ADDR_1);
        if (i2c_handle_2 < 0) {
            fprintf(stderr, "Failed to initialize I2C for sensor 2 on both addresses.\n");
            i2cClose(i2c_handle_1);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
    }

    // Read calibration data for both sensors
    if (read_calibration_data(i2c_handle_1, &calib_1) != 0) {
        fprintf(stderr, "Failed to read calibration data for sensor 1\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_handle_2, &calib_2) != 0) {
        fprintf(stderr, "Failed to read calibration data for sensor 2\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature1, raw_pressure1, raw_temperature2, raw_pressure2;
        double temperature1, pressure1, temperature2, pressure2;

        // Read raw data from sensor 1
        if (read_raw_data(i2c_handle_1, &raw_temperature1, &raw_pressure1) == 0) {
            // Compensate temperature and pressure for sensor 1
            temperature1 = compensate_temperature(raw_temperature1, calib_1);
            pressure1 = compensate_pressure(raw_pressure1, temperature1, calib_1);
        } else {
            fprintf(stderr, "Error reading data from sensor 1\n");
            temperature1 = -999.0; // Indicate error
            pressure1 = -999.0;
        }

        // Read raw data from sensor 2
        if (read_raw_data(i2c_handle_2, &raw_temperature2, &raw_pressure2) == 0) {
            // Compensate temperature and pressure for sensor 2
            temperature2 = compensate_temperature(raw_temperature2, calib_2);
            pressure2 = compensate_pressure(raw_pressure2, temperature2, calib_2);
        } else {
            fprintf(stderr, "Error reading data from sensor 2\n");
            temperature2 = -999.0; // Indicate error
            pressure2 = -999.0;
        }

        // Write data to file
        write_data_to_file(temperature1, pressure1, temperature2, pressure2);

        // Set sensor 1 to forced mode
        if (i2cWriteByteData(i2c_handle_1, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
            fprintf(stderr, "Error writing to sensor 1 control register\n");
        }

        // Set sensor 2 to forced mode
        if (i2cWriteByteData(i2c_handle_2, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
            fprintf(stderr, "Error writing to sensor 2 control register\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C and log file
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

