#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define ALERT_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SLEEP_SECONDS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    int mutex;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
float read_temperature();
void update_running_average(float new_temp);
void control_alert_led(float avg_temp);
void signal_handler(int signal);
int init_gpio();
int init_i2c();
void cleanup();
void init_circular_buffer(CircularBuffer *cb);
void add_to_circular_buffer(CircularBuffer *cb, float value);
float calculate_running_average(CircularBuffer *cb);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    cb->mutex = 0; // Not used in this implementation
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

// Add a value to the circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the running average
float calculate_running_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Read temperature from LM75 sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -100.0; // Indicate error
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits

    float temp_celsius = raw_temp * 0.125;
    return temp_celsius;
}

// Update running average
void update_running_average(float new_temp) {
    add_to_circular_buffer(&temp_buffer, new_temp);
}

// Control alert LED
void control_alert_led(float avg_temp) {
    if (avg_temp > TEMP_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(ALERT_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    gpioWrite(ALERT_GPIO, 0); // Ensure LED is off initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Turn off LED
    gpioSetMode(ALERT_GPIO, PI_INPUT); // Set back to input
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Temperature monitoring started...\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -99.0) { // Check for valid temperature reading
            update_running_average(temperature);
            float avg_temp = calculate_running_average(&temp_buffer);
            control_alert_led(avg_temp);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, avg_temp);
        } else {
            fprintf(stderr, "Error reading temperature, skipping alert.\n");
        }
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

