#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define PT100_NOMINAL_RESISTANCE 100.0 // 100 ohms
#define PT100_REFERENCE_RESISTANCE 430.0 // 430 ohms
#define TARGET_TEMPERATURE_DEFAULT 25.0
#define KP_DEFAULT 1.0
#define KI_DEFAULT 0.1
#define KD_DEFAULT 0.01
#define MAX_TEMPERATURE 80.0
#define MAX_SPI_RETRIES 3

// Global variables
static volatile int running = 1;
static int spi_handle;
static double target_temperature = TARGET_TEMPERATURE_DEFAULT;
static double Kp = KP_DEFAULT;
static double Ki = KI_DEFAULT;
static double Kd = KD_DEFAULT;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_value, double Kp, double Ki, double Kd, double *integral, double *previous_error);
void set_heater_pwm(int duty_cycle);
void load_configuration(const char *filename);
void signal_handler(int signal);
void log_error(const char *message);

// Function to read temperature from MAX31865 via SPI
double read_temperature() {
    unsigned char buffer[5];
    int retries = 0;
    int status;

    while (retries < MAX_SPI_RETRIES) {
        status = spiRead(spi_handle, buffer, 5);
        if (status == 5) {
            // Check for fault bits
            if (buffer[1] & 0x01) {
                log_error("MAX31865 Fault: Open circuit.");
                return -1000.0; // Indicate error
            } else if (buffer[1] & 0x02) {
                log_error("MAX31865 Fault: Short to GND.");
                return -1000.0; // Indicate error
            } else if (buffer[1] & 0x04) {
                log_error("MAX31865 Fault: Short to VCC.");
                return -1000.0; // Indicate error
            }

            // Extract RTD value (bits 3-18)
            int rtd_raw = ((buffer[1] << 8) | buffer[2]) >> 3;

            // Convert RTD value to resistance (using PT100 formula)
            double rtd_resistance = ((double)rtd_raw / 32768.0) * PT100_REFERENCE_RESISTANCE;

            // Convert resistance to temperature (using PT100 datasheet)
            double temperature = (rtd_resistance - PT100_NOMINAL_RESISTANCE) / 0.385; // Simplified conversion

            return temperature;
        } else {
            log_error("SPI read failed. Retrying...");
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    log_error("SPI read failed after multiple retries.");
    return -1000.0; // Indicate error
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_value, double Kp, double Ki, double Kd, double *integral, double *previous_error) {
    double error = setpoint - actual_value;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to load configuration from JSON file
void load_configuration(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load configuration file: %s\n", error.text);
        return;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    if (json_is_real(target_temp)) {
        target_temperature = json_real_value(target_temp);
    }

    json_t *kp = json_object_get(root, "Kp");
    if (json_is_real(kp)) {
        Kp = json_real_value(kp);
    }

    json_t *ki = json_object_get(root, "Ki");
    if (json_is_real(ki)) {
        Ki = json_real_value(ki);
    }

    json_t *kd = json_object_get(root, "Kd");
    if (json_is_real(kd)) {
        Kd = json_real_value(kd);
    }

    json_decref(root);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to log errors with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Load configuration from file
    load_configuration("heater_config.json");

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature < -900) {
            log_error("Temperature reading failed. Shutting down heater.");
            set_heater_pwm(0);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        // Check for failsafe conditions
        if (temperature > MAX_TEMPERATURE) {
            log_error("Temperature exceeds maximum limit. Shutting down heater.");
            set_heater_pwm(0);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        // Calculate PID output
        double pid_output = calculate_pid(target_temperature, temperature, Kp, Ki, Kd, &integral, &previous_error);

        // Set heater PWM duty cycle
        int duty_cycle = (int)pid_output;
        set_heater_pwm(duty_cycle);

        // Print current temperature and PID output (for debugging)
        printf("Temperature: %.2f °C, PID Output: %d\n", temperature, duty_cycle);

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    set_heater_pwm(0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

