#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 2000000 // 2 MHz
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define KP 1.0
#define KI 0.1
#define INTEGRAL_LIMIT 100.0
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
float calculate_duty_cycle(float temperature, float target_temperature, float max_duty_cycle);
void set_heater_duty_cycle(int gpio, float duty_cycle);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1;
    }

    // Check for fault conditions
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate duty cycle using PI controller
float calculate_duty_cycle(float temperature, float target_temperature, float max_duty_cycle) {
    static float integral = 0.0;
    float error = target_temperature - temperature;

    integral += error;
    if (integral > INTEGRAL_LIMIT) integral = INTEGRAL_LIMIT;
    if (integral < -INTEGRAL_LIMIT) integral = -INTEGRAL_LIMIT;

    float duty_cycle = KP * error + KI * integral;

    if (duty_cycle > max_duty_cycle) {
        duty_cycle = max_duty_cycle;
    } else if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    }

    return duty_cycle;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(int gpio, float duty_cycle) {
    int pwm_value = (int)(duty_cycle * 255.0 / 100.0);
    gpioPWM(gpio, pwm_value);
}

// Function to log data to file
void log_data(float temperature, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 2MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(HEATER_GPIO, 255); // PWM range of 0-255

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, duty_cycle;

    // Main loop
    while (!terminate) {
        if (read_max31855(spi_handle, &temperature) == 0) {
            if (temperature >= MIN_TEMPERATURE && temperature <= MAX_TEMPERATURE) {
                duty_cycle = calculate_duty_cycle(temperature, TARGET_TEMPERATURE, MAX_DUTY_CYCLE);
                set_heater_duty_cycle(HEATER_GPIO, duty_cycle);
                log_data(temperature, duty_cycle);
            } else {
                fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                set_heater_duty_cycle(HEATER_GPIO, 0.0);
                log_data(temperature, 0.0);
            }
        } else {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0\n");
            set_heater_duty_cycle(HEATER_GPIO, 0.0);
            log_data(0.0, 0.0); // Log the error
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Shutdown sequence
    set_heater_duty_cycle(HEATER_GPIO, 0.0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

