    } else if (temperature < 60000) {
        red = 0;
        green = 255;
        blue = 0;
    } else {
        red = 255;
        green = 0;
        blue = 0;
    }

    // Invert duty cycle for common anode
    int red_duty = 255 - red;
    int green_duty = 255 - green;
    int blue_duty = 255 - blue;

