    if (gpioPWM(GREEN_PIN, green_duty) < 0) {
        fprintf(stderr, "Error: Failed to set green PWM duty cycle\n");
    }
    if (gpioPWM(BLUE_PIN, blue_duty) < 0) {
        fprintf(stderr, "Error: Failed to set blue PWM duty cycle\n");
    }
}

