#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <curl/curl.h>
#include <pigpio.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_BASE_MS 100
#define TIMEOUT_MS 100

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int read_dht22(int gpio, SensorData *data);
int validate_checksum(const unsigned char *data);
int post_data(const char *url, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the response here if needed
    return real_size;
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, SensorData *data) {
    unsigned char data_buffer[5] = {0};
    int i, j;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // 1ms
    gpioWrite(gpio, 1);
    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDown(gpio, PI_PUD_UP);
    gpioDelay(30); // Wait for sensor to respond

    // Read data
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // 1ms
    gpioWrite(gpio, 1);
    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDown(gpio, PI_PUD_UP);

    // Wait for the sensor to pull the line low (response signal)
    int timeout_count = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Check every 1ms
        timeout_count++;
        if (timeout_count > TIMEOUT_MS) {
            fprintf(stderr, "Error: DHT22 timeout waiting for start signal.\n");
            return -1; // Timeout
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 5; i++) {
        data_buffer[i] = 0;
        for (j = 0; j < 8; j++) {
            // Wait for the line to go high
            timeout_count = 0;
            while (gpioRead(gpio) == 0) {
                gpioDelay(1); // Check every 1ms
                timeout_count++;
                if (timeout_count > TIMEOUT_MS) {
                    fprintf(stderr, "Error: DHT22 timeout waiting for data high.\n");
                    return -1; // Timeout
                }
            }

            // Measure the length of the high pulse
            struct timeval start, end;
            gettimeofday(&start, NULL);
            timeout_count = 0;
            while (gpioRead(gpio) == 1) {
                gpioDelay(1); // Check every 1ms
                timeout_count++;
                if (timeout_count > TIMEOUT_MS) {
                    fprintf(stderr, "Error: DHT22 timeout waiting for data low.\n");
                    return -1; // Timeout
                }
            }
            gettimeofday(&end, NULL);

            // Determine if the bit is a 0 or a 1 based on the pulse length
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec) > 40) {
                data_buffer[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    if (!validate_checksum(data_buffer)) {
        fprintf(stderr, "Error: DHT22 checksum validation failed.\n");
        return -1;
    }

    // Convert data to temperature and humidity
    data->humidity = (float)(((unsigned int)data_buffer[0] << 8) | data_buffer[1]) / 10.0;
    data->temperature = (float)(((unsigned int)data_buffer[2] << 8) | data_buffer[3]) / 10.0;
    if (data->temperature > 125) {
        data->temperature = data->temperature - 256;
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data) {
    return (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF));
}

// Function to post data to the server
int post_data(const char *url, float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    char json_payload[128];
    int retry = 0;

    // Create JSON payload
    snprintf(json_payload, sizeof(json_payload), "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);

    while (retry < MAX_RETRIES) {
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

            // Set timeout
            curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, TIMEOUT_MS);

            res = curl_easy_perform(curl);
            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    printf("Data posted successfully. HTTP code: %ld\n", response_code);
                    curl_easy_cleanup(curl);
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error: HTTP request failed with code: %ld\n", response_code);
                }
            } else {
                fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            }
            curl_easy_cleanup(curl);
        } else {
            fprintf(stderr, "Error: curl_easy_init() failed\n");
        }

        retry++;
        if (retry < MAX_RETRIES) {
            int delay_ms = RETRY_DELAY_BASE_MS * (1 << retry); // Exponential backoff
            printf("Retrying in %d ms... (%d/%d)\n", delay_ms, retry, MAX_RETRIES);
            gpioDelay(delay_ms);
        }
    }

    fprintf(stderr, "Error: Failed to post data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received: %d. Shutting down...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (pigpio_initialized) {
        gpioTerminate();
        printf("pigpio terminated.\n");
    }
}

int main() {
    SensorData sensor_data;
    int retry;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Main loop
    while (running) {
        retry = 0;
        while (retry < MAX_RETRIES) {
            if (read_dht22(DHT22_GPIO, &sensor_data) == 0) {
                // Data validation
                if (sensor_data.temperature >= -40.0 && sensor_data.temperature <= 80.0 &&
                    sensor_data.humidity >= 0.0 && sensor_data.humidity <= 100.0) {
                    if (post_data(SERVER_URL, sensor_data.temperature, sensor_data.humidity) == 0) {
                        break; // Success, exit retry loop
                    }
                } else {
                    fprintf(stderr, "Error: Invalid sensor data: temperature=%.1f, humidity=%.1f\n", sensor_data.temperature, sensor_data.humidity);
                }
            }

            retry++;
            if (retry < MAX_RETRIES) {
                int delay_ms = RETRY_DELAY_BASE_MS * (1 << retry); // Exponential backoff
                printf("Retrying sensor read in %d ms... (%d/%d)\n", delay_ms, retry, MAX_RETRIES);
                gpioDelay(delay_ms);
            }
        }

        if (retry == MAX_RETRIES) {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }

        sleep(60); // Read every 60 seconds
    }

    cleanup();
    return 0;
}

