// Function to calculate pressure in hPa
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature) {
    double X1 = (((double)raw_temperature - (double)ac6) * (double)ac5) / pow(2, 15);
    double X2 = ((double)mc * pow(2, 11)) / (X1 + (double)md);
    double B5 = X1 + X2;

    double B6 = B5 - 4000;
    double X3 = ((double)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    double X4 = ((double)ac2 * B6) / pow(2, 11);
