#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <getopt.h>
#include <pigpio.h>
#include <time.h>

// Configuration
#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define BACKOFF_BASE 2
#define READ_INTERVAL 10 // seconds
#define API_ENDPOINT "http://your-api-endpoint.com/api/humidity"

// Global variables
static volatile int running = 1;
static char *api_url = NULL;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Function prototypes
int init_gpio();
int read_dht22(DHT22Data *data);
int validate_checksum(const unsigned char *data);
int post_data(const DHT22Data *data);
void signal_handler(int sig);
void cleanup();

// Helper function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Callback function for libcurl to handle response data (not used here, but required)
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    return real_size;
}

int main(int argc, char *argv[]) {
    int opt;
    DHT22Data data;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
                return 1;
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio.");
        closelog();
        return 1;
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Main loop
    while (running) {
        // Read DHT22 sensor
        if (read_dht22(&data) == 0) {
            // Validate data
            if (validate_checksum((const unsigned char *)&data)) {
                // Post data to API endpoint
                if (post_data(&data) != 0) {
                    syslog(LOG_ERR, "Failed to post data to API endpoint.");
                }
            } else {
                syslog(LOG_ERR, "Checksum validation failed.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor.");
        }

        // Wait for the next read interval
        sleep(READ_INTERVAL);
    }

    // Cleanup
    cleanup();

    // Close syslog
    closelog();

    return 0;
}

// Initialize pigpio library
int init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(DHT22_GPIO, PI_OUTPUT); // Set GPIO as output initially
    return 0;
}

// Read data from DHT22 sensor
int read_dht22(DHT22Data *data) {
    int retries = 0;
    int result;
    unsigned char data_buffer[5] = {0};

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1 ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(30); // 30 us

        // Switch to input mode
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // Read data
        int bit_count = 0;
        unsigned long start_time = gpioTick();
        while (bit_count < 40) {
            while (gpioRead(DHT22_GPIO) == 0) {
                if (gpioTick() - start_time > 200) {
                    syslog(LOG_ERR, "DHT22 timeout waiting for start signal.");
                    return -1;
                }
            }

            unsigned long pulse_start = gpioTick();
            while (gpioRead(DHT22_GPIO) == 1) {
                if (gpioTick() - pulse_start > 200) {
                    syslog(LOG_ERR, "DHT22 timeout waiting for end of pulse.");
                    return -1;
                }
            }

            unsigned long pulse_end = gpioTick();
            unsigned long pulse_length = pulse_end - pulse_start;

            if (pulse_length > 40) {
                data_buffer[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
            }

            bit_count++;
        }

        // Validate checksum
        if (validate_checksum(data_buffer)) {
            // Convert data to temperature and humidity
            data->humidity = (float)(((data_buffer[0] << 8) | data_buffer[1])) / 10.0;
            data->temperature = (float)(((data_buffer[2] & 0x7F) << 8) | data_buffer[3]) / 10.0;
            if (data_buffer[2] & 0x80) {
                data->temperature *= -1;
            }

            // Data is valid
            return 0;
        } else {
            syslog(LOG_ERR, "Checksum validation failed. Retrying...");
            retries++;
            sleep(BACKOFF_BASE * retries);
        }
    }

    syslog(LOG_ERR, "Failed to read DHT22 sensor after %d retries.", MAX_RETRIES);
    return -1;
}

// Validate checksum
int validate_checksum(const unsigned char *data) {
    return ((data[0] + data[1] + data[2] + data[3]) & 0xFF) == data[4];
}

// Post data to API endpoint
int post_data(const DHT22Data *data) {
    CURL *curl;
    CURLcode res;
    char json_data[128];
    char timestamp[20];

    // Format data as JSON
    snprintf(json_data, sizeof(json_data), "{\"temperature\": %.1f, \"humidity\": %.1f}", data->temperature, data->humidity);

    // Get timestamp
    get_timestamp(timestamp);

    // Create JSON payload with timestamp
    char json_payload[256];
    snprintf(json_payload, sizeof(json_payload), "{\"timestamp\": \"%s\", \"data\": %s}", timestamp, json_data);

    // Create libcurl request
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url ? api_url : API_ENDPOINT);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback); // Required but not used

        // Set Content-Type header
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Retry logic
        int retries = 0;
        while (retries < 3) {
            // Perform the request
            res = curl_easy_perform(curl);

            // Check for errors
            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    syslog(LOG_INFO, "Data posted successfully. Response code: %ld", response_code);
