#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char temp_str[10];
    int temp_milli_celsius;

    fp = fopen(CPU_TEMP_PATH, "r");
    if (fp == NULL) {
        perror("Error opening CPU temperature file");
        return -1; // Indicate error
    }

    if (fgets(temp_str, sizeof(temp_str), fp) == NULL) {
        perror("Error reading CPU temperature");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    temp_milli_celsius = atoi(temp_str);
    return temp_milli_celsius / 1000; // Convert to Celsius
}

// Function to read fan state from file
int read_fan_state() {
    FILE *fp;
    char state_str[2];
    int state;

    fp = fopen(FAN_STATE_PATH, "r");
    if (fp == NULL) {
        perror("Error opening fan state file");
        return -1; // Indicate error
    }

    if (fgets(state_str, sizeof(state_str), fp) == NULL) {
        perror("Error reading fan state");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    state = atoi(state_str);
    return state;
}

// Function to read fan max state from file
int read_fan_max_state() {
    FILE *fp;
    char state_str[2];
    int state;

    fp = fopen(FAN_MAX_STATE_PATH, "r");
    if (fp == NULL) {
        perror("Error opening fan max state file");
        return -1; // Indicate error
    }

    if (fgets(state_str, sizeof(state_str), fp) == NULL) {
        perror("Error reading fan max state");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    state = atoi(state_str);
    return state;
}

// Function to set fan state
int set_fan_state(int state) {
    FILE *fp;
    char state_str[2];

    fp = fopen(FAN_STATE_PATH, "w");
    if (fp == NULL) {
        perror("Error opening fan state file for writing");
        return -1; // Indicate error
    }

    snprintf(state_str, sizeof(state_str), "%d", state);
    if (fputs(state_str, fp) == EOF) {
        perror("Error writing fan state");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return 0;
}

// Function to log fan state changes
int log_fan_state(int state) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1; // Indicate error
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Fan state changed to: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, state);

    fclose(fp);
    return 0;
}

// Function to determine fan speed based on temperature
int determine_fan_speed(int temperature) {
    if (temperature < 45) {
        return 0; // Off
    } else if (temperature < 55) {
        return 1; // Low
    } else if (temperature < 65) {
        return 2; // Medium
    } else {
        return 3; // High
    }
}

int main() {
    int current_temp, current_fan_state, max_fan_state, new_fan_state;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Validate fan max state
    max_fan_state = read_fan_max_state();
    if (max_fan_state == -1) {
        fprintf(stderr, "Error reading fan max state. Exiting.\n");
        return 1;
    }

    printf("Fan control started. Max state: %d\n", max_fan_state);

    while (program_running) {
        current_temp = read_cpu_temp();
        if (current_temp == -1) {
            fprintf(stderr, "Error reading CPU temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        current_fan_state = read_fan_state();
        if (current_fan_state == -1) {
            fprintf(stderr, "Error reading fan state. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        new_fan_state = determine_fan_speed(current_temp);

        if (new_fan_state != current_fan_state) {
            if (set_fan_state(new_fan_state) == 0) {
                log_fan_state(new_fan_state);
                printf("Temperature: %d°C, Fan state: %d\n", current_temp, new_fan_state);
            } else {
                fprintf(stderr, "Error setting fan state. Retrying in 5 seconds.\n");
            }
        }

        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down fan control...\n");
    if (set_fan_state(0) == 0) {
        log_fan_state(0);
    } else {
        fprintf(stderr, "Error setting fan state to off during shutdown.\n");
    }

    printf("Fan control stopped.\n");
    return 0;
}

