#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define LOG_FILE "heater_log.txt"

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// PID Variables
double integral = 0.0;
double previous_error = 0.0;

// Function Prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_value, double *integral, double *previous_error);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(double temperature, int duty_cycle, double pid_output);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int i;

    if (wiringPiSPIDataRW(SPI_CHANNEL, data, 4) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return NAN; // Indicate error with NaN
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(log_file, "%ld: Open circuit fault detected!\n", time(NULL));
        fflush(log_file);
        return NAN;
    }
    if (data[3] & 0x02) {
        fprintf(log_file, "%ld: Short to GND fault detected!\n", time(NULL));
        fflush(log_file);
        return NAN;
    }
    if (data[3] & 0x04) {
        fprintf(log_file, "%ld: Short to VCC fault detected!\n", time(NULL));
        fflush(log_file);
        return NAN;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_value, double *integral, double *previous_error) {
    double error = setpoint - actual_value;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Clamp the output to the PWM range
    if (output < 0) output = 0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    pwmWrite(HEATER_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f °C, Duty Cycle: %d, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off the heater
    set_pwm_duty_cycle(0);

    // Close the SPI interface
    // wiringPiSPIClose(SPI_CHANNEL); // wiringPiSPIClose is not a standard function, using a dummy implementation

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

