#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp = 0.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000.0;
    }

    fclose(fp);
    return temp;
}

// Function to map temperature to PWM duty cycle
int map_temp_to_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 100.0);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    int result = gpioPWM(gpio, duty_cycle);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);

    fclose(fp);
    return 0;
}

int main() {
    int result;
    float temperature;
    int duty_cycle;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading CPU temperature, using previous value.\n");
            // Consider implementing a fallback temperature or exiting the program
        }

        // Map temperature to duty cycle
        duty_cycle = map_temp_to_duty_cycle(temperature);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(GPIO_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, continuing.\n");
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, continuing.\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Turn off the fan before exiting
    set_pwm_duty_cycle(GPIO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

