#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flow_sensor(int i2c_handle, float *flow1, float *flow2);
uint8_t calculate_crc(const uint8_t *data, int len);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint8_t data[2];
    uint8_t crc;
} sensor_data_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read flow sensor data
int read_flow_sensor(int i2c_handle, float *flow1, float *flow2) {
    sensor_data_t sensor1_data, sensor2_data;
    int retries = 0;
    int bytes_read;

    // Read sensor 1 data
    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)sensor1_data.data, 2);
        if (bytes_read == 2) {
            break;
        } else {
            fprintf(stderr, "I2C read error (sensor 1), retry %d: %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read sensor 1 after %d retries\n", MAX_RETRIES);
        return 1;
    }

    // Read sensor 2 data
    retries = 0;
    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)sensor2_data.data, 2);
        if (bytes_read == 2) {
            break;
        } else {
            fprintf(stderr, "I2C read error (sensor 2), retry %d: %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read sensor 2 after %d retries\n", MAX_RETRIES);
        return 1;
    }

    // Read CRC data for sensor 1
    retries = 0;
    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)&sensor1_data.crc, 1);
        if (bytes_read == 1) {
            break;
        } else {
            fprintf(stderr, "I2C read error (CRC sensor 1), retry %d: %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read CRC sensor 1 after %d retries\n", MAX_RETRIES);
        return 1;
    }

    // Read CRC data for sensor 2
    retries = 0;
    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)&sensor2_data.crc, 1);
        if (bytes_read == 1) {
            break;
        } else {
            fprintf(stderr, "I2C read error (CRC sensor 2), retry %d: %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read CRC sensor 2 after %d retries\n", MAX_RETRIES);
        return 1;
    }

    // Validate CRC for sensor 1
    if (calculate_crc(sensor1_data.data, 2) != sensor1_data.crc) {
        fprintf(stderr, "CRC check failed for sensor 1\n");
        return 1;
    }

    // Validate CRC for sensor 2
    if (calculate_crc(sensor2_data.data, 2) != sensor2_data.crc) {
        fprintf(stderr, "CRC check failed for sensor 2\n");
        return 1;
    }

    // Convert data to flow rates
    *flow1 = (float)((sensor1_data.data[0] << 8) | sensor1_data.data[1]) / 100.0; // Example conversion
    *flow2 = (float)((sensor2_data.data[0] << 8) | sensor2_data.data[1]) / 100.0; // Example conversion

    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to clean up resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float flow1, flow2;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    if (initialize()) {
        return 1;
    }

    while (!terminate) {
        if (read_flow_sensor(i2c_handle, &flow1, &flow2) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data to file
            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
            fflush(log_file); // Ensure data is written to disk

            printf("%s,%.2f,%.2f\n", timestamp, flow1, flow2);
        } else {
            fprintf(stderr, "Failed to read flow sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

