#include <string.h>

// Define GPIO pins for the encoder channels
#define ENCODER_A 17
#define ENCODER_B 18

// Define the number of pulses per revolution
#define PPR 360.0

// Define the number of states in the quadrature state machine
#define NUM_STATES 4

// Define the states of the quadrature state machine
enum {
    STATE_00,
    STATE_01,
    STATE_10,
    STATE_11
};

// Global variables
static volatile int current_state = STATE_00;
static volatile int last_state = STATE_00;
static volatile int pulse_count = 0;
static volatile double angular_position = 0.0;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_angular_position(int pulse_count);
int log_angular_position(double angular_position);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    FILE *log_file;
} ProgramState;

ProgramState state = {0, NULL};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetMode(ENCODER_B, PI_INPUT);

    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    state.gpio_initialized = 1;
    return 0;
}

// Callback function for encoder pulses
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int a_val = gpioRead(ENCODER_A);
    int b_val = gpioRead(ENCODER_B);

    // Determine the current state based on the encoder values
    if (a_val == 0 && b_val == 0) {
        current_state = STATE_00;
    } else if (a_val == 0 && b_val == 1) {
        current_state = STATE_01;
    } else if (a_val == 1 && b_val == 0) {
        current_state = STATE_10;
    } else {
        current_state = STATE_11;
    }

    // Determine the pulse direction based on the state transitions
    if (current_state != last_state) {
        if (current_state == STATE_01 || current_state == STATE_10) {
            pulse_count++;
        } else {
            pulse_count--;
        }
        last_state = current_state;
    }

    // Calculate the angular position
    angular_position = calculate_angular_position(pulse_count);

    // Log the angular position
    if (log_angular_position(angular_position) != 0) {
        fprintf(stderr, "Error logging angular position\n");
    }
}

// Function to calculate the angular position
double calculate_angular_position(int pulse_count) {
    return (double)pulse_count / PPR * 360.0;
}

// Function to log the angular position to a file
int log_angular_position(double angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state.log_file == NULL) {
        state.log_file = fopen("encoder_log.txt", "a");
        if (state.log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return 1;
        }
    }

    fprintf(state.log_file, "%s, %.2f\n", timestamp, angular_position);
    fflush(state.log_file); // Ensure data is written to the file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;

    // Disable the callback function
    gpioSetAlertFuncEx(ENCODER_A, NULL, NULL);
    gpioSetAlertFuncEx(ENCODER_B, NULL, NULL);

    // Close the log file
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up the callback function for both encoder channels
    gpioSetAlertFuncEx(ENCODER_A, encoder_callback, NULL);
    gpioSetAlertFuncEx(ENCODER_B, encoder_callback, NULL);

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Do other tasks here if needed
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

