#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x38
#define RED_REG 0x00
#define IR_REG 0x02
#define LED_GPIO 17
#define INFRARED_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *red, int *ir);
void log_data(int red, int ir);
void control_led(int ir_value);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    int red;
    int ir;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    int red, ir;
    while (!terminate) {
        if (read_sensor_data(&red, &ir) == 0) {
            log_data(red, ir);
            control_led(ir);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *red, int *ir) {
    char buf[4];
    int result;

    // Read Red data
    result = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Red data: %d\n", result);
        return 1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read IR data
    result = i2cReadI2CBlockData(i2c_handle, IR_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read IR data: %d\n", result);
        return 1;
    }
    *ir = (buf[1] << 8) | buf[0];

    return 0;
}

// Log data to file
void log_data(int red, int ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on IR value
void control_led(int ir_value) {
    if (ir_value > INFRARED_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

