#define GAIN_SELECT_PIN 18

// Define audio threshold
#define AUDIO_THRESHOLD 1

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int set_gain(int gain_level);
int read_audio_input();
int detect_peak(int audio_value);
int log_event(int level);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int audio_input_pin;
    int gain_select_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);
    gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT);

    return 0;
}

// Set gain level (0: 60 dB, 1: 20 dB)
int set_gain(int gain_level) {
    if (gain_level == 0) {
        gpioWrite(GAIN_SELECT_PIN, 0); // 60 dB
    } else if (gain_level == 1) {
        gpioWrite(GAIN_SELECT_PIN, 1); // 20 dB
    } else {
        fprintf(stderr, "Invalid gain level: %d\n", gain_level);
        return 1;
    }
    return 0;
}

// Read audio input from GPIO pin
int read_audio_input() {
    return gpioRead(AUDIO_INPUT_PIN);
}

// Detect peak sound event
int detect_peak(int audio_value) {
    return (audio_value > AUDIO_THRESHOLD) ? 1 : 0;
}

// Log event to file
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s LEVEL:%d\n", timestamp, level);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set gain to 60 dB
    if (set_gain(0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int audio_value = read_audio_input();
        int peak_detected = detect_peak(audio_value);

        if (peak_detected) {
            log_event(1);
        }

        gpioDelay(10000); // 10 milliseconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Audio peak detection stopped.\n");

    return 0;
}

