#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDRESS 0x36
#define FLOW_RATE_SCALE_FACTOR 0.0625 // uL/min per unit
#define LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_rate(int *raw_flow_rate);
float convert_to_ul_min(int raw_flow_rate);
int validate_crc(int data, int crc);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    int raw_flow_rate;
    float flow_rate_ul_min;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    int raw_flow_rate;
    float flow_rate_ul_min;
    while (!terminate) {
        // Read flow rate
        if (read_flow_rate(&raw_flow_rate) == 0) {
            // Convert to uL/min
            flow_rate_ul_min = convert_to_ul_min(raw_flow_rate);

            // Log flow rate
            if (log_flow_rate(flow_rate_ul_min) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }

        // Wait 1000 ms
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int *raw_flow_rate) {
    char buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return 1;
    }

    // Extract raw flow rate and CRC
    int raw_flow = (buffer[0] << 8) | buffer[1];
    int crc = buffer[2];

    // Validate CRC
    if (!validate_crc(raw_flow, crc)) {
        fprintf(stderr, "CRC validation failed\n");
        return 1;
    }

    *raw_flow_rate = raw_flow;
    return 0;
}

// Convert raw flow rate to uL/min
float convert_to_ul_min(int raw_flow_rate) {
    return (float)raw_flow_rate * FLOW_RATE_SCALE_FACTOR;
}

// Validate CRC
int validate_crc(int data, int crc) {
    unsigned char crc_calculated = 0xFF;
    unsigned char data_byte[2];

    data_byte[0] = (data >> 8) & 0xFF;
    data_byte[1] = data & 0xFF;

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_byte[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated = (crc_calculated << 1);
            }
        }
    }

    return (crc_calculated == (unsigned char)crc);
}

// Log flow rate to CSV file
int log_flow_rate(float flow_rate_ul_min) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

