#define LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_rate(int *raw_flow_rate);
float convert_to_ul_min(int raw_flow_rate);
int validate_crc(int data, int crc);
