    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    int raw_flow_rate;
    float flow_rate_ul_min;
    while (!terminate) {
        // Read flow rate
        if (read_flow_rate(&raw_flow_rate) == 0) {
            // Convert to uL/min
            flow_rate_ul_min = convert_to_ul_min(raw_flow_rate);

            // Log flow rate
            if (log_flow_rate(flow_rate_ul_min) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }

        // Wait 1000 ms
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int *raw_flow_rate) {
    char buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return 1;
    }

    // Extract raw flow rate and CRC
    int raw_flow = (buffer[0] << 8) | buffer[1];
    int crc = buffer[2];

    // Validate CRC
    if (!validate_crc(raw_flow, crc)) {
        fprintf(stderr, "CRC validation failed\n");
        return 1;
    }

    *raw_flow_rate = raw_flow;
    return 0;
}

