    unsigned char crc_calculated = 0xFF;
    unsigned char data_byte[2];

    data_byte[0] = (data >> 8) & 0xFF;
    data_byte[1] = data & 0xFF;

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_byte[i];
