#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define TAMPER_THRESHOLD_SEC 5
#define POLL_INTERVAL_MS 100

static volatile int running = 1;
static volatile time_t last_touch_time = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor value
int read_sensor()
{
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to check for tamper event
void check_tamper()
{
    time_t current_time = time(NULL);
    if (current_time == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return;
    }

    if (read_sensor() == 1) {
        // Sensor is HIGH (touched)
        if (difftime(current_time, last_touch_time) >= TAMPER_THRESHOLD_SEC) {
            // Tamper event detected
            printf("INTRUSION DETECTED!\n");
            last_touch_time = current_time; // Reset timer
        }
    } else {
        // Sensor is LOW (released)
        last_touch_time = current_time; // Reset timer
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-down resistor (optional, depending on sensor wiring)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        check_tamper();
        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return EXIT_SUCCESS;
}

