    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        snd_pcm_close(pcm_handle);
        return 1;
    }

    // Open file for writing
    fp = fopen(FILE_NAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        gpioTerminate();
        snd_pcm_close(pcm_handle);
        return 1;
    }

    short buffer[BUFFER_SIZE];

    // Capture and write audio data
    while (running) {
        // Select left channel
        select_channel(0);
        gpioDelay(1000); // Delay for 1ms

        // Capture and write audio
        if (capture_audio(buffer, BUFFER_SIZE) == 0) {
            if (write_to_file(buffer, BUFFER_SIZE) != 0) {
                running = 0; // Stop if file write fails
            }
        } else {
            running = 0; // Stop if capture fails
        }

        // Select right channel
        select_channel(1);
        gpioDelay(1000); // Delay for 1ms

        // Capture and write audio
        if (capture_audio(buffer, BUFFER_SIZE) == 0) {
            if (write_to_file(buffer, BUFFER_SIZE) != 0) {
                running = 0; // Stop if file write fails
            }
        } else {
            running = 0; // Stop if capture fails
        }

    }

    // Cleanup
    fclose(fp);
    snd_pcm_close(pcm_handle);
