#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
FILE *log_file = NULL;
int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void start_fan();
void stop_fan();
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int fan_on;
} ProgramState;

ProgramState state = {0}; // Initialize fan_on to 0

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("System Start");

    // Main loop
    while (1) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) { // Flame detected (LOW signal)
            if (!state.fan_on) {
                start_fan();
                state.fan_on = 1;
                log_event("Flame Detected");
            }
        } else {
            if (state.fan_on) {
                stop_fan();
                state.fan_on = 0;
                log_event("Flame End");
            }
        }

        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
    }

    return 0;
}

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return 1; // Return 1 to avoid fan activation on error
    }
    return value;
}

// Function to start the fan
void start_fan() {
    gpioPWM(FAN_PIN, 128); // 50% duty cycle (128/255)
}

// Function to stop the fan
void stop_fan() {
    gpioPWM(FAN_PIN, 0); // Stop PWM
}

// Function to log events to file
void log_event(const char *event_type) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    log_event("System Shutdown");
    cleanup();
    exit(0);
}

// Cleanup function to reset GPIO and terminate pigpio
void cleanup() {
    if (pigpio_initialized) {
        stop_fan();
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

