#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FRAME_PERIOD_MS 100
#define HEATMAP_SIZE 32768
#define HEADER_SIZE 4144
#define MAGIC_NUMBER 0x1001

// GPIO pins
#define HW_TRIGGER_PIN 23
#define DATA_READY_PIN 24

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t num_chirps;
    uint16_t num_samples;
} config_t;

// Function prototypes
int init_gpio();
int init_spi();
int init_log_file();
void close_resources();
void signal_handler(int signal);
void hw_trigger_callback(int gpio, int level, uint32_t tick);
void data_ready_callback(int gpio, int level, uint32_t tick);
int read_heatmap_data(uint8_t *data);
int write_header(FILE *fp, config_t config);
int write_frame_data(FILE *fp, uint8_t *data, struct timespec ts);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Hardware trigger callback
void hw_trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        printf("Hardware trigger received!\n");
        // Trigger the SPI transfer
        uint8_t *heatmap_data = malloc(HEATMAP_SIZE);
        if (heatmap_data == NULL) {
            perror("Failed to allocate memory for heatmap data");
            close_resources();
            exit(EXIT_FAILURE);
        }

        if (read_heatmap_data(heatmap_data) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            write_frame_data(log_file, heatmap_data, ts);
        } else {
            fprintf(stderr, "Failed to read heatmap data.\n");
        }
        free(heatmap_data);
    }
}

// Data ready interrupt callback
void data_ready_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        printf("Data ready interrupt received!\n");
        // Trigger the SPI transfer
        uint8_t *heatmap_data = malloc(HEATMAP_SIZE);
        if (heatmap_data == NULL) {
            perror("Failed to allocate memory for heatmap data");
            close_resources();
            exit(EXIT_FAILURE);
        }

        if (read_heatmap_data(heatmap_data) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            write_frame_data(log_file, heatmap_data, ts);
        } else {
            fprintf(stderr, "Failed to read heatmap data.\n");
        }
        free(heatmap_data);
    }
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HW_TRIGGER_PIN, PI_INPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(HW_TRIGGER_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN);

    // Set interrupt on rising edge for HW trigger
    gpioSetISRFuncEx(HW_TRIGGER_PIN, RISING_EDGE, 0, hw_trigger_callback, NULL);

    // Set interrupt on rising edge for data ready
    gpioSetISRFuncEx(DATA_READY_PIN, RISING_EDGE, 0, data_ready_callback, NULL);

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize log file
int init_log_file() {
    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    // Write header
    config_t config = {
        .start_frequency = 7700000000, // 77 GHz
        .end_frequency = 7900000000,   // 79 GHz
        .num_chirps = 64,
        .num_samples = 256
    };

    if (write_header(log_file, config) != 0) {
        fprintf(stderr, "Failed to write header to log file.\n");
        fclose(log_file);
        return -1;
    }

    return 0;
}

// Write header to log file
int write_header(FILE *fp, config_t config) {
    uint32_t magic = MAGIC_NUMBER;
    fwrite(&magic, sizeof(uint32_t), 1, fp);

    // Write timestamp (placeholder)
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fwrite(&ts, sizeof(struct timespec), 1, fp);

    // Write configuration
    fwrite(&config, sizeof(config_t), 1, fp);

    return 0;
}

// Write frame data to log file
int write_frame_data(FILE *fp, uint8_t *data, struct timespec ts) {
    // Write timestamp
    fwrite(&ts, sizeof(struct timespec), 1, fp);

    // Write frame number (placeholder)
    uint32_t frame_number = 0; // Replace with actual frame number
    fwrite(&frame_number, sizeof(uint32_t), 1, fp);

    // Write heatmap data
    fwrite(data, sizeof(uint8_t), HEATMAP_SIZE, fp);

    return 0;
}

// Read heatmap data from SPI
int read_heatmap_data(uint8_t *data) {
    char tx_buf[1] = {0x00}; // Dummy data for SPI transfer
    char rx_buf[HEATMAP_SIZE];

    int result = spiXfer(spi_handle, tx_buf, rx_buf, HEATMAP_SIZE);
    if (result != HEATMAP_SIZE) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf, HEATMAP_SIZE);
    return 0;
}

// Close resources
void close_resources() {
    printf("Closing resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    // Initialize log file
    if (init_log_file() != 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    printf("Radar data logging started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(FRAME_PERIOD_MS * 1000); // Delay for frame period
    }

    // Close resources before exiting
    close_resources();

    return EXIT_SUCCESS;
}

