    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return 0;
}

// Function to read the flame sensor state
int read_flame_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the flame event to a file
int log_flame_event(const char *timestamp, const char *state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s - Flame %s\n", timestamp, state);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file.\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file.\n");
        return -1;
    }
    return 0;
}

