        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    int previous_state = -1; // Initialize to an invalid state

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_flame_sensor(GPIO_PIN);

        if (current_state == -1) {
            fprintf(stderr, "Error reading sensor state.\n");
            gpioTerminate();
            return 1;
        }

        if (current_state != previous_state) {
            char timestamp[30];
            if (get_iso8601_timestamp(timestamp) == 0) {
                const char *state = (current_state == 0) ? "Detected" : "Cleared";
                if (log_flame_event(timestamp, state) == 0) {
                    printf("%s - Flame %s\n", timestamp, state);
                } else {
                    fprintf(stderr, "Error logging flame event.\n");
                }
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
            previous_state = current_state;
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

