#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONTINUOUS_MODE 0x1000 // Continuous conversion mode
#define FULL_SCALE_RANGE 0x0800 // Automatic full-scale range
#define CONFIG_VALUE (CONTINUOUS_MODE | FULL_SCALE_RANGE)
#define LUX_SCALE 0.01
#define LUX_OFFSET 0.0
#define SLEEP_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(float *lux);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float lux;
    char timestamp[32];
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        status = i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
        if (status == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error configuring sensor (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }
    fprintf(stderr, "Failed to configure sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(float *lux) {
    int retries = 0;
    int raw_data;

    while (retries < MAX_RETRIES) {
        raw_data = i2cReadWordData(i2c_handle, RESULT_REG);
        if (raw_data >= 0) {
            // Extract exponent and result
            int exponent = (raw_data >> 12) & 0x0F;
            int result = raw_data & 0x0FFF;

            // Calculate lux value
            *lux = result * (0.01 * (1 << exponent));
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", retries + 1, raw_data);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log data to file
int log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f lux\n", timestamp, lux);
    fclose(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    float lux;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(SLEEP_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

