// Define the GPIO pin connected to the flame sensor
#define FLAME_SENSOR_GPIO 17

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an input with a pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read the flame sensor and log the status
    while (!terminate)
    {
        // Read the digital value from the flame sensor
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        // Get the current time
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Format the timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the flame detection status
        if (sensor_value == 0)
        {
            printf("%s Flame Detected: YES\n", timestamp);
        }
        else
        {
            printf("%s Flame Detected: NO\n", timestamp);
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

