#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the TTP226 channels
#define CHANNEL_1 2
#define CHANNEL_2 3
#define CHANNEL_3 4
#define CHANNEL_4 17
#define CHANNEL_5 27
#define CHANNEL_6 22
#define CHANNEL_7 10
#define CHANNEL_8 9

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to read the state of all TTP226 channels
int read_all_channels() {
    int channel_states[8];
    int i;

    // Read each channel and store the state
    for (i = 0; i < 8; i++) {
        channel_states[i] = gpioRead(i + 2); // Start from 2, as CHANNEL_1 is 2
    }

    return channel_states[0] | (channel_states[1] << 1) | (channel_states[2] << 2) |
           (channel_states[3] << 3) | (channel_states[4] << 4) | (channel_states[5] << 5) |
           (channel_states[6] << 6) | (channel_states[7] << 7);
}

// Function to format the data into a CSV string
char* format_csv(int channel_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    static char csv_string[100]; // Static to preserve across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    snprintf(csv_string, sizeof(csv_string), "%s,%d", timestamp, channel_states);
    return csv_string;
}

int main() {
    int i;
    int result;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs
    for (i = 2; i <= 9; i++) {
        result = gpioSetMode(i, PI_INPUT);
        if (result != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input: %d\n", i, result);
            gpioTerminate();
            return 1;
        }
        result = gpioSetPullUpDown(i, PI_PUD_OFF); // Disable pull-up/pull-down resistors
        if (result != 0) {
            fprintf(stderr, "Failed to disable pull-up/down on GPIO %d: %d\n", i, result);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and print sensor data
    while (program_running) {
        int channel_states = read_all_channels();
        char* csv_data = format_csv(channel_states);
        printf("%s\n", csv_data);
        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

