#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"
#define START_MEASUREMENT_CMD 0x3608
#define MEASUREMENT_DELAY_US 100000 // 100 ms
#define SAMPLE_INTERVAL_S 1

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_flow_rate(int i2c_handle);
float validate_flow_rate(int raw_flow);
float calculate_average_flow(float flow1, float flow2);
void set_alarm(int alarm_state);
void log_data(float flow1, float flow2, float avg_flow);
void signal_handler(int signal);
void cleanup();

// CRC-8-Maxim polynomial: 0x31 (x^8 + x^5 + x^4 + x^0)
#define CRC_POLYNOMIAL 0x31

// CRC-8-Maxim initial value: 0x00
#define CRC_INITIAL_VALUE 0x00

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        cleanup();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float flow1 = 0.0, flow2 = 0.0;
        int valid_flow1 = 0, valid_flow2 = 0;

        // Read flow rate from sensor 1
        int raw_flow1 = read_flow_rate(i2c_handle1);
        if (raw_flow1 >= 0) {
            flow1 = validate_flow_rate(raw_flow1);
            valid_flow1 = 1;
        } else {
            fprintf(stderr, "Error reading flow rate from sensor 1\n");
        }

        // Read flow rate from sensor 2
        int raw_flow2 = read_flow_rate(i2c_handle2);
        if (raw_flow2 >= 0) {
            flow2 = validate_flow_rate(raw_flow2);
            valid_flow2 = 1;
        } else {
            fprintf(stderr, "Error reading flow rate from sensor 2\n");
        }

        // Calculate average flow rate
        float avg_flow = calculate_average_flow(flow1, flow2);

        // Set alarm based on average flow rate
        set_alarm(avg_flow < FLOW_THRESHOLD);

        // Log data
        log_data(flow1, flow2, avg_flow);

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }

    // Send start measurement command
    char cmd[2] = {(START_MEASUREMENT_CMD >> 8) & 0xFF, START_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send start measurement command: %d\n", result);
        i2cClose(handle);
        return -1;
    }

    // Wait for measurement delay
    gpioDelay(MEASUREMENT_DELAY_US);

    return handle;
}

// Read flow rate from sensor
int read_flow_rate(int i2c_handle) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read flow rate: %d\n", result);
        return -1;
    }

    // Extract flow rate and CRC
    int raw_flow = (buffer[0] << 8) | buffer[1];
    uint8_t crc = buffer[2];

    // Calculate CRC8 checksum
    uint8_t calculated_crc = crc8((uint8_t *)buffer, 2);

    // Validate CRC
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return raw_flow;
}

// Validate flow rate
float validate_flow_rate(int raw_flow) {
    // Scaling factor from datasheet (example: 0.0625 ml/min per unit)
    float scaling_factor = 0.0625;
    return raw_flow * scaling_factor;
}

// Calculate average flow rate
float calculate_average_flow(float flow1, float flow2) {
    if (flow1 == -1.0 && flow2 == -1.0) {
        return -1.0; // Both sensors failed
    } else if (flow1 == -1.0) {
        return flow2; // Only sensor 2 is valid
    } else if (flow2 == -1.0) {
        return flow1; // Only sensor 1 is valid
    } else {
        return (flow1 + flow2) / 2.0; // Both sensors are valid
    }
}

// Set alarm state
void set_alarm(int alarm_state) {
    gpioWrite(ALARM_GPIO, alarm_state);
}

// Log data to file
void log_data(float flow1, float flow2, float avg_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Avg: %.2f ml/min\n",
            timestamp, flow1, flow2, avg_flow);
    fflush(log_file);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    // Close I2C connections
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Set alarm low
    gpioWrite(ALARM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
}

