#include <string.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 50

// Structure to hold timestamp and detection status
typedef struct {
    time_t timestamp;
    int obstacle_detected;
} DetectionEvent;

// Circular buffer
DetectionEvent buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int obstacle_detected);
void dump_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        int obstacle_detected = read_sensor();
        add_to_buffer(obstacle_detected);

        if (obstacle_detected) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            printf("Obstacle detected at: %s\n", buf);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 50 milliseconds
    }

    // Dump the buffer before exiting
    dump_buffer();

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

// Initializes the pigpio library and configures the GPIO pin.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Reads the sensor value from the GPIO pin.
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Adds a new detection event to the circular buffer.
void add_to_buffer(int obstacle_detected) {
    time_t now = time(NULL);
    buffer[buffer_index].timestamp = now;
    buffer[buffer_index].obstacle_detected = obstacle_detected;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Dumps the contents of the circular buffer to stdout.
void dump_buffer() {
    printf("\n--- Detection Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate correct index
        time_t timestamp = buffer[index].timestamp;
        struct tm *tstruct = localtime(&timestamp);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        printf("[%s] Obstacle: %s\n", buf, buffer[index].obstacle_detected ? "Detected" : "Not Detected");
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for SIGINT (Ctrl+C).
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

