#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define MODE_REGISTER 0x00
#define ACCEL_X_LSB 0x28
#define ACCEL_X_MSB 0x29
#define ACCEL_Y_LSB 0x2A
#define ACCEL_Y_MSB 0x2B
#define ACCEL_Z_LSB 0x2C
#define ACCEL_Z_MSB 0x2D
#define MODE_ACTIVE 0x01
#define MODE_STANDBY 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define TIMEOUT_S 1
#define POLL_INTERVAL_MS 500

// Global variables
int i2c_handle = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int set_sensor_mode(int mode);
int wait_for_sensor_active(int timeout_s);
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
int write_csv_header();
int write_csv_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to set the sensor mode
int set_sensor_mode(int mode) {
    int result = i2cWriteByteData(i2c_handle, MODE_REGISTER, mode);
    if (result < 0) {
        fprintf(stderr, "Error writing to mode register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to wait for the sensor to become active
int wait_for_sensor_active(int timeout_s) {
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < timeout_s) {
        // Add a small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms

        // Check if the sensor is active (mode register should be 0x01)
        int mode = i2cReadByteData(i2c_handle, MODE_REGISTER);
        if (mode < 0) {
            fprintf(stderr, "Error reading mode register: %s\n", strerror(errno));
            return -1;
        }
        if (mode == MODE_ACTIVE) {
            return 0; // Sensor is active
        }
    }
    fprintf(stderr, "Timeout waiting for sensor to become active\n");
    return -1; // Timeout
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to write the CSV header
int write_csv_header() {
    csv_file = fopen("fan_health.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(csv_file, "Timestamp,X,Y,Z\n");
    fflush(csv_file);
    return 0;
}

// Function to write the CSV data
int write_csv_data(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and CSV file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set sensor to active mode
    if (set_sensor_mode(MODE_ACTIVE) != 0) {
        cleanup();
        return 1;
    }

    // Wait for sensor to become active
    if (wait_for_sensor_active(TIMEOUT_S) != 0) {
        cleanup();
        return 1;
    }

    // Write CSV header
    if (write_csv_header() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Write data to CSV file
            if (write_csv_data(x, y, z) != 0) {
                fprintf(stderr, "Error writing data to CSV file\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        // Wait for the next sample
        gpioDelay(POLL_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

