#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up resistors on sensor pins (optional, depending on sensor module)
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR_1_PIN);
    int sensor2_value = gpioRead(SENSOR_2_PIN);

    if (sensor1_value < 0 || sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate error
    }

    return (sensor1_value << 1) | sensor2_value; // Return combined sensor values
}

// Function to control the LED
void control_led(int sensor_values) {
    // Check if either sensor detects an obstacle (LOW signal)
    if ((sensor_values & 0x01) == 0 || (sensor_values & 0x02) == 0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Function to clean up and terminate the pigpio library
void cleanup() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize() != 0) {
        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_values = read_sensors();
        if (sensor_values != -1) {
            control_led(sensor_values);
        }
        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and terminate pigpio
    cleanup();

    return 0;
}

