#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x08
#define CONTINUOUS_MODE 0x00
#define RANGE_50MT 0x00
#define DATA_READY_BIT 0x08

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure the TMAG5170 sensor
int configure_sensor() {
    // Configure for continuous mode, all axes enabled, 50mT range
    uint8_t config_data[2];
    config_data[0] = CONTINUOUS_MODE | (1 << 2) | (1 << 1); // Continuous mode, all axes enabled
    config_data[1] = RANGE_50MT; // 50mT range

    int result = i2cWriteDevice(i2c_handle, (char *)config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[6];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Check data ready bit
    if (!(buffer[0] & DATA_READY_BIT)) {
        fprintf(stderr, "Data not ready yet.\n");
        return -1;
    }

    // Extract X, Y, and Z values
    data->x = (int16_t)((buffer[1] << 8) | buffer[2]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[6]);

    return 0;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Log data to CSV file
int log_data(const char *timestamp, sensor_data_t data) {
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            log_data(timestamp, sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

