#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for the Hall effect sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Mutex to protect the quadrature state
pthread_mutex_t quadrature_mutex = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for signaling main thread
pthread_cond_t signal_condition = PTHREAD_COND_INITIALIZER;

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Quadrature state
typedef enum {
    STATE_A_HIGH_B_HIGH,
    STATE_A_HIGH_B_LOW,
    STATE_A_LOW_B_LOW,
    STATE_A_LOW_B_HIGH
} QuadratureState;

QuadratureState current_state = STATE_A_HIGH_B_HIGH;

// Function prototypes
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_rotation(const char *direction);
void signal_handler(int signal);

// Structure to pass data to the interrupt handler
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} InterruptData;

// Function to handle interrupts
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    InterruptData *data = (InterruptData *)user_data;
    gpio = data->gpio;
    level = data->level;
    tick = data->tick;

    pthread_mutex_lock(&quadrature_mutex);

    QuadratureState previous_state = current_state;

    if (gpio == SENSOR_A_GPIO) {
        if (level == PI_HIGH) {
            if (current_state == STATE_A_LOW_B_LOW || current_state == STATE_A_LOW_B_HIGH) {
                current_state = STATE_A_HIGH_B_LOW;
            } else {
                current_state = STATE_A_HIGH_B_HIGH;
            }
        } else {
            if (current_state == STATE_A_HIGH_B_LOW || current_state == STATE_A_HIGH_B_HIGH) {
                current_state = STATE_A_LOW_B_HIGH;
            } else {
                current_state = STATE_A_LOW_B_LOW;
            }
        }
    } else if (gpio == SENSOR_B_GPIO) {
        if (level == PI_HIGH) {
            if (current_state == STATE_A_LOW_B_LOW || current_state == STATE_A_HIGH_B_LOW) {
                current_state = STATE_A_HIGH_B_HIGH;
            } else {
                current_state = STATE_A_LOW_B_HIGH;
            }
        } else {
            if (current_state == STATE_A_HIGH_B_HIGH || current_state == STATE_A_LOW_B_HIGH) {
                current_state = STATE_A_LOW_B_LOW;
            } else {
                current_state = STATE_A_HIGH_B_LOW;
            }
        }
    }

    // Determine rotation direction
    if (previous_state == STATE_A_HIGH_B_HIGH) {
        if (current_state == STATE_A_LOW_B_LOW) {
            log_rotation("Clockwise");
        } else if (current_state == STATE_A_HIGH_B_LOW) {
            log_rotation("Counter-Clockwise");
        }
    } else if (previous_state == STATE_A_LOW_B_LOW) {
        if (current_state == STATE_A_HIGH_B_HIGH) {
            log_rotation("Clockwise");
        } else if (current_state == STATE_A_LOW_B_HIGH) {
            log_rotation("Counter-Clockwise");
        }
    } else if (previous_state == STATE_A_HIGH_B_LOW) {
        if (current_state == STATE_A_LOW_B_LOW) {
            log_rotation("Clockwise");
        } else if (current_state == STATE_A_HIGH_B_HIGH) {
            log_rotation("Counter-Clockwise");
        }
    } else if (previous_state == STATE_A_LOW_B_HIGH) {
        if (current_state == STATE_A_HIGH_B_LOW) {
            log_rotation("Clockwise");
        } else if (current_state == STATE_A_LOW_B_LOW) {
            log_rotation("Counter-Clockwise");
        }
    }

    pthread_mutex_unlock(&quadrature_mutex);
    pthread_cond_signal(&signal_condition);
}

// Function to log rotation events
void log_rotation(const char *direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    long milliseconds = gpioTick() % 1000;
    char millisecond_str[4];
    snprintf(millisecond_str, sizeof(millisecond_str), ".%03ld", milliseconds);

    fprintf(fp, "%s%s Rotation: %s\n", timestamp, millisecond_str, direction);
    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Set up interrupt handlers
    InterruptData a_data = {SENSOR_A_GPIO, 0, 0};
    InterruptData b_data = {SENSOR_B_GPIO, 0, 0};

    if (gpioSetISRFuncEx(SENSOR_A_GPIO, EITHER_EDGE, 0, interrupt_handler, &a_data) != 0) {
        fprintf(stderr, "Failed to set ISR for SENSOR_A_GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(SENSOR_B_GPIO, EITHER_EDGE, 0, interrupt_handler, &b_data) != 0) {
        fprintf(stderr, "Failed to set ISR for SENSOR_B_GPIO\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        pthread_mutex_lock(&quadrature_mutex);
        pthread_cond_wait(&signal_condition, &quadrature_mutex);
        pthread_mutex_unlock(&quadrature_mutex);
    }

    // Clean up
    gpioSetISRFuncEx(SENSOR_A_GPIO, EITHER_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR_B_GPIO, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&quadrature_mutex);
    pthread_cond_destroy(&signal_condition);

    return 0;
}

