#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set TOUCH_SENSOR_PIN to input");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED_PIN to output");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log events to syslog
void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int main() {
    // Open syslog for logging
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        int touch_state = read_touch_sensor();

        if (touch_state == 1) {
            control_led(1); // Turn LED on
            log_event("Touch detected, LED on");
        } else {
            control_led(0); // Turn LED off
            log_event("Touch released, LED off");
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Cleanup before exiting
    log_event("Turning LED off");
    control_led(0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
    log_event("Program terminated");
    closelog(); // Close syslog

    return 0;
}

