#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define LOG_BUFFER_SIZE 100

// Structure to store log entries
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} log_entry_t;

// Global variables
volatile sig_atomic_t program_running = 1;
int overflow_count = 0;
log_entry_t log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;

// Function prototypes
int read_sensor(int pin);
void update_led(int pin, int state);
void log_event(int sensor_pin, int state);
void signal_handler(int signal);
void cleanup();

// Function to read sensor state with debouncing
int read_sensor(int pin) {
    int i;
    for (i = 0; i < 5; i++) {
        if (gpioRead(pin) != gpioRead(pin)) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
        } else {
            break;
        }
    }
    return gpioRead(pin);
}

// Function to update LED state
void update_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log events to the circular buffer
void log_event(int sensor_pin, int state) {
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].state = state;

    log_index = (log_index + 1) % LOG_BUFFER_SIZE;

    if (log_index == 0) {
        overflow_count++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to turn off LEDs and terminate pigpio
void cleanup() {
    update_led(LED_1_PIN, 0);
    update_led(LED_2_PIN, 0);
    gpioTerminate();
    printf("\npigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_state = read_sensor(SENSOR_1_PIN);
        int sensor2_state = read_sensor(SENSOR_2_PIN);

        update_led(LED_1_PIN, sensor1_state);
        update_led(LED_2_PIN, sensor2_state);

        log_event(SENSOR_1_PIN, sensor1_state);
        log_event(SENSOR_2_PIN, sensor2_state);

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay for debouncing
    }

    // Cleanup and exit
    cleanup();

    // Print log buffer
    printf("\n--- Log Buffer ---\n");
    printf("Overflow Count: %d\n", overflow_count);
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        int index = (log_index + i) % LOG_BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Sensor %d: %d\n", timestamp_str, log_buffer[index].sensor_pin, log_buffer[index].state);
    }

    return 0;
}

