// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define ALARM_DURATION_MS 2000
#define POLL_INTERVAL_MS 100

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int check_threshold(int sensor1_value, int sensor2_value);
void log_event(const char *event_type);
void activate_alarm();
void deactivate_alarm();
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} SensorData;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Enable pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to check if threshold is exceeded
int check_threshold(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 1 || sensor2_value == 1) ? 1 : 0;
}

// Function to log events to file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // YYYY-MM-DDTHH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
    log_event("alarm_activated");
}

// Function to deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
    log_event("alarm_deactivated");
}

// Function to cleanup GPIO and close log file
void cleanup() {
    printf("Cleaning up and exiting...\n");
    deactivate_alarm();

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    cleanup();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    SensorData sensor_data;
    int alarm_active = 0;
    unsigned long alarm_start_time = 0;

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor values
        sensor_data.sensor1_value = read_sensor(SENSOR_1_PIN);
        sensor_data.sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for threshold exceeded
        int threshold_exceeded = check_threshold(sensor_data.sensor1_value, sensor_data.sensor2_value);

        if (threshold_exceeded) {
            if (!alarm_active) {
                alarm_active = 1;
                alarm_start_time = gpioTick();
                log_event("threshold_exceeded");
            }
        } else {
            alarm_active = 0;
            deactivate_alarm();
        }

        // Activate alarm if threshold is exceeded for ALARM_DURATION_MS
        if (alarm_active) {
            if (gpioTick() - alarm_start_time >= ALARM_DURATION_MS * 1000) {
                activate_alarm();
            }
        }

        gpioDelay(POLL_INTERVAL_MS); // Delay for 100ms
    }

    cleanup();

    return 0;
}

