#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define LED_GPIO 17
#define THRESHOLD 500
#define NUM_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

// Sensor Registers
#define X_AXIS_LSB 0x28
#define X_AXIS_MSB 0x29
#define Y_AXIS_LSB 0x2A
#define Y_AXIS_MSB 0x2B
#define Z_AXIS_LSB 0x2C
#define Z_AXIS_MSB 0x2D
#define CTRL1 0x10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(double magnitude);
void control_led(double magnitude);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor() {
    int retries = NUM_RETRIES;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CTRL1, 0x00) == 0) { // Clear power-down bit
            return 0; // Success
        }
        fprintf(stderr, "Error initializing sensor, retrying... (%d retries left)\n", retries - 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    int retries = NUM_RETRIES;
    while (retries > 0) {
        char buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, X_AXIS_LSB, buffer, 6) == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        }
        fprintf(stderr, "Error reading sensor data, retrying... (%d retries left)\n", retries - 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate the Euclidean magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log an event
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s - Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

