#include <pigpio.h>
#include <unistd.h>

// Configuration
#define NUM_SENSORS 5
const int SENSOR_PINS[NUM_SENSORS] = {2, 3, 4, 17, 27};
const char* LOG_FILE = "/var/log/flame_events.log";
const int DEBOUNCE_DELAY_MS = 50;

// Global variables
static volatile sig_atomic_t terminate = 0;
int gpio_handles[NUM_SENSORS];

// Function prototypes
void signal_handler(int sig);
int initialize_gpio();
int read_sensor(int gpio_pin);
int debounce_sensor(int gpio_pin);
int log_event(int sensor_id, int gpio_pin);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpio_handles[i] = gpioSetMode(SENSOR_PINS[i], PI_INPUT);
        if (gpio_handles[i] != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as input", SENSOR_PINS[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read GPIO %d", gpio_pin);
        return -1;
    }
    return value;
}

// Debounce sensor
int debounce_sensor(int gpio_pin) {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    int debounced_value = gpioRead(gpio_pin);
    if (debounced_value < 0) {
        syslog(LOG_ERR, "Failed to debounce GPIO %d", gpio_pin);
        return -1;
    }
    return debounced_value;
}

// Log event to file
int log_event(int sensor_id, int gpio_pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
        return -1;
    }

    // Acquire exclusive lock
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file %s", LOG_FILE);
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);
    fflush(fp);

    // Release lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file %s", LOG_FILE);
    }

    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpioSetMode(SENSOR_PINS[i], PI_INPUT); // Reset to input
    }
    gpioTerminate();
    closelog();
    syslog(LOG_INFO, "Cleanup complete. Exiting.");
}

int main() {
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame monitor...");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    int previous_values[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        previous_values[i] = -1; // Initialize to an invalid state
    }

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int current_value = read_sensor(SENSOR_PINS[i]);
            if (current_value < 0) {
                syslog(LOG_ERR, "Failed to read sensor %d, continuing...", i);
                continue;
            }

            if (previous_values[i] == -1) {
                previous_values[i] = current_value;
                continue; // Skip initial read
            }

            if (previous_values[i] == 1 && current_value == 0) {
                int debounced_value = debounce_sensor(SENSOR_PINS[i]);
                if (debounced_value == 0) {
                    if (log_event(i, SENSOR_PINS[i]) != 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d", i);
                    }
                    syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %d)", i, SENSOR_PINS[i]);
                }
            }
            previous_values[i] = current_value;
        }
        gpioDelay(1000000); // Check every 1 second
    }

    cleanup();
    return 0;
}

