#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define NUM_LINES 8

// Structure to hold GPIO line information
struct gpio_line {
    int pin;
    int index;
    struct gpiod_line *line;
};

// Global variables
struct gpiod_chip *chip;
struct gpio_line lines[NUM_LINES];
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int request_lines(void);
int read_touch_states(void);
void log_touch_event(int index, int pin, int state);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Release GPIO lines
    for (int i = 0; i < NUM_LINES; i++) {
        if (lines[i].line) {
            gpiod_line_release(lines[i].line);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Initialize GPIO chip
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    return 0;
}

// Request GPIO lines
int request_lines(void) {
    int pins[NUM_LINES] = {5, 6, 13, 19, 26, 12, 16, 20};
    for (int i = 0; i < NUM_LINES; i++) {
        lines[i].pin = pins[i];
        lines[i].index = i;
        lines[i].line = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i].line) {
            perror("Error getting GPIO line");
            return -1;
        }

        if (gpiod_line_request_input(lines[i].line, "touch_sensor") < 0) {
            perror("Error requesting GPIO line as input");
            return -1;
        }
    }
    return 0;
}

// Read touch states
int read_touch_states(void) {
    for (int i = 0; i < NUM_LINES; i++) {
        int value = gpiod_line_get_value(lines[i].line);
        if (value < 0) {
            perror("Error reading GPIO line value");
            return -1;
        }

        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO line value: %d\n", value);
            return -1;
        }

        if (value != lines[i].line->value) {
