int init_veml7700(int fd) {
    // Configuration: Integration time = 100ms, Gain = 2
    // ALS_CONF register: IT = 100ms, Gain = 2x, Enable ALS
    int config_value = 0x02D0; //0b0010001101000000
    if (wiringPiI2CWriteReg16(fd, VEML7700_ALS_CONF, config_value) == -1) {
        perror("Failed to write to VEML7700_ALS_CONF");
        return -1;
    }
    return 0;
}

