    if (init_veml7700(i2c_fd) == -1) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Set PWM frequency
    if (set_pwm_frequency(GPIO_PIN, PWM_FREQUENCY) == -1) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        fclose(log_file);
        return 1;
    }

    // Register signal handlers
