#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define CHANNEL_1_PIN 2
#define CHANNEL_2_PIN 3
#define CHANNEL_3_PIN 4
#define CHANNEL_4_PIN 5
#define CHANNEL_5_PIN 6
#define CHANNEL_6_PIN 7
#define CHANNEL_7_PIN 8
#define CHANNEL_8_PIN 9

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold channel states
typedef struct {
    int channel1;
    int channel2;
    int channel3;
    int channel4;
    int channel5;
    int channel6;
    int channel7;
    int channel8;
} ChannelStates;

ChannelStates current_states = {0, 0, 0, 0, 0, 0, 0, 0};
ChannelStates previous_states = {0, 0, 0, 0, 0, 0, 0, 0};

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_touch_event(int channel);
void signal_handler(int signal);
int read_channel(int pin);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set sensor pins as input with pull-down resistors
    gpioSetMode(CHANNEL_1_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_1_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_2_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_2_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_3_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_3_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_4_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_4_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_5_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_5_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_6_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_6_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_7_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_7_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_8_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_8_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

// Function to log touch event
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to read channel state with debouncing
int read_channel(int pin) {
    int i;
    int state = gpioRead(pin);

    for (i = 0; i < DEBOUNCE_TIME; ++i) {
        gpioDelay(1); // Wait 1 ms
        if (gpioRead(pin) != state) {
            return state; // Return the initial state if it changes during debounce
        }
    }

    return state;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
