        current_states.channel4 = read_channel(CHANNEL_4_PIN);
        current_states.channel5 = read_channel(CHANNEL_5_PIN);
        current_states.channel6 = read_channel(CHANNEL_6_PIN);
        current_states.channel7 = read_channel(CHANNEL_7_PIN);
        current_states.channel8 = read_channel(CHANNEL_8_PIN);

        // Check for touch events and log them
        if (current_states.channel1 && !previous_states.channel1) {
            log_touch_event(1);
        }
