#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define FULL_SCALE_RANGE 100.0
#define LUX_SCALE_FACTOR 0.01
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_opt3001();
int read_opt3001(float *lux);
int format_data(float lux, char *buffer);
int write_to_log(const char *data);
void print_to_console(const char *data);
void signal_handler(int signal);
void cleanup();

// Structure for OPT3001 configuration
typedef struct {
    uint16_t config_value;
} opt3001_config_t;

// Configuration options
const opt3001_config_t CONTINUOUS_MODE_100MS = {0xCC10}; // Continuous mode, 100ms conversion time

int main() {
    float lux;
    char data_buffer[50];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (config_opt3001() != 0) {
        fprintf(stderr, "OPT3001 configuration failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read OPT3001 data
        if (read_opt3001(&lux) == 0) {
            // Format data
            if (format_data(lux, data_buffer) == 0) {
                // Write to log file
                if (write_to_log(data_buffer) != 0) {
                    fprintf(stderr, "Failed to write to log file\n");
                }

                // Print to console
                print_to_console(data_buffer);
            } else {
                fprintf(stderr, "Failed to format data\n");
            }
        } else {
            fprintf(stderr, "Failed to read OPT3001 data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure OPT3001
int config_opt3001() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = (CONTINUOUS_MODE_100MS.config_value >> 8) & 0xFF; // MSB
    buf[2] = CONTINUOUS_MODE_100MS.config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to OPT3001 config register: %d\n", result);
        return 1;
    }
    gpioDelay(100); // Wait 100ms after writing config
    return 0;
}

// Read OPT3001 data
int read_opt3001(float *lux) {
    char buf[1];
    char result_buf[2];
    uint16_t raw_result;

    // Write the result register address
    buf[0] = RESULT_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to OPT3001 result register\n");
        return 1;
    }

    // Read the result register
    if (i2cReadDevice(i2c_handle, result_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from OPT3001 result register\n");
        return 1;
    }

    // Byte swap the result
    raw_result = (result_buf[0] << 8) | result_buf[1];

    // Extract exponent and result
    int exponent = (raw_result >> 12) & 0x0F;
    int result = raw_result & 0x0FFF;

    // Calculate lux value
    *lux = result * (LUX_SCALE_FACTOR * (1 << exponent));

    return 0;
}

// Format data
int format_data(float lux, char *buffer) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 50, "%Y-%m-%d %H:%M:%S, ", timeinfo);
    char lux_str[10];
    snprintf(lux_str, 10, "%.2f", lux);
    strcat(buffer, lux_str);

    return 0;
}

// Write to log file
int write_to_log(const char *data) {
    if (fprintf(log_file, "%s\n", data) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return 1;
    }
    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

// Print to console
void print_to_console(const char *data) {
    printf("%s\n", data);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

