#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17

// Define constants
#define POLL_INTERVAL_MS 500
#define ALERT_DURATION_S 1

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int open_log_file();
int read_flame_sensor();
int set_alert_pin(int state);
int log_event(int flame_detected);
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int flame_sensor_pin;
    int alert_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    return 0;
}

// Open the log file in append mode
int open_log_file() {
    log_file = fopen("fire_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return value;
}

// Set the alert pin to a given state
int set_alert_pin(int state) {
    gpioWrite(ALERT_PIN, state);
    return 0;
}

// Log an event to the log file
int log_event(int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (flame_detected == 0) {
        fprintf(log_file, "%s - Flame detected\n", timestamp);
        fflush(log_file); // Ensure immediate write to file
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_PIN, 0); // Set alert pin to LOW
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    cleanup();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == 0) {
            set_alert_pin(1); // Set alert pin HIGH
            log_event(flame_detected);
            gpioDelay(ALERT_DURATION_S * 1000); // Wait for 1 second
            set_alert_pin(0); // Set alert pin LOW
        } else if (flame_detected < 0) {
            // Error reading sensor, but continue running
            fprintf(stderr, "Error reading sensor, continuing...\n");
        }

        gpioDelay(POLL_INTERVAL_MS); // Wait 500ms
    }

    return 0;
}

