#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x36
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_rate(int16_t *flow_rate);
uint8_t calculate_crc(const uint8_t *data, size_t length);
float convert_flow_rate(int16_t raw_flow_rate);
const char *get_status_string(float flow_rate);
int log_data(float flow_rate, uint8_t raw_flags, const char *status);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    float flow_rate_min;
    float flow_rate_max;
    uint8_t crc_polynomial;
    uint8_t crc_initial_value;
    int sample_interval_sec;
    const char *log_file;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .i2c_address = I2C_ADDRESS,
    .flow_rate_min = FLOW_RATE_MIN,
    .flow_rate_max = FLOW_RATE_MAX,
    .crc_polynomial = CRC_POLYNOMIAL,
    .crc_initial_value = CRC_INITIAL_VALUE,
    .sample_interval_sec = SAMPLE_INTERVAL_SEC,
    .log_file = LOG_FILE
};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int16_t raw_flow_rate;
        uint8_t raw_flags;
        float flow_rate;
        const char *status;

        // Read flow rate
        if (read_flow_rate(&raw_flow_rate) == 0) {
            // Convert flow rate
            flow_rate = convert_flow_rate(raw_flow_rate);

            // Get status string
            status = get_status_string(flow_rate);

            // Log data
            if (log_data(flow_rate, raw_flags, status) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            // Log error
            if (log_data(-1.0, 0, "ERROR") != 0) {
                fprintf(stderr, "Failed to log error\n");
            }

            // Attempt recovery (re-initialize I2C)
            fprintf(stderr, "Attempting to re-initialize I2C...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialisation failed\n");
                terminate = 1; // Exit loop if recovery fails
            }
        }

        // Wait for the next sample
        sleep(config.sample_interval_sec);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int16_t *flow_rate) {
    char cmd[1] = {0x00}; // Command to trigger a single measurement
    char buffer[3];
    int result;

    // Send command to trigger measurement
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    // Wait for at least 2 ms
    gpioDelay(2000); // pigpio uses microseconds

    // Read 3 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    // Extract flow rate and CRC
    *flow_rate = (int16_t)((buffer[0] << 8) | buffer[1]);
    uint8_t crc = buffer[2];

    // Calculate CRC
    uint8_t calculated_crc = calculate_crc((uint8_t *)buffer, 2);

    // Validate CRC
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC validation failed: calculated=0x%02X, received=0x%02X\n", calculated_crc, crc);
        return -1;
    }

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t length) {
    uint8_t crc = config.crc_initial_value;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ config.crc_polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw flow rate to ml/min
float convert_flow_rate(int16_t raw_flow_rate) {
    // Scaling factor from the datasheet (example, adjust as needed)
    float scaling_factor = 0.01; // Example: 0.01 ml/min per unit
    return (float)raw_flow_rate * scaling_factor;
}

// Get status string based on flow rate
const char *get_status_string(float flow_rate) {
    if (flow_rate < config.flow_rate_min || flow_rate > config.flow_rate_max) {
        return "INVALID";
    } else {
        return "OK";
    }
}

// Log data to file
int log_data(float flow_rate, uint8_t raw_flags, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

