#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip path
#define GPIO_CHIP_PATH "/dev/gpiochip4"

// Define log file path
#define LOG_FILE_PATH "touch_log.txt"

// Global variables
int gpio_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int log_event(const char *timestamp, int led_state);
void signal_handler(int signal);

// Helper function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int len;

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(gpio_fd, buffer, len) != len) {
        perror("Failed to export GPIO pin");
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int len;

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(gpio_fd, buffer, len) != len) {
        perror("Failed to unexport GPIO pin");
        return -1;
    }
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_CHIP_PATH "/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("Failed to set GPIO direction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), GPIO_CHIP_PATH "/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file for reading");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        perror("Failed to read GPIO value");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int gpio_write(int pin, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), GPIO_CHIP_PATH "/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file for writing");
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) != strlen(value_str)) {
        perror("Failed to write GPIO value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log an event to the log file
int log_event(const char *timestamp, int led_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, LED State: %s\n", timestamp, led_state ? "ON" : "OFF");
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int touch_value;
    int led_state = 0; // Initial LED state is OFF
    char *timestamp;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(TOUCH_SENSOR_PIN) < 0 || gpio_export(LED_PIN) < 0) {
        close(gpio_fd);
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(TOUCH_SENSOR_PIN, "in") < 0 || gpio_set_direction(LED_PIN, "out") < 0) {
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        close(gpio_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        close(gpio_fd);
        return 1;
    }

    printf("Touch-activated lamp started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        touch_value = gpio_read(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor value.\n");
            break; // Exit loop on error
        }

        if (touch_value == 1) {
            // Touch detected
            led_state = !led_state; // Toggle LED state
            if (gpio_write(LED_PIN, led_state) < 0) {
                fprintf(stderr, "Error writing to LED pin.\n");
                break; // Exit loop on error
            }

            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (log_event(timestamp, led_state) < 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Failed to get timestamp.\n");
            }

            // Debounce delay (100ms)
            struct timespec delay;
            delay.tv_sec = 0;
            delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
            nanosleep(&delay, NULL);
        }

        // Polling delay (1 second)
        struct timespec delay;
        delay.tv_sec = 1;
        delay.tv_nsec = 0;
        nanosleep(&delay, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_unexport(TOUCH_SENSOR_PIN);
    gpio_unexport(LED_PIN);
    close(gpio_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

