#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_DELAY_MS 200

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the timestamp to the file
int log_timestamp(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: Failed to write to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to toggle the LED state
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_level);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(TOUCH_PIN);
    int debouncing = 0;

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(TOUCH_PIN);

        if (current_state == 0 && last_state == 1) { // Rising edge detected
            if (!debouncing) {
                debouncing = 1;
                toggle_led();

                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_timestamp(timestamp) != 0) {
                        fprintf(stderr, "Warning: Failed to log timestamp.\n");
                    }
                    free(timestamp); // Free the allocated memory
                }

                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
                debouncing = 0;
            }
        }

        last_state = current_state;
        gpioDelay(10000); // Poll every 10 ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Touch sensor logging stopped.\n");
    return 0;
}

