#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HB_RATE_REG 0x24
#define CONFIG_REG 0x02
#define CONFIG_VALUE 0x03
#define BPM_MIN 30
#define BPM_MAX 220
#define MOVING_AVG_SIZE 5
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int bpm;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *raw_data);
int validate_data(int raw_data);
int apply_moving_average(int new_data, int *buffer, int *index, int *sum);
int write_to_file(int bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize sensor
int initialize_sensor() {
    int part_id, hw_rev;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (part_id < 0) {
            fprintf(stderr, "Error reading PART_ID_REG: %d\n", part_id);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
        if (hw_rev < 0) {
            fprintf(stderr, "Error reading HW_REV_REG: %d\n", hw_rev);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        if (part_id == 0x82 && hw_rev == 0x00) {
            printf("Si1182 sensor found (PART_ID: 0x%02X, HW_REV: 0x%02X)\n", part_id, hw_rev);
            return 0; // Success
        } else {
            fprintf(stderr, "Sensor not found or incorrect (PART_ID: 0x%02X, HW_REV: 0x%02X)\n", part_id, hw_rev);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read sensor data
int read_sensor_data(int *raw_data) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, HB_RATE_REG);
        if (result >= 0) {
            *raw_data = result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading HB_RATE_REG: %d\n", result);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Validate data
int validate_data(int raw_data) {
    if (raw_data >= BPM_MIN && raw_data <= BPM_MAX) {
        return 0; // Valid
    } else {
        fprintf(stderr, "Invalid BPM value: %d\n", raw_data);
        return -1; // Invalid
    }
}

// Apply moving average filter
int apply_moving_average(int new_data, int *buffer, int *index, int *sum) {
    // Subtract the oldest value from the sum
    *sum -= buffer[*index];

    // Add the new value to the sum
    *sum += new_data;

