#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure the buffer is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
void log_message(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", get_timestamp(), message);
        fflush(log_file); // Ensure the message is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle the SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with a pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to monitor the flame sensor
    while (running) {
        gpio_status = gpioRead(FLAME_SENSOR_GPIO);

        if (gpio_status == 0) { // Flame detected (LOW signal)
            log_message("FLAME DETECTED");
            gpioDelay(100); // Debounce delay
        }

        gpioDelay(100); // Polling interval
    }

    // Cleanup and exit
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

