#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for touch sensors
#define SENSOR_1 5
#define SENSOR_2 6
#define SENSOR_3 7
#define SENSOR_4 8
#define SENSOR_5 9
#define SENSOR_6 10
#define SENSOR_7 11
#define SENSOR_8 12

// Define GPIO pins for output bits
#define OUTPUT_1 17
#define OUTPUT_2 18
#define OUTPUT_3 19
#define OUTPUT_4 20
#define OUTPUT_5 21
#define OUTPUT_6 22
#define OUTPUT_7 23
#define OUTPUT_8 24

// Define the number of output bits
#define NUM_OUTPUT_BITS 8

// Define the counter increment delay (in milliseconds)
#define COUNTER_DELAY 10

// Define the stabilization delay (in milliseconds)
#define STABILIZATION_DELAY 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int update_output(int counter);
int log_event(int channel, int counter);
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int sensor_pins[8];
    int output_pins[8];
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set sensor pins as inputs with pull-down resistors
    int sensor_pins[] = {SENSOR_1, SENSOR_2, SENSOR_3, SENSOR_4, SENSOR_5, SENSOR_6, SENSOR_7, SENSOR_8};
    for (int i = 0; i < 8; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    // Set output pins as outputs
    int output_pins[] = {OUTPUT_1, OUTPUT_2, OUTPUT_3, OUTPUT_4, OUTPUT_5, OUTPUT_6, OUTPUT_7, OUTPUT_8};
    for (int i = 0; i < 8; i++) {
        gpioSetMode(output_pins[i], PI_OUTPUT);
        gpioWrite(output_pins[i], 0); // Initialize all outputs to LOW
    }

    return 0;
}

// Function to read the state of a sensor pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to update the output pins based on the counter value
int update_output(int counter) {
    int output_pins[] = {OUTPUT_1, OUTPUT_2, OUTPUT_3, OUTPUT_4, OUTPUT_5, OUTPUT_6, OUTPUT_7, OUTPUT_8};

    for (int i = 0; i < NUM_OUTPUT_BITS; i++) {
        int bit = (counter >> (NUM_OUTPUT_BITS - 1 - i)) & 1; // Extract the bit from the counter
        if (gpioWrite(output_pins[i], bit) != 0) {
            fprintf(stderr, "Error writing to output pin %d: %s\n", output_pins[i], strerror(errno));
            return -1; // Indicate an error
        }
    }
    return 0;
}

// Function to log the event to a file
int log_event(int channel, int counter) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    return 0;
}

// Function to clean up GPIO resources
void cleanup() {
    printf("Cleaning up and exiting...\n");

    // Reset all output pins to LOW
    int output_pins[] = {OUTPUT_1, OUTPUT_2, OUTPUT_3, OUTPUT_4, OUTPUT_5, OUTPUT_6, OUTPUT_7, OUTPUT_8};
    for (int i = 0; i < NUM_OUTPUT_BITS; i++) {
        gpioWrite(output_pins[i], 0);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    cleanup();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        // Continue without logging to file, but print to stdout
    }

    // Stabilization delay
    gpioDelay(STABILIZATION_DELAY * 1000); // Convert milliseconds to microseconds

    int counter = 0;
    int last_sensor_states[8] = {0, 0, 0, 0, 0, 0, 0, 0}; // Store the last known state of each sensor

    while (running) {
        int current_sensor_states[8];
        int any_sensor_changed = 0;

        // Read sensor states
        int sensor_pins[] = {SENSOR_1, SENSOR_2, SENSOR_3, SENSOR_4, SENSOR_5, SENSOR_6, SENSOR_7, SENSOR_8};
        for (int i = 0; i < 8; i++) {
            current_sensor_states[i] = read_sensor(sensor_pins[i]);
            if (current_sensor_states[i] < 0) {
                // Handle sensor read error, but continue with other sensors
                current_sensor_states[i] = last_sensor_states[i]; // Use the last known state
            } else {
                any_sensor_changed |= (current_sensor_states[i] != last_sensor_states[i]);
                last_sensor_states[i] = current_sensor_states[i];
            }
        }

        // Increment counter on rising edge
        if (any_sensor_changed) {
            counter++;
            if (counter > 255) {
                counter = 0;
            }

            // Update output pins
            if (update_output(counter) != 0) {
                fprintf(stderr, "Error updating output pins.\n");
            }

            // Log event
            for (int i = 0; i < 8; i++) {
                if (current_sensor_states[i] == 1) {
                    if (log_event(i + 1, counter) != 0) {
                        fprintf(stderr, "Error logging event for channel %d.\n", i + 1);
                    }
                    printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                }
            }
        }

        // Delay before next iteration
        gpioDelay(COUNTER_DELAY * 1000); // Convert milliseconds to microseconds
    }

    cleanup();

    return 0;
}

