    printf("Cleaning up and exiting...\n");

    // Reset all output pins to LOW
    int output_pins[] = {OUTPUT_1, OUTPUT_2, OUTPUT_3, OUTPUT_4, OUTPUT_5, OUTPUT_6, OUTPUT_7, OUTPUT_8};
    for (int i = 0; i < NUM_OUTPUT_BITS; i++) {
        gpioWrite(output_pins[i], 0);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    cleanup();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        // Continue without logging to file, but print to stdout
    }

    // Stabilization delay
    gpioDelay(STABILIZATION_DELAY * 1000); // Convert milliseconds to microseconds

    int counter = 0;
    int last_sensor_states[8] = {0, 0, 0, 0, 0, 0, 0, 0}; // Store the last known state of each sensor

    while (running) {
        int current_sensor_states[8];
        int any_sensor_changed = 0;

        // Read sensor states
        int sensor_pins[] = {SENSOR_1, SENSOR_2, SENSOR_3, SENSOR_4, SENSOR_5, SENSOR_6, SENSOR_7, SENSOR_8};
        for (int i = 0; i < 8; i++) {
            current_sensor_states[i] = read_sensor(sensor_pins[i]);
            if (current_sensor_states[i] < 0) {
                // Handle sensor read error, but continue with other sensors
                current_sensor_states[i] = last_sensor_states[i]; // Use the last known state
            } else {
                any_sensor_changed |= (current_sensor_states[i] != last_sensor_states[i]);
                last_sensor_states[i] = current_sensor_states[i];
            }
        }

        // Increment counter on rising edge
        if (any_sensor_changed) {
            counter++;
            if (counter > 255) {
                counter = 0;
            }

            // Update output pins
            if (update_output(counter) != 0) {
                fprintf(stderr, "Error updating output pins.\n");
            }

            // Log event
            for (int i = 0; i < 8; i++) {
                if (current_sensor_states[i] == 1) {
                    if (log_event(i + 1, counter) != 0) {
                        fprintf(stderr, "Error logging event for channel %d.\n", i + 1);
                    }
                    printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                }
            }
        }

        // Delay before next iteration
        gpioDelay(COUNTER_DELAY * 1000); // Convert milliseconds to microseconds
    }

    cleanup();

    return 0;
}

