    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("tracking_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(log_file);
    }

    // Main loop
    while (running) {
        SensorData data;

        // Read sensor values
        data.sensor1 = read_sensor(SENSOR1_PIN);
        data.sensor2 = read_sensor(SENSOR2_PIN);
        data.sensor3 = read_sensor(SENSOR3_PIN);
        data.sensor4 = read_sensor(SENSOR4_PIN);

        // Log the data if all sensor reads were successful
        if (data.sensor1 != -1 && data.sensor2 != -1 && data.sensor3 != -1 && data.sensor4 != -1) {
            if (log_data(log_file, data.sensor1, data.sensor2, data.sensor3, data.sensor4) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log\n");
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Close the log file and terminate GPIO
    fclose(log_file);
    gpioTerminate();

    return 0;
}

