#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define DEBOUNCE_MS 50
#define POLL_MS 100

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure timestamp is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
void log_event(int gpio) {
    char* timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, gpio);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle GPIO interrupt for sensor 1
void sensor1_interrupt(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_MS * 1000) { // Convert ms to microseconds
        if (level == 0) { // Assuming active-low tilt sensor
            log_event(1);
        }
        last_tick = current_tick;
    }
}

// Function to handle GPIO interrupt for sensor 2
void sensor2_interrupt(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_MS * 1000) { // Convert ms to microseconds
        if (level == 0) { // Assuming active-low tilt sensor
            log_event(2);
        }
        last_tick = current_tick;
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(GPIO_17, PI_INPUT);
    gpioSetPullUpDown(GPIO_17, PI_PUD_UP);
    gpioSetMode(GPIO_18, PI_INPUT);
    gpioSetPullUpDown(GPIO_18, PI_PUD_UP);

    // Set up interrupt handlers for both sensors
    if (gpioSetAlertFuncEx(GPIO_17, sensor1_interrupt, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for GPIO %d\n", GPIO_17);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(GPIO_18, sensor2_interrupt, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for GPIO %d\n", GPIO_18);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(POLL_MS * 1000); // Convert ms to microseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

