#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Define constants
#define POLL_INTERVAL_MS 100
#define LOG_FILE_NAME "obstacle_log.csv"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int determine_led_state(int sensor1_value, int sensor2_value);
int log_data(int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to determine LED state
int determine_led_state(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

// Function to log data to file
int log_data(int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Exiting.\n");
            break;
        }

        // Determine LED state
        int led_state = determine_led_state(sensor1_value, sensor2_value);

        // Set LED state
        gpioWrite(LED_PIN, led_state);

        // Log data
        if (log_data(sensor1_value, sensor2_value, led_state) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for the next poll interval
        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Obstacle avoidance system stopped.\n");

    return 0;
}

