#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_ALS_VIS_LSB 0x22
#define SI1175_REG_ALS_VIS_MSB 0x23
#define SI1175_REG_PART_ID     0x00
#define SI1175_REG_RESET       0x07

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the Si1175 sensor
int init_si1175() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1175_REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1175\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify Part ID
    int part_id = i2cReadByteData(i2c_handle, SI1175_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read Part ID\n");
        return -1;
    }
    if (part_id != 0x75) {
        fprintf(stderr, "Error: Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Si1175 sensor initialized successfully.\n");
    return 0;
}

// Function to read the ALS data from the Si1175
int read_als_data(uint16_t *als_data) {
    int lsb, msb;

    lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error: Failed to read ALS LSB\n");
        return -1;
    }

    msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error: Failed to read ALS MSB\n");
        return -1;
    }

    *als_data = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1175 sensor
    if (init_si1175() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t als_data;

        if (read_als_data(&als_data) == 0) {
            printf("ALS Data: %u\n", als_data);
        } else {
            fprintf(stderr, "Error: Failed to read ALS data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

