#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for each touch sensor channel
#define TP1_GPIO 5
#define TP2_GPIO 6
#define TP3_GPIO 13
#define TP4_GPIO 19
#define TP5_GPIO 26
#define TP6_GPIO 12
#define TP7_GPIO 16
#define TP8_GPIO 20

// Structure to hold the state of the touch sensor channels
typedef struct {
    int ch1;
    int ch2;
    int ch3;
    int ch4;
    int ch5;
    int ch6;
    int ch7;
    int ch8;
} TouchState;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of a single touch sensor channel
int read_touch_channel(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in seconds with millisecond precision
double get_timestamp() {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1.0; // Indicate an error
    }
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
}

// Function to format the touch sensor data into a string
char* format_touch_data(TouchState state) {
    static char buffer[100]; // Static buffer to hold the formatted string
    snprintf(buffer, sizeof(buffer), "[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
             get_timestamp(),
             state.ch1, state.ch2, state.ch3, state.ch4, state.ch5, state.ch6, state.ch7, state.ch8);
    return buffer;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(TP1_GPIO, PI_INPUT);
    gpioSetMode(TP2_GPIO, PI_INPUT);
    gpioSetMode(TP3_GPIO, PI_INPUT);
    gpioSetMode(TP4_GPIO, PI_INPUT);
    gpioSetMode(TP5_GPIO, PI_INPUT);
    gpioSetMode(TP6_GPIO, PI_INPUT);
    gpioSetMode(TP7_GPIO, PI_INPUT);
    gpioSetMode(TP8_GPIO, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to poll touch sensor data
    while (program_running) {
        TouchState touch_state;

        // Read the state of each touch sensor channel
        touch_state.ch1 = read_touch_channel(TP1_GPIO);
        touch_state.ch2 = read_touch_channel(TP2_GPIO);
        touch_state.ch3 = read_touch_channel(TP3_GPIO);
