#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE      255

// Define hue range for interpolation
#define MIN_HUE 0
#define MAX_HUE 360

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

// Function to interpolate between two hues
void interpolate_hue(int start_hue, int end_hue, int steps, int delay_ms, int (*set_color)(int, int, int))
{
    float hue_diff = (float)(end_hue - start_hue);
    float step_size = hue_diff / steps;

    for (int i = 0; i < steps; i++)
    {
        int current_hue = start_hue + (int)(i * step_size);

        // Map hue to RGB color values
        float h = (float)current_hue / 360.0;
        float r = 0, g = 0, b = 0;

        if (h < 1.0 / 6.0) {
            r = 1; g = h * 6; b = 0;
        } else if (h < 2.0 / 6.0) {
            r = (2 - h) * 6; g = 1; b = 0;
        } else if (h < 3.0 / 6.0) {
            r = 0; g = 1; b = h * 6 - 2;
        } else if (h < 4.0 / 6.0) {
            r = 0; g = (4 - h) * 6; b = 1;
        } else if (h < 5.0 / 6.0) {
            r = h * 6 - 4; g = 0; b = 1;
        } else {
            r = 1; g = 0; b = (6 - h) * 6;
        }

        r = r * 255;
        g = g * 255;
        b = b * 255;

        // Clamp values to 0-255 range
        int red   = (int)r;
        int green = (int)g;
        int blue  = (int)b;

        if (red   > 255) red   = 255;
        if (green > 255) green = 255;
        if (blue  > 255) blue  = 255;

        if (red   < 0) red   = 0;
        if (green < 0) green = 0;
        if (blue  < 0) blue  = 0;

        // Set the LED color
        set_color(red, green, blue);

        // Delay for the specified interval
        gpioDelay(delay_ms * 1000); // pigpioDelay takes microseconds
    }
}

int main()
{
    // Initialize syslog
    openlog("rgb_led_control", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with entropy from /dev/urandom
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        perror("fopen");
        closelog();
        return 1;
    }
    unsigned int seed;
    if (fread(&seed, sizeof(unsigned int), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read random seed from /dev/urandom");
        perror("fread");
        fclose(urandom);
        closelog();
        return 1;
    }
    fclose(urandom);
    srand(seed);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY);
    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    // Register signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "RGB LED control program started");

    // Main loop
    while (!terminate)
    {
        // Generate random hues for the start and end points of the interpolation
        int start_hue = rand() % (MAX_HUE - MIN_HUE + 1) + MIN_HUE;
        int end_hue   = rand() % (MAX_HUE - MIN_HUE + 1) + MIN_HUE;

        // Interpolate between the two hues
        interpolate_hue(start_hue, end_hue, 50, 50, set_led_color);
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    // Close syslog
    closelog();

    syslog(LOG_INFO, "RGB LED control program terminated");

    return 0;
}

