#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_ID              (0x12)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_PON             (0x01)
#define TCS34725_AEN             (0x02)
#define TCS34725_AIEN            (0x10)

// Integration Time Values
#define TCS34725_INTEGRATIONTIME_2_4MS  (0xFF)   // 2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS   (0xF6)   // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_101MS  (0xD5)   // 101ms - 42 cycles   - Max Count: 43008
#define TCS34725_INTEGRATIONTIME_154MS  (0xC0)   // 154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_501MS  (0x00)   // 501ms - 256 cycles  - Max Count: 65535

// Gain Values
#define TCS34725_GAIN_1X          (0x00)
#define TCS34725_GAIN_4X          (0x01)
#define TCS34725_GAIN_16X         (0x02)
#define TCS34725_GAIN_60X         (0x03)

// Global Variables
static int i2c_fd = -1;
static int gpio_led = -1;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int tcs34725_init(int fd);
int tcs34725_read_raw_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c);
void tcs34725_calculate_color_values(uint16_t r, uint16_t g, uint16_t b, uint16_t c, float *red, float *green, float *blue);
void control_led(int gpio, int state);
void signal_handler(int signal);

// I2C Read Function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    int result;
    uint8_t buf[1];

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *value = buf[0];
    return 0;
}

// I2C Write Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];

    buf[0] = reg | TCS34725_COMMAND_BIT;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// TCS34725 Initialization Function
int tcs34725_init(int fd) {
    uint8_t id;

    // Check device ID
    if (i2c_read_reg(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and RGBC
    if (i2c_write_reg(fd, TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) != 0) {
        fprintf(stderr, "Error enabling power and RGBC\n");
        return -1;
    }

    // Set integration time
    if (i2c_write_reg(fd, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_154MS) != 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain
    if (i2c_write_reg(fd, TCS34725_CONTROL, TCS34725_GAIN_1X) != 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    return 0;
}

// TCS34725 Read Raw Data Function
int tcs34725_read_raw_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t data[8];
    int result;

    // Read all color data registers in one go
    if (write(fd, (uint8_t[]){TCS34725_CDATA | TCS34725_COMMAND_BIT}, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, 8) != 8) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *c = (data[1] << 8) | data[0];
    *r = (data[3] << 8) | data[2];
    *g = (data[5] << 8) | data[4];
    *b = (data[7] << 8) | data[6];

    return 0;
}

// TCS34725 Calculate Color Values Function
void tcs34725_calculate_color_values(uint16_t r, uint16_t g, uint16_t b, uint16_t c, float *red, float *green, float *blue) {
    float clear = (float)c;

    *red = (float)r / clear;
    *green = (float)g / clear;
    *blue = (float)b / clear;
}

// GPIO Control Function
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    uint16_t r, g, b, c;
    float red, green, blue;
    int retry_count = 0;
    const int max_retries = 3;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpio_led = 17;
    gpioSetMode(gpio_led, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw color data
        if (tcs34725_read_raw_data(i2c_fd, &r, &g, &b, &c) == 0) {
            // Calculate calibrated color values
            tcs34725_calculate_color_values(r, g, b, c, &red, &green, &blue);

            // Print color values
            printf("R: %.2f, G: %.2f, B: %.2f, C: %d\n", red, green, blue, c);

            // Control LED based on red value
            if (red > 200.0) {
                control_led(gpio_led, 1); // Turn LED on
            } else {
                control_led(gpio_led, 0); // Turn LED off
            }

            retry_count = 0; // Reset retry count on success
        } else {
            fprintf(stderr, "Error reading color data, retrying...\n");
            retry_count++;

            if (retry_count > max_retries) {
                fprintf(stderr, "Max retries reached, attempting sensor re-initialization...\n");
                close(i2c_fd);
                i2c_fd = open("/dev/i2c-1", O_RDWR);
                if (i2c_fd < 0) {
                    fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
                    terminate = 1; // Exit if I2C fails after re-init
                    break;
                }
                if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                    fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
                    terminate = 1;
                    break;
                }
                if (tcs34725_init(i2c_fd) != 0) {
                    fprintf(stderr, "TCS34725 re-initialization failed\n");
                    terminate = 1;
                    break;
                }
                retry_count = 0; // Reset retry count after re-init
            }
        }

        usleep(200000); // Wait 200ms
    }

    // Cleanup
    close(i2c_fd);
    control_led(gpio_led, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

