// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_PIN 18 // BCM numbering
#define NUM_LEDS 10
#define PWM_FREQUENCY 800000 // 800 kHz
#define PWM_RANGE 4096
#define WS2812B_T0H 0.35 // 0.35us
#define WS2812B_T0L 0.8  // 0.8us
#define WS2812B_T1H 0.7  // 0.7us
#define WS2812B_T1L 0.6  // 0.6us
#define WS2812B_RESET_TIME 50 // us

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_bh1750();
float map_lux_to_brightness(float lux);
void set_led_color(int led_index, float brightness);
void send_led_data();
void cleanup();
void signal_handler(int signal);

// WS2812B timing functions
void ws2812b_set_bit(int bit);
void ws2812b_send_byte(uint8_t byte);
void ws2812b_send_color(uint8_t red, uint8_t green, uint8_t blue);

// WS2812B timing functions implementation
void ws2812b_set_bit(int bit) {
    if (bit) {
        gpioWaveAddGeneric(1, (gpioPulse_t[]){{.gpioOn=1<<GPIO_PIN, .gpioOff=0, .usDelay=WS2812B_T1H}});
        gpioWaveAddGeneric(1, (gpioPulse_t[]){{.gpioOn=0, .gpioOff=1<<GPIO_PIN, .usDelay=WS2812B_T1L}});
    } else {
        gpioWaveAddGeneric(1, (gpioPulse_t[]){{.gpioOn=1<<GPIO_PIN, .gpioOff=0, .usDelay=WS2812B_T0H}});
        gpioWaveAddGeneric(1, (gpioPulse_t[]){{.gpioOn=0, .gpioOff=1<<GPIO_PIN, .usDelay=WS2812B_T0L}});
    }
}

void ws2812b_send_byte(uint8_t byte) {
    for (int i = 7; i >= 0; i--) {
        ws2812b_set_bit(byte & (1 << i));
    }
}

void ws2812b_send_color(uint8_t red, uint8_t green, uint8_t blue) {
    ws2812b_send_byte(green);
    ws2812b_send_byte(red);
    ws2812b_send_byte(blue);
}


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set PWM frequency (not strictly needed for WS2812B, but good practice)
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();
        if (lux >= 0) {
            float brightness = map_lux_to_brightness(lux);

            for (int i = 0; i < NUM_LEDS; i++) {
                set_led_color(i, brightness);
            }
            send_led_data();
        } else {
            fprintf(stderr, "Error reading BH1750 sensor\n");
        }

        gpioDelay(100); // Delay 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

float read_bh1750() {
    char config_cmd = 0x10; // Continuous high-resolution mode
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, 0x00, config_cmd) == 0) {
            gpioDelay(180); // Wait 180ms
            int raw_value = i2cReadWordData(i2c_handle, 0x00);
            if (raw_value >= 0) {
                float lux = (float)raw_value / 1.2;
                return lux;
            } else {
                fprintf(stderr, "Error reading from I2C device: %d\n", raw_value);
            }
        } else {
            fprintf(stderr, "Error writing to I2C device\n");
        }
        retries--;
        gpioDelay(100); // Wait before retrying
    }

    return -1.0; // Indicate error
}

float map_lux_to_brightness(float lux) {
    // Logarithmic mapping
    float brightness = log10(lux + 1) / log10(10000 + 1); // Assuming max lux is 10000
    if (brightness < 0) brightness = 0;
    if (brightness > 1) brightness = 1;
    return brightness;
}

void set_led_color(int led_index, float brightness) {
    // Simple grayscale color (adjust as needed)
    uint8_t red = (uint8_t)(brightness * 255);
    uint8_t green = (uint8_t)(brightness * 255);
    uint8_t blue = (uint8_t)(brightness * 255);

    // Store the color data for each LED
    static uint8_t led_colors[NUM_LEDS][3];
    led_colors[led_index][0] = red;
    led_colors[led_index][1] = green;
    led_colors[led_index][2] = blue;
}

void send_led_data() {
    gpioWaveClear();
    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_send_color(led_colors[i][0], led_colors[i][1], led_colors[i][2]);
    }

    gpioWaveCreate();
    gpioPulse_t reset_pulse = {.gpioOn=0, .gpioOff=0, .usDelay=WS2812B_RESET_TIME};
    gpioWaveAddGeneric(1, &reset_pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT); // Send the wave once
        while (gpioWaveTxBusy()) gpioDelay(10); // Wait for transmission to finish
        gpioWaveDelete(wave_id);
    }
}

void cleanup() {
    printf("Cleaning up...\n");
    gpioWaveClear(); // Stop any ongoing wave transmission
    gpioPWM(GPIO_PIN, 0); // Disable PWM
    i2cClose(i2c_handle);
    gpioTerminate();
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

