#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SENSORS 3
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define APA102_START_FRAME_SIZE 4
#define APA102_END_FRAME_SIZE 4
#define APA102_LED_COUNT 1
#define APA102_BYTES_PER_LED 4 // RGB + brightness
#define APA102_FRAME_SIZE (APA102_START_FRAME_SIZE + APA102_LED_COUNT * APA102_BYTES_PER_LED + APA102_END_FRAME_SIZE)
#define BRIGHTNESS_FADE_TIME_MS 500
#define SENSOR_READ_DELAY_MS 180
#define MAIN_LOOP_DELAY_MS 100

// Global variables
int i2c_handles[NUM_SENSORS];
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_spi(int channel, int speed);
int read_bh1750(int handle);
float average_light_levels(int sensor_values[], int num_sensors);
int init_apa102(int spi_handle);
int set_apa102_brightness(int spi_handle, int brightness);
int fade_brightness(int spi_handle, int target_brightness, int fade_time_ms);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to initialize SPI
int init_spi(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Function to read data from BH1750 sensor
int read_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CONTINUOUS_HIGH_RES_MODE) != 0) {
        fprintf(stderr, "Error writing to BH1750 sensor\n");
        return -1;
    }
    gpioDelay(SENSOR_READ_DELAY_MS * 1000); // Delay for conversion

    int word = i2cReadWordData(handle, 0);
    if (word < 0) {
        fprintf(stderr, "Error reading from BH1750 sensor: %d\n", word);
        return -1;
    }

    // BH1750 returns big-endian, pigpio swaps bytes, so we need to swap back
    uint16_t raw_value = ((word & 0xFF) << 8) | ((word & 0xFF00) >> 8);
    return (int)raw_value;
}

// Function to average light levels
float average_light_levels(int sensor_values[], int num_sensors) {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (sensor_values[i] >= 0) { // Only include valid readings
            sum += sensor_values[i];
            count++;
        }
    }
    if (count > 0) {
        return sum / count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

// Function to initialize APA102 LED strip
int init_apa102(int spi_handle) {
    // Start frame (4 bytes of 0x00)
    char start_frame[APA102_START_FRAME_SIZE];
    for (int i = 0; i < APA102_START_FRAME_SIZE; i++) {
        start_frame[i] = 0x00;
    }

    if (spiWrite(spi_handle, start_frame, APA102_START_FRAME_SIZE) != APA102_START_FRAME_SIZE) {
        fprintf(stderr, "Error writing start frame to APA102\n");
        return -1;
    }

    return 0;
}

// Function to set APA102 brightness
int set_apa102_brightness(int spi_handle, int brightness) {
    // LED data (RGB: 0xE0, 0xE0, 0xE0, Brightness: brightness)
    char led_data[APA102_BYTES_PER_LED];
    led_data[0] = 0xE0; // Red
    led_data[1] = 0xE0; // Green
    led_data[2] = 0xE0; // Blue
    led_data[3] = brightness; // Brightness

    if (spiWrite(spi_handle, led_data, APA102_BYTES_PER_LED) != APA102_BYTES_PER_LED) {
        fprintf(stderr, "Error writing LED data to APA102\n");
        return -1;
    }

    return 0;
}

// Function to fade brightness
int fade_brightness(int spi_handle, int target_brightness, int fade_time_ms) {
    int current_brightness = 0; // Assuming initial brightness is 0
    int step = (target_brightness > current_brightness) ? 1 : -1;
    int num_steps = abs(target_brightness - current_brightness);
    int delay_ms = fade_time_ms / num_steps;

    for (int i = 0; i < num_steps; i++) {
        current_brightness += step;
        if (set_apa102_brightness(spi_handle, current_brightness) != 0) {
            return -1;
        }
        gpioDelay(delay_ms * 1000); // Delay in microseconds
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C sensors
    i2c_handles[0] = init_i2c(I2C_BUS, BH1750_ADDR_1);
    i2c_handles[1] = init_i2c(I2C_BUS, BH1750_ADDR_2);
    i2c_handles[2] = -1; // Placeholder for a potential third sensor

    // Initialize SPI
    spi_handle = init_spi(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize APA102
    if (init_apa102(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int sensor_values[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                sensor_values[i] = read_bh1750(i2c_handles[i]);
                if (sensor_values[i] < 0) {
                    fprintf(stderr, "Error reading sensor %d, setting to -1\n", i);
                    sensor_values[i] = -1; // Mark as invalid
                }
            } else {
                sensor_values[i] = -1; // Sensor not present
            }
        }

        float average_light = average_light_levels(sensor_values, NUM_SENSORS);
        int target_brightness = (int)average_light / 10; // Scale down the light level
        if (target_brightness > 255) {
            target_brightness = 255;
        }

        if (fade_brightness(spi_handle, target_brightness, BRIGHTNESS_FADE_TIME_MS) != 0) {
            fprintf(stderr, "Error fading brightness\n");
        }

        gpioDelay(MAIN_LOOP_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

