#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Function prototypes
int self_test();
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void activate_led();
void deactivate_led();
void log_event(const char *event);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Perform self-test
    if (self_test() != 0) {
        fprintf(stderr, "Self-test failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Self-test passed. Starting main loop.\n");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) { // Flame detected (active low)
            activate_buzzer();
            activate_led();
            log_event("Flame detected");
        } else {
            deactivate_buzzer();
            deactivate_led();
        }

        gpioDelay(50); // Check every 50ms
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Self-test function
int self_test() {
    printf("Performing self-test...\n");

    // Blink LED twice
    for (int i = 0; i < 2; i++) {
        activate_led();
        gpioDelay(500); // 500ms
        deactivate_led();
        gpioDelay(500); // 500ms
    }

    // Read flame sensor 5 times
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value != 0) {
            fprintf(stderr, "Self-test failed: Flame sensor not active on sample %d\n", i + 1);
            return 1; // Error: Flame sensor not active
        }
        gpioDelay(100); // 100ms delay between reads
    }

    printf("Self-test passed.\n");
    return 0; // Success
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1);
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0);
}

// Function to activate the LED
void activate_led() {
    gpioWrite(LED_PIN, 1);
}

// Function to deactivate the LED
void deactivate_led() {
    gpioWrite(LED_PIN, 0);
}

// Function to log events with timestamps
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] %s\n", timestamp, event);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0; // Set flag to exit main loop

    // Deactivate buzzer and LED
    deactivate_buzzer();
    deactivate_led();

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

