#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define MIN_LUX 0.0
#define MAX_LUX 1000.0
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_bh1750(float *lux);
void update_led_frequency(float average_lux);
void signal_handler(int signal);

// Function to read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char config_mode = 0x10; // Continuous high resolution mode
    char buffer[2];
    int result;

    // Send configuration command
    result = i2cWriteDevice(i2c_handle, &config_mode, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read two bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert data to lux value
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to update LED blinking frequency based on average lux value
void update_led_frequency(float average_lux) {
    float frequency = MIN_FREQUENCY + (average_lux - MIN_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_LUX - MIN_LUX);
    int period_us = (int)(1000000.0 / frequency); // Period in microseconds

    gpioWrite(GPIO_LED, 1); // Turn LED on
    gpioDelay(period_us / 2); // Wait for half the period
    gpioWrite(GPIO_LED, 0); // Turn LED off
    gpioDelay(period_us / 2); // Wait for half the period
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float lux;
    float sum_lux = 0.0;
    int sample_count = 0;

    // Main loop
    while (!terminate) {
        // Read lux value from BH1750 sensor
        if (read_bh1750(&lux) == 0) {
            // Update circular buffer
            sum_lux -= lux_buffer[buffer_index];
            lux_buffer[buffer_index] = lux;
            sum_lux += lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            sample_count++;

            // Calculate average lux value
            float average_lux = sum_lux / ((sample_count > BUFFER_SIZE) ? BUFFER_SIZE : sample_count);

            // Update LED blinking frequency
            update_led_frequency(average_lux);
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

