void blink_digit(int digit) {
    display_digit(digit);
    gpioDelay(500); // On time
    display_digit(0); // Turn off all segments
    gpioDelay(500); // Off time
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

