    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Seven-segment display blinker started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        blink_digit(5); // Blink the digit '5'
    }

    // Cleanup GPIO
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

