#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output and initialize to LOW
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    // Set button pin as input with pull-up resistor
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Register callback function for falling edge detection on button pin
    if (gpioSetAlertFunc(BUTTON_PIN, button_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for button pin\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Blinking loop
    while (program_running) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(1000); // 1 second
        gpioWrite(LED_PIN, 0);
        gpioDelay(1000); // 1 second
    }

    // Cleanup and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    return 0;
}

// Callback function for button press
void button_callback(int gpio, int level, uint32_t tick) {
    if (gpio == BUTTON_PIN && level == 0) { // Falling edge detected
        printf("Button pressed!\n");
        program_running = 0; // Stop the blinking loop
    }
}

