    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set BUTTON_PIN as input\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on BUTTON_PIN\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(500);       // Wait 500ms
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(500);       // Wait 500ms
}

