    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Press the button to blink the LED. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (gpioRead(BUTTON_PIN) == 1) { // Button is pressed
            blink_led();
            while (gpioRead(BUTTON_PIN) == 1) {
                gpioDelay(10); // Small delay to avoid busy-waiting
            }
            gpioWrite(LED_PIN, 0); // Turn LED off after button release
            gpioDelay(100); // Debounce delay
        } else {
            gpioDelay(100); // Reduce CPU usage when button is not pressed
        }
    }

    return 0;
}

