// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM period (ms)
#define PWM_PERIOD (1000 / PWM_FREQUENCY)

// Define PWM resolution (bits)
#define PWM_RESOLUTION 8

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
}

// Function to generate a random integer between 0 and 100
int generate_random_intensity() {
    return rand() % 101;
}

// Function to set the RGB LED color
void set_rgb_color(int red_intensity, int green_intensity, int blue_intensity) {
    // Convert intensity values to PWM duty cycles (0-255)
    int red_duty_cycle   = (int)(((float)red_intensity   / 100.0) * 255.0);
    int green_duty_cycle = (int)(((float)green_intensity / 100.0) * 255.0);
    int blue_duty_cycle  = (int)(((float)blue_intensity  / 100.0) * 255.0);

    // Set the PWM duty cycles for each color
    gpioPWM(RED_PIN,   red_duty_cycle);
    gpioPWM(GREEN_PIN, green_duty_cycle);
    gpioPWM(BLUE_PIN,  blue_duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM range for each color
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate random intensity values
        int red_intensity   = generate_random_intensity();
        int green_intensity = generate_random_intensity();
        int blue_intensity  = generate_random_intensity();

        // Set the RGB LED color
        set_rgb_color(red_intensity, green_intensity, blue_intensity);

        // Wait for 100 milliseconds
        usleep(100000); // 100 ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

