#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact interrupt
#define INTERRUPT_PIN 17

// Default impact threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double impact_threshold = DEFAULT_THRESHOLD;
bool running = true;

// Function prototypes
int init_lsm303();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void trigger_interrupt();
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        impact_threshold = atof(argv[1]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set interrupt pin as output
    gpioSetMode(INTERRUPT_PIN, PI_OUTPUT);

    // Initialize LSM303DLHC
    if (init_lsm303() != 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    accelerometer_data_t accel_data;
    while (running) {
        // Read accelerometer data
        if (read_accelerometer(&accel_data.x, &accel_data.y, &accel_data.z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            continue; // Continue to the next iteration
        }

        // Calculate magnitude
        double magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

        // Check if impact occurred
        if (magnitude > impact_threshold) {
            printf("Impact detected! Magnitude: %.2f G\n", magnitude);
            trigger_interrupt();
            log_data(accel_data.x, accel_data.y, accel_data.z);
        }

        // Delay for 100ms (10Hz polling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize LSM303DLHC
int init_lsm303() {
    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Configure CTRL_REG1_A (Enable all axes, 100Hz data rate)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure CTRL_REG4_A (Full scale +/- 2G)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        i2cClose(i2c_handle);
        return -1;
