#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void control_led(uint16_t als);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.als, &sensor_data.red, &sensor_data.green, &sensor_data.blue) == 0) {
            // Log data
            log_data(sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue);

            // Control LED brightness
            control_led(sensor_data.als);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data from ADPD188BI
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[2];
    int result;

    // Read ALS LSB
    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read ALS LSB: %s\n", strerror(errno));
        return -1;
    }
    *als = (uint16_t)buf[0];

    // Read ALS MSB
    result = i2cReadI2CBlockData(i2c_handle, ALS_MSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read ALS MSB: %s\n", strerror(errno));
        return -1;
    }
    *als |= ((uint16_t)buf[0] << 8);

    // Read Red LSB
    result = i2cReadI2CBlockData(i2c_handle, RED_LSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read Red LSB: %s\n", strerror(errno));
        return -1;
    }
    *red = (uint16_t)buf[0];

    // Read Red MSB
    result = i2cReadI2CBlockData(i2c_handle, RED_MSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read Red MSB: %s\n", strerror(errno));
        return -1;
    }
    *red |= ((uint16_t)buf[0] << 8);

    // Read Green LSB
    result = i2cReadI2CBlockData(i2c_handle, GREEN_LSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read Green LSB: %s\n", strerror(errno));
        return -1;
    }
    *green = (uint16_t)buf[0];

    // Read Green MSB
    result = i2cReadI2CBlockData(i2c_handle, GREEN_MSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read Green MSB: %s\n", strerror(errno));
        return -1;
    }
    *green |= ((uint16_t)buf[0] << 8);

    // Read Blue LSB
    result = i2cReadI2CBlockData(i2c_handle, BLUE_LSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read Blue LSB: %s\n", strerror(errno));
        return -1;
    }
    *blue = (uint16_t)buf[0];

    // Read Blue MSB
    result = i2cReadI2CBlockData(i2c_handle, BLUE_MSB_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read Blue MSB: %s\n", strerror(errno));
        return -1;
    }
    *blue |= ((uint16_t)buf[0] << 8);

    return 0;
}

// Log data to CSV file
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED brightness using PWM
void control_led(uint16_t als) {
    // Map ALS value (0-65535) to PWM duty cycle (0-PWM_RANGE)
    int duty_cycle = (int)(((float)als / 65535.0) * PWM_RANGE);

    gpioPWM(LED_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Turn off LED
    gpioPWM(LED_GPIO, 0);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

