#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define GYRO_ADDRESS 0x69 // Or 0x68, check your sensor
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CALIBRATION_SAMPLES 100
#define DPS_THRESHOLD 50.0
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define GYRO_SENSITIVITY 0.00875 // 8.75 mdps/digit

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_gyro();
gyro_data_t read_gyro_data();
gyro_data_t calibrate_gyro();
void log_data(gyro_data_t data);
void check_thresholds(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize gyroscope
int init_gyro() {
    // Enable the gyroscope (Normal mode, 100Hz, all axes enabled)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", i2c_handle);
        return -1;
    }

    // Set full-scale range to 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %d\n", i2c_handle);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%X, got 0x%X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;

    raw_x = i2cReadWordData(i2c_handle, OUT_X_L);
    if (raw_x < 0) {
        fprintf(stderr, "Error reading OUT_X_L: %d\n", raw_x);
        data.x = 0.0; // Set to 0 to avoid using uninitialized data
    } else {
        data.x = (float)raw_x * GYRO_SENSITIVITY;
    }

    raw_y = i2cReadWordData(i2c_handle, OUT_Y_L);
    if (raw_y < 0) {
        fprintf(stderr, "Error reading OUT_Y_L: %d\n", raw_y);
        data.y = 0.0;
    } else {
        data.y = (float)raw_y * GYRO_SENSITIVITY;
    }

    raw_z = i2cReadWordData(i2c_handle, OUT_Z_L);
    if (raw_z < 0) {
        fprintf(stderr, "Error reading OUT_Z_L: %d\n", raw_z);
        data.z = 0.0;
    } else {
        data.z = (float)raw_z * GYRO_SENSITIVITY;
    }

    return data;
}

// Calibrate gyroscope
gyro_data_t calibrate_gyro() {
    gyro_data_t offsets = {0.0, 0.0, 0.0};
    gyro_data_t sum = {0.0, 0.0, 0.0};
    gyro_data_t data;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        data = read_gyro_data();
        sum.x += data.x;
        sum.y += data.y;
        sum.z += data.z;
        gpioDelay(SAMPLE_PERIOD_MS * 1000); // Delay in microseconds
    }

    offsets.x = sum.x / CALIBRATION_SAMPLES;
    offsets.y = sum.y / CALIBRATION_SAMPLES;
    offsets.z = sum.z / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", offsets.x, offsets.y, offsets.z);
    return offsets;
}

// Log data to file
void log_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check thresholds and log alerts
void check_thresholds(gyro_data_t data) {
    if (fabs(data.x) > DPS_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        fprintf(log_file, "%s,ALERT,X-axis exceeded threshold: %.2f dps\n", timestamp, data.x);
        fprintf(stderr, "%s,ALERT,X-axis exceeded threshold: %.2f dps\n", timestamp, data.x);
        fflush(log_file);
    }
    if (fabs(data.y) > DPS_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        fprintf(log_file, "%s,ALERT,Y-axis exceeded threshold: %.2f dps\n", timestamp, data.y);
        fprintf(stderr, "%s,ALERT,Y-axis exceeded threshold: %.2f dps\n", timestamp, data.y);
        fflush(log_file);
    }
    if (fabs(data.z) > DPS_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        fprintf(log_file, "%s,ALERT,Z-axis exceeded threshold: %.2f dps\n", timestamp, data.z);
        fprintf(stderr, "%s,ALERT,Z-axis exceeded threshold: %.2f dps\n", timestamp, data.z);
        fflush(log_file);
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Calibrate gyroscope
    gyro_data_t offsets = calibrate_gyro();

    // Main loop
    gyro_data_t raw_data, calibrated_data;
    while (!terminate) {
        raw_data = read_gyro_data();
        calibrated_data.x = raw_data.x - offsets.x;
        calibrated_data.y = raw_data.y - offsets.y;
        calibrated_data.z = raw_data.z - offsets.z;

        log_data(calibrated_data);
        check_thresholds(calibrated_data);

        gpioDelay(SAMPLE_PERIOD_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

