// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define LED_GPIO 17
#define SAMPLE_RATE_MS 100
#define ACCEL_THRESHOLD 2.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_adxl345();
int read_acceleration(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int init_adxl345() {
    // Set data format register to +/- 2g and full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set power control register to measure mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes, and convert to g units
    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

