#define MAG_SENSITIVITY 0.08 // Gauss/LSB (for +/- 1.3 Gauss range)

// Global variables
int i2c_handle_accel, i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x, y, z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_accelerometer();
sensor_data_t read_magnetometer();
float calculate_heading(sensor_data_t accel_data, sensor_data_t mag_data);
void log_data(sensor_data_t accel_data, float heading, sensor_data_t mag_data);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return -1;
    }

    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return -1;
    }

    // Configure accelerometer (enable all axes, 50 Hz data rate)
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return -1;
    }

    // Configure accelerometer (set full-scale range to +/- 2g)
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG4_A\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return -1;
    }

    // Configure magnetometer (set data rate to 75 Hz)
    if (i2cWriteByteData(i2c_handle_mag, CRA_REG_M, 0x18) < 0) {
        fprintf(stderr, "Failed to write to magnetometer CRA_REG_M\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return -1;
    }

    // Configure magnetometer (set gain to +/- 1.3 Gauss)
    if (i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer MR_REG_M\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
sensor_data_t read_accelerometer() {
    sensor_data_t accel_data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        accel_data.x = accel_data.y = accel_data.z = NAN; // Indicate error
        return accel_data;
    }

    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    accel_data.x = (float)x * ACCEL_SENSITIVITY;
    accel_data.y = (float)y * ACCEL_SENSITIVITY;
    accel_data.z = (float)z * ACCEL_SENSITIVITY;

    return accel_data;
}

// Function to read magnetometer data
sensor_data_t read_magnetometer() {
    sensor_data_t mag_data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        mag_data.x = mag_data.y = mag_data.z = NAN; // Indicate error
        return mag_data;
    }

    int16_t x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t z = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t y = (int16_t)((buffer[4] << 8) | buffer[5]);

    mag_data.x = (float)x * MAG_SENSITIVITY;
    mag_data.y = (float)y * MAG_SENSITIVITY;
    mag_data.z = (float)z * MAG_SENSITIVITY;

    return mag_data;
}

// Function to calculate heading using tilt compensation
float calculate_heading(sensor_data_t accel_data, sensor_data_t mag_data) {
    float roll = atan2(accel_data.y, accel_data.z);
    float pitch = atan2(-accel_data.x, sqrt(accel_data.y * accel_data.y + accel_data.z * accel_data.z));

    float mag_x = mag_data.x * cos(pitch) + mag_data.z * sin(pitch);
    float mag_y = mag_data.x * sin(roll) * sin(pitch) + mag_data.y * cos(roll) - mag_data.z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y, mag_x) * 180 / M_PI;

    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Function to log data to file
void log_data(sensor_data_t accel_data, float heading, sensor_data_t mag_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, heading, accel_data.x, accel_data.y, accel_data.z, mag_data.x, mag_data.y);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y\n");
    }

    // Main loop
    while (!terminate) {
        sensor_data_t accel_data = read_accelerometer();
        sensor_data_t mag_data = read_magnetometer();

        if (!isnan(accel_data.x) && !isnan(mag_data.x)) {
            float heading = calculate_heading(accel_data, mag_data);
            log_data(accel_data, heading, mag_data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

