#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// Define I2C bus and sensor addresses
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C register addresses (replace with actual values from datasheet)
#define DATA_REG 0x00 // Example: Register to read audio data

// Define sampling interval (10 ms)
#define SAMPLING_INTERVAL_MS 10
#define SAMPLING_INTERVAL_US (SAMPLING_INTERVAL_MS * 1000)

// Define CSV filename
#define CSV_FILENAME "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sample;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int i2c_handle, int16_t *sample);
int get_timestamp(struct timespec *ts);
double calculate_tdoa(struct timespec ts1, struct timespec ts2);
int log_data(struct timespec ts, int16_t sensor1, int16_t sensor2, double tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int16_t *sample) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *sample = (int16_t)((buf[1] << 8) | buf[0]);

    return 0;
}

// Function to get timestamp
int get_timestamp(struct timespec *ts) {
    if (clock_gettime(CLOCK_REALTIME, ts) == -1) {
        perror("clock_gettime");
        return -1;
    }
    return 0;
}

// Function to calculate TDOA
double calculate_tdoa(struct timespec ts1, struct timespec ts2) {
    // Calculate time difference in seconds
    double time_diff = (double)(ts2.tv_sec - ts1.tv_sec) + (double)(ts2.tv_nsec - ts1.tv_nsec) / 1000000000.0;
    return time_diff;
}

// Function to log data to CSV file
int log_data(struct timespec ts, int16_t sensor1, int16_t sensor2, double tdoa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%ld,%ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, sensor1, sensor2, tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        struct timespec ts1, ts2;
        int16_t sensor1_data, sensor2_data;

        // Read sensor data with retries
        int retries = 3;
        while (retries > 0) {
            if (read_sensor_data(i2c_handle1, &sensor1_data) == 0) {
                break;
            }
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to read sensor 1 data after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        retries = 3;
        while (retries > 0) {
            if (read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
                break;
            }
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to read sensor 2 data after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Get timestamp
        if (get_timestamp(&ts1) != 0) {
            fprintf(stderr, "Failed to get timestamp.\n");
            continue;
        }

        // Wait for the sampling interval
        gpioDelay(SAMPLING_INTERVAL_US);

        // Get timestamp after the sampling interval
        if (get_timestamp(&ts2) != 0) {
            fprintf(stderr, "Failed to get timestamp after sampling interval.\n");
            continue;
        }

        // Calculate TDOA
        double tdoa = calculate_tdoa(ts1, ts2);

        // Log data
        if (log_data(ts1, sensor1_data, sensor2_data, tdoa) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
