#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define GYRO_XOUT 0x04
#define GYRO_YOUT 0x06
#define GYRO_ZOUT 0x08
#define ACCEL_XOUT 0x0A
#define ACCEL_YOUT 0x0C
#define ACCEL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Sensor Sensitivities
#define GYRO_SENSITIVITY 0.005 // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// Global Variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile int running = 1;

// Function Prototypes
int spi_read_register(int spi_handle, uint8_t reg_addr, int16_t *data);
int spi_write_register(int spi_handle, uint8_t reg_addr, uint16_t data);
int read_imu_data(int spi_handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(void);
void signal_handler(int signal);

// Function to read a register from the ADIS16488A
int spi_read_register(int spi_handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the read command (MSB = 0, register address)
    tx_buf[0] = 0x00 | (reg_addr << 1);
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// Function to write a register in the ADIS16488A
int spi_write_register(int spi_handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];

    // Construct the write command (MSB = 1, register address, data)
    tx_buf[0] = 0x80 | (reg_addr << 1);
    tx_buf[1] = data & 0xFF; // LSB

    if (spiWrite(spi_handle, tx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Function to read IMU data and convert to physical units
int read_imu_data(int spi_handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(spi_handle, GYRO_XOUT, &raw_gyro_x) != 0) return -1;
    if (spi_read_register(spi_handle, GYRO_YOUT, &raw_gyro_y) != 0) return -1;
    if (spi_read_register(spi_handle, GYRO_ZOUT, &raw_gyro_z) != 0) return -1;
    if (spi_read_register(spi_handle, ACCEL_XOUT, &raw_accel_x) != 0) return -1;
    if (spi_read_register(spi_handle, ACCEL_YOUT, &raw_accel_y) != 0) return -1;
    if (spi_read_register(spi_handle, ACCEL_ZOUT, &raw_accel_z) != 0) return -1;

    // Convert raw data to physical units
    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp_ms, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) < 0) {
        fprintf(stderr, "Error: Failed to write data to file\n");
        return -1;
    }

    return 0;
}

// Cleanup function to close SPI and file on exit
void cleanup(void) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received: %d\n", signal);
    running = 0;
    cleanup();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Register cleanup function
    atexit(cleanup);

    // Register signal handlers
