#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_imu();
sensor_data_t read_imu_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the IMU
int init_imu() {
    // Wake up the IMU (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU\n");
        return -1;
    }
    gpioDelay(100); // Short delay after waking up
    return 0;
}

// Read accelerometer and gyroscope data
sensor_data_t read_imu_data() {
    sensor_data_t data;
    char buf[12];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 12) < 0) {
        fprintf(stderr, "Error: Could not read IMU data\n");
        data.accel_x = data.accel_y = data.accel_z = 0;
        data.gyro_x = data.gyro_y = data.gyro_z = 0;
        return data;
    }

    data.accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    data.accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    data.accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    data.gyro_x  = (int16_t)((buf[6] << 8) | buf[7]);
    data.gyro_y  = (int16_t)((buf[8] << 8) | buf[9]);
    data.gyro_z  = (int16_t)((buf[10] << 8) | buf[11]);

    return data;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize IMU
    if (init_imu() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

