#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D // Or 0x1C, check your sensor
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define WHO_AM_I 0x0D
#define WHO_AM_I_VALUE 0x2A
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.0 // g
#define SENSITIVITY 0.0048828125 // g/LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mma8451q();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z);
void control_led(int on);
void signal_handler(int signal);

// Structure for grouping accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q() != 0) {
        fprintf(stderr, "MMA8451Q initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    accelerometer_data_t accel_data;
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Calculate magnitude
            float magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Log impact
                log_impact(accel_data.x, accel_data.y, accel_data.z);

                // Turn on LED
                control_led(1);

                // Wait for 500ms
                gpioDelay(500000); // 500ms

                // Turn off LED
                control_led(0);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set back to input
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize MMA8451Q
int init_mma8451q() {
    // Verify sensor ID
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%X (expected 0x%X)\n", who_am_i, WHO_AM_I_VALUE);
        return 1;
    }

    // Set to active mode, 800 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return 1;
    }

    // Set +/- 2g range
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG2\n");
        return 1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char raw_data[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, raw_data, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return 1;
    }

    *x = (int16_t)((raw_data[0] << 8) | raw_data[1]) >> 4;
    *y = (int16_t)((raw_data[2] << 8) | raw_data[3]) >> 4;
    *z = (int16_t)((raw_data[4] << 8) | raw_data[5]) >> 4;

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = x * SENSITIVITY;
    float y_g = y * SENSITIVITY;
    float z_g = z * SENSITIVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact
void log_impact(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Impact detected: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

