#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMAG5273_ADDR 0x08
#define DATA_REG 0x01 // Example register address, adjust as needed
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define CSV_FILE "magnetic_field_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
int create_csv_header();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMAG5273_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from TMAG5273
int read_sensor_data(sensor_data_t *data) {
    char buf[6]; // Assuming 2 bytes per axis (x, y, z)
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    // Assuming little-endian format
    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Log data to CSV file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data->x, data->y, data->z);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Create CSV header if the file is new
int create_csv_header() {
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and create the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        create_csv_header();
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Continuing...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

