// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_FF 0x28
#define ADXL345_REG_TIME_FF 0x29
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_POWER_CTL 0x2D

// GPIO pin for interrupt
#define INT1_GPIO 17

// Free-fall threshold (adjust as needed)
#define FREEFALL_THRESHOLD 0x0A

// Free-fall time (adjust as needed)
#define FREEFALL_TIME 0x0A

// File descriptor for the I2C device
int i2c_fd;

// File pointer for the CSV log file
FILE *log_file = NULL;

// Flag to indicate if the program should exit
volatile sig_atomic_t program_running = 1;

// Function prototypes
int adxl345_init();
int adxl345_read_register(int reg);
int adxl345_write_register(int reg, int value);
int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Function to initialize the ADXL345
int adxl345_init() {
    // Verify device ID
    int devid = adxl345_read_register(ADXL345_REG_DEVID);
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set standby mode
    if (adxl345_write_register(ADXL345_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set standby mode\n");
        return -1;
    }

    // Configure free-fall threshold
    if (adxl345_write_register(ADXL345_REG_THRESH_FF, FREEFALL_THRESHOLD) != 0) {
        fprintf(stderr, "Error: Failed to configure free-fall threshold\n");
        return -1;
    }

    // Configure free-fall time
    if (adxl345_write_register(ADXL345_REG_TIME_FF, FREEFALL_TIME) != 0) {
        fprintf(stderr, "Error: Failed to configure free-fall time\n");
        return -1;
    }

    // Enable free-fall interrupt
    if (adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to enable free-fall interrupt\n");
        return -1;
    }

    return 0;
}

// Function to read a register from the ADXL345
int adxl345_read_register(int reg) {
    int value = i2cReadByteData(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error: I2C read failed for register 0x%02X\n", reg);
        return -1;
    }
    return value;
}

// Function to write a register to the ADXL345
int adxl345_write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error: I2C write failed for register 0x%02X with value 0x%02X\n", reg, value);
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    int result = i2cReadI2CBlockData(i2c_fd, ADXL345_REG_DATAX0, data, 6);
    if (result < 0) {
        fprintf(stderr, "Error: I2C block read failed\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    if (level == FALLING_EDGE) {
        // Disable further interrupts
        adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x00);

        // Read acceleration data
        int16_t x, y, z;
        if (adxl345_read_acceleration(&x, &y, &z) == 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Write data to CSV file
            fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
            fflush(log_file);

            // Re-enable interrupts
            adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x40);
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data in interrupt handler\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV log file
    log_file = fopen("freefall_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set GPIO mode for INT1 pin
    gpioSetMode(INT1_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(INT1_GPIO, PI_PUD_UP);

    // Register interrupt handler
    if (gpioSetISRFuncEx(INT1_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Poll the I2C device for interrupts (optional, but good practice)
        // In a real application, you might want to add a timeout here
        // to prevent the loop from consuming too much CPU.
        // For this example, we just sleep for a short time.
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    gpioSetISRFuncEx(INT1_GPIO, FALLING_EDGE, 0, NULL, NULL); // Disable interrupt handler
    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

