#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28
#define WHO_AM_I 0x0F

// Scaling factors
#define ACCEL_SCALE 0.061  // mg/LSB for +/- 2g range
#define GYRO_SCALE 8.75   // mdps/LSB for +/- 250 dps range

// Fall detection parameters
#define FREEFALL_THRESHOLD 0.2 * 9.81 // m/s^2
#define IMPACT_THRESHOLD 2.5 * 9.81   // m/s^2
#define IMPACT_WINDOW 1.0            // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Fall detection state
typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} FallState;

FallState current_state = IDLE;

// Function prototypes
int init_lsm6dsr();
int read_accel_gyro(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z);
float calculate_acceleration_magnitude(float accel_x, float accel_y, float accel_z);
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z);
void fall_detection(float acceleration_magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Configure accelerometer: 104 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 104 Hz, ±2g
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: 104 Hz, +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 104 Hz, ±250 dps
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x69) {
        fprintf(stderr, "Error reading WHO_AM_I or incorrect value: 0x%X\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data
int read_accel_gyro(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buffer[12];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Error reading accelerometer/gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine high and low bytes for gyroscope data
    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to physical units
    *accel_x = (float)raw_accel_x * ACCEL_SCALE / 1000.0f; // Convert mg to g
    *accel_y = (float)raw_accel_y * ACCEL_SCALE / 1000.0f;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE / 1000.0f;
    *gyro_x = (float)raw_gyro_x * GYRO_SCALE / 1000.0f;   // Convert mdps to dps
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE / 1000.0f;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE / 1000.0f;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(float accel_x, float accel_y, float accel_z) {
    return sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);
}

// Log data to CSV file
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(float acceleration_magnitude) {
    static time_t freefall_start_time = 0;
    static int freefall_detected = 0;

    switch (current_state) {
        case IDLE:
            if (acceleration_magnitude < FREEFALL_THRESHOLD) {
                current_state = FREEFALL;
                freefall_start_time = time(NULL);
                freefall_detected = 1;
            }
            break;
        case FREEFALL:
            if (acceleration_magnitude > IMPACT_THRESHOLD) {
                current_state = IMPACT;
                freefall_detected = 0; // Reset flag
            } else if (time(NULL) - freefall_start_time > IMPACT_WINDOW && !freefall_detected) {
                current_state = IDLE;
                freefall_detected = 0; // Reset flag
            }
            break;
        case IMPACT:
            // Do nothing, just stay in this state
            break;
    }

    printf("State: %s, Acceleration: %.6f g\n",
           current_state == IDLE ? "IDLE" : (current_state == FREEFALL ? "FREEFALL" : "IMPACT"),
           acceleration_magnitude);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float acceleration_magnitude;

    // Main loop
    while (program_running) {
        if (read_accel_gyro(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            acceleration_magnitude = calculate_acceleration_magnitude(accel_x, accel_y, accel_z);
            log_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
            fall_detection(acceleration_magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(10000); // 10 ms delay (104 Hz)
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

