#define ADIS16266_REG_WHO_AM_I   0x02
#define ADIS16266_REG_XGYRO_OUT  0x04
#define ADIS16266_REG_YGYRO_OUT  0x06
#define ADIS16266_REG_ZGYRO_OUT  0x08
#define ADIS16266_REG_TEMP_OUT   0x0A
#define ADIS16266_REG_GLOB_CMD   0x68
#define ADIS16266_REG_MSC_CTRL   0x64
#define ADIS16266_REG_SMPL_PRD   0x36

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    3

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t reg_addr, uint16_t *data);
int spi_write_register(uint8_t reg_addr, uint16_t data);
int verify_who_am_i();
int read_gyro_data(float *x_rate, float *y_rate, float *z_rate);
int log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data & 0xFF;      // LSB

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Verify WHO_AM_I Register
int verify_who_am_i() {
    uint16_t who_am_i;
    if (spi_read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x5669) {
        fprintf(stderr, "Error: WHO_AM_I check failed. Expected 0x5669, got 0x%04X\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I check passed. Device ID: 0x%04X\n", who_am_i);
    return 0;
}

