int read_gyro_data(float *x_rate, float *y_rate, float *z_rate) {
    uint16_t x_raw, y_raw, z_raw;

    if (spi_read_register(ADIS16266_REG_XGYRO_OUT, &x_raw) != 0) return -1;
    if (spi_read_register(ADIS16266_REG_YGYRO_OUT, &y_raw) != 0) return -1;
    if (spi_read_register(ADIS16266_REG_ZGYRO_OUT, &z_raw) != 0) return -1;

    *x_rate = (float)((int16_t)x_raw) * 0.0305; // Convert to degrees/sec
    *y_rate = (float)((int16_t)y_raw) * 0.0305;
    *z_rate = (float)((int16_t)z_raw) * 0.0305;

    return 0;
}

// Log Data to CSV File
int log_data(float x_rate, float y_rate, float z_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate, y_rate, z_rate);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal Handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Rate(deg/s),Y_Rate(deg/s),Z_Rate(deg/s)\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x_rate, &y_rate, &z_rate) == 0) {
            log_data(x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data\n");
        }

        gpioDelay(10); // Sample every 10 ms
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

