#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SAMPLE_RATE 10 // ms
#define SENSITIVITY 0.0875 // mdps/LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    double x;
    double y;
    double z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Check WHO_AM_I register
        char buf[1];
        status = i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, buf, 1);
        if (status != 1) {
            fprintf(stderr, "Error reading WHO_AM_I register (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        if (buf[0] != WHO_AM_I_VALUE) {
            fprintf(stderr, "WHO_AM_I value mismatch (0x%02X != 0xD3) (attempt %d)\n", buf[0], 4 - retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG1 (Enable all axes, 100Hz data rate)
        char config_data[2] = {CTRL_REG1, 0x0F}; // 0x0F = 0b00001111 (ODR = 100Hz, Enable X, Y, Z axes)
        status = i2cWriteI2CBlockData(i2c_handle, CTRL_REG1, config_data + 1, 1);
        if (status != 1) {
            fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG4 (Full scale selection)
        config_data[0] = CTRL_REG4;
        config_data[1] = 0x00; // +/- 250 dps
        status = i2cWriteI2CBlockData(i2c_handle, CTRL_REG4, config_data + 1, 1);
        if (status != 1) {
            fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        printf("Gyroscope initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Gyroscope initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Read raw gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char raw_data[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, raw_data, 6); // Enable auto-increment
