    double x;
    double y;
    double z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Check WHO_AM_I register
        char buf[1];
        status = i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, buf, 1);
        if (status != 1) {
            fprintf(stderr, "Error reading WHO_AM_I register (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        if (buf[0] != WHO_AM_I_VALUE) {
            fprintf(stderr, "WHO_AM_I value mismatch (0x%02X != 0xD3) (attempt %d)\n", buf[0], 4 - retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG1 (Enable all axes, 100Hz data rate)
        char config_data[2] = {CTRL_REG1, 0x0F}; // 0x0F = 0b00001111 (ODR = 100Hz, Enable X, Y, Z axes)
        status = i2cWriteI2CBlockData(i2c_handle, CTRL_REG1, config_data + 1, 1);
        if (status != 1) {
            fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG4 (Full scale selection)
        config_data[0] = CTRL_REG4;
        config_data[1] = 0x00; // +/- 250 dps
        status = i2cWriteI2CBlockData(i2c_handle, CTRL_REG4, config_data + 1, 1);
        if (status != 1) {
            fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        printf("Gyroscope initialized successfully.\n");
        return 0; // Success
    }

