#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"

static volatile int running = 1;
FILE *log_file = NULL;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log flame events to a file
void log_flame_event(int flame_detected) {
    char *timestamp = get_timestamp();
    const char *status = flame_detected ? "YES" : "NO";

    if (log_file != NULL) {
        fprintf(log_file, "%s – Flame detected: %s\n", timestamp, status);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to check for flame detection
int is_flame_detected(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return (value == 0) ? 1 : 0; // Active LOW: 0 = flame, 1 = no flame
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        gpioTerminate(); // Clean up pigpio before exiting
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = is_flame_detected(FLAME_SENSOR_GPIO);
        if (flame_detected == 1) {
            printf("FLAME DETECTED!\n");
        } else if (flame_detected == 0) {
            // No flame detected
        } else {
            // Error reading sensor, log error
            log_flame_event(-1); // Log error
        }

        log_flame_event(flame_detected);
        gpioDelay(500); // Wait 500 milliseconds
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

