#include <string.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

static volatile int running = 1;

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorData;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to read sensor state
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log sensor data to file
void log_sensor_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(fp, "%ld,%d,%d\n", timestamp_ms, data.sensor1_state, data.sensor2_state);
    fclose(fp);
}

// Function to check if both sensors are HIGH
int check_both_high(int sensor1_state, int sensor2_state) {
    return (sensor1_state == 1 && sensor2_state == 1);
}

// Function to simulate halting the conveyor
void halt_conveyor() {
    printf("Halting conveyor!\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Create sensor data struct
        SensorData data = {sensor1_state, sensor2_state};

        // Log sensor data
        log_sensor_data(data);

        // Check if both sensors are HIGH
        if (check_both_high(sensor1_state, sensor2_state)) {
            halt_conveyor();
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Conveyor monitoring stopped.\n");

    return 0;
}

