#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define DATA_RATE_100HZ 0x01
#define FULL_SCALE_2G 0x00
#define FALL_LOG_FILE "fall_log.txt"
#define TILT_THRESHOLD 45.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void process_accelerometer_data(int16_t x, int16_t y, int16_t z, float *tilt_x, float *tilt_y, float *tilt_z);
void log_fall_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error: Could not read register value");
        return -1;
    }

    return value;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error: Could not write to register");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (ioctl(fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, (uint8_t[]){OUT_X_MSB}, 1) != 1) {
        perror("Error: Could not write register address for data read");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("Error: Could not read accelerometer data");
        return -1;
    }

    *x = (int16_t)(((data[0] << 8) | data[1]) >> 4);
    *y = (int16_t)(((data[2] << 8) | data[3]) >> 4);
    *z = (int16_t)(((data[4] << 8) | data[5]) >> 4);

    return 0;
}

// Process accelerometer data
void process_accelerometer_data(int16_t x, int16_t y, int16_t z, float *tilt_x, float *tilt_y, float *tilt_z) {
    *tilt_x = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
    *tilt_y = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
    *tilt_z = atan2(z, sqrt(x * x + y * y)) * 180 / M_PI;
}

// Log fall event
void log_fall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    program_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    // Verify sensor ID
    int who_am_i = i2c_read_reg(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x2A)\n", who_am_i);
        close(i2c_fd);
        return 1;
    }
    printf("MMA8452Q sensor ID verified.\n");

    // Initialize accelerometer
    if (i2c_write_reg(i2c_fd, CTRL_REG1, DATA_RATE_100HZ | FULL_SCALE_2G) < 0) {
        fprintf(stderr, "Error: Could not initialize accelerometer.\n");
        close(i2c_fd);
        return 1;
    }
    printf("MMA8452Q initialized.\n");

    // Open log file
    log_file = fopen(FALL_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(i2c_fd);
        return 1;
    }
    printf("Log file opened.\n");

    int16_t x, y, z;
    float tilt_x, tilt_y, tilt_z;

    // Main loop
    while (program_running) {
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            process_accelerometer_data(x, y, z, &tilt_x, &tilt_y, &tilt_z);

            if (fabs(tilt_x) > TILT_THRESHOLD || fabs(tilt_y) > TILT_THRESHOLD || fabs(tilt_z) > TILT_THRESHOLD) {
                log_fall_event(x, y, z);
                printf("Fall detected! Logged to file.\n");
            }
        } else {
            fprintf(stderr, "Error: Could not read accelerometer data. Retrying...\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

