#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants
#define OFFSET_X 0.0
#define OFFSET_Y 0.0
#define OFFSET_Z 0.0
#define SCALE_X 1.0
#define SCALE_Y 1.0
#define SCALE_Z 1.0

// Metal detection threshold
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_magnitude(float x, float y, float z);
void log_data(float x, float y, float z, float magnitude);
void metal_detector_alert(float magnitude);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
    float magnitude;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t data;
    int16_t raw_x, raw_y, raw_z;
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate data
            calibrate_data(raw_x, raw_y, raw_z, &data.x, &data.y, &data.z);

            // Calculate magnitude
            data.magnitude = calculate_magnitude(data.x, data.y, data.z);

            // Log data
            log_data(data.x, data.y, data.z, data.magnitude);

            // Metal detector alert
            metal_detector_alert(data.magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize the LIS3MDL sensor
int initialize_sensor() {
    int retries = 0;
    int status;

    while (retries < 3) {
        // Open I2C device
        i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
            retries++;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Configure CTRL_REG1: 100 Hz, continuous conversion mode
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); //0x70 = 11100000
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(100000);
            continue;
        }

        // Configure CTRL_REG3: +/- 4 gauss
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00); // +/- 4 gauss
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3: %d\n", status);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(100000);
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Sensor initialization failed after multiple retries\n");
    return -1; // Failure
}

// Read raw sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    // Read all six registers at once
    status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
