// SPI Read Register Function
int spi_read_register(uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int retries = 3;

    tx_buf[0] = reg_addr | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte for reading

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 2) == 0) {
            *data = rx_buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "SPI Read Error (Reg 0x%02X), Retrying...\n", reg_addr);
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI Read Failed (Reg 0x%02X) after multiple retries.\n", reg_addr);
    return -1; // Failure
}

