#include <unistd.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define ADIS16362_REG_X_GYRO_OUT 0x04
#define ADIS16362_REG_Y_GYRO_OUT 0x06
#define ADIS16362_REG_Z_GYRO_OUT 0x08
#define ADIS16362_REG_X_ACCEL_OUT 0x0A
#define ADIS16362_REG_Y_ACCEL_OUT 0x0C
#define ADIS16362_REG_Z_ACCEL_OUT 0x0E
#define ADIS16362_REG_GLOB_CMD 0x68
#define ADIS16362_REG_DIAG_STAT 0x02
#define ADIS16362_REG_PROD_ID 0x56

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // SPI Mode 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_imu();
int read_register(uint8_t address, int16_t *data);
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z, float *gyro_x_deg_sec, float *gyro_y_deg_sec, float *gyro_z_deg_sec, float *accel_x_g, float *accel_y_g, float *accel_z_g);
int log_data(float gyro_x_deg_sec, float gyro_y_deg_sec, float gyro_z_deg_sec, float accel_x_g, float accel_y_g, float accel_z_g);
void signal_handler(int signal);

// Structure to hold IMU data
typedef struct {
    float gyro_x_deg_sec;
    float gyro_y_deg_sec;
    float gyro_z_deg_sec;
    float accel_x_g;
    float accel_y_g;
    float accel_z_g;
} imu_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize IMU
    if (initialize_imu() != 0) {
        fprintf(stderr, "IMU initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Main loop
    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
        float gyro_x_deg_sec, gyro_y_deg_sec, gyro_z_deg_sec, accel_x_g, accel_y_g, accel_z_g;

        // Read IMU data
        if (read_register(ADIS16362_REG_X_GYRO_OUT, &gyro_x) != 0 ||
            read_register(ADIS16362_REG_Y_GYRO_OUT, &gyro_y) != 0 ||
            read_register(ADIS16362_REG_Z_GYRO_OUT, &gyro_z) != 0 ||
            read_register(ADIS16362_REG_X_ACCEL_OUT, &accel_x) != 0 ||
            read_register(ADIS16362_REG_Y_ACCEL_OUT, &accel_y) != 0 ||
            read_register(ADIS16362_REG_Z_ACCEL_OUT, &accel_z) != 0) {
            fprintf(stderr, "Failed to read IMU data\n");
            continue; // Skip to the next iteration
        }

        // Process data
        process_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z, &gyro_x_deg_sec, &gyro_y_deg_sec, &gyro_z_deg_sec, &accel_x_g, &accel_y_g, &accel_z_g);

        // Log data
        if (log_data(gyro_x_deg_sec, gyro_y_deg_sec, gyro_z_deg_sec, accel_x_g, accel_y_g, accel_z_g) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

// Initialize IMU
int initialize_imu() {
    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }

    // Verify product ID
    int16_t product_id;
    if (read_register(ADIS16362_REG_PROD_ID, &product_id) != 0) {
        fprintf(stderr, "Failed to read product ID\n");
        spiClose(spi_handle);
        return 1;
    }

    if (product_id != 0x3F42) {
        fprintf(stderr, "Incorrect product ID: 0x%X\n", product_id);
        spiClose(spi_handle);
        return 1;
    }

    // Reset the device
    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = ADIS16362_REG_GLOB_CMD; // Command register
    tx_buffer[1] = 0x04; // Reset command
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Failed to reset device\n");
        spiClose(spi_handle);
        return 1;
    }

    gpioDelay(100000); // Wait for reset to complete (100 ms)

    return 0;
}

// Read data from IMU register
int read_register(uint8_t address, int16_t *data) {
    char tx_buffer[3];
    char rx_buffer[3];

    // MSB of address must be set for read operation
    tx_buffer[0] = address | 0x80; // Set MSB for read
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return 1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = (rx_buffer[1] << 8) | rx_buffer[2];

    return 0;
}

// Process raw data to physical units
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z, float *gyro_x_deg_sec, float *gyro_y_deg_sec, float *gyro_z_deg_sec, float *accel_x_g, float *accel_y_g, float *accel_z_g) {
    *gyro_x_deg_sec = (float)gyro_x * GYRO_SCALE;
    *gyro_y_deg_sec = (float)gyro_y * GYRO_SCALE;
    *gyro_z_deg_sec = (float)gyro_z * GYRO_SCALE;
    *accel_x_g = (float)accel_x * ACCEL_SCALE;
    *accel_y_g = (float)accel_y * ACCEL_SCALE;
    *accel_z_g = (float)accel_z * ACCEL_SCALE;
}

// Log data to file
int log_data(float gyro_x_deg_sec, float gyro_y_deg_sec, float gyro_z_deg_sec, float accel_x_g, float accel_y_g, float accel_z_g) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            ts.tv_sec, ts.tv_nsec, gyro_x_deg_sec, gyro_y_deg_sec, gyro_z_deg_sec, accel_x_g, accel_y_g, accel_z_g);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

