#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define GPIO_CHIP 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_handle;
    int sensor_value;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    gpio_handle = gpioOpen(GPIO_CHIP, 0, 0);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to open GPIO chip %d: %d\n", GPIO_CHIP, gpio_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioClose(gpio_handle);
        gpioTerminate();
        return 1;
    }

    printf("Self-parking system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PIN);
            break; // Exit loop on error
        }

        // Check for obstacle detection (LOW signal)
        if (sensor_value == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log self-parking sequence started
            printf("[%s] Self-parking sequence started\n", timestamp);

            // Simulate self-parking routine (5 seconds)
            gpioDelay(5000000); // 5 seconds

            // Log self-parking sequence completed
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Self-parking sequence completed\n", timestamp);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Clean up and exit
    gpioClose(gpio_handle);
    gpioTerminate();

    printf("Self-parking system stopped.\n");

    return 0;
}

