#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int pigpio_init_result;
    int sensor1_value, sensor2_value;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20]; // Buffer to hold the formatted timestamp

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Main loop to continuously poll the sensors
    while (program_running) {
        // Read the sensor values using a single bulk read
        int sensor_values = gpioRead(SENSOR1_GPIO) | (gpioRead(SENSOR2_GPIO) << 1);

        // Extract sensor values
        sensor1_value = (sensor_values & 0x01);
        sensor2_value = (sensor_values & 0x02) >> 1;

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log the sensor data to the console
        printf("%s - Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);

        // Wait for 100 milliseconds
        gpioDelay(100); // pigpio's delay function
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

