// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling factor
#define SCALE_FACTOR 0.02

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read data from ADIS16266
int read_adis16266(int spi_handle, int reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI transaction failed: %d\n", result);
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("ADIS16266 Gyroscope Data Logger\n");

    // Main loop
    while (!terminate) {
        int16_t x_gyro, y_gyro, z_gyro;

        // Read gyroscope data
        if (read_adis16266(spi_handle, ADIS16266_XGYRO_OUT, &x_gyro) != 0) {
            fprintf(stderr, "Error reading X gyro data\n");
            continue; // Skip to the next iteration
        }
        if (read_adis16266(spi_handle, ADIS16266_YGYRO_OUT, &y_gyro) != 0) {
            fprintf(stderr, "Error reading Y gyro data\n");
            continue; // Skip to the next iteration
        }
        if (read_adis16266(spi_handle, ADIS16266_ZGYRO_OUT, &z_gyro) != 0) {
            fprintf(stderr, "Error reading Z gyro data\n");
            continue; // Skip to the next iteration
        }

        // Convert to degrees per second
        float x_rate = x_gyro * SCALE_FACTOR;
        float y_rate = y_gyro * SCALE_FACTOR;
        float z_rate = z_gyro * SCALE_FACTOR;

        // Print the data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

