#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Sensitivity values (from datasheet)
#define ACCEL_SENSITIVITY 0.061  // mg/LSB at +/- 2g
#define GYRO_SENSITIVITY 4.375   // mdps/LSB at +/- 250 dps

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lsm6dsr();
int read_accel_data(float *x, float *y, float *z);
int read_gyro_data(float *x, float *y, float *z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM6DSR
int init_lsm6dsr() {
    // Configure accelerometer: 104 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: 104 Hz, +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

