    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x * GYRO_SENSITIVITY / 1000.0f; // Convert to dps
    *y = (float)raw_y * GYRO_SENSITIVITY / 1000.0f;
    *z = (float)raw_z * GYRO_SENSITIVITY / 1000.0f;

    return 0;
}

