#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_STATUS 0x00
#define FXOS8700_OUT_X_MSB 0x01

// Expected WHO_AM_I value
#define FXOS8700_WHO_AM_I_VALUE 0xC7

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    int retries = 3;
    int status;

    // Set accelerometer range to +/-2g and ODR to 100 Hz
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, FXOS8700_XYZ_DATA_CFG, 0x00); // +/-2g range
        if (status >= 0) break;
        fprintf(stderr, "Error writing to XYZ_DATA_CFG (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x01 | (1 << 1)); // Active mode, 100 Hz ODR
        if (status >= 0) break;
        fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) return -1;

    return 0;
}

// Function to read raw sensor data
int read_sensor_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 12);
        if (status == 12) break;
        fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) return -1;

    *accel_x = (int16_t)((((uint16_t)buffer[0]) << 8) | buffer[1]) >> 2;
    *accel_y = (int16_t)((((uint16_t)buffer[2]) << 8) | buffer[3]) >> 2;
    *accel_z = (int16_t)((((uint16_t)buffer[4]) << 8) | buffer[5]) >> 2;
    *mag_x = (int16_t)((((uint16_t)buffer[6]) << 8) | buffer[7]);
    *mag_y = (int16_t)((((uint16_t)buffer[8]) << 8) | buffer[9]);
    *mag_z = (int16_t)((((uint16_t)buffer[10]) << 8) | buffer[11]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", FXOS8700_WHO_AM_I_VALUE, who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700() != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Mag: X=%6d, Y=%6d, Z=%6d\n", accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

