#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5000 // 5 seconds in milliseconds
#define SAMPLE_INTERVAL 1 // 1 millisecond

volatile sig_atomic_t program_running = 1;

// Structure to hold program state
typedef struct {
    int threshold;
    int high_count;
} ProgramState;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sound sensor
int read_sound_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to process the data and check for alert
int process_data(int high_count, int threshold) {
    return (high_count > threshold) ? 1 : 0;
}

// Function to print the alert message
void print_alert(int alert) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (alert) {
        printf("%s ALERT\n", buf);
    } else {
        printf("%s OK\n", buf);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    long threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    ProgramState state;
    state.threshold = (int)threshold;
    state.high_count = 0;

    while (program_running) {
        state.high_count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            int sensor_value = read_sound_sensor(GPIO_PIN);
            if (sensor_value == 1) {
                state.high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL);
        }

        int alert = process_data(state.high_count, state.threshold);
        print_alert(alert);
        gpioDelay(1000); // Pause for 1 second
    }

    gpioTerminate();
    return 0;
}

