#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define security code range
#define MIN_CODE 100000
#define MAX_CODE 999999

// Define unlock duration (seconds)
#define UNLOCK_DURATION 5

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int generate_security_code();
int unlock_door(int gpio_pin, int duration_seconds);
int lock_door(int gpio_pin);
int compare_codes(int entered_code, int generated_code);
int log_access(int generated_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
    }
}

// Function to generate a random security code
int generate_security_code() {
    return (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
}

// Function to unlock a door
int unlock_door(int gpio_pin, int duration_seconds) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d HIGH\n", gpio_pin);
        return -1;
    }
    gpioDelay(duration_seconds * 1000000); // Delay in microseconds
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d LOW\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to lock a door
int lock_door(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d LOW\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to compare entered code with generated code
int compare_codes(int entered_code, int generated_code) {
    return (entered_code == generated_code);
}

// Function to log access to a file
int log_access(int generated_code) {
    FILE *fp = fopen("access_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open access_log.txt for writing\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%06d\n", timestamp, generated_code);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(DOOR_A_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", DOOR_A_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(DOOR_B_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", DOOR_B_GPIO);
        gpioTerminate();
        return 1;
    }

    // Lock both doors initially
    if (lock_door(DOOR_A_GPIO) != 0 || lock_door(DOOR_B_GPIO) != 0) {
        fprintf(stderr, "Error: Failed to lock both doors initially\n");
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Generate a security code
        int generated_code = generate_security_code();
        printf("Generated code: %06d\n", generated_code);

        // Read user input
        int entered_code;
        if (scanf("%d", &entered_code) != 1) {
            fprintf(stderr, "Error: Invalid input. Please enter a number.\n");
            // Clear the input buffer
            while (getchar() != '\n');
            continue; // Skip to the next iteration
        }

        // Compare codes
        if (compare_codes(entered_code, generated_code)) {
            printf("Access granted!\n");

            // Unlock doors
            if (unlock_door(DOOR_A_GPIO, UNLOCK_DURATION) != 0 || unlock_door(DOOR_B_GPIO, UNLOCK_DURATION) != 0) {
                fprintf(stderr, "Error: Failed to unlock doors\n");
            } else {
                // Log access
                if (log_access(generated_code) != 0) {
                    fprintf(stderr, "Error: Failed to log access\n");
                }
            }
        } else {
            printf("Access denied!\n");
        }

        // Clear the input buffer
        while (getchar() != '\n');
    }

    // Cleanup
    printf("Cleaning up...\n");
