#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define the log file name
#define LOG_FILE "light_log.txt"

// Global variables for I2C handle and file pointer
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_bh1750(int i2c_handle, float *lux);
int log_data(FILE *log_file, float lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the I2C bus
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read illuminance from the BH1750FVI sensor
int read_bh1750(int i2c_handle, float *lux) {
    char config_cmd = 0x10; // Continuous high resolution mode
    char buffer[2];
    int result;

    // Write the configuration command to the sensor
    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for the measurement to complete (at least 180ms)
    gpioDelay(200); // Wait 200ms

    // Read two bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert the two bytes to a lux value
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to log the data to a file
int log_data(FILE *log_file, float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Write the data to the log file
    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    float lux;
    int result;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl-C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read the illuminance from the sensor
        result = read_bh1750(i2c_handle, &lux);
        if (result == 0) {
            // Log the data
            log_data(log_file, lux);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

