#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define PWM_FREQUENCY 440 // Initial frequency
#define PWM_DUTY_CYCLE 50  // 50% duty cycle
#define SERVER_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define FREQUENCY_LOG_FILE "frequency_log.txt"
#define TOUCH_SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_S 5

// Global variables
int i2c_handle;
int server_socket;
FILE *log_file;

// Function prototypes
int initialize_mpr121();
int read_touch_data(unsigned char *touch_data);
int process_touch_data(unsigned char *touch_data, int *electrode_values);
int calculate_frequency(int electrode_values[12]);
int play_tone(int frequency);
int handle_client(int client_socket);
void signal_handler(int signal);

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// Function to write a byte to an MPR121 register
int write_mpr121_register(int handle, unsigned char reg, unsigned char value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to MPR121 register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from an MPR121 register
int read_mpr121_register(int handle, unsigned char reg, unsigned char *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from MPR121 register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (unsigned char)result;
    return 0;
}

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (write_mpr121_register(i2c_handle, MPR121_SOFTRESET, 0x63) != 0) {
        fprintf(stderr, "Error resetting MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity (example values)
    for (int i = 0; i < 12; i++) {
        if (write_mpr121_register(i2c_handle, 0x41 + i, 0x10) != 0) { // Touch threshold
            fprintf(stderr, "Error setting touch threshold for electrode %d\n", i);
            return -1;
        }
        if (write_mpr121_register(i2c_handle, 0x4D + i, 0x0A) != 0) { // Release threshold
            fprintf(stderr, "Error setting release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    if (write_mpr121_register(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x3F) != 0) {
        fprintf(stderr, "Error configuring electrode enable\n");
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_touch_data(unsigned char *touch_data) {
    int result = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, (char *)touch_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading touch data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to process touch data and extract electrode values
int process_touch_data(unsigned char *touch_data, int *electrode_values) {
    electrode_values[0] = (touch_data[0] & 0x01) ? 1 : 0;
    electrode_values[1] = (touch_data[0] & 0x02) ? 1 : 0;
    electrode_values[2] = (touch_data[0] & 0x04) ? 1 : 0;
    electrode_values[3] = (touch_data[0] & 0x08) ? 1 : 0;
    electrode_values[4] = (touch_data[0] & 0x10) ? 1 : 0;
    electrode_values[5] = (touch_data[0] & 0x20) ? 1 : 0;
    electrode_values[6] = (touch_data[0] & 0x40) ? 1 : 0;
    electrode_values[7] = (touch_data[0] & 0x80) ? 1 : 0;
    electrode_values[8] = (touch_data[1] & 0x01) ? 1 : 0;
    electrode_values[9] = (touch_data[1] & 0x02) ? 1 : 0;
    electrode_values[10] = (touch_data[1] & 0x04) ? 1 : 0;
    electrode_values[11] = (touch_data[1] & 0x08) ? 1 : 0;
    return 0;
}

// Function to calculate the frequency based on electrode values
int calculate_frequency(int electrode_values[12]) {
    // Simple frequency mapping: electrode 0 increases frequency, electrode 1 decreases frequency
    int frequency = PWM_FREQUENCY;
    if (electrode_values[0]) {
        frequency += 10; // Increase frequency
    }
    if (electrode_values[1]) {
        frequency -= 10; // Decrease frequency
    }

    // Clamp frequency within reasonable bounds
    if (frequency < 200) frequency = 200;
    if (frequency > 1000) frequency = 1000;

    return frequency;
}

// Function to play a PWM tone
int play_tone(int frequency) {
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, PWM_DUTY_CYCLE); // Set duty cycle
    return 0;
}

// Function to handle client connection
int handle_client(int client_socket) {
    char buffer[256];
    ssize_t bytes_received;
    int frequency;
    int electrode_values[12];

    // Receive data from client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        return -1;
    }
    buffer[bytes_received] = '\0';

    // Check for authentication
    if (strncmp(buffer, "MOTION_DETECTED:", 16) != 0) {
        fprintf(stderr, "Authentication failed\n");
        const char *response = "Authentication failed\n";
        send(client_socket, response, strlen(response), 0);
        return -1;
    }

    // Extract shared secret
    char *secret_start = strstr(buffer, SHARED_SECRET);
    if (secret_start == NULL) {
        fprintf(stderr, "Shared secret not found\n");
        const char *response = "Shared secret not found\n";
        send(client_socket, response, strlen(response), 0);
        return -1;
    }

    // Playback loop
    for (int i = 0; i < PLAYBACK_DURATION_S * 1000 / TOUCH_SAMPLE_INTERVAL_MS; i++) {
        // Read touch data
        unsigned char touch_data[2];
        if (read_touch_data(touch_data) != 0) {
            fprintf(stderr, "Error reading touch data during playback\n");
            break;
        }

        // Process touch data
        if (process_touch_data(touch_data, electrode_values) != 0) {
            fprintf(stderr, "Error processing touch data during playback\n");
            break;
        }

        // Calculate frequency
        frequency = calculate_frequency(electrode_values);

        // Play tone
        if (play_tone(frequency) != 0) {
            fprintf(stderr, "Error playing tone during playback\n");
            break;
        }

        // Log frequency
        fprintf(log_file, "%d\n", frequency);
        fflush(log_file);

        // Wait for the next sample
        gpioDelay(TOUCH_SAMPLE_INTERVAL_MS);
    }

    // Stop PWM output
    gpioPWM(PWM_PIN, 0);

    // Send response
    const char *response = "Tone played successfully\n";
    send(client_socket, response, strlen(response), 0);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, shutting down...\n");

    // Stop PWM output
    gpioPWM(PWM_PIN, 0);

    // Close I2C interface
    i2cClose(i2c_handle);

    // Close server socket
    close(server_socket);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C interface: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(FREQUENCY_LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create server socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for incoming connections
    if (listen(server_socket, 5) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Accept incoming connections and handle them
    while (1) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        if (handle_client(client_socket) != 0) {
            fprintf(stderr, "Error handling client\n");
        }

        close(client_socket);
    }

    return 0;
}

