#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x09
#define OUT_Y_L_M 0x0A
#define OUT_Y_H_M 0x0B
#define OUT_Z_L_M 0x0C
#define OUT_Z_H_M 0x0D
#define CTRL_REG1_M 0x20
#define CTRL_REG2_M 0x21
#define CTRL_REG3_M 0x22

// GPIO pin for LED (BCM numbering)
#define LED_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int initialize_magnetometer();
magnetometer_data_t read_magnetometer_data();
double calculate_magnitude(magnetometer_data_t data);
void set_led_brightness(double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the LSM303DLHC magnetometer
int initialize_magnetometer() {
    // Enable continuous conversion mode and set data rate (e.g., 50 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_M, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_M\n");
        return -1;
    }

    // Set gain (e.g., +/- 1.3 Gauss)
    if (i2cWriteByteData(i2c_handle, CTRL_REG2_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2_M\n");
        return -1;
    }

    // Enable I2C (optional, but good practice)
    if (i2cWriteByteData(i2c_handle, CTRL_REG3_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3_M\n");
        return -1;
    }

    return 0;
}

// Reads magnetometer data from the LSM303DLHC
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculates the magnitude of the magnetic field vector
double calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Sets the LED brightness using hardware PWM
void set_led_brightness(double magnitude) {
    // Map the magnitude to a PWM duty cycle (0-255)
    int duty_cycle = (int)(magnitude * 255.0 / 1000.0); // Assuming max magnitude of 1000 Gauss
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(LED_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the magnetometer
    if (initialize_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(LED_PIN, 1000);

    // Set PWM range (0-255)
    gpioSetPWMrange(LED_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data();

        // Calculate magnitude
        double magnitude = calculate_magnitude(data);

        // Set LED brightness
        set_led_brightness(magnitude);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    gpioPWM(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

