#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set continuous measurement mode.\n");
        return -1;
    }

    // Set gain (example: +/- 1.3 Ga)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error: Could not set gain.\n");
        return -1;
    }

    // Set data output rate (example: 8 Hz)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error: Could not set data output rate.\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read magnetometer data.\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to calculate the running average of magnetometer data
magnetometer_data_t calculate_running_average(magnetometer_data_t *data, int num_samples, int *index, magnetometer_data_t *running_average) {
    running_average->x = 0;
    running_average->y = 0;
    running_average->z = 0;

    // Subtract the oldest sample from the running total
    running_average->x -= data[*index];
    running_average->y -= data[*index];
    running_average->z -= data[*index];

    // Add the new sample to the running total
    running_average->x += data[(*index + 1) % num_samples];
    running_average->y += data[(*index + 1) % num_samples];
    running_average->z += data[(*index + 1) % num_samples];

    // Update the index
    *index = (*index + 1) % num_samples;

    // Calculate the average
    running_average->x /= num_samples;
    running_average->y /= num_samples;
    running_average->z /= num_samples;

    return *running_average;
}

// Function to apply hard iron offsets
magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t data, magnetometer_data_t offset) {
    data.x -= offset.x;
    data.y -= offset.y;
    data.z -= offset.z;
    return data;
}

int main() {
