    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Data buffer for running average
    magnetometer_data_t data_buffer[100];
    int data_index = 0;
    magnetometer_data_t running_average = {0, 0, 0};

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data();

        // Store raw data in the buffer
        data_buffer[data_index] = raw_data;

        // Calculate running average
        calculate_running_average(data_buffer, 100, &data_index, &running_average);

        // Apply hard iron offsets
        magnetometer_data_t offset_corrected_data = apply_hard_iron_offsets(raw_data, running_average);

        // Print offset-corrected data
        printf("X: %d, Y: %d, Z: %d\n", offset_corrected_data.x, offset_corrected_data.y, offset_corrected_data.z);

        // Wait 500 ms
        gpioDelay(500000); // pigpioDelay takes microseconds
