#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_OUT_X_H_A 0x29
#define LSM303D_OUT_Y_L_A 0x2A
#define LSM303D_OUT_Y_H_A 0x2B
#define LSM303D_OUT_Z_L_A 0x2C
#define LSM303D_OUT_Z_H_A 0x2D
#define LSM303D_INT1_CFG 0x30
#define LSM303D_INT1_THS 0x32
#define LSM303D_INT1_DURATION 0x33
#define LSM303D_WHO_AM_I 0x0F

// Sensitivity
#define SENSITIVITY 0.061 // mg/LSB

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    time_t timestamp;
    float x, y, z;
} AccelData;

// Circular buffer
AccelData buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_lsm303d();
int read_acceleration(float *x, float *y, float *z);
void dump_buffer();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to initialize the LSM303D
int init_lsm303d() {
    // Verify device ID
    int who_am_i = i2cReadByteData(i2c_handle, LSM303D_WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x49) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
        return -1;
    }

    // Enable accelerometer, 100 Hz data rate, +/- 2g full scale
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG1_A\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG4_A\n");
        return -1;
    }

    // Configure interrupt 1 for high-resolution mode and enable interrupt on INT1 pin
    if (i2cWriteByteData(i2c_handle, LSM303D_INT1_CFG, 0x40) < 0) {
        fprintf(stderr, "Error: Could not write to INT1_CFG\n");
        return -1;
    }

    // Set interrupt threshold (2000 mg)
    if (i2cWriteByteData(i2c_handle, LSM303D_INT1_THS, 0x70) < 0) {
        fprintf(stderr, "Error: Could not write to INT1_THS\n");
        return -1;
    }

    // Set interrupt duration (0 for immediate trigger)
    if (i2cWriteByteData(i2c_handle, LSM303D_INT1_DURATION, 0x00) < 0) {
        fprintf(stderr, "Error: Could not write to INT1_DURATION\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, LSM303D_OUT_X_L_A | 0x80, raw_data, 6) < 0) {
        fprintf(stderr, "Error: Could not read acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    *x = (float)x_raw * SENSITIVITY / 1000.0; // Convert to g
    *y = (float)y_raw * SENSITIVITY / 1000.0;
    *z = (float)z_raw * SENSITIVITY / 1000.0;

    return 0;
}

// Function to dump the circular buffer
void dump_buffer() {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index - BUFFER_SIZE + i + BUFFER_SIZE) % BUFFER_SIZE; // Ensure positive index
        printf("[%d] X: %.3f g, Y: %.3f g, Z: %.3f g ", i, buffer[index].x, buffer[index].y, buffer[index].z);
    }
    printf("\n");
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        dump_buffer();
    }
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() < 0) {
        fprintf(stderr, "Error: LSM303D initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set interrupt handler
    gpioSetAlertFuncEx(23, interrupt_handler, NULL); // GPIO 23 (BCM)

    // Set signal handler
    signal(SIGINT, signal_handler);

    float x, y, z;
    time_t now;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            now = time(NULL);
            buffer[buffer_index].timestamp = now;
            buffer[buffer_index].x = x;
            buffer[buffer_index].y = y;
            buffer[buffer_index].z = z;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            fprintf(stderr, "Warning: Failed to read acceleration data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Disable accelerometer
    i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG1_A, 0x00);

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

