#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Function prototypes
int initialize_gpio();
void set_solenoid_state(int pin, int state);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Activate solenoid 1
        set_solenoid_state(SOLENOID_1_PIN, 1);
        gpioDelay(500000); // 500 ms

        // Activate solenoid 2
        set_solenoid_state(SOLENOID_2_PIN, 1);
        gpioDelay(500000); // 500 ms

        // Deactivate both solenoids
        set_solenoid_state(SOLENOID_1_PIN, 0);
        set_solenoid_state(SOLENOID_2_PIN, 0);
        gpioDelay(500000); // 500 ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

// Initializes the pigpio library and sets the GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Ensure both solenoids are initially off
    set_solenoid_state(SOLENOID_1_PIN, 0);
    set_solenoid_state(SOLENOID_2_PIN, 0);

    return 0;
}

// Sets the state of a solenoid (1 for ON, 0 for OFF)
void set_solenoid_state(int pin, int state) {
    gpioWrite(pin, state);
}

// Cleans up the pigpio library and sets the GPIO pins as inputs
void cleanup_gpio() {
    // Set both solenoid pins as inputs to avoid accidental activation
    gpioSetMode(SOLENOID_1_PIN, PI_INPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_INPUT);

    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0; // Stop the main loop
    cleanup_gpio();       // Release GPIO resources
    exit(0);
}

