    // Ensure both solenoids are initially off
    set_solenoid_state(SOLENOID_1_PIN, 0);
    set_solenoid_state(SOLENOID_2_PIN, 0);

    return 0;
}

// Sets the state of a solenoid (1 for ON, 0 for OFF)
void set_solenoid_state(int pin, int state) {
    gpioWrite(pin, state);
}

// Cleans up the pigpio library and sets the GPIO pins as inputs
void cleanup_gpio() {
    // Set both solenoid pins as inputs to avoid accidental activation
    gpioSetMode(SOLENOID_1_PIN, PI_INPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_INPUT);

    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0; // Stop the main loop
    cleanup_gpio();       // Release GPIO resources
    exit(0);
}

