#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define RELAY1_PIN 17
#define RELAY2_PIN 27

// Define UART ports
#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout (in seconds)
#define TIMEOUT 5

// Define expected code
#define EXPECTED_CODE "123456"

// Define code length
#define CODE_LENGTH 6

// Global variables
int primary_uart_handle = -1;
int secondary_uart_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int open_uart(const char *port);
int read_code(int uart_handle, char *code, int timeout_sec);
int compare_codes(const char *code1, const char *code2);
int control_relays(int state);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);

    return 0;
}

// Function to open UART port
int open_uart(const char *port) {
    int handle = serOpen(port, BAUD_RATE, 0); // 0 for default flags (8N1)
    if (handle < 0) {
        fprintf(stderr, "Failed to open UART %s: %d\n", port, handle);
        return -1;
    }
    return handle;
}

// Function to read code from UART port
int read_code(int uart_handle, char *code, int timeout_sec) {
    time_t start_time = time(NULL);
    int i = 0;

    while (1) {
        if (time(NULL) - start_time > timeout_sec) {
            fprintf(stderr, "Timeout reading from UART\n");
            return -1; // Timeout
        }

        int c = serReadByte(uart_handle);
        if (c >= 0) {
            if (c >= '0' && c <= '9') {
                code[i++] = (char)c;
                if (i >= CODE_LENGTH) {
                    code[i] = '\0';
                    return 0; // Code complete
                }
            } else {
                // Reset buffer on non-digit character
                i = 0;
            }
        } else {
            // Handle error or no data
            gpioDelay(1000); // Small delay to avoid busy-waiting
        }
    }
}

// Function to compare codes (constant-time comparison)
int compare_codes(const char *code1, const char *code2) {
    int result = 0;
    for (int i = 0; i < CODE_LENGTH; i++) {
        result |= (code1[i] ^ code2[i]);
    }
    return (result == 0);
}

// Function to control relays
int control_relays(int state) {
    if (gpioWrite(RELAY1_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY1_PIN);
        return -1;
    }
    if (gpioWrite(RELAY2_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY2_PIN);
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Force relays to LOW (locked state)
    control_relays(0);

    // Close UART ports
    if (primary_uart_handle >= 0) {
        serClose(primary_uart_handle);
    }
    if (secondary_uart_handle >= 0) {
        serClose(secondary_uart_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open UART ports
    primary_uart_handle = open_uart(PRIMARY_UART);
    if (primary_uart_handle < 0) {
        cleanup();
        return 1;
    }

    secondary_uart_handle = open_uart(SECONDARY_UART);
    if (secondary_uart_handle < 0) {
        cleanup();
        return 1;
    }

    char primary_code[CODE_LENGTH + 1];
    char secondary_code[CODE_LENGTH + 1];

    printf("Authentication system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read codes from UART ports
        memset(primary_code, 0, sizeof(primary_code));
        memset(secondary_code, 0, sizeof(secondary_code));

        if (read_code(primary_uart_handle, primary_code, TIMEOUT) != 0) {
            fprintf(stderr, "Error reading from primary UART\n");
            continue; // Try again
        }

        if (read_code(secondary_uart_handle, secondary_code, TIMEOUT) != 0) {
            fprintf(stderr, "Error reading from secondary UART\n");
            continue; // Try again
        }

        // Compare codes
        if (compare_codes(primary_code, secondary_code)) {
            if (compare_codes(primary_code, EXPECTED_CODE)) {
                printf("Codes match and are correct. Unlocking doors.\n");
                if (control_relays(1) == 0) {
                    gpioDelay(2000); // Keep relays HIGH for 2 seconds
                    control_relays(0);
                } else {
                    fprintf(stderr, "Failed to unlock doors\n");
                }
            } else {
                printf("Codes match, but are incorrect.\n");
            }
        } else {
            printf("Codes do not match.\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

