#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLL_INTERVAL_MS 50
#define RELAY_ON_TIME_S 1
#define MOTION_DURATION_S 10

// Global variables
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
void log_event(int priority, const char *message);
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    log_event(LOG_INFO, "GPIO initialisation successful");
    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    char message[50];
    snprintf(message, sizeof(message), "Relay set to %d", state);
    log_event(LOG_INFO, message);
    return 0;
}

// Function to log events
void log_event(int priority, const char *message) {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    log_event(LOG_INFO, "Cleaning up GPIO and exiting");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event(LOG_INFO, "Signal received, shutting down...");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    time_t motion_start_time = 0;
    int motion_detected = 0;

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            if (!motion_detected) {
                motion_detected = 1;
                motion_start_time = time(NULL);
                log_event(LOG_INFO, "Motion detected!");
                control_relay(1); // Activate relay
            } else {
                // Check if motion has been continuous for MOTION_DURATION_S
                if (time(NULL) - motion_start_time >= MOTION_DURATION_S) {
                    log_event(LOG_WARNING, "Potential malfunction: Motion detected continuously.");
                    control_relay(0); // Deactivate relay
                    log_event(LOG_CRIT, "System shutdown due to potential malfunction.");
                    running = 0; // Exit the loop
                }
            }
        } else {
            if (motion_detected) {
                motion_detected = 0;
                control_relay(0); // Deactivate relay
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for POLL_INTERVAL_MS milliseconds
    }

    cleanup_gpio();
    return 0;
}

