#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define relay activation time (seconds)
#define RELAY_ACTIVATION_TIME 300

// Define pause time (seconds)
#define PAUSE_TIME 60

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_relay(int gpio);
void deactivate_relay(int gpio);
void log_message(int priority, const char *message);
void timer_callback();
void signal_handler(int signal);

// Structure to hold relay GPIO pins
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} RelayPins;

RelayPins relay_pins = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    // Set up timer callback
    if (gpioSetTimerFuncEx(0, 60000, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set up timer callback. Exiting.");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup and exit
    gpioTerminate();
    closelog();
    return 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set all relays to OFF (HIGH)
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    gpioWrite(RELAY1_GPIO, 1);
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);

    log_message(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Function to activate a relay
void activate_relay(int gpio) {
    gpioWrite(gpio, 0); // Active LOW
    char message[100];
    snprintf(message, sizeof(message), "Relay %d activated", gpio);
    log_message(LOG_INFO, message);
}

// Function to deactivate a relay
void deactivate_relay(int gpio) {
    gpioWrite(gpio, 1); // Active LOW
    char message[100];
    snprintf(message, sizeof(message), "Relay %d deactivated", gpio);
    log_message(LOG_INFO, message);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char log_message_with_timestamp[200];
    snprintf(log_message_with_timestamp, sizeof(log_message_with_timestamp), "%s: %s", timestamp, message);
    syslog(priority, "%s", log_message_with_timestamp);
}

// Timer callback function
void timer_callback() {
    static int current_relay = 1; // Start with relay 1

    // Deactivate the current relay
    deactivate_relay(relay_pins.relay1 + current_relay - 1);

    // Activate the next relay
    current_relay++;
    if (current_relay > 4) {
        current_relay = 1;
    }

    activate_relay(relay_pins.relay1 + current_relay - 1);

    // Set up the next timer callback after the pause
    gpioSetTimerFuncEx(0, PAUSE_TIME * 1000, timer_callback, NULL);
}

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;

    // Deactivate all relays
    deactivate_relay(relay_pins.relay1);
    deactivate_relay(relay_pins.relay2);
    deactivate_relay(relay_pins.relay3);
    deactivate_relay(relay_pins.relay4);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    exit(0);
}

