#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68 // Or 0x69, check your sensor
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define PWR_MGMT_1 0x6B
#define SAMPLE_RATE 100 // Hz
#define BUFFER_SIZE 100
#define SENSITIVITY 16384.0f // LSB/g for +/- 2g range
#define GRAVITY 9.81f

// Data structure for accelerometer readings
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Circular buffer structure
typedef struct {
    accelerometer_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int mpu6050_init(int fd);
int read_accelerometer_data(int fd, accelerometer_data_t *data);
void circular_buffer_init(circular_buffer_t *buffer);
void circular_buffer_add(circular_buffer_t *buffer, accelerometer_data_t data);
bool circular_buffer_get_latest(circular_buffer_t *buffer, accelerometer_data_t *data);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050 (clear sleep bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Set to 0 to wake up

    if (write(fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, accelerometer_data_t *data) {
    uint8_t reg = ACCEL_XOUT_H;
    uint8_t buffer[6];

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to register");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to g-force units
    data->x = (float)x / SENSITIVITY * GRAVITY;
    data->y = (float)y / SENSITIVITY * GRAVITY;
    data->z = (float)z / SENSITIVITY * GRAVITY;

    return 0;
}

// Circular buffer initialization function
void circular_buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Circular buffer add function
void circular_buffer_add(circular_buffer_t *buffer, accelerometer_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Circular buffer get latest function
bool circular_buffer_get_latest(circular_buffer_t *buffer, accelerometer_data_t *data) {
    if (buffer->count > 0) {
        int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        *data = buffer->data[index];
        return true;
    } else {
        return false;
    }
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize MPU6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    circular_buffer_init(&buffer);

    // Set up timer
    struct sigevent sev;
    struct itimerspec its;
    timer_t timerid;

    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    sev.sigev_value.sival_ptr = &timerid;

    if (timer_create(CLOCK_REALTIME, &sev, &timerid) == -1) {
        perror("timer_create");
        close(i2c_fd);
        return 1;
    }

    // Configure timer interval
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10 ms (100 Hz)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10 ms (100 Hz)

    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        perror("timer_settime");
        close(i2c_fd);
        timer_delete(timerid);
        return 1;
    }

    // Main loop
    accelerometer_data_t data;
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &data) == 0) {
            // Add data to circular buffer
            circular_buffer_add(&buffer, data);
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying.\n");
        }

        // Check for latest data
        accelerometer_data_t latest_data;
        if (circular_buffer_get_latest(&buffer, &latest_data)) {
            printf("Latest X: %.2f g, Y: %.2f g, Z: %.2f g\n", latest_data.x, latest_data.y, latest_data.z);
        }

        // Wait for the next timer event
        pause();
    }

    // Cleanup
    timer_delete(timerid);
    close(i2c_fd);

    return 0;
}

