// Define GPIO pins for the relays
#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define relay activation times in seconds
#define RELAY1_TIME 2
#define RELAY2_TIME 3
#define RELAY3_TIME 5
#define RELAY4_TIME 7

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to toggle a relay
int toggle_relay(int gpio_pin) {
    int current_level = gpioRead(gpio_pin);
    int new_level = (current_level == 0) ? 1 : 0;

    if (gpioWrite(gpio_pin, new_level) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to turn off all relays
void turn_off_all_relays() {
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioWrite(RELAY3_GPIO, 0);
    gpioWrite(RELAY4_GPIO, 0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Relay 1
        if (toggle_relay(RELAY1_GPIO) != 0) {
            turn_off_all_relays();
            break;
        }
        gpioDelay(RELAY1_TIME * 1000000); // Delay in microseconds

        // Relay 2
        if (toggle_relay(RELAY2_GPIO) != 0) {
            turn_off_all_relays();
            break;
        }
        gpioDelay(RELAY2_TIME * 1000000); // Delay in microseconds

        // Relay 3
        if (toggle_relay(RELAY3_GPIO) != 0) {
            turn_off_all_relays();
            break;
        }
        gpioDelay(RELAY3_TIME * 1000000); // Delay in microseconds

        // Relay 4
        if (toggle_relay(RELAY4_GPIO) != 0) {
            turn_off_all_relays();
            break;
        }
        gpioDelay(RELAY4_TIME * 1000000); // Delay in microseconds
    }

    // Turn off all relays before exiting
    turn_off_all_relays();

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

