#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47
#define GYRO_CONFIG  0x1B

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_fd;
bool running = true;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_gyro_data(int fd, float *x, float *y, float *z);
float calculate_angular_velocity(float x, float y, float z);
void add_to_buffer(CircularBuffer *cb, float value);
float get_average_from_buffer(CircularBuffer *cb);
void check_threshold(float avg_angular_velocity);
void signal_handler(int signal);
void init_circular_buffer(CircularBuffer *cb);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    raw_x = (int16_t)((i2c_read_reg(fd, GYRO_XOUT_H) << 8) | i2c_read_reg(fd, GYRO_XOUT_H + 1));
    raw_y = (int16_t)((i2c_read_reg(fd, GYRO_YOUT_H) << 8) | i2c_read_reg(fd, GYRO_YOUT_H + 1));
    raw_z = (int16_t)((i2c_read_reg(fd, GYRO_ZOUT_H) << 8) | i2c_read_reg(fd, GYRO_ZOUT_H + 1));

    // Convert to degrees per second (dps) - assuming sensitivity of 131 LSB/dps
    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;

    return 0;
}

// Function to calculate the magnitude of the angular velocity vector
float calculate_angular_velocity(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to add a new value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average of the values in the circular buffer
float get_average_from_buffer(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to check if the average angular velocity exceeds the threshold
void check_threshold(float avg_angular_velocity) {
    if (avg_angular_velocity > 50.0) {
        printf("Threshold exceeded! Average angular velocity: %.2f degrees/second\n", avg_angular_velocity);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize circular buffer
    CircularBuffer angular_velocity_buffer;
    init_circular_buffer(&angular_velocity_buffer);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU-6050
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    // Configure gyroscope sensitivity
    if (i2c_write_reg(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring gyroscope sensitivity\n");
        close(i2c_fd);
        return 1;
    }

    float x, y, z, avg_angular_velocity;

    // Main loop
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate angular velocity
            float angular_velocity = calculate_angular_velocity(x, y, z);

            // Add to circular buffer
            add_to_buffer(&angular_velocity_buffer, angular_velocity);

            // Calculate average angular velocity
            avg_angular_velocity = get_average_from_buffer(&angular_velocity_buffer);

            // Check threshold
            check_threshold(avg_angular_velocity);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        // Delay for 10 milliseconds
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

