    fd_set readfds;
    int retval;

    // Send command
    if (serWrite(uart_handle, command, sizeof(command)) != sizeof(command)) {
        log_error("Failed to write command to UART");
        return -1;
    }

    // Wait for response with timeout
    FD_ZERO(&readfds);
    FD_SET(uart_handle, &readfds);

    gettimeofday(&start_time, NULL);
    retval = select(uart_handle + 1, &readfds, NULL, NULL, &(struct timeval){TIMEOUT_MS / 1000, (TIMEOUT_MS % 1000) * 1000});

    if (retval == -1) {
        perror("select()");
        log_error("select() error");
        return -1;
    } else if (retval == 0) {
        log_error("Timeout waiting for response");
        return -1;
    }

    // Read response
    bytes_read = 0;
    while (bytes_read < sizeof(response)) {
        int result = serRead(uart_handle, response + bytes_read, sizeof(response) - bytes_read);
        if (result > 0) {
            bytes_read += result;
        } else if (result < 0) {
            log_error("Error reading from UART");
            return -1;
        } else {
            // Timeout or no data available
            break;
        }
    }

    if (bytes_read != sizeof(response)) {
        log_error("Incomplete response received");
        return -1;
    }

    // Validate checksum
    if (!validate_checksum(response, sizeof(response))) {
        log_error("Checksum mismatch");
        return -1;
    }

    // Extract PPM value
    *ppm = (response[2] << 8) | response[3];

    return 0;
}

// Validate checksum
int validate_checksum(unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 1; i < len - 1; i++) {
        checksum += data[i];
    }
    return (checksum == data[len - 1]);
}

// Log data to file
int log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": %d}\n", timestamp, data.ppm, data.error);
    fflush(log_file);

    printf("{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": %d}\n", timestamp, data.ppm, data.error);

    return 0;
}

// Log error to file
int log_error(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

int main() {
    int ppm;
    sensor_data_t data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen("co2_log.json", "a");
    if (log_file == NULL) {
        perror("Failed to open co2_log.json");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen("co2_error.log", "a");
    if (error_log_file == NULL) {
        perror("Failed to open co2_error.log");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_mhz19b(&ppm) == 0) {
            // Get timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            data.timestamp_us = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
            data.ppm = ppm;
            data.error = 0;

            // Log data
            log_data(data);
        } else {
            // Log error
            data.timestamp_us = 0; // Indicate error
            data.ppm = 0;
            data.error = 1;
            log_data(data);
        }

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    serClose(uart_handle);
    fclose(log_file);
    fclose(error_log_file);
    gpioTerminate();

    return 0;
}

