#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Hard iron compensation offsets
#define X_OFFSET 100.0
#define Y_OFFSET -50.0

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_hmc5883l();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
float compensate_heading(int16_t x, int16_t y);
void update_circular_buffer(CircularBuffer *cb, float heading);
float calculate_average_heading(CircularBuffer *cb);
void set_gpio_output(float deviation);
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize the HMC5883L
int init_hmc5883l() {
    // Set configuration register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Set configuration register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set mode register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read raw magnetometer data
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Compensate heading using hard iron offsets
float compensate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)(y - Y_OFFSET), (float)(x - X_OFFSET)) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Update circular buffer with new heading
void update_circular_buffer(CircularBuffer *cb, float heading) {
    cb->buffer[cb->head] = heading;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average heading from circular buffer
float calculate_average_heading(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Set GPIO output based on heading deviation
void set_gpio_output(float deviation) {
    if (fabs(deviation) > 10.0) {
        gpioWrite(GPIO_PIN, 1); // Set high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set low
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer heading_buffer;
    init_circular_buffer(&heading_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    float heading, average_heading, deviation;

    while (!terminate) {
        // Read raw data
        if (read_raw_data(&x, &y, &z) == 0) {
            // Compensate heading
            heading = compensate_heading(x, y);

            // Update circular buffer
            update_circular_buffer(&heading_buffer, heading);

            // Calculate average heading
            average_heading = calculate_average_heading(&heading_buffer);

            // Calculate deviation from target heading
            deviation = average_heading - TARGET_HEADING;
            if (deviation < 0) {
                deviation += 360.0;
            }

            // Set GPIO output
            set_gpio_output(deviation);

            // Print heading and deviation (for debugging)
            printf("Heading: %.2f, Deviation: %.2f\n", average_heading, deviation);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set low before exiting
    gpioTerminate();

    return 0;
}

