// Define lux thresholds
#define LUX_THRESHOLD_RED   50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE  300

// Define I2C bus
#define I2C_BUS 1

// Global variables
int fd1 = -1, fd2 = -1; // File descriptors for I2C devices
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_bh1750(int fd);
void control_rgb_lamp(int lux);
void log_data(int lux1, int lux2, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
int initialize_i2c(int address);

// Function to initialize I2C
int initialize_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C device at address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int fd) {
    if (wiringPiI2CWrite(fd, 0x10) == -1) { // Start measurement in high resolution mode
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    delay(120); // Wait for measurement

    int msb = wiringPiI2CReadReg8(fd, 0x00);
    int lsb = wiringPiI2CReadReg8(fd, 0x01);

    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw_value = (msb << 8) | lsb;
    return (int)(raw_value / 1.2); // Convert to lux
}

// Function to control RGB lamp based on lux value
void control_rgb_lamp(int lux) {
    if (lux < LUX_THRESHOLD_RED) {
        digitalWrite(RED_PIN, HIGH);
        digitalWrite(GREEN_PIN, LOW);
        digitalWrite(BLUE_PIN, LOW);
    } else if (lux >= LUX_THRESHOLD_RED && lux < LUX_THRESHOLD_GREEN) {
        digitalWrite(RED_PIN, LOW);
        digitalWrite(GREEN_PIN, HIGH);
        digitalWrite(BLUE_PIN, LOW);
    } else if (lux >= LUX_THRESHOLD_GREEN && lux < LUX_THRESHOLD_BLUE) {
        digitalWrite(RED_PIN, LOW);
        digitalWrite(GREEN_PIN, LOW);
        digitalWrite(BLUE_PIN, HIGH);
    } else {
        digitalWrite(RED_PIN, HIGH);
        digitalWrite(GREEN_PIN, HIGH);
        digitalWrite(BLUE_PIN, HIGH);
    }
}

// Function to log data to file
void log_data(int lux1, int lux2, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp, lux1, lux2, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C devices
    fd1 = initialize_i2c(BH1750_ADDR_1);
    if (fd1 == -1) {
        fprintf(stderr, "Failed to initialize BH1750 sensor 1. Continuing without it.\n");
    }

    fd2 = initialize_i2c(BH1750_ADDR_2);
    if (fd2 == -1) {
        fprintf(stderr, "Failed to initialize BH1750 sensor 2. Continuing without it.\n");
    }

    // Set GPIO pins as output
    pinMode(RED_PIN, OUTPUT);
    pinMode(GREEN_PIN, OUTPUT);
    pinMode(BLUE_PIN, OUTPUT);

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting lighting control program. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int lux1 = -1, lux2 = -1;
        int red_state = 0, green_state = 0, blue_state = 0;

        // Read lux values from sensors
        if (fd1 != -1) {
            lux1 = read_bh1750(fd1);
            if (lux1 == -1) {
                fprintf(stderr, "Error reading from sensor 1. Setting lux to -1.\n");
                lux1 = -1; // Set to -1 to indicate error
            }
        }

        if (fd2 != -1) {
            lux2 = read_bh1750(fd2);
            if (lux2 == -1) {
                fprintf(stderr, "Error reading from sensor 2. Setting lux to -1.\n");
                lux2 = -1; // Set to -1 to indicate error
            }
        }

        // Control RGB lamp
        if (lux1 != -1 || lux2 != -1) {
            int max_lux = (lux1 == -1) ? lux2 : ((lux2 == -1) ? lux1 : (lux1 > lux2 ? lux1 : lux2));
            control_rgb_lamp(max_lux);

            red_state   = digitalRead(RED_PIN);
            green_state = digitalRead(GREEN_PIN);
            blue_state  = digitalRead(BLUE_PIN);
        }

        // Log data
        log_data(lux1, lux2, red_state, green_state, blue_state);

        delay(1000); // Wait for 1 second
    }

    // Cleanup
    if (fd1 != -1) {
        close(fd1);
    }
    if (fd2 != -1) {
        close(fd2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    digitalWrite(RED_PIN, LOW);
    digitalWrite(GREEN_PIN, LOW);
    digitalWrite(BLUE_PIN, LOW);

    printf("Exiting.\n");
    return 0;
}

