#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Distance range for proportional control
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Proportional gain
#define KP 50.0

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, stopping motors and cleaning up...\n");
}

// Function to set motor direction and PWM duty cycle
void set_motor_speed(int in1_pin, int in2_pin, int in3_pin, int in4_pin, int distance) {
    if (distance < 50) {
        // Forward
        gpioWrite(in1_pin, 1);
        gpioWrite(in3_pin, 1);

        // Proportional control
        int duty_cycle = (int)((KP * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) + 0.5); // Round to nearest integer
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;

        gpioPWM(in2_pin, duty_cycle);
        gpioPWM(in4_pin, duty_cycle);
    } else {
        // Backward
        gpioWrite(in1_pin, 0);
        gpioWrite(in3_pin, 0);

        // Proportional control
        int duty_cycle = (int)((KP * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) + 0.5); // Round to nearest integer
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;

        gpioPWM(in2_pin, duty_cycle);
        gpioPWM(in4_pin, duty_cycle);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    if (distance_a < MIN_DISTANCE || distance_a > MAX_DISTANCE || distance_b < MIN_DISTANCE || distance_b > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance values must be between %d and %d cm.\n", MIN_DISTANCE, MAX_DISTANCE);
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (!terminate) {
        set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, distance_a);
        set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, distance_b);
        gpioDelay(100); // 100 ms delay
    }

    // Stop motors and cleanup
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    gpioTerminate();

    return 0;
}

