#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// Servo PWM channel
#define SERVO_PWM_CHANNEL 0

// PWM chip and channel paths
#define PWM_CHIP_PATH "/sys/class/pwm/pwmchip2"
#define PWM_EXPORT_PATH PWM_CHIP_PATH "/export"
#define PWM_UNEXPORT_PATH PWM_CHIP_PATH "/unexport"
#define PWM_PERIOD_PATH PWM_CHIP_PATH "/pwm0/period"
#define PWM_DUTY_CYCLE_PATH PWM_CHIP_PATH "/pwm0/duty_cycle"
#define PWM_ENABLE_PATH PWM_CHIP_PATH "/pwm0/enable"

// Log file path
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int init_mpu6050(int fd);
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_position(int position);
void log_data(float pitch, float roll, int position);
void signal_handler(int signal);
int export_pwm(void);
int unexport_pwm(void);
int set_pwm_period(int period_ns);
int set_pwm_duty_cycle(int duty_cycle_ns);
int enable_pwm(int enable);

// I2C read function with error handling and exponential backoff
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int delay_ms = 1;
    int result;

    while (retries < 5) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device: %s (read %d bytes, expected %d)\n", strerror(errno), result, len);
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "Failed to read from I2C after multiple retries.\n");
    return -1; // Failure
}

// I2C write function with error handling and exponential backoff
