#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the log file name
#define LOG_FILE "lighting_log.txt"

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define the fade duration (seconds)
#define FADE_DURATION 1800

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries);
int validate_schedule(schedule_entry_t *schedule, int num_entries);
int calculate_fade_time(int current_time, int schedule_time, int fade_duration);
int control_relay(int relay_number, int on_off);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read the lighting schedule from a file
int read_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    // Count the number of lines in the file
    int line_count = 0;
    char ch;
    while ((ch = fgetc(fp)) != EOF) {
        if (ch == '\n') {
            line_count++;
        }
    }
    rewind(fp);

    // Allocate memory for the schedule entries
    *schedule = (schedule_entry_t *)malloc(line_count * sizeof(schedule_entry_t));
    if (*schedule == NULL) {
        perror("Error allocating memory for schedule");
        fclose(fp);
        return -1;
    }

    // Read the schedule entries from the file
    char line[256];
    *num_entries = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
