#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200.0   // Minimum buzzer frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum buzzer frequency in Hz
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth() {
    long start_time = 0, end_time = 0;
    int timeout_count = 0;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        timeout_count++;
        if (timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse start timeout\n");
            return -1; // Timeout
        }
    }

    timeout_count = 0;
    // Wait for echo to go low
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        timeout_count++;
        if (timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse end timeout\n");
            return -1; // Timeout
        }
    }

    return end_time - start_time;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    if (distance < 0) return MIN_FREQUENCY; // Handle error case
    if (distance > 100) distance = 100; // Clamp distance
    return MIN_FREQUENCY + (distance / 100.0) * (MAX_FREQUENCY - MIN_FREQUENCY);
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    int pwm_range = gpioGetPWMrange(BUZZER_PIN);
    int pwm_value = (int)((frequency / MAX_FREQUENCY) * pwm_range);
    gpioPWM(BUZZER_PIN, pwm_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 1000); // Example range
    gpioSetPWMfrequency(BUZZER_PIN, 1000); // Example frequency

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_width = getPulseWidth();

        if (pulse_width < 0) {
            fprintf(stderr, "Error: Invalid pulse width, setting frequency to minimum\n");
            setBuzzerFrequency(MIN_FREQUENCY);
        } else {
            float distance = calculateDistance(pulse_width);
            float frequency = mapDistanceToFrequency(distance);
            setBuzzerFrequency(frequency);
        }

        gpioDelay(60); // Delay to avoid overwhelming the sensor
    }

    // Cleanup
    gpioPWM(BUZZER_PIN, 0); // Stop the buzzer
    gpioTerminate();       // Terminate pigpio

    fprintf(stderr, "Theremin stopped.\n");
    return 0;
}

