#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Scaling factor for gyroscope (±250°/s)
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int i2c_setup(int address);
int mpu6050_init(int fd);
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float convert_to_dps(int16_t raw_data);
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t pwr_mgmt_1 = 0x00;
    if (write(fd, &pwr_mgmt_1, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    // Set gyroscope full-scale range to ±250°/s
    uint8_t gyro_config = 0x00; // 0x00 = ±250°/s
    if (write(fd, &gyro_config, 1) != 1) {
        perror("Error writing to GYRO_CONFIG register");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t reg_gyro_x_h = GYRO_XOUT_H;
    uint8_t reg_gyro_x_l = GYRO_XOUT_L;
    uint8_t reg_gyro_y_h = GYRO_YOUT_H;
    uint8_t reg_gyro_y_l = GYRO_YOUT_L;
    uint8_t reg_gyro_z_h = GYRO_ZOUT_H;
    uint8_t reg_gyro_z_l = GYRO_ZOUT_L;

    if (write(fd, &reg_gyro_x_h, 1) != 1) {
        perror("Error writing to GYRO_XOUT_H register");
        return -1;
    }

    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    *gyro_x = (int16_t)((data[0] << 8) | data[1]);
    *gyro_y = (int16_t)((data[2] << 8) | data[3]);
    *gyro_z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE;
}

// Function to log data to file
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, gyro_x, gyro_y, gyro_z) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;

    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x_raw, &gyro_y_raw, &gyro_z_raw) == 0) {
            // Convert to degrees per second
            gyro_x_dps = convert_to_dps(gyro_x_raw);
            gyro_y_dps = convert_to_dps(gyro_y_raw);
            gyro_z_dps = convert_to_dps(gyro_z_raw);

            // Log data
            if (log_data(log_file, gyro_x_dps, gyro_y_dps, gyro_z_dps) != 0) {
                fprintf(stderr, "Error logging data. Continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Continuing...\n");
        }

        // Wait 100 milliseconds
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

