#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define PWM frequency
#define PWM_FREQUENCY 440

// Define debounce interval (in milliseconds)
#define DEBOUNCE_INTERVAL 50

// Define melody duration (in milliseconds)
#define MELODY_DURATION 2000

// Define PWM range
#define PWM_RANGE 1000

// Define PWM duty cycle (50% = 500)
#define PWM_DUTY_CYCLE 500

// Define melody structure
typedef struct {
    int frequency;
    int duration;
} MelodyNote;

// Define melody lookup table
const MelodyNote melody[] = {
    {440, 200},   // A4
    {494, 200},   // B4
    {523, 200},   // C5
    {587, 200},   // D5
    {659, 200},   // E5
    {698, 200},   // F5
    {784, 200},   // G5
    {880, 200},   // A5
    {988, 200},   // B5
    {1047, 200}   // C6
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int button_pressed = 0;
int pwm_handle;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Interrupt service routine (ISR) for button press
void button_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick < DEBOUNCE_INTERVAL * 1000) {
        return; // Ignore the interrupt
    }

    last_tick = current_tick;

    if (level == 0) { // Button pressed (active low)
        button_pressed = 1;
    }
}

// Function to play the melody
void play_melody() {
    for (int i = 0; i < melody_length; i++) {
        gpioPWM(BUZZER_GPIO, PWM_DUTY_CYCLE); // Set duty cycle
        gpioSetPWMfrequency(BUZZER_GPIO, melody[i].frequency); // Set frequency
        gpioDelay(melody[i].duration * 1000); // Delay for note duration
    }
}

// Function to stop the melody
void stop_melody() {
    gpioPWM(BUZZER_GPIO, 0); // Stop PWM
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Enable pull-up resistor on the button GPIO
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set PWM range
    gpioSetPWMrange(BUZZER_GPIO, PWM_RANGE);

    // Set PWM frequency (initial value)
    gpioSetPWMfrequency(BUZZER_GPIO, PWM_FREQUENCY);

    // Set PWM duty cycle (initial value)
    gpioPWM(BUZZER_GPIO, PWM_DUTY_CYCLE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine (ISR) for button press
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    printf("Doorbell program started. Press the button to play the melody.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            printf("Button pressed!\n");
            play_melody();
            button_pressed = 0; // Reset the flag

            // Check for second press during melody playback
            gpioDelay(DEBOUNCE_INTERVAL * 1000); // Debounce
            if (button_pressed) {
                printf("Button pressed again during melody playback!\n");
                stop_melody();
                button_pressed = 0; // Reset the flag
            }
        }
        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    return 0;
}

