#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3
#define LOG_FILE "vibration_events.log"

volatile sig_atomic_t terminate = 0;

// Structure to hold the sliding window
typedef struct {
    int window[WINDOW_SIZE];
    int index;
    int count;
} SlidingWindow;

// Function to initialize the sliding window
void sliding_window_init(SlidingWindow *window) {
    memset(window->window, 0, sizeof(window->window));
    window->index = 0;
    window->count = 0;
}

// Function to add a new event to the sliding window
void sliding_window_add(SlidingWindow *window, int event) {
    window->window[window->index] = event;
    window->index = (window->index + 1) % WINDOW_SIZE;
    if (window->count < WINDOW_SIZE) {
        window->count++;
    }
}

// Function to check if the sliding window contains enough HIGH events
int sliding_window_check(const SlidingWindow *window) {
    int high_count = 0;
    for (int i = 0; i < window->count; i++) {
        if (window->window[i] == 1) {
            high_count++;
        }
    }
    return (high_count >= EARTHQUAKE_THRESHOLD);
}

// Function to get the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to log an event to the file
int log_event(const char *timestamp, int value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s %d\n", timestamp, value);
    fflush(fp); // Ensure data is written to disk immediately
    fsync(fileno(fp)); // Ensure data is written to disk

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main(int argc, char *argv[]) {
    int poll_timeout = 1000; // Default timeout of 1 second
    int edge_count = 0;
    int last_edge = 0; // Store the last edge detected
    SlidingWindow window;
    char timestamp[21];

    // Parse command-line arguments
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
        if (poll_timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default timeout of 1000ms.\n");
            poll_timeout = 1000;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Initialize the sliding window
    sliding_window_init(&window);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring vibration sensor on GPIO %d. Poll timeout: %dms. Press Ctrl+C to exit.\n", GPIO_PIN, poll_timeout);

    // Main loop
    while (!terminate) {
        int current_edge = gpioRead(GPIO_PIN);

        // Detect rising edge
        if (current_edge == 1 && last_edge == 0) {
            get_iso8601_timestamp(timestamp);
            if (log_event(timestamp, current_edge) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
            sliding_window_add(&window, current_edge);
            edge_count++;
            last_edge = current_edge;
        }

        // Detect falling edge
        if (current_edge == 0 && last_edge == 1) {
            get_iso8601_timestamp(timestamp);
            if (log_event(timestamp, current_edge) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
            sliding_window_add(&window, current_edge);
            edge_count++;
            last_edge = current_edge;
        }

        // Check for earthquake condition
        if (edge_count >= 3 && sliding_window_check(&window)) {
            get_iso8601_timestamp(timestamp);
            printf("EARTHQUAKE ALERT: %s\n", timestamp);
            // Optionally, log the alert to a separate file
            FILE *alert_fp = fopen("earthquake_alert.log", "a");
            if (alert_fp != NULL) {
                fprintf(alert_fp, "EARTHQUAKE ALERT: %s\n", timestamp);
                fclose(alert_fp);
            } else {
                fprintf(stderr, "Error opening earthquake alert log file.\n");
            }
        }

        edge_count = (edge_count >= 3) ? 3 : edge_count; // Keep edge_count at 3 after 3 edges

        gpioDelay(poll_timeout * 1000); // Delay for the specified timeout
    }

    // Clean up
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

