#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_REG_MR_REG_M 0x02
#define LSM303_REG_OUT_X_H_M 0x03
#define LSM303_REG_OUT_X_L_M 0x04
#define LSM303_REG_OUT_Z_H_M 0x05
#define LSM303_REG_OUT_Z_L_M 0x06
#define LSM303_REG_OUT_Y_H_M 0x07
#define LSM303_REG_OUT_Y_L_M 0x08

// Calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass directions
enum CompassDirection { N, NE, E, SE, S, SW, W, NW };

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_heading(float calibrated_x, float calibrated_y);
enum CompassDirection determine_direction(float heading);
int log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading, enum CompassDirection direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure magnetometer for continuous measurement mode
    if (i2cWriteByteData(i2c_handle, LSM303_REG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error configuring magnetometer: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM303_REG_OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", i2c_handle);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calibrate magnetometer data
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - X_OFFSET;
    *calibrated_y = (float)y - Y_OFFSET;
    *calibrated_z = (float)z - Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(float calibrated_x, float calibrated_y) {
    float heading = atan2(calibrated_y, calibrated_x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Determine compass direction
enum CompassDirection determine_direction(float heading) {
    if (heading >= 0 && heading < 22.5) return N;
    if (heading >= 22.5 && heading < 67.5) return NE;
    if (heading >= 67.5 && heading < 112.5) return E;
    if (heading >= 112.5 && heading < 157.5) return SE;
    if (heading >= 157.5 && heading < 202.5) return S;
    if (heading >= 202.5 && heading < 247.5) return SW;
    if (heading >= 247.5 && heading < 292.5) return W;
    if (heading >= 292.5 && heading < 337.5) return NW;
    return N; // Default to N if heading is outside the range
}

// Log data to CSV file
int log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading, enum CompassDirection direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%s\n",
            timestamp, calibrated_x, calibrated_y, calibrated_z, heading,
            (direction == N) ? "N" :
            (direction == NE) ? "NE" :
            (direction == E) ? "E" :
            (direction == SE) ? "SE" :
            (direction == S) ? "S" :
            (direction == SW) ? "SW" :
            (direction == W) ? "W" :
            (direction == NW) ? "NW" : "Unknown");

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(log_file);

    int16_t x, y, z;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;
    enum CompassDirection direction;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calibrate data
            calibrate_data(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Determine direction
            direction = determine_direction(heading);

            // Log data
            log_data(calibrated_x, calibrated_y, calibrated_z, heading, direction);

            // Print to console
            printf("Heading: %.2f degrees, Direction: %s\n", heading,
                   (direction == N) ? "N" :
                   (direction == NE) ? "NE" :
                   (direction == E) ? "E" :
                   (direction == SE) ? "SE" :
                   (direction == S) ? "S" :
                   (direction == SW) ? "SW" :
                   (direction == W) ? "W" :
                   (direction == NW) ? "NW" : "Unknown");
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

