    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(log_file);

    int16_t x, y, z;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;
    enum CompassDirection direction;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calibrate data
            calibrate_data(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Determine direction
            direction = determine_direction(heading);

            // Log data
            log_data(calibrated_x, calibrated_y, calibrated_z, heading, direction);

            // Print to console
            printf("Heading: %.2f degrees, Direction: %s\n", heading,
                   (direction == N) ? "N" :
                   (direction == NE) ? "NE" :
                   (direction == E) ? "E" :
                   (direction == SE) ? "SE" :
                   (direction == S) ? "S" :
                   (direction == SW) ? "SW" :
                   (direction == W) ? "W" :
                   (direction == NW) ? "NW" : "Unknown");
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

