#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 200

static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log relay state to file
int log_relay_state(const char *timestamp, int state) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    const char *state_str = (state == 1) ? "ON" : "OFF";
    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, state_str);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Interrupt handler for touch sensor
void touch_interrupt_handler(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();

    // Debounce the touch sensor
    if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) {
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            toggle_relay();
            log_relay_state(timestamp, relay_state);
            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error: Failed to get timestamp in interrupt handler.\n");
        }
        last_touch_time = current_time;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Force relay OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Log final OFF state
    char *timestamp = get_iso8601_timestamp();
    if (timestamp != NULL) {
        log_relay_state(timestamp, relay_state);
        free(timestamp);
    } else {
        fprintf(stderr, "Error: Failed to get timestamp for final log entry.\n");
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on touch pin
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        perror("Failed to open relay_log.json");
        gpioTerminate();
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program running. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

