#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define relay activation duration
#define RELAY_DURATION 5

// Define delay between relays
#define RELAY_DELAY 1

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_soil_moisture();
int control_relay(int relay_pin, int state);
int log_irrigation_event(int relay_pin, int moisture_level);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} gpio_config_t;

// Global GPIO configuration
gpio_config_t gpio_config = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read soil moisture level
        int moisture_level = read_soil_moisture();

        // Log the moisture level
        log_irrigation_event(-1, moisture_level); // -1 indicates no specific relay

        // Check if moisture level is below threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            // Activate relays sequentially
            if (control_relay(gpio_config.relay1, 0) != 0) {
                fprintf(stderr, "Error activating relay 1.\n");
            }
            log_irrigation_event(gpio_config.relay1, moisture_level);
            gpioDelay(RELAY_DURATION * 1000000); // Delay for relay duration (microseconds)
            gpioDelay(RELAY_DELAY * 1000000); // Delay between relays (microseconds)

            if (control_relay(gpio_config.relay2, 0) != 0) {
                fprintf(stderr, "Error activating relay 2.\n");
            }
            log_irrigation_event(gpio_config.relay2, moisture_level);
            gpioDelay(RELAY_DURATION * 1000000); // Delay for relay duration (microseconds)
            gpioDelay(RELAY_DELAY * 1000000); // Delay between relays (microseconds)

            if (control_relay(gpio_config.relay3, 0) != 0) {
