            }
            log_irrigation_event(gpio_config.relay3, moisture_level);
            gpioDelay(RELAY_DURATION * 1000000); // Delay for relay duration (microseconds)
            gpioDelay(RELAY_DELAY * 1000000); // Delay between relays (microseconds)

            if (control_relay(gpio_config.relay4, 0) != 0) {
                fprintf(stderr, "Error activating relay 4.\n");
            }
            log_irrigation_event(gpio_config.relay4, moisture_level);
            gpioDelay(RELAY_DURATION * 1000000); // Delay for relay duration (microseconds)
            gpioDelay(RELAY_DELAY * 1000000); // Delay between relays (microseconds)
        }

        // Wait for 10 seconds
        gpioDelay(10000000); // 10 seconds (microseconds)
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

