    gpioSetMode(gpio_config.relay1, PI_OUTPUT);
    gpioSetMode(gpio_config.relay2, PI_OUTPUT);
    gpioSetMode(gpio_config.relay3, PI_OUTPUT);
    gpioSetMode(gpio_config.relay4, PI_OUTPUT);

    // Set initial state to HIGH (relays inactive)
    gpioWrite(gpio_config.relay1, 1);
    gpioWrite(gpio_config.relay2, 1);
    gpioWrite(gpio_config.relay3, 1);
