    if (gpioWrite(relay_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", relay_pin);
        return 1;
    }
    return 0;
}

// Function to log irrigation events to a file
int log_irrigation_event(int relay_pin, int moisture_level) {
    FILE *fp = fopen("irrigation_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return 1;
    }

    // Get current timestamp in ISO 8601 format
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write log entry
    fprintf(fp, "%s - Relay: %d, Moisture: %d\n", timestamp, relay_pin, moisture_level);

    // Flush the buffer to ensure immediate writing
    fflush(fp);

    // Close the file
    fclose(fp);

    return 0;
}

