void cleanup_gpio() {
    // Deactivate all relays
    gpioWrite(gpio_config.relay1, 1);
    gpioWrite(gpio_config.relay2, 1);
    gpioWrite(gpio_config.relay3, 1);
    gpioWrite(gpio_config.relay4, 1);

    // Terminate pigpio library
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

