#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

// Define servo pulse widths (microseconds)
#define OPEN_PULSE_WIDTH 1500
#define CLOSE_PULSE_WIDTH 500

// Define nozzle angles (degrees)
#define NOZZLE_ANGLES {0, 45, 90, 135, 180}

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to set servo pulse width
int set_servo_pulse(int gpio, int pulse_width)
{
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse on GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to open the valve
int open_valve()
{
    return set_servo_pulse(VALVE_GPIO, OPEN_PULSE_WIDTH);
}

// Function to close the valve
int close_valve()
{
    return set_servo_pulse(VALVE_GPIO, CLOSE_PULSE_WIDTH);
}

// Function to spray the nozzle
int spray_nozzle(int gpio, int angles[], int num_angles)
{
    for (int i = 0; i < num_angles; i++) {
        int pulse_width = 500 + (angles[i] * 500 / 180); // Map angle to pulse width
        if (set_servo_pulse(gpio, pulse_width) != 0) {
            fprintf(stderr, "Error setting nozzle angle on GPIO %d\n", gpio);
            return -1;
        }
        gpioDelay(2000); // Spend 2 seconds on each angle
    }
    return 0;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for servos
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(NOZZLE_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Simulate soil moisture values
    int soil_moisture = 20;
    int moisture_sequence[] = {20, 40, 60, 80, 100};
    int num_moisture_values = sizeof(moisture_sequence) / sizeof(moisture_sequence[0]);
    int moisture_index = 0;

    // Main loop
    while (!terminate) {
        // Simulate soil moisture reading
        soil_moisture = moisture_sequence[moisture_index];
        moisture_index = (moisture_index + 1) % num_moisture_values;

        printf("Soil Moisture: %d\n", soil_moisture);

        if (soil_moisture < 50) {
            // Open the valve
            if (open_valve() != 0) {
                fprintf(stderr, "Error opening valve, exiting\n");
                break;
            }

            // Spray the nozzle
            int nozzle_angles[] = {0, 45, 90, 135, 180};
            if (spray_nozzle(NOZZLE_GPIO, nozzle_angles, sizeof(nozzle_angles) / sizeof(nozzle_angles[0])) != 0) {
                fprintf(stderr, "Error spraying nozzle, continuing\n");
