// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    // This is a simplified example and may not be sufficient for all sensors
    char data[2];

    // Check sensor ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    if (data[0] != 0xEA) { // Expected value for VL53L1X
        fprintf(stderr, "VL53L1X not found or incorrect ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Enable ranging (example)
    data[0] = VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTIONS_ENABLES;
    data[1] = 0x01; // Enable ranging
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    return 0;
}

