#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    int x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = read_register(handle, GYRO_XOUT_H);
    x_l = read_register(handle, GYRO_XOUT_L);
    y_h = read_register(handle, GYRO_YOUT_H);
    y_l = read_register(handle, GYRO_YOUT_L);
    z_h = read_register(handle, GYRO_ZOUT_H);
    z_l = read_register(handle, GYRO_ZOUT_L);

    if (x_h < 0 || x_l < 0 || y_h < 0 || y_l < 0 || z_h < 0 || z_l < 0) {
        return -1; // Indicate error
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0; // Indicate success
}

// Function to convert raw data to degrees per second
void convert_gyro_data(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps)
{
    *x_dps = (float)x / GYRO_SCALE;
    *y_dps = (float)y / GYRO_SCALE;
    *z_dps = (float)z / GYRO_SCALE;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6050
    if (write_register(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure gyroscope sensitivity
    if (write_register(i2c_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Error configuring gyroscope sensitivity\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t x, y, z;
        float x_dps, y_dps, z_dps;

        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            convert_gyro_data(x, y, z, &x_dps, &y_dps, &z_dps);
            printf("X: %.2f, Y: %.2f, Z: %.2f\n", x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

