int set_relay_state(int pin, int state);
int set_relay_intensity(int pin, int intensity);
int log_event(const char *message);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int pin;
    int mode;
} gpio_config_t;

// Array of GPIO configurations
gpio_config_t gpio_configs[] = {
    {RELAY1_PIN, PI_OUTPUT},
    {RELAY2_PIN, PI_OUTPUT},
    {RELAY3_PIN, PI_OUTPUT},
    {RELAY4_PIN, PI_OUTPUT}
};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Log the start of the program
    log_event("Program started");

    // Calculate the number of steps for the sunrise effect
    int num_steps = 1800; // 30 minutes * 60 seconds / 1 second

    // Calculate the increment for each step
    int intensity_increment = 255 / num_steps;

    // Initialize the current intensity to 0
    int current_intensity = 0;

    // Main loop for the sunrise effect
    for (int i = 0; i < num_steps && program_running; ++i) {
        // Set the intensity for all relays
        set_relay_intensity(RELAY1_PIN, current_intensity);
        set_relay_intensity(RELAY2_PIN, current_intensity);
        set_relay_intensity(RELAY3_PIN, current_intensity);
        set_relay_intensity(RELAY4_PIN, current_intensity);

        // Log the current intensity
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Intensity: %d", current_intensity);
        log_event(log_message);

        // Increment the current intensity
        current_intensity += intensity_increment;

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Turn off all relays
    set_relay_intensity(RELAY1_PIN, 0);
    set_relay_intensity(RELAY2_PIN, 0);
    set_relay_intensity(RELAY3_PIN, 0);
    set_relay_intensity(RELAY4_PIN, 0);

