    // Set the GPIO modes for the relay pins
    for (int i = 0; i < sizeof(gpio_configs) / sizeof(gpio_configs[0]); ++i) {
        if (gpioSetMode(gpio_configs[i].pin, gpio_configs[i].mode) != 0) {
