    // Turn off all relays
    set_relay_intensity(RELAY1_PIN, 0);
    set_relay_intensity(RELAY2_PIN, 0);
    set_relay_intensity(RELAY3_PIN, 0);
    set_relay_intensity(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

