#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// LED GPIO pin (BCM 17)
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    time_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C file descriptor
int fd;

// Function prototypes
int init_i2c(int address);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void store_data(gyro_data_t *buffer, int buffer_size, int16_t x, int16_t y, int16_t z);
bool check_threshold(int16_t x, int16_t y, int16_t z);
void control_led(int pin, bool on);
void cleanup(int signal);

// Signal handler for Ctrl+C and SIGTERM
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(fd); // Close I2C device
    exit(0);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) == -1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int retries = 3;
    while (retries > 0) {
        int16_t x_h, x_l, y_h, y_l, z_h, z_l;

        x_h = wiringPiI2CReadReg8(fd, GYRO_XOUT_H);
        x_l = wiringPiI2CReadReg8(fd, GYRO_XOUT_H + 1);
        y_h = wiringPiI2CReadReg8(fd, GYRO_YOUT_H);
        y_l = wiringPiI2CReadReg8(fd, GYRO_YOUT_H + 1);
        z_h = wiringPiI2CReadReg8(fd, GYRO_ZOUT_H);
        z_l = wiringPiI2CReadReg8(fd, GYRO_ZOUT_H + 1);

        if (x_h == -1 || x_l == -1 || y_h == -1 || y_l == -1 || z_h == -1 || z_l == -1) {
            fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
            retries--;
            delay(10); // Small delay before retrying
            continue;
        }

        *x = (x_h << 8) | x_l;
        *y = (y_h << 8) | y_l;
        *z = (z_h << 8) | z_l;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read gyro data after multiple retries.\n");
    return -1; // Failure
}

// Store data in the circular buffer
void store_data(gyro_data_t *buffer, int buffer_size, int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    buffer[buffer_index].timestamp = now;
    buffer[buffer_index].x = x;
    buffer[buffer_index].y = y;
    buffer[buffer_size].z = z;

    buffer_index = (buffer_index + 1) % buffer_size;
}

// Check if any axis exceeds the threshold
bool check_threshold(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > 250 || abs(y) > 250 || abs(z) > 250) {
        return true;
    }
    return false;
}

// Control the LED
void control_led(int pin, bool on) {
    digitalWrite(pin, on ? HIGH : LOW);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    fd = init_i2c(MPU6050_ADDR);
    if (fd == -1) {
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Register signal handler for Ctrl+C and SIGTERM
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int16_t x, y, z;
    bool threshold_exceeded = false;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(fd, &x, &y, &z) == 0) {
            // Store data in the circular buffer
            store_data(gyro_buffer, BUFFER_SIZE, x, y, z);

            // Check if any axis exceeds the threshold
            threshold_exceeded = check_threshold(x, y, z);

            // Control the LED
            control_led(LED_PIN, threshold_exceeded);
        } else {
            fprintf(stderr, "Error reading gyro data. Attempting to re-initialize...\n");
            close(fd);
            delay(100); // Small delay before re-initializing
            fd = init_i2c(MPU6050_ADDR);
            if (fd == -1) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
        }

        // Delay to achieve 20 Hz sampling rate
        delay(50);
    }

    return 0;
}

