#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8 // BCM GPIO 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_LSB_FIRST 1
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_INTERVAL_MS 10
#define MAX_RETRIES 3

// MPU-9250 Registers
#define MPU9250_WHO_AM_I 0x75
#define MPU9250_PWR_MGMT_1 0x6B
#define MPU9250_GYRO_CONFIG 0x1B
#define MPU9250_GYRO_XOUT_H 0x43

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t reg, uint8_t *data, size_t len);
int gpio_init(void);
int mpu9250_init(void);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
char *format_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = SPI_SPEED;
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    // Configure SPI LSB first
    uint8_t lsb = SPI_LSB_FIRST;
    ret = ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &lsb);
    if (ret == -1) {
        perror("Error setting SPI LSB first");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer with retry
int spi_transfer(uint8_t reg, uint8_t *data, size_t len) {
    int retries = 0;
    int ret;
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long) &reg,
        .rx_buf = (unsigned long) data,
        .len = len + 1, // Include register address
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    while (retries < MAX_RETRIES) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
        if (ret == len + 1) { // Expect len + 1 bytes to be transferred (reg + data)
            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(1000); // Wait before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// GPIO Initialization
int gpio_init(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_line, "mpu9250", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// MPU-9250 Initialization
int mpu9250_init(void) {
    uint8_t who_am_i;
    int ret;

    // Wake up the MPU-9250
    ret = spi_transfer(MPU9250_PWR_MGMT_1, NULL, 0);
    if (ret < 0) return ret;

    // Verify WHO_AM_I register
    ret = spi_transfer(MPU9250_WHO_AM_I | 0x80, &who_am_i, 1); // Read WHO_AM_I
    if (ret < 0) return ret;

    if (who_am_i != 0x71) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x71, got 0x%02x\n", who_am_i);
        return -1;
    }

    // Configure gyroscope
    ret = spi_transfer(MPU9250_GYRO_CONFIG, NULL, 0);
    if (ret < 0) return ret;

    return 0;
}

// Read Gyroscope Data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    int ret;

    ret = spi_transfer(MPU9250_GYRO_XOUT_H | 0x80, data, 6); // Read X, Y, and Z
    if (ret < 0) return ret;

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Format ISO 8601 Timestamp
char *format_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%09ldZ", ts.tv_nsec);

    return timestamp_str;
}

// Log Data to File
int log_data(const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Cleanup Resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int16_t x_rate, y_rate, z_rate;
    char timestamp_str[30];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    // Initialize MPU-9250
    if (mpu9250_init() < 0) {
        fprintf(stderr, "MPU-9250 initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x_rate, &y_rate, &z_rate) == 0) {
            // Format timestamp
            format_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

            // Log data
            if (log_data(timestamp_str, x_rate, y_rate, z_rate) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

