#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s for +/- 250 deg/s range
#define GYRO_THRESHOLD 200.0
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define SAMPLE_RATE 100 // Hz

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43

// Data structure for gyroscope data
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int init_spi();
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void store_data(float x, float y, float z);
void check_threshold(float x, float y, float z);
void blink_led();
void signal_handler(int signal);
void print_buffer_csv();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 3.9 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize MPU6050
int init_mpu6050() {
    char buf[2];
    buf[0] = MPU6050_PWR_MGMT_1;
    buf[1] = 0x00; // Wake up the sensor
    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100); // Short delay after waking up
    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[7];
    buf[0] = MPU6050_GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H

    if (spiXfer(spi_handle, buf, buf, 7) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second
    *x = (float)gyro_x / GYRO_SENSITIVITY;
    *y = (float)gyro_y / GYRO_SENSITIVITY;
    *z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Store data in circular buffer
void store_data(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if threshold is exceeded
void check_threshold(float x, float y, float z) {
    if (fabs(x) > GYRO_THRESHOLD || fabs(y) > GYRO_THRESHOLD || fabs(z) > GYRO_THRESHOLD) {
        blink_led();
    }
}

// Blink LED
void blink_led() {
    gpioWrite(LED_GPIO, 1); // Turn on LED
    gpioDelay(500);         // Wait 500 ms
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioDelay(500);         // Wait 500 ms
}

// Print buffer to CSV
void print_buffer_csv() {
    FILE *fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        return;
    }

    fprintf(fp, "Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        fprintf(fp, "%ld.%09ld,%f,%f,%f\n", gyro_buffer[i].timestamp.tv_sec, gyro_buffer[i].timestamp.tv_nsec, gyro_buffer[i].x, gyro_buffer[i].y, gyro_buffer[i].z);
    }

    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000000 / SAMPLE_RATE; // 100 ms for 100 Hz

    printf("Starting data acquisition...\n");

    while (1) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            store_data(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper cleanup in case the loop is ever modified.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

