#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define ALS_DATA_REG 0x22
#define PS_DATA_REG 0x24
#define LED_GPIO 17
#define PROXIMITY_THRESHOLD 100
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000 // 10 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int *ambient_light, int *proximity);
int log_data(int ambient_light, int proximity);
void control_led(int proximity);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    int ambient_light;
    int proximity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(int *ambient_light, int *proximity) {
    int retry = 0;
    int result;

    while (retry < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, ALS_DATA_REG);
        if (result >= 0) {
            *ambient_light = result;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retry + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retry++;
            continue;
        }

        result = i2cReadWordData(i2c_handle, PS_DATA_REG);
        if (result >= 0) {
            *proximity = result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retry + 1, result);
