#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define READ_BIT 0x80
#define DATA_FILE "gyro_data.csv"
#define SAMPLE_DELAY_US 10000 // 10 ms
#define SPI_REINIT_ATTEMPTS 3

// Global variables
int spi_handle = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int spi_init();
int spi_read_register(uint8_t reg, uint8_t *data);
int spi_write_register(uint8_t reg, uint8_t data);
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// SPI initialization function
int spi_init() {
    int attempts = 0;
    while (attempts < SPI_REINIT_ATTEMPTS) {
        spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        if (spi_handle >= 0) {
            printf("SPI initialized successfully (attempt %d).\n", attempts + 1);
            return 0; // Success
        } else {
            fprintf(stderr, "Error opening SPI channel (attempt %d): %d\n", attempts + 1, spi_handle);
            attempts++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to initialize SPI after %d attempts.\n", SPI_REINIT_ATTEMPTS);
    return -1; // Failure
}

// SPI read register function
int spi_read_register(uint8_t reg, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | READ_BIT;
    tx_buf[1] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result == 2) {
        *data = rx_buf[1];
        return 0; // Success
    } else {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Failure
    }
}

// SPI write register function
int spi_write_register(uint8_t reg, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = reg & ~READ_BIT; // Ensure write bit is not set
    tx_buf[1] = data;

    int result = spiWrite(spi_handle, tx_buf, 2);
    if (result == 2) {
        return 0; // Success
    } else {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1; // Failure
    }
}

// Read gyroscope data function
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    uint8_t x_data, y_data;

    if (spi_read_register(GYRO_X_REG, &x_data) != 0) {
        fprintf(stderr, "Error reading X axis data.\n");
        data.x_rate = 0; // Set to 0 to avoid garbage values
    } else {
        data.x_rate = (int16_t)x_data; // Cast to signed 16-bit integer
    }

    if (spi_read_register(GYRO_Y_REG, &y_data) != 0) {
        fprintf(stderr, "Error reading Y axis data.\n");
        data.y_rate = 0; // Set to 0 to avoid garbage values
    } else {
        data.y_rate = (int16_t)y_data; // Cast to signed 16-bit integer
    }

    return data;
}

// Log data to file function
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(data_file, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000, data.x_rate, data.y_rate);
    fflush(data_file); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        printf("SPI closed.\n");
    }
    if (data_file != NULL) {
        fclose(data_file);
        printf("Data file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "w");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_DELAY_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

