#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION_MS 2000
#define SEISMIC_THRESHOLD_MS 500

// Global variables
static volatile int sensor1_state = 0;
static volatile int sensor2_state = 0;
static volatile unsigned long sensor1_start_time = 0;
static volatile unsigned long sensor2_start_time = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void sensor1_callback(int gpio, int level, unsigned int tick, void *user);
void sensor2_callback(int gpio, int level, unsigned int tick, void *user);
void seismic_event_alert();
void log_seismic_event();
void signal_handler(int signal);

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick, void *user) {
    if (level == 1) { // Rising edge
        sensor1_state = 1;
        sensor1_start_time = gpioTick();
    } else if (level == 0) { // Falling edge
        sensor1_state = 0;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick, void *user) {
    if (level == 1) { // Rising edge
        sensor2_state = 1;
        sensor2_start_time = gpioTick();
    } else if (level == 0) { // Falling edge
        sensor2_state = 0;
    }
}

// Function to trigger the seismic event alert
void seismic_event_alert() {
    gpioWrite(ALERT_PIN, 1); // Set ALERT_PIN HIGH
    gpioDelay(ALERT_DURATION_MS * 1000); // Delay for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
}

// Function to log the seismic event to a file
void log_seismic_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors (if needed, depends on sensor wiring)
    // gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    // gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor1_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for sensor 1!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor2_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for sensor 2!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (sensor1_state && sensor2_state) {
            unsigned long current_time = gpioTick();
            if ((current_time - sensor1_start_time) >= (SEISMIC_THRESHOLD_MS * 1000) &&
                (current_time - sensor2_start_time) >= (SEISMIC_THRESHOLD_MS * 1000)) {
                seismic_event_alert();
                log_seismic_event();
                sensor1_state = 0; // Reset states after alert
                sensor2_state = 0;
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
    fclose(log_file);
    gpioTerminate(); // Terminate pigpio

    return 0;
}

