void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors (if needed, depends on sensor wiring)
    // gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    // gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor1_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for sensor 1!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor2_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for sensor 2!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (sensor1_state && sensor2_state) {
            unsigned long current_time = gpioTick();
            if ((current_time - sensor1_start_time) >= (SEISMIC_THRESHOLD_MS * 1000) &&
                (current_time - sensor2_start_time) >= (SEISMIC_THRESHOLD_MS * 1000)) {
                seismic_event_alert();
                log_seismic_event();
                sensor1_state = 0; // Reset states after alert
                sensor2_state = 0;
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
    fclose(log_file);
    gpioTerminate(); // Terminate pigpio

    return 0;
}

