#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define GYRO_X_REG 0x02
#define GYRO_RATE_THRESHOLD 20.0
#define LED_GPIO 17
#define BUFFER_SIZE 100

// Data structure for storing timestamped gyroscope data
typedef struct {
    struct timespec timestamp;
    int16_t rate;
} gyro_data_t;

// Circular buffer
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int read_gyro_rate(int16_t *rate);
void add_to_buffer(circular_buffer_t *cb, int16_t rate);
int check_threshold(int16_t rate);
void control_led(int on);
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *cb);

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *cb, int16_t rate) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    cb->buffer[cb->head].timestamp = ts;
    cb->buffer[cb->head].rate = rate;

    cb->head = (cb->head + 1) % BUFFER_SIZE;

    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read gyroscope rate
int read_gyro_rate(int16_t *rate) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the read command (MSB = 1 for read)
    tx_buf[0] = GYRO_X_REG | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte for reading data

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit rate
    *rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Function to check if the rate exceeds the threshold
int check_threshold(int16_t rate) {
    return (abs(rate) > (GYRO_RATE_THRESHOLD * 100)); // Scale rate for integer comparison
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t gyro_rate;

    fprintf(stderr, "Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read gyroscope rate
        if (read_gyro_rate(&gyro_rate) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, gyro_rate);

            // Check threshold and control LED
            if (check_threshold(gyro_rate)) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading gyroscope rate\n");
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    control_led(0); // Turn LED off
    gpioTerminate();

    fprintf(stderr, "Gyroscope monitoring stopped.\n");

    return 0;
}

