#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to store the total duration in seconds
int total_duration = 0;

// Function prototypes
int initialize_gpio();
int set_pwm_frequency(int gpio, int frequency);
int set_pwm_range(int gpio, int range);
int set_pwm_dutycycle(int gpio, int dutycycle);
int fade_lamp(int gpio, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_pwm_dutycycle(LAMP1_GPIO, 0);
    set_pwm_dutycycle(LAMP2_GPIO, 0);
    set_pwm_dutycycle(LAMP3_GPIO, 0);
    gpioTerminate();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency for each GPIO pin
    if (set_pwm_frequency(LAMP1_GPIO, PWM_FREQUENCY) != 0) return 1;
    if (set_pwm_frequency(LAMP2_GPIO, PWM_FREQUENCY) != 0) return 1;
    if (set_pwm_frequency(LAMP3_GPIO, PWM_FREQUENCY) != 0) return 1;

    // Set PWM range for each GPIO pin
    if (set_pwm_range(LAMP1_GPIO, PWM_RANGE) != 0) return 1;
    if (set_pwm_range(LAMP2_GPIO, PWM_RANGE) != 0) return 1;
    if (set_pwm_range(LAMP3_GPIO, PWM_RANGE) != 0) return 1;

    return 0; // Indicate success
}

// Function to set the PWM frequency for a given GPIO pin
int set_pwm_frequency(int gpio, int frequency) {
    if (gpioSetPWMfrequency(gpio, frequency) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpio);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to set the PWM range for a given GPIO pin
int set_pwm_range(int gpio, int range) {
    if (gpioSetPWMrange(gpio, range) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", gpio);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_dutycycle(int gpio, int dutycycle) {
    if (gpioPWM(gpio, dutycycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to fade a lamp from full brightness to off over a given duration
int fade_lamp(int gpio, int duration) {
    int i;
    int steps = PWM_RANGE; // Number of steps for the fade
    int delay_ms = duration * 1000 / steps; // Calculate delay in milliseconds

    printf("Fading lamp on GPIO %d for %d seconds (%d steps, %d ms delay)\n", gpio, duration, steps, delay_ms);

    for (i = PWM_RANGE; i >= 0; i--) {
        if (set_pwm_dutycycle(gpio, i) != 0) {
            return 1; // Indicate failure
        }
        gpioDelay(delay_ms * 1000); // Delay in microseconds
    }
    return 0; // Indicate success
}

int main(int argc, char *argv[]) {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Convert command-line argument to integer
    total_duration = atoi(argv[1]);

    // Validate total duration
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600 seconds\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Print start message
    printf("Starting sunset simulation for %d seconds...\n", total_duration);

    // Fade lamps sequentially
    if (fade_lamp(LAMP1_GPIO, total_duration) != 0) {
        gpioTerminate();
        return 1;
    }
    if (fade_lamp(LAMP2_GPIO, total_duration) != 0) {
        gpioTerminate();
        return 1;
    }
    if (fade_lamp(LAMP3_GPIO, total_duration) != 0) {
        gpioTerminate();
        return 1;
    }

    // Print completion message
    printf("Sunset simulation complete.\n");

    // Clean up and exit
    gpioTerminate();
    return 0;
}

