#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the traffic lights
#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define ALL_TRAFFIC_PIN 24

// Define signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    gpioWrite(RED_PIN, 1);   // Turn off red light
    gpioWrite(YELLOW_PIN, 1); // Turn off yellow light
    gpioWrite(GREEN_PIN, 1);  // Turn off green light
    gpioWrite(ALL_TRAFFIC_PIN, 1); // Turn off all traffic light
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(YELLOW_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(ALL_TRAFFIC_PIN, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to simulate traffic light sequence
    while (1) {
        // Red light
        printf("Red light ON\n");
        gpioWrite(RED_PIN, 0);   // Turn on red light
        gpioWrite(YELLOW_PIN, 1); // Turn off yellow light
        gpioWrite(GREEN_PIN, 1);  // Turn off green light
        gpioWrite(ALL_TRAFFIC_PIN, 1); // Turn off all traffic light
        sleep(10);

        // Red + Yellow light
        printf("Red + Yellow light ON\n");
        gpioWrite(RED_PIN, 0);   // Turn on red light
        gpioWrite(YELLOW_PIN, 0); // Turn on yellow light
        gpioWrite(GREEN_PIN, 1);  // Turn off green light
        gpioWrite(ALL_TRAFFIC_PIN, 1); // Turn off all traffic light
        sleep(2);

        // Green light
        printf("Green light ON\n");
        gpioWrite(RED_PIN, 1);   // Turn off red light
        gpioWrite(YELLOW_PIN, 1); // Turn off yellow light
        gpioWrite(GREEN_PIN, 0);  // Turn on green light
        gpioWrite(ALL_TRAFFIC_PIN, 1); // Turn off all traffic light
        sleep(10);

        // Yellow light
        printf("Yellow light ON\n");
        gpioWrite(RED_PIN, 1);   // Turn off red light
        gpioWrite(YELLOW_PIN, 0); // Turn off yellow light
        gpioWrite(GREEN_PIN, 1);  // Turn off green light
        gpioWrite(ALL_TRAFFIC_PIN, 1); // Turn off all traffic light
        sleep(3);
    }

    return 0;
}

