#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define RELAY_ON_TIME_MS 500
#define READ_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status(uint16_t *touch_status);
void debounce_touch();
void toggle_relay();
void log_error(const char *message);
void signal_handler(int signal);

// Structure for MPR121 configuration
typedef struct {
    uint8_t touch_threshold[12];
    uint8_t release_threshold[12];
    uint8_t electrode_config;
} mpr121_config_t;

// MPR121 configuration
mpr121_config_t mpr121_config = {
    {0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F}, // Touch threshold
    {0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A}, // Release threshold
    0x0F // Electrode config (all electrodes enabled)
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        log_error("MPR121 initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize to LOW

    uint16_t touch_status = 0;
    uint16_t last_touch_status = 0;

    // Main loop
    while (!terminate) {
        // Read touch status
        if (read_touch_status(&touch_status) != 0) {
            log_error("Failed to read touch status");
        } else {
            // Check for touch event on electrode 0
            if ((touch_status & 0x01) && !(last_touch_status & 0x01)) {
                debounce_touch();
                toggle_relay();
            }
            last_touch_status = touch_status;
        }

        gpioDelay(READ_DELAY_MS * 1000); // Delay for 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Set relay to LOW
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Initialize MPR121
int initialize_mpr121() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_error("Failed to set MPR121 to stop mode");
        return -1;
    }
    gpioDelay(1000); // Delay 1 ms

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, mpr121_config.touch_threshold[i]) < 0) {
            log_error("Failed to set touch threshold");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, mpr121_config.release_threshold[i]) < 0) {
            log_error("Failed to set release threshold");
            return -1;
        }
    }

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, mpr121_config.electrode_config) < 0) {
        log_error("Failed to set electrode configuration");
        return -1;
    }

    // Start mode (enable all electrodes)
    if (i2cWriteByteData(i2c_handle, 0x80, 0x10) < 0) {
        log_error("Failed to set MPR121 to start mode");
        return -1;
    }
    gpioDelay(1000); // Delay 1 ms

    return 0;
}

// Read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_error("Failed to read touch status");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Debounce touch event
void debounce_touch() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay for 100 ms
}

// Toggle relay
void toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
    gpioDelay(RELAY_ON_TIME_MS * 1000); // Delay for 500 ms
    gpioWrite(RELAY_GPIO, !current_state); // Return to original state
}

// Log error to file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
    perror(message); // Also print to stderr
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

