    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int flame_count = 0;
    int last_state = -1; // Initialize to an invalid state

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_flame_sensor();

        if (current_state < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (current_state == 0 && last_state == 0) {
            flame_count++;
        } else {
            flame_count = 0;
        }

        last_state = current_state;

        if (flame_count >= FLAME_THRESHOLD) {
            log_flame_event();
            activate_buzzer();
            activate_led();
            gpioDelay(BUZZER_DURATION_MS);
            deactivate_buzzer();
            deactivate_led();
            flame_count = 0; // Reset the counter after activation
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup (in case the loop exits normally)
    deactivate_buzzer();
    deactivate_led();
    gpioTerminate();
    fclose(log_file);

    return 0;
}

