#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (in milliseconds)
#define DISPENSE_DURATION 1000

// Define dispense interval (in milliseconds)
#define DISPENSE_INTERVAL 5000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void dispense_solenoid(int solenoid_pin, int duration_ms);
void log_dispense_event(int solenoid_pin, int duration_ms);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int solenoid1_pin;
    int solenoid2_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_1_PIN, 0); // Ensure solenoids are initially off
    gpioWrite(SOLENOID_2_PIN, 0);

    return 0; // Indicate success
}

// Function to dispense a solenoid for a specified duration
void dispense_solenoid(int solenoid_pin, int duration_ms) {
    gpioWrite(solenoid_pin, 1); // Activate solenoid
    gpioDelay(duration_ms * 1000); // Delay for specified duration (in microseconds)
    gpioWrite(solenoid_pin, 0); // Deactivate solenoid
}

// Function to log dispense event to file
void log_dispense_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Solenoid Pin: %d, Duration: %d ms\n", timestamp, solenoid_pin, duration_ms);
    fclose(fp);
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(SOLENOID_1_PIN, 0); // Ensure solenoids are off
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
}

// Signal handler for Ctrl+C
