#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// Ultrasonic Sensor
#define TRIGGER_PIN 4
#define ECHO_PIN 5

// PID Constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Global Variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
float simulate_tilt_error();
float simulate_distance();
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// PID Variables
float integral = 0.0;
float previous_error = 0.0;

// Function to simulate tilt error
float simulate_tilt_error() {
    return ((float)(rand() % 21) - 10.0); // Random float between -10.0 and 10.0
}

// Function to simulate distance reading
float simulate_distance() {
    return ((float)(rand() % 381) + 20.0); // Random float between 20.0 and 400.0
}

// Function to set motor speeds
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    // Clamp speeds to ±255
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;

    // Motor A
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(MOTOR_A_ENABLE, abs(motor_a_speed));
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, 0);
    }

    // Motor B
    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(MOTOR_B_ENABLE, abs(motor_b_speed));
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, 0);
    }
}

// Function to stop motors
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(MOTOR_A_ENABLE, 0);
    gpioPWM(MOTOR_B_ENABLE, 0);
}

// Function to log data
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_ENABLE, 255);
    gpioSetPWMrange(MOTOR_B_ENABLE, 255);

    // Open log file
    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate sensor readings
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        // PID control
        float error = tilt_error;
        integral += error;
        float derivative = error - previous_error;
        float output = KP * error + KI * integral + KD * derivative;

        // Motor speeds
        int motor_a_speed = (int)output;
        int motor_b_speed = (int)output;

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            printf("Obstacle detected! Reversing motors...\n");
            motor_a_speed = -255;
            motor_b_speed = -255;
        }

        // Set motor speeds
        set_motor_speed(motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Update previous error
        previous_error = error;

        // Delay
        gpioDelay(50000); // 50 milliseconds
    }

    // Stop motors
    stop_motors();

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

