#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int relay_pin;
} gpio_config_t;

// Global configuration
gpio_config_t config = {TOUCH_SENSOR_PIN, RELAY_PIN};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensor
        if (read_touch_sensor() == 1) {
            // Toggle relay state
            relay_state = !relay_state;

            // Control relay
            if (control_relay(relay_state) != 0) {
                fprintf(stderr, "Failed to control relay.\n");
            }

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // Check every 1 ms
    }

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(config.touch_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin mode.\n");
        cleanup_gpio();
        return 1;
    }

    if (gpioSetMode(config.relay_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode.\n");
        cleanup_gpio();
        return 1;
    }

    // Set pull-down resistor on touch sensor pin
    if (gpioSetPullUpDown(config.touch_pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on touch sensor pin.\n");
        cleanup_gpio();
        return 1;
    }

    return 0;
}

// Read touch sensor
int read_touch_sensor() {
    return gpioRead(config.touch_pin);
}

// Control relay
int control_relay(int state) {
    if (gpioWrite(config.relay_pin, state) != 0) {
        fprintf(stderr, "Failed to write to relay pin.\n");
        return 1;
    }
    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    gpioTerminate();
    printf("GPIO terminated.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up and exiting.\n", signal);
    cleanup_gpio();
    exit(0);
}

