// Calculate RMS amplitude
double calculate_rms(const short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / buffer_size);
}

// Map amplitude to color (non-linear mapping)
void map_amplitude_to_color(double amplitude, double sensitivity, int *red, int *green, int *blue) {
    // Normalize amplitude to a range of 0-1
    double normalized_amplitude = amplitude / sensitivity;
    if (normalized_amplitude > 1.0) normalized_amplitude = 1.0;
    if (normalized_amplitude < 0.0) normalized_amplitude = 0.0;

    // Map amplitude to HSL color space (Hue, Saturation, Lightness)
    double hue = normalized_amplitude * 360.0; // Hue (0-360 degrees)
    double saturation = 1.0; // Saturation (1.0 is fully saturated)
    double lightness = 0.5; // Lightness (0.0 is black, 1.0 is white)

    // Convert HSL to RGB (simplified, assumes saturation = 1)
    double r = 0.0, g = 0.0, b = 0.0;
    if (hue < 120.0) {
        r = 1.0;
        g = hue / 120.0;
        b = 0.0;
    } else if (hue < 240.0) {
        r = (240.0 - hue) / 120.0;
        g = 1.0;
        b = 0.0;
    } else {
        r = 0.0;
        g = (hue - 240.0) / 120.0;
        b = 1.0;
    }

    // Scale RGB values to 0-255 range
    *red = (int)(r * lightness * 255.0);
    *green = (int)(g * lightness * 255.0);
    *blue = (int)(b * lightness * 255.0);
}

// Set LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(GPIO_RED, red);
    gpioPWM(GPIO_GREEN, green);
    gpioPWM(GPIO_BLUE, blue);
}

