#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define sunrise and sunset durations (in seconds)
#define SUNRISE_DURATION 3600
#define SUNSET_DURATION 3600

// Define daytime and nighttime durations (in seconds)
#define DAYTIME_DURATION 21600
#define NIGHTTIME_DURATION 5400

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, turning off relays and exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to set the state of a relay (active-low)
void set_relay_state(int pin, int state) {
    gpioWrite(pin, !state); // Active-low, so invert the state
}

// Function to simulate sunrise
void sunrise(int duration) {
    printf("Sunrise phase (%d seconds)...\n", duration);
    for (int i = 0; i <= duration && program_running; ++i) {
        // Calculate duty cycle (0-100%)
        int duty_cycle = (int)(((float)i / duration) * 100);

        // Set relay states based on duty cycle
        set_relay_state(RELAY1_PIN, (duty_cycle > 0));
        set_relay_state(RELAY2_PIN, (duty_cycle > 25));
        set_relay_state(RELAY3_PIN, (duty_cycle > 50));
        set_relay_state(RELAY4_PIN, (duty_cycle > 75));

        // Sleep for 1 second
        sleep(1);
    }
}

// Function to simulate sunset
void sunset(int duration) {
    printf("Sunset phase (%d seconds)...\n", duration);
    for (int i = 0; i <= duration && program_running; ++i) {
        // Calculate duty cycle (0-100%)
        int duty_cycle = 100 - (int)(((float)i / duration) * 100);

        // Set relay states based on duty cycle
        set_relay_state(RELAY1_PIN, (duty_cycle > 75));
        set_relay_state(RELAY2_PIN, (duty_cycle > 50));
        set_relay_state(RELAY3_PIN, (duty_cycle > 25));
        set_relay_state(RELAY4_PIN, (duty_cycle > 0));

        // Sleep for 1 second
        sleep(1);
    }
}

// Function to simulate daytime
void daytime(int duration) {
    printf("Daytime phase (%d seconds)...\n", duration);
    for (int i = 0; i <= duration && program_running; ++i) {
        // Set all relays to ON
        set_relay_state(RELAY1_PIN, 1);
        set_relay_state(RELAY2_PIN, 1);
        set_relay_state(RELAY3_PIN, 1);
        set_relay_state(RELAY4_PIN, 1);

        // Sleep for 1 second
        sleep(1);
    }
}

// Function to simulate nighttime
void nighttime(int duration) {
    printf("Nighttime phase (%d seconds)...\n", duration);
    for (int i = 0; i <= duration && program_running; ++i) {
        // Set all relays to OFF
        set_relay_state(RELAY1_PIN, 0);
        set_relay_state(RELAY2_PIN, 0);
        set_relay_state(RELAY3_PIN, 0);
        set_relay_state(RELAY4_PIN, 0);

        // Sleep for 1 second
        sleep(1);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        sunrise(SUNRISE_DURATION);
        daytime(DAYTIME_DURATION);
        sunset(SUNSET_DURATION);
        nighttime(NIGHTTIME_DURATION);
    }

    // Turn off all relays before exiting
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

