#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log motion event to file
int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to capture video using raspivid
int capture_video() {
    char filename[100];
    char timestamp[25];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d000", filename, VIDEO_DURATION_S);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspivid command.\n");
        return -1;
    } else if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to handle motion detection
void handle_motion() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    if (log_motion_event(timestamp) != 0) {
        fprintf(stderr, "Error logging motion event.\n");
    }

    if (capture_video() != 0) {
        fprintf(stderr, "Error capturing video.\n");
    }

    free(timestamp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int last_state = 1; // Assume no motion initially (HIGH)
    unsigned long last_trigger_time = 0;

    while (running) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state == 0 && last_state == 1) { // Motion detected (LOW)
            unsigned long current_time = gpioTick();
            if (current_time - last_trigger_time > DEBOUNCE_DELAY_MS * 1000) { // Debounce
                handle_motion();
                last_trigger_time = current_time;
            }
        }

        last_state = current_state;
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

