#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor (±250°/s)
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    double x_degps;
    double y_degps;
    double z_degps;
} gyro_data_t;

// Function prototypes
int init_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 0;
    int status;

    // Wake up the MPU-6050
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0);
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error: Could not wake up MPU-6050 (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == 3) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050 after multiple retries.\n");
        return -1;
    }

    // Configure gyroscope sensitivity
    retries = 0;
