// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Global variable for the log file
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int pin, int state);
int log_data(int sensor_value, int relay1_state, int relay2_state, int relay3_state, int relay4_state);
void cleanup_handler(int signum);

// Structure to hold relay pin assignments
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} RelayPins;

RelayPins relay_pins = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

int main() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Register the cleanup handler for SIGINT
    signal(SIGINT, cleanup_handler);

    // Main loop
    while (1) {
        // Read the moisture sensor
        int moisture_level = read_moisture_sensor();

        // Determine the relay states based on the moisture level
        int relay1_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay2_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;

        // Control the relays
        control_relay(relay_pins.relay1, relay1_state);
        control_relay(relay_pins.relay2, relay2_state);
        control_relay(relay_pins.relay3, relay3_state);
        control_relay(relay_pins.relay4, relay4_state);

        // Log the data
        if (log_data(moisture_level, relay1_state, relay2_state, relay3_state, relay4_state) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Function to read the moisture sensor
int read_moisture_sensor() {
    // Generate a random moisture level between 0 and 100
    int moisture_level = rand() % 101;
    return moisture_level;
}

// Function to control a relay
void control_relay(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log the data to a file
int log_data(int sensor_value, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, sensor_value, relay1_state, relay2_state, relay3_state, relay4_state);
    fflush(log_file); // Ensure data is written to the file immediately

    return 0;
}

// Function to handle the SIGINT signal (Ctrl+C)
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

