#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36

// GPIO pin for alarm
#define ALARM_GPIO 27

// Free-fall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Free-fall duration (seconds)
#define FREEFALL_DURATION 0.5

// Alarm duration (seconds)
#define ALARM_DURATION 5

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_adxl345();
int read_acceleration(float *x, float *y, float *z);
int detect_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is initially off

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    accelerometer_data_t current_data, previous_data;
    time_t start_time;
    int freefall_confirmed = 0;

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(&current_data.x, &current_data.y, &current_data.z) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue; // Continue to the next iteration
        }

        // Detect free-fall
        if (detect_freefall(current_data.x, current_data.y, current_data.z)) {
            if (!freefall_confirmed) {
                // First confirmation
                start_time = time(NULL);
                freefall_confirmed = 1;
            } else {
                // Check if duration has been confirmed
                if (time(NULL) - start_time >= FREEFALL_DURATION) {
                    // Free-fall confirmed
                    trigger_alarm();
                    log_freefall(current_data.x, current_data.y, current_data.z);
                    freefall_confirmed = 0; // Reset for next free-fall
                }
            }
        } else {
            // Not in free-fall, reset confirmation
            freefall_confirmed = 0;
        }

        // Store current data for next iteration
        previous_data = current_data;

        // Delay
        gpioDelay(100); // 100 ms
    }

    return 0;
}

// Initialize ADXL345
int init_adxl345() {
    // Set data format: +/- 2g range, full resolution
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to set data format\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];

    // Read 6 bytes of data (X, Y, Z)
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    // Convert raw data to g-force units (assuming +/- 2g range, 10-bit resolution)
    int16_t x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    *x = (float)x_raw / 256.0; // 256 LSB/g for +/- 2g range
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Detect free-fall
int detect_freefall(float x, float y, float z) {
    return (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD);
}

// Trigger alarm
void trigger_alarm() {
    gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    gpioDelay(ALARM_DURATION * 1000); // Delay for 5 seconds
    gpioWrite(ALARM_GPIO, 0); // Set GPIO low
}

// Log free-fall event
