#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 100000       // 100ms timeout
#define MAX_PULSE_WIDTH 23200   // Maximum pulse width in us (4m)
#define TRIGGER_PULSE_DURATION_US 10 // Trigger pulse duration in us

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static pthread_mutex_t echo_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void trigger_pulse();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION_US);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt handler for rising edge on ECHO pin
void echo_rising_edge(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&echo_mutex);
    echo_start_tick = tick;
    echo_end_tick = 0; // Reset end tick
    echo_valid = 0;    // Reset valid flag
    pthread_mutex_unlock(&echo_mutex);
}

// Interrupt handler for falling edge on ECHO pin
void echo_falling_edge(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&echo_mutex);
    echo_end_tick = tick;
    echo_valid = 1; // Set valid flag
    pthread_mutex_unlock(&echo_mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register interrupt handlers
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge, NULL);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_pulse();
        gpioDelay(200000); // Wait 200ms

        pthread_mutex_lock(&echo_mutex);
        int pulse_width = echo_end_tick - echo_start_tick;
        echo_valid = 0; // Reset valid flag after reading
        pthread_mutex_unlock(&echo_mutex);

        if (pulse_width > MAX_PULSE_WIDTH || pulse_width < 0) {
            fprintf(stderr, "Error: Invalid pulse width: %d us\n", pulse_width);
        } else {
            double distance = calculate_distance(pulse_width);
            if (distance >= 0.0) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Error: Could not calculate distance.\n");
            }
        }
    }

    // Cleanup
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable interrupts
    gpioSetMode(TRIG_PIN, PI_INPUT); // Set TRIG pin to input (safer)
    gpioSetMode(ECHO_PIN, PI_INPUT); // Set ECHO pin to input (safer)

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    pthread_mutex_destroy(&echo_mutex);

    printf("Program terminated.\n");
    return 0;
}

