int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g units (assuming +/- 2g range)
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Function to calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(config.buzzer_gpio, 1); // Turn on buzzer
    gpioDelay(IMPACT_DURATION * 1000000); // Delay for impact duration (microseconds)
    gpioWrite(config.buzzer_gpio, 0); // Turn off buzzer
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        config.freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        config.impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(config.buzzer_gpio, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    printf("Freefall threshold: %.2f g, Impact threshold: %.2f g\n", config.freefall_threshold, config.impact_threshold);

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            // Freefall detection
            if (magnitude < config.freefall_threshold) {
                printf("Freefall detected!\n");
            }

            // Impact detection
            if (magnitude > config.impact_threshold) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (init_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break;
            }
            if (init_lis3dh() < 0) {
                fprintf(stderr, "Failed to re-initialize LIS3DH, exiting.\n");
                break;
            }
        }

        gpioDelay(10000); // Delay 10ms (100Hz data rate)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(config.buzzer_gpio, 0); // Ensure buzzer is off
    gpioTerminate();

    return 0;
}

