#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Stepper motor parameters
#define STEPS_PER_REVOLUTION 2048.0
#define GEAR_RATIO 1.0 / 64.0
#define STEP_DELAY_US 1000

// Target square size (mm)
#define TARGET_SQUARE_SIZE 50.0

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    program_running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    return 0;
}

// Function to calculate the number of steps required to move a given distance
double calculate_steps(double distance) {
    return (distance / (20.0 * GEAR_RATIO)) * STEPS_PER_REVOLUTION;
}

// Function to perform a single step of the stepper motor
void step_motor(int motor_id, int step) {
    int in1, in2, in3, in4;

    if (motor_id == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor_id == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Invalid motor ID: %d\n", motor_id);
        return;
    }

    gpioWrite(in1, 0);
    gpioWrite(in2, 0);
    gpioWrite(in3, 0);
    gpioWrite(in4, 0);

    switch (step) {
        case 0:
            gpioWrite(in1, 1);
            break;
        case 1:
            gpioWrite(in2, 1);
            break;
        case 2:
            gpioWrite(in3, 1);
            break;
        case 3:
            gpioWrite(in4, 1);
            break;
        default:
            fprintf(stderr, "Invalid step number: %d\n", step);
            return;
    }

    gpioDelay(STEP_DELAY_US);
}

// Function to move a motor a specified number of steps
void move_motor(int motor_id, double steps) {
    int num_steps = (int)steps;
    for (int i = 0; i < num_steps; i++) {
        step_motor(motor_id, i % 4);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Calculate the number of steps required to trace the square
    double x_steps = calculate_steps(TARGET_SQUARE_SIZE);
    double y_steps = calculate_steps(TARGET_SQUARE_SIZE);

    printf("Moving X-axis %f steps, Y-axis %f steps\n", x_steps, y_steps);

    // Move the motors
    move_motor(1, x_steps);
    move_motor(2, y_steps);

    // Stop motors
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

