#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

// Global variables
int i2c_handle;
double threshold = 2.0;
int lis3dh_address = LIS3DH_ADDR;

// Function prototypes
int init_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
void log_high_acceleration(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to initialize the LIS3DH sensor
int init_lis3dh(int i2c_handle) {
    // Configure CTRL_REG1: 100Hz, enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: +/- 2g, high resolution
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH sensor
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0; *y = 0; *z = 0; // Return zeros on error
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to log high acceleration events to a file
void log_high_acceleration(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                lis3dh_address = strtol(optarg, NULL, 16);
                if (lis3dh_address < 0x18 || lis3dh_address > 0x19) {
                    fprintf(stderr, "Invalid I2C address. Must be 0x18 or 0x19.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtod(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, lis3dh_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH sensor
    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    accelerometer_data_t accel_data;
    while (1) {
        if (read_acceleration(i2c_handle, &accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Check for high acceleration
            if (abs(accel_data.x) > threshold || abs(accel_data.y) > threshold || abs(accel_data.z) > threshold) {
                log_high_acceleration(accel_data.x, accel_data.y, accel_data.z);
                system("sudo shutdown -h now");
                break; // Exit the loop after shutdown is initiated
            }
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup (should not reach here under normal circumstances due to shutdown)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

