#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define GPIO_RELAY 17
#define MAGNETIC_FIELD_THRESHOLD 5.0
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 50
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_magnetic_field(float *magnetic_field);
int control_relay(int state);
int log_event(const char *event_type, float magnetic_field);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7210_address;
    int gpio_relay;
    float magnetic_field_threshold;
    int sample_interval_ms;
    int max_retries;
    int timeout_ms;
} Config;

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read magnetic field from Si7210
int read_magnetic_field(float *magnetic_field) {
    char buf[2];
    int result;

    // Read two bytes from register 0x00
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (buf[0] << 8) | buf[1];

    // Convert raw value to magnetic field in mT (example conversion, adjust as needed)
    *magnetic_field = (float)raw_value * 0.01; // Example scaling factor

    return 0;
}

// Control the relay
int control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

// Log events to file
int log_event(const char *event_type, float magnetic_field) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s - %s: Magnetic Field = %.2f mT\n", timestamp, event_type, magnetic_field);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_RELAY as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float magnetic_field;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        // Read magnetic field
        if (read_magnetic_field(&magnetic_field) == 0) {
            // Log the reading
            log_event("Reading", magnetic_field);

            // Check if threshold is exceeded
            if (magnetic_field > MAGNETIC_FIELD_THRESHOLD && relay_state == 0) {
                // Activate relay
                control_relay(1);
                relay_state = 1;
                log_event("Relay Activated", magnetic_field);
            } else if (magnetic_field <= MAGNETIC_FIELD_THRESHOLD && relay_state == 1) {
                // Deactivate relay
                control_relay(0);
                relay_state = 0;
                log_event("Relay Deactivated", magnetic_field);
            }
        } else {
            fprintf(stderr, "Failed to read magnetic field. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

