#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"

int server_fd, new_socket;
FILE *log_file;

// Function to log messages to a file
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Received signal %d, shutting down...", signum);
    log_message(log_message_buffer);

    // Turn off the relay
    gpioWrite(GPIO_PIN, 0);

    // Close the socket
    close(new_socket);
    close(server_fd);

    // Close the log file
    fclose(log_file);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0'; // Null-terminate the received data

        // Trim trailing whitespace
        size_t len = strlen(buffer);
        while (len > 0 && (buffer[len - 1] == ' ' || buffer[len - 1] == '\n' || buffer[len - 1] == '\r' || buffer[len - 1] == '\t')) {
            buffer[len - 1] = '\0';
            len--;
        }

        if (strcasecmp(buffer, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
            log_message("Relay ON");
        } else if (strcasecmp(buffer, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0);
            log_message("Relay OFF");
        } else {
            char log_message_buffer[256];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Invalid command received: %s", buffer);
            log_message(log_message_buffer);
        }
    }

    if (bytes_received < 0) {
        perror("recv failed");
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_message("Socket creation failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        log_message("setsockopt failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind the socket to the specified address and port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_message("Socket bind failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        log_message("Socket listen failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_message("Server listening on port 5000");

    // Accept incoming connections
    while ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen))) {
        log_message("Connection accepted");
        handle_client(new_socket);
    }

    if (new_socket < 0) {
        perror("accept failed");
        log_message("Socket accept failed");
    }

    // Clean up resources before exiting
    close(server_fd);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

