// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define CRC_FINAL_XOR 0x00
#define START_MEASUREMENT_CMD_1 0x36
#define START_MEASUREMENT_CMD_2 0x2F

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int write_start_measurement(int handle);
int read_flow_rate(int handle, float *flow_rate);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
void control_relay(int gpio, int state);
void log_flow_rates(float flow_rate1, float flow_rate2);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float flow_rate;
    int crc_valid;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        cleanup();
        return 1;
    }

    // Configure relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    float flow_rate1, flow_rate2;
    int relay_state = 0; // 0 = off, 1 = on

    while (!terminate) {
        // Read flow rates from sensors
        if (read_flow_rate(i2c_handle1, &flow_rate1) != 0) {
            fprintf(stderr, "Error reading flow rate from sensor 1\n");
        }

        if (read_flow_rate(i2c_handle2, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading flow rate from sensor 2\n");
        }

        // Log flow rates
        log_flow_rates(flow_rate1, flow_rate2);

        // Control relay based on flow rates
        if (flow_rate1 < FLOW_THRESHOLD && flow_rate2 < FLOW_THRESHOLD) {
            if (relay_state == 0) {
                control_relay(RELAY_GPIO, 1); // Energize relay
                relay_state = 1;
            }
        } else {
            if (relay_state == 1) {
                control_relay(RELAY_GPIO, 0); // De-energize relay
                relay_state = 0;
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }

    // Start measurement command
    if (write_start_measurement(handle) != 0) {
        fprintf(stderr, "Failed to write start measurement command to sensor at address 0x%02X\n", addr);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Write start measurement command to sensor
int write_start_measurement(int handle) {
    char cmd[2] = {START_MEASUREMENT_CMD_1, START_MEASUREMENT_CMD_2};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write start measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read flow rate from sensor
int read_flow_rate(int handle, float *flow_rate) {
    char buffer[3];
    int result = i2cReadDevice(handle, buffer, 3);

    if (result != 3) {
        fprintf(stderr, "Failed to read 3 bytes from sensor: %d\n", result);
        return -1;
    }

    // Validate CRC
    if (!validate_crc((const uint8_t *)buffer, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to flow rate (example conversion, adjust as needed)
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 100.0; // Example scaling factor

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len);
    return (crc == data[len]);
}

// Control relay (active-high)
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log flow rates to file
void log_flow_rates(float flow_rate1, float flow_rate2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.2f,%.2f\n", timestamp_ms, flow_rate1, flow_rate2);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // De-energize relay
    control_relay(RELAY_GPIO, 0);

    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

