#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define DRY_READINGS_THRESHOLD 3
#define MOTOR_RUN_TIME_MS 5000
#define POLL_INTERVAL_MS 200

// Global variables
static volatile int running = 1;
static int dry_readings_count = 0;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    int reading = gpioRead(RAIN_SENSOR_PIN);
    if (reading < 0) {
        syslog(LOG_ERR, "Error reading rain sensor: %d", reading);
        return -1; // Indicate error
    }
    return reading;
}

// Function to close the window
void close_window() {
    syslog(LOG_INFO, "Closing window...");

    // Set motor control pins
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        syslog(LOG_ERR, "Error setting ENA high");
        return;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Error setting IN1 high");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Error setting IN2 low");
        return;
    }

    // Run motor for specified time
    gpioDelay(MOTOR_RUN_TIME_MS * 1000); // Convert ms to microseconds

    // Stop motor
    stop_motor();

    syslog(LOG_INFO, "Window closed.");
}

// Function to stop the motor
void stop_motor() {
    syslog(LOG_INFO, "Stopping motor...");

    // Set motor control pins to LOW
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_ERR, "Error setting ENA low");
        return;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Error setting IN1 low");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Error setting IN2 low");
        return;
    }

    syslog(LOG_INFO, "Motor stopped.");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Error setting rain sensor pin to input");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Error setting ENA pin to output");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Error setting IN1 pin to output");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Error setting IN2 pin to output");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set pull-up resistor on rain sensor pin
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "Error setting pull-up resistor on rain sensor pin");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Rain sensor monitoring started.");

    // Main loop
    while (running) {
        int rain_detected = 0;
        int i;

        // Read rain sensor multiple times
        for (i = 0; i < DRY_READINGS_THRESHOLD; i++) {
            int reading = read_rain_sensor();
            if (reading < 0) {
                // Error reading sensor, exit loop
                running = 0;
                break;
            }
            if (reading == 0) {
                rain_detected = 1;
                break;
            }
        }

        if (rain_detected) {
            // Rain detected
            dry_readings_count = 0; // Reset counter
            close_window();
        } else {
            // No rain detected
            dry_readings_count++;
            if (dry_readings_count >= DRY_READINGS_THRESHOLD) {
                // Sensor has been dry for the required time
                dry_readings_count = DRY_READINGS_THRESHOLD; // Prevent overflow
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Clean up and exit
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

