        int rain_detected = 0;
        int i;

        // Read rain sensor multiple times
        for (i = 0; i < DRY_READINGS_THRESHOLD; i++) {
            int reading = read_rain_sensor();
            if (reading < 0) {
                // Error reading sensor, exit loop
                running = 0;
                break;
            }
            if (reading == 0) {
                rain_detected = 1;
                break;
            }
        }

        if (rain_detected) {
            // Rain detected
            dry_readings_count = 0; // Reset counter
            close_window();
        } else {
            // No rain detected
            dry_readings_count++;
            if (dry_readings_count >= DRY_READINGS_THRESHOLD) {
                // Sensor has been dry for the required time
                dry_readings_count = DRY_READINGS_THRESHOLD; // Prevent overflow
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Clean up and exit
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

