    while (program_running) {
        // Read button states
        int lock_button_pressed = read_button(LOCK_BUTTON_PIN);
        int unlock_button_pressed = read_button(UNLOCK_BUTTON_PIN);

        // Handle lock button
        if (lock_button_pressed) {
            if (set_servo_pulse_width(LOCK_PULSE_WIDTH) == 0) {
                log_message("Locking door");
            } else {
                fprintf(stderr, "Error locking door.\n");
            }
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Handle unlock button
        if (unlock_button_pressed) {
            if (set_servo_pulse_width(UNLOCK_PULSE_WIDTH) == 0) {
                log_message("Unlocking door");
            } else {
                fprintf(stderr, "Error unlocking door.\n");
            }
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10 milliseconds
    }

    // Cleanup and exit
    return 0;
}

// Initializes the pigpio library and sets up the GPIO pins.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Reads the state of a button.
int read_button(int pin) {
    return gpioRead(pin);
}

// Sets the servo pulse width.
int set_servo_pulse_width(int pulse_width) {
    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return 1;
    }
    return 0;
}

// Logs a message to the console.
void log_message(const char *message) {
    printf("%s\n", message);
}

// Signal handler for graceful shutdown.
void signal_handler(int signal) {
    program_running = 0;
    log_message("Shutting down...");

    // Stop the servo
    set_servo_pulse_width(0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

