#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define LED_PIN 17

// Define constants
#define LED_ON_DURATION 60 // seconds
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int on);
int log_event(const char *event_type, int duration);
void cleanup();
void signal_handler(int signal);

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the PIR sensor state
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the LED (turn on or off)
int control_led(int on) {
    gpioWrite(LED_PIN, on);
    return 0;
}

// Function to log events to the security_log.txt file
int log_event(const char *event_type, int duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }

    if (strcmp(event_type, "activation") == 0) {
        fprintf(log_file, "%s - Motion detected - LED activated for %d seconds\n", timestamp, duration);
    } else if (strcmp(event_type, "deactivation") == 0) {
        fprintf(log_file, "%s - Motion stopped - LED deactivated after %d seconds\n", timestamp, duration);
    } else {
        fprintf(stderr, "Error: Invalid event type: %s\n", event_type);
        return 1;
    }

    fflush(log_file); // Ensure data is written to the file immediately
    return 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Function to clean up resources before exiting
void cleanup() {
    // Turn off the LED
    control_led(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int led_on = 0; // Flag to track LED state
    int motion_detected = 0;
    time_t start_time = 0;

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1 && !motion_detected) {
            // Motion detected
            motion_detected = 1;
            if (led_on == 0) {
                if (control_led(1) == 0) {
                    led_on = 1;
                    time(&start_time);
                    log_event("activation", LED_ON_DURATION);
                } else {
                    fprintf(stderr, "Error turning LED on!\n");
                    cleanup();
                    return 1;
                }
            }
        } else if (pir_value == 0 && motion_detected) {
            // Motion stopped
            motion_detected = 0;
            if (led_on == 1) {
                time_t current_time;
                time(&current_time);
                double elapsed_time = difftime(current_time, start_time);
                int duration = (int)elapsed_time;

                if (control_led(0) == 0) {
                    led_on = 0;
                    log_event("deactivation", duration);
                } else {
                    fprintf(stderr, "Error turning LED off!\n");
                    cleanup();
                    return 1;
                }
            }
        }

        gpioDelay(POLLING_INTERVAL); // Delay for polling interval
    }

    cleanup();
    return 0;
}

