// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17 // BCM GPIO 17
#define DEBOUNCE_DELAY_MS 200

// Global variables
int i2c_fd;
bool relay_state = false;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void relay_toggle();
void cleanup_handler(int signum);

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_E0FDL 0x41
#define MPR121_E0FDM 0x42
#define MPR121_E0FDH 0x43
#define MPR121_E0THL 0x44
#define MPR121_E0THH 0x45
#define MPR121_E0TL 0x46
#define MPR121_E0TH 0x47
#define MPR121_E0RH 0x48
#define MPR121_E0WH 0x49
#define MPR121_E0CFG 0x5E
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C


// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_FDLR, 0x06) < 0) return -1;

    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_MHDF, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_NHDF, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_NCLF, 0x0E) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_FDLF, 0x06) < 0) return -1;

    // Set debounce and filter threshold
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_FILTERTH_L, 0x10) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_FILTERTH_H, 0x00) < 0) return -1;

    // Configure electrode sensitivity
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0FDL, 0x05) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0FDM, 0x05) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0FDH, 0x05) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0THL, 0x05) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0THH, 0x05) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0TL, 0x00) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0TH, 0x00) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0RH, 0x00) < 0) return -1;
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_E0WH, 0x00) < 0) return -1;

    // Enable electrode 0
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x01) < 0) return -1;

    // Enable all electrodes
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x3F) < 0) return -1;

    // Configure operation mode
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG1, 0x10) < 0) return -1; // Set Electrode Configuration to 12 electrodes
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG2, 0x20) < 0) return -1; // Set operation mode to Run

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status_low = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_L);
    int touch_status_high = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_low < 0 || touch_status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Function to toggle the relay state
void relay_toggle() {
    relay_state = !relay_state;
    digitalWrite(RELAY_PIN, relay_state ? HIGH : LOW);
    printf("Relay toggled to: %s\n", relay_state ? "ON" : "OFF");
}

// Signal handler for cleanup
void cleanup_handler(int signum) {
    printf("Cleaning up and exiting...\n");
    digitalWrite(RELAY_PIN, LOW); // Ensure relay is OFF on exit
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPiSetupGpio failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: I2C setup failed\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() == -1) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW); // Initialize relay to OFF state

    // Set up signal handlers for cleanup
    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    printf("MPR121 and Relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Check if electrode 0 is touched (bit 0 of touch_status)
        if (touch_status & 0x01) {
            // Debounce delay
            delay(DEBOUNCE_DELAY_MS);

            // Re-read touch status to confirm the touch
            int confirmed_touch_status = mpr121_read_touch_status();
            if (confirmed_touch_status < 0) {
                fprintf(stderr, "Error reading touch status during debounce, retrying...\n");
                delay(100); // Small delay before retrying
                continue;
            }

            // Check if electrode 0 is still touched after debounce
            if (confirmed_touch_status & 0x01) {
                relay_toggle();
            }
        }

        delay(50); // Small delay to avoid busy-waiting
    }

    return 0;
}

