#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <stdarg.h>
#include <errno.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PULSE_WIDTH 1000 // 1-2ms pulse width
#define PWM_FREQUENCY 50
#define BUFFER_SIZE 1024

int server_fd, new_socket;
FILE *log_file;

// Function to log messages with timestamp
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    char message[BUFFER_SIZE];
    vsnprintf(message, sizeof(message), format, args);

    syslog(priority, "%s %s", timestamp, message);

    va_end(args);
}

// Function to set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid angle: %d. Angle must be between 0 and 180.", angle);
        return -1;
    }

    // Calculate pulse width (500us - 2500us)
    int pulse_width = 500 + (angle * 2000 / 180);

    if (gpioServo(SERVO_GPIO, pulse_width) != 0) {
        log_message(LOG_ERR, "Failed to set servo pulse width to %d", pulse_width);
        return -1;
    }

    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Servo angle set to %d degrees (pulse width: %d)", angle, pulse_width);
    log_message(LOG_INFO, log_message_buffer);

    return 0;
}

// Function to read PIR sensor
int read_pir_sensor() {
    int pir_value = gpioRead(PIR_GPIO);
    if (pir_value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor value.");
        return -1;
    }

    char log_message_buffer[50];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "PIR sensor value: %d", pir_value);
    log_message(LOG_INFO, log_message_buffer);

    return pir_value;
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        log_message(LOG_INFO, "Received command: %s", buffer);

        if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value != -1) {
                char response[50];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                send(client_socket, response, strlen(response), 0);
                log_message(LOG_INFO, "Sent PIR response: %s", response);
            }
        } else if (strncmp(buffer, "servo", 5) == 0) {
            char *angle_str = strchr(buffer, ' ');
            if (angle_str != NULL) {
                angle_str++; // Move past the space
                int angle = atoi(angle_str);
                if (set_servo_angle(angle) == 0) {
                    send(client_socket, "OK", 2, 0);
                    log_message(LOG_INFO, "Sent OK response");
                } else {
                    send(client_socket, "ERROR", 5, 0);
                    log_message(LOG_ERR, "Sent ERROR response");
                }
            } else {
                log_message(LOG_ERR, "Invalid servo command format.");
                send(client_socket, "ERROR", 5, 0);
            }
        } else {
            log_message(LOG_ERR, "Unknown command: %s", buffer);
            send(client_socket, "ERROR", 5, 0);
        }
    }

    if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected.");
    } else if (bytes_received < 0) {
        log_message(LOG_ERR, "Error receiving data: %s", strerror(errno));
    }

    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received, shutting down...");

    // Stop PWM
    gpioServo(SERVO_GPIO, 0);

    // Close socket
    close(new_socket);
    close(server_fd);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    closelog();

    exit(0);
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Set log message function
    log_message(LOG_INFO, "Starting security system...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(SERVO_GPIO, 255);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d...", PORT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Accept connections and handle them
    struct sockaddr_in client_address;
    int client_address_len = sizeof(client_address);

    while (1) {
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len);
        if (new_socket < 0) {
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue; // Continue listening for new connections
        }

        log_message(LOG_INFO, "Connection accepted from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(new_socket);
    }

    // The following lines will never be reached due to the infinite loop.
    close(server_fd);
    gpioTerminate();
    fclose(log_file);
    closelog();

    return 0;
}

