#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <getopt.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_DURATION 500

// Global variables
static volatile int running = 1;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static double threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;

// Function prototypes
int read_hx711(int *value);
double tare_hx711();
double read_weight();
void control_solenoid(int state);
void signal_handler(int signal);
void cleanup();

// Function to read data from HX711
int read_hx711(int *value) {
    int i;
    int data = 0;

    // Wait for DOUT to go low
    int timeout = 1000; // 1 second timeout
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "HX711 timeout waiting for DOUT low");
        return -1; // Timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse SCK one more time for gain selection (Channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *value = data;
    return 0; // Success
}

// Function to tare the HX711
double tare_hx711() {
    int i;
    double sum = 0.0;
    int value;

    for (i = 0; i < 10; i++) {
        if (read_hx711(&value) != 0) {
            syslog(LOG_ERR, "Error reading HX711 during tare");
            return 0.0; // Return 0 on error
        }
        sum += value;
        gpioDelay(10); // Small delay between readings
    }

    return sum / 10.0;
}

// Function to read weight from HX711
double read_weight() {
    int i;
    double sum = 0.0;
    int value;

    for (i = 0; i < 5; i++) {
        if (read_hx711(&value) != 0) {
            syslog(LOG_ERR, "Error reading HX711 during weight reading");
            return 0.0; // Return 0 on error
        }
        sum += value;
        gpioDelay(10); // Small delay between readings
    }

    return sum / 5.0;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    gpioDelay(duration);
    gpioWrite(SOLENOID_PIN, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    int hx711_value;
    double weight;

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:d:")) != -1) {
        switch (opt) {
            case 's':
                scale_factor = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s scale_factor] [-t threshold] [-d duration]\n", argv[0]);
                closelog();
                return 1;
        }
    }

    syslog(LOG_INFO, "Starting weight monitor...");
    syslog(LOG_INFO, "Scale factor: %f, Threshold: %f, Duration: %d", scale_factor, threshold, duration);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Tare the HX711
    double tare_value = tare_hx711();
    syslog(LOG_INFO, "Tare value: %f", tare_value);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        weight = (read_weight() - tare_value) * scale_factor;
        syslog(LOG_INFO, "Weight: %f", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded, activating solenoid");
            control_solenoid(1); // Activate solenoid
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

