#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define MQTT_KEEPALIVE 60

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to set GPIO pin state
int set_gpio_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", gpio);
        return -1;
    }
    return 0;
}

// Function to handle MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            if (set_gpio_state(GPIO_PIN, 1) != 0) {
                syslog(LOG_ERR, "Failed to set GPIO %d HIGH", GPIO_PIN);
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (set_gpio_state(GPIO_PIN, 0) != 0) {
                syslog(LOG_ERR, "Failed to set GPIO %d LOW", GPIO_PIN);
            }
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

// Function to handle MQTT connection
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_USER, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// Function to handle MQTT disconnection
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_USER, "MQTT disconnected with code %d", rc);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    syslog(LOG_USER, "Signal received, exiting...");
    running = 0;
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output and set initial state to LOW
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (set_gpio_state(GPIO_PIN, 0) != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set MQTT callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            sleep(5);
            rc = mosquitto_reconnect(mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "MQTT reconnect error: %s", mosquitto_strerror(rc));
            }
        }
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

