    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);

    gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT);
    gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT);
    gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT);
    gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE);

    // Set PWM duty cycle (initially 0)
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);

    // Set direction pins to forward
    gpioWrite(MOTOR_A_DIR, 1);
    gpioWrite(MOTOR_B_DIR, 1);

    // Register interrupt handlers
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A Phase A\n");
        stop_motors();
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A Phase B\n");
        stop_motors();
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B Phase A\n");
        stop_motors();
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B Phase B\n");
        stop_motors();
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    time_t last_print_time = time(NULL);

    while (1) {
        // Calculate RPM and PWM duty cycle
        double rpm_a, rpm_b;
        double duty_cycle_a, duty_cycle_b;

        // Protect shared resources with a mutex
        pthread_mutex_lock(&encoder_mutex);
        rpm_a = calculate_rpm(encoder_a_ticks);
        rpm_b = calculate_rpm(encoder_b_ticks);
        encoder_a_ticks = 0; // Reset ticks after reading
        encoder_b_ticks = 0;
        pthread_mutex_unlock(&encoder_mutex);

        duty_cycle_a = calculate_pwm_duty_cycle(rpm_a, TARGET_RPM);
        duty_cycle_b = calculate_pwm_duty_cycle(rpm_b, TARGET_RPM);

        // Anti-windup clamping
        if (duty_cycle_a > PWM_RANGE) duty_cycle_a = PWM_RANGE;
        if (duty_cycle_a < 0) duty_cycle_a = 0;
        if (duty_cycle_b > PWM_RANGE) duty_cycle_b = PWM_RANGE;
        if (duty_cycle_b < 0) duty_cycle_b = 0;

        // Set motor speeds
        set_motor_speed(MOTOR_A_PWM, MOTOR_A_DIR, duty_cycle_a);
        set_motor_speed(MOTOR_B_PWM, MOTOR_B_DIR, duty_cycle_b);

        // Stall detection
        time_t current_time = time(NULL);
        if (encoder_a_ticks == 0 && (current_time - last_encoder_a_tick) > STALL_TIMEOUT) {
            fprintf(stderr, "Encoder A stall detected!\n");
            last_encoder_a_tick = current_time; // Prevent repeated warnings
        }
        if (encoder_b_ticks == 0 && (current_time - last_encoder_b_tick) > STALL_TIMEOUT) {
            fprintf(stderr, "Encoder B stall detected!\n");
            last_encoder_b_tick = current_time; // Prevent repeated warnings
        }

        // Print RPM and PWM duty cycle every 1 second
        if (time(NULL) - last_print_time >= 1) {
            printf("Motor A RPM: %.2f, Duty Cycle: %.2f\n", rpm_a, duty_cycle_a);
            printf("Motor B RPM: %.2f, Duty Cycle: %.2f\n", rpm_b, duty_cycle_b);
            last_print_time = time(NULL);
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user; // Unused parameters
    pthread_mutex_lock(&encoder_mutex);
    encoder_a_ticks++;
    last_encoder_a_tick = time(NULL);
    pthread_mutex_unlock(&encoder_mutex);
}

void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user; // Unused parameters
    pthread_mutex_lock(&encoder_mutex);
    encoder_b_ticks++;
    last_encoder_b_tick = time(NULL);
    pthread_mutex_unlock(&encoder_mutex);
}

double calculate_rpm(int ticks) {
    return (double)ticks / ENCODER_TICKS_PER_RPM;
}

double calculate_pwm_duty_cycle(double rpm, double target_rpm) {
    double error = target_rpm - rpm;
    integral_a += error;
    if (integral_a > PWM_RANGE) integral_a = PWM_RANGE;
    if (integral_a < 0) integral_a = 0;
    double output = Kp * error + Ki * integral_a;
    return output;
}

void set_motor_speed(int motor_pwm, int motor_dir, double duty_cycle) {
    gpioWrite(motor_dir, 1); // Forward
    gpioPWM(motor_pwm, (int)duty_cycle);
}

void stop_motors() {
    gpioWrite(MOTOR_A_PWM, 0);
    gpioWrite(MOTOR_B_PWM, 0);
}

void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping motors and exiting.\n");
    stop_motors();
    gpioTerminate();
    exit(0);
}

