#define LUX_THRESHOLD_HIGH 200
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_gpio();
int read_bh1750(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_data(FILE *log_file, int lux, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char config_mode[] = {0x10}; // Continuous high resolution mode
    char buffer[2];
    int lux;

    if (i2cWriteDevice(i2c_handle, config_mode, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

// Control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log data to file
void log_data(FILE *log_file, int lux, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int lux, relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Chicken coop monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read lux value
        lux = read_bh1750(i2c_handle);
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, turning off relay\n");
            control_relay(GPIO_PIN, 0);
            relay_state = 0;
            log_data(log_file, -1, relay_state); // Log error
        } else {
            // Control relay based on lux value
            if (lux < LUX_THRESHOLD_LOW && relay_state == 0) {
                control_relay(GPIO_PIN, 1);
                relay_state = 1;
                log_data(log_file, lux, relay_state);
            } else if (lux > LUX_THRESHOLD_HIGH && relay_state == 1) {
                control_relay(GPIO_PIN, 0);
                relay_state = 0;
                log_data(log_file, lux, relay_state);
            }
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Turn off relay on exit
    fclose(log_file);
    gpioTerminate();

    printf("Chicken coop monitoring stopped.\n");

    return 0;
}

