// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the current relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
int debounce_touch();
int toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch() {
    int stable_high_count = 0;
    while (stable_high_count < 2) {
        if (read_touch_sensor() == 1) {
            stable_high_count++;
        } else {
            stable_high_count = 0;
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }
    return 1; // Valid touch detected
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Function to log the relay state with timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state == 1) {
        printf("%s Relay ON\n", timestamp);
    } else {
        printf("%s Relay OFF\n", timestamp);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Touch-toggled relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            if (debounce_touch()) {
                toggle_relay();
                log_relay_state(relay_state);
                // Wait for the touch sensor to return LOW
                while (read_touch_sensor() == 1) {
                    gpioDelay(10000); // Check every 10ms
                }
            }
        }
        gpioDelay(10000); // Sleep for 10ms
    }

    return 0;
}

