#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT_MS 1000 // 1 second
#define LOG_FILE "water_flow.log"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulse_count);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Function to handle the interrupt service routine (ISR)
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulse_count)
{
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm)
{
    static int solenoid_state = 1; // Initially open

    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1)
    {
        gpioWrite(SOLENOID_GPIO, 0); // Close solenoid
        solenoid_state = 0;
        log_data(lpm, solenoid_state);
    }
    else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0)
    {
        gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
        solenoid_state = 1;
        log_data(lpm, solenoid_state);
    }
}

// Function to log data to file
void log_data(double lpm, int solenoid_state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n",
            timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    log_data(0.0, 1); // Log solenoid open state on shutdown

    gpioWrite(SOLENOID_GPIO, 1); // Ensure solenoid is open on exit
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL)
    {
        fclose(log_file);
    }

    pthread_mutex_destroy(&pulse_mutex);

    exit(0);
}

int main()
{
