    gpioWrite(SOLENOID_GPIO, 1);

    // Set up interrupt service routine (ISR)
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT_MS, flow_sensor_isr, NULL) != 0)
    {
