#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <sys/file.h>
#include <errno.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Log file path
#define LOG_FILE "dispensing_log.json"

// Default values
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_SERVO_PIN 18

// HX711 GPIO pins
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24

// Servo PWM pin
#define SERVO_PIN 18

// Servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Load cell calibration factor
float calibration_factor = DEFAULT_CALIBRATION_FACTOR;

// Server IP address and port
char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
int server_port = DEFAULT_SERVER_PORT;

// Servo pin
int servo_pin = DEFAULT_SERVO_PIN;

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_socket = -1;

// Function prototypes
int read_config();
int read_hx711();
float calibrate_weight(float raw_weight);
int dispense(float target_weight);
int send_weight_to_server(float target_weight, float actual_weight, const char *error_message);
int log_dispensing_event(float target_weight, float actual_weight, const char *error_message);
void signal_handler(int signal);

// Function to read configuration from file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse the line
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
                server_ip[INET_ADDRSTRLEN - 1] = 0; // Ensure null termination
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            } else if (strcmp(key, "servo_pin") == 0) {
                servo_pin = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 1000) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "Error: HX711 data pin timeout\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calibrate the raw weight reading
float calibrate_weight(float raw_weight) {
    return raw_weight / calibration_factor;
}

// Function to dispense the specified weight
int dispense(float target_weight) {
    int pulse_width;

    // Map the target weight to the servo pulse width range
    pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (target_weight / 1000.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set the servo pulse width
    gpioServo(servo_pin, pulse_width);

    // Wait for 1 second
    gpioDelay(1000); // 1000 ms = 1 second

    // Stop the servo
    gpioServo(servo_pin, 0);

    return 0;
}

// Function to send the actual weight to the server
int send_weight_to_server(float target_weight, float actual_weight, const char *error_message) {
    int sock = 0, valread;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};
    char json_string[256];

    snprintf(json_string, sizeof(json_string), "{\"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}", target_weight, actual_weight, error_message);

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation error");
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(server_port);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, server_ip, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection Failed");
        close(sock);
        return -1;
    }

    send(sock, json_string, strlen(json_string), 0);
    close(sock);
    return 0;
}

// Function to log the dispensing event
int log_dispensing_event(float target_weight, float actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Acquire exclusive lock
    if (flock(fileno(fp), LOCK_EX) == -1) {
        perror("Error acquiring lock");
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n", timestamp, target_weight, actual_weight, error_message);

    // Release lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        perror("Error releasing lock");
    }

    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, shutting down...\n");

    // Close server socket if open
    if (server_socket != -1) {
        close(server_socket);
    }

    // Stop PWM
    gpioServo(servo_pin, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration from file
    if (read_config() != 0) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(servo_pin, PI_OUTPUT);

    // Create server socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Could not create socket");
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(server_port);

    // Bind the socket to the specified address and port
    if (bind(server_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    // Listen for incoming connections
    if (listen(server_socket, 3) < 0) {
        perror("Listen failed");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);

    // Main loop
    while (program_running) {
        int new_socket;
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);

        // Accept incoming connection
        new_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (new_socket < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        // Receive target weight from client
        char buffer[1024] = {0};
        ssize_t bytes_received = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Receive failed");
            close(new_socket);
            continue;
        }

        buffer[bytes_received] = '\0';
        float target_weight = atof(buffer);

        printf("Received target weight: %.2f grams\n", target_weight);

        // Dispense the weight
        float actual_weight = 0.0;
        const char *error_message = NULL;
        int raw_weight = read_hx711();
        if (raw_weight != -1) {
            actual_weight = calibrate_weight((float)raw_weight);
            if (dispense(target_weight) != 0) {
                error_message = "Servo control failed";
            }
        } else {
            error_message = "HX711 read error";
        }

        // Send weight to server
        if (send_weight_to_server(target_weight, actual_weight, error_message) != 0) {
            fprintf(stderr, "Failed to send weight to server\n");
        }

        // Log dispensing event
        if (log_dispensing_event(target_weight, actual_weight, error_message) != 0) {
            fprintf(stderr, "Failed to log dispensing event\n");
        }

        // Close the connection
        close(new_socket);
    }

    // Clean up
    close(server_socket);
    gpioServo(servo_pin, 0);
    gpioTerminate();

    return 0;
}

