// Global variables
static volatile int running = 1;
static int debounce_interval = DEFAULT_DEBOUNCE_INTERVAL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_relay();
void log_relay_state(int state);
