    int current_state = gpioRead(RELAY_PIN);
    int new_state = (current_state == 0) ? 1 : 0; // Toggle the state
    gpioWrite(RELAY_PIN, new_state);
    return new_state;
}

// Function to log the relay state
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate(); // Terminate pigpio
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0 && argc > 2) {
            debounce_interval = atoi(argv[2]);
            if (debounce_interval <= 0) {
                fprintf(stderr, "Invalid debounce interval. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_INTERVAL);
                debounce_interval = DEFAULT_DEBOUNCE_INTERVAL;
            }
        } else {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor relay control started. Debounce interval: %d ms\n", debounce_interval);

    // Main loop
    while (running) {
        if (read_touch_sensor() == 1) {
            int relay_state = toggle_relay();
            log_relay_state(relay_state);
            gpioDelay(debounce_interval * 1000); // Debounce
        }
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

