#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define ANGLE_INCREMENT 10
#define DEFAULT_ANGLE 90

volatile sig_atomic_t program_running = 1;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = (int)(((float)angle / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

    // Set the servo pulse width
    int result = gpioPWM(GPIO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width. pigpio error code: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to get the current servo angle
int get_servo_angle() {
    // Calculate angle based on current pulse width
    int pulse_width = gpioGetPWMdutycycle(GPIO_PIN);
    if (pulse_width < 0) {
        fprintf(stderr, "Error: Failed to get servo pulse width.\n");
        return -1;
    }

    int angle = (int)(((float)pulse_width / MAX_PULSE_WIDTH) * MAX_ANGLE);
    return angle;
}

// Function to handle keyboard input
int handle_keyboard_input() {
    int input;
    struct termios old_termios, new_termios;

    // Save current terminal settings
    if (tcgetattr(STDIN_FILENO, &old_termios) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    // Set new terminal settings for raw input
    new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_cc[VMIN] = 1;  // Read at least 1 character
    new_termios.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    // Read input character
    input = getchar();

    // Restore original terminal settings
    if (tcsetattr(STDIN_FILENO, TCSANOW, &old_termios) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return input;
}

int main() {
    int angle;
    int input;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set initial servo angle
    if (set_servo_angle(DEFAULT_ANGLE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Servo control. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    // Main loop
    while (program_running) {
        input = handle_keyboard_input();

        if (input == '+') {
            angle = get_servo_angle();
            if (angle == -1) {
                program_running = 0; // Exit on error
                break;
            }
            angle += ANGLE_INCREMENT;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }
            if (set_servo_angle(angle) != 0) {
                program_running = 0; // Exit on error
                break;
            }
            printf("Angle: %d\n", angle);
        } else if (input == '-') {
            angle = get_servo_angle();
            if (angle == -1) {
                program_running = 0; // Exit on error
                break;
            }
            angle -= ANGLE_INCREMENT;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            }
            if (set_servo_angle(angle) != 0) {
                program_running = 0; // Exit on error
                break;
            }
            printf("Angle: %d\n", angle);
        } else if (input == 'q') {
            break;
        }

        usleep(10000); // Small delay to prevent busy-waiting
    }

    // Stop PWM signal
    gpioPWM(GPIO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

