#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

static volatile int running = 1;
static volatile unsigned long last_tick = 0;
static volatile int pulse_count = 0;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize the pigpio library and GPIO pin
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to detect rising edge with debouncing
void pulse_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) { // Rising edge
        unsigned long current_tick = tick;
        if (current_tick - last_tick > DEBOUNCE_MS * 1000) { // Convert ms to microseconds
            pulse_count++;
            last_tick = current_tick;
        }
    }
}

// Function to calculate RPM
double calculate_rpm() {
    static unsigned long last_pulse_count = 0;
    static struct timespec last_time;
    struct timespec current_time;
    double time_diff_sec;
    double rpm;

    clock_gettime(CLOCK_MONOTONIC, &current_time);

    time_diff_sec = (current_time.tv_sec - last_time.tv_sec) + (current_time.tv_nsec - last_time.tv_nsec) / 1e9;

    if (time_diff_sec > 0) {
        unsigned long pulse_diff = pulse_count - last_pulse_count;
        rpm = (double)pulse_diff / time_diff_sec * 60.0;
    } else {
        rpm = 0.0;
    }

    last_pulse_count = pulse_count;
    last_time = current_time;

    return rpm;
}

// Function to log RPM to file
int log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Function to print RPM to console
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize() != 0) {
        return 1;
    }

    // Set up interrupt handler for rising edge detection
    gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);

    struct timespec sleep_time;
    sleep_time.tv_sec = 5;  // 5 seconds
    sleep_time.tv_nsec = 0;

    // Main loop
    while (running) {
        nanosleep(&sleep_time, NULL);

        double rpm = calculate_rpm();
        print_rpm(rpm);

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Error logging RPM\n");
        }
    }

    // Cleanup
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

