#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int rc;
    int touch_state = 0; // 0 = released, 1 = touched
    time_t touch_start_time = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read touch sensor state
        int sensor_value = gpioRead(TOUCH_SENSOR_PIN);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading touch sensor\n");
            break; // Exit loop on error
        }

        // Detect rising edge
        if (sensor_value == 1 && touch_state == 0) {
            // Toggle relay state
            int current_relay_state = gpioRead(RELAY_PIN);
            int new_relay_state = (current_relay_state == 0) ? 1 : 0;
            rc = gpioWrite(RELAY_PIN, new_relay_state);
            if (rc != 0) {
                fprintf(stderr, "Error writing to relay pin\n");
                break; // Exit loop on error
            }

            touch_state = 1; // Update touch state
            touch_start_time = time(NULL); // Record start time
        } else if (sensor_value == 0 && touch_state == 1) {
            touch_state = 0; // Update touch state
        }

        // Check for continuous touch
        if (touch_state == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, touch_start_time) >= 10.0) {
                // Force relay OFF
                rc = gpioWrite(RELAY_PIN, 0);
                if (rc != 0) {
                    fprintf(stderr, "Error writing to relay pin\n");
                    break; // Exit loop on error
                }
                touch_state = 0; // Reset touch state
                fprintf(stderr, "Forcing relay OFF due to continuous touch\n");
            }
        }

        // Delay
        gpioDelay(50000); // 50 milliseconds
    }

    // Cleanup
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();

    return 0;
}

