#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define Kp (proportional gain)
#define KP 1.0

// Define target flow rate (L/min)
#define TARGET_FLOW_RATE 1.0

// Define flow rate measurement interval (ms)
#define FLOW_MEASUREMENT_INTERVAL 100

// Define log file name
#define LOG_FILE "flow_log.csv"

// Global variables
static volatile int pulse_count = 0;
static volatile int program_running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
double calculate_flow_rate(int pulses);
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate, double kp);
int set_valve_position(int duty_cycle);
int log_data(double flow_rate, int valve_position);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }

    // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    return 0;
}

// Function to calculate flow rate (L/min) from pulse count
double calculate_flow_rate(int pulses) {
    // Assuming one pulse per L/min
    return (double)pulses / FLOW_MEASUREMENT_INTERVAL * 60000.0 / 1000.0; // Convert pulses/ms to L/min
}

// Function to calculate PWM duty cycle based on flow rate and target flow rate
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate, double kp) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = kp * error;

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return (int)duty_cycle;
}

// Function to set valve position using PWM
int set_valve_position(int duty_cycle) {
    if (gpioPWM(VALVE_PWM_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", VALVE_PWM_PIN);
        return 1;
    }
    return 0;
}

// Function to log data to file
int log_data(double flow_rate, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L/min>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "-t") != 0) {
        fprintf(stderr, "Invalid argument: %s\n", argv[1]);
        return 1;
    }

    if (argc != 3) {
        fprintf(stderr, "Target flow rate missing.\n");
        return 1;
    }

    char *endptr;
    double target_flow_rate = strtod(argv[2], &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate: %s\n", argv[2]);
        return 1;
    }

    TARGET_FLOW_RATE = target_flow_rate;

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to register interrupt handler for GPIO %d\n", FLOW_SENSOR_PIN);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Measure flow rate
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval
        double flow_rate = calculate_flow_rate(current_pulse_count);

        // Calculate PWM duty cycle
        int duty_cycle = calculate_pwm_duty_cycle(flow_rate, TARGET_FLOW_RATE, KP);

        // Set valve position
        if (set_valve_position(duty_cycle) != 0) {
            program_running = 0; // Stop the program if setting valve position fails
        }

        // Log data
        if (log_data(flow_rate, duty_cycle) != 0) {
            program_running = 0; // Stop the program if logging fails
        }

        // Wait for the next measurement interval
        gpioDelay(FLOW_MEASUREMENT_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Shutdown sequence
    printf("Shutting down valve and cleaning up...\n");
    set_valve_position(0); // Close the valve
    gpioWrite(VALVE_ENABLE_PIN, 0); // Disable the valve
    fclose(log_file);
    gpioTerminate();

    return 0;
}

