#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Define RFID tag value
#define RFID_TAG_VALUE "1234567890"

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;

// Function prototypes
int read_rfid_tag(char *tag_value);
int verify_rfid_tag(const char *tag_value);
int read_button_press();
void control_locks(int lock1_state, int lock2_state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to read RFID tag from MFRC522
int read_rfid_tag(char *tag_value) {
    char spi_data[2];
    char spi_return_data[2];
    int result;

    // MFRC522 command to request tag data (example, adjust as needed)
    spi_data[0] = 0x02; // Request command
    spi_data[1] = 0x00; // Dummy data

    result = spiXfer(spi_handle, spi_data, spi_return_data, 2);

    if (result != 0) {
        log_event("ERROR", "SPI read failed");
        return -1; // Indicate error
    }

    // Check for all-zero response (no tag present)
    if (spi_return_data[0] == 0 && spi_return_data[1] == 0) {
        return 0; // No tag present
    }

    // Copy the received data to the tag_value buffer
    strncpy(tag_value, spi_return_data, 10); // Copy up to 10 bytes
    tag_value[10] = '\0'; // Null-terminate the string

    return 1; // Tag read successfully
}

// Function to verify RFID tag value
int verify_rfid_tag(const char *tag_value) {
    return (strcmp(tag_value, RFID_TAG_VALUE) == 0) ? 1 : 0;
}

// Function to read button press
int read_button_press() {
    return (gpioRead(BUTTON_PIN) == 0) ? 1 : 0; // Button is active low
}

// Function to control locks
void control_locks(int lock1_state, int lock2_state) {
    gpioWrite(LOCK_1_PIN, lock1_state);
    gpioWrite(LOCK_2_PIN, lock2_state);
}

// Function to log events
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s %s: %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("INFO", "Received signal, shutting down...");

    // Force locks to engaged state
    control_locks(1, 1);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

