#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID parameters
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Target speed (RPM)
#define TARGET_SPEED 60.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// PWM range
#define PWM_RANGE 1000

// Sampling time (ms)
#define SAMPLING_TIME 100

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

// Function prototypes
void motor_forward(int motor, int speed);
void motor_backward(int motor, int speed);
void motor_stop(int motor);
void encoder1_isr(int gpio, int level, uint32_t tick, void *user);
void encoder2_isr(int gpio, int level, uint32_t tick, void *user);
double pid_calculate(double setpoint, double actual_value, double *integral, double *previous_error);
void log_data(double motor1_speed, double motor2_speed, double pid_output, double pid_p, double pid_i, double pid_d);
void signal_handler(int signal);

// Motor control functions
void motor_forward(int motor, int speed) {
    if (motor == 1) {
        gpioWrite(MOTOR1_IN1, 1);
        gpioWrite(MOTOR1_IN2, 0);
        gpioPWM(MOTOR1_ENA, speed);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_IN3, 1);
        gpioWrite(MOTOR2_IN4, 0);
        gpioPWM(MOTOR2_ENB, speed);
    }
}

void motor_backward(int motor, int speed) {
    if (motor == 1) {
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 1);
        gpioPWM(MOTOR1_ENA, speed);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 1);
        gpioPWM(MOTOR2_ENB, speed);
    }
}

void motor_stop(int motor) {
    if (motor == 1) {
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioPWM(MOTOR1_ENA, 0);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);
        gpioPWM(MOTOR2_ENB, 0);
    }
}

// Encoder interrupt service routines
void encoder1_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user; // unused parameters
    pthread_mutex_lock(&encoder1_mutex);
    if (gpioRead(ENCODER1_B) == 0) {
        encoder1_count++;
    } else {
        encoder1_count--;
    }
    pthread_mutex_unlock(&encoder1_mutex);
}

void encoder2_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user; // unused parameters
    pthread_mutex_lock(&encoder2_mutex);
    if (gpioRead(ENCODER2_B) == 0) {
        encoder2_count++;
    } else {
        encoder2_count--;
    }
    pthread_mutex_unlock(&encoder2_mutex);
}

// PID controller function
double pid_calculate(double setpoint, double actual_value, double *integral, double *previous_error) {
    double error = setpoint - actual_value;
    *integral += error * SAMPLING_TIME / 1000.0; // Integrate the error
    double derivative = (error - *previous_error) / SAMPLING_TIME * 1000.0; // Differentiate the error
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Data logging function
void log_data(double motor1_speed, double motor2_speed, double pid_output, double pid_p, double pid_i, double pid_d) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_speed, motor2_speed, pid_output, pid_p, pid_i, pid_d);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    motor_stop(1);
    motor_stop(2);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE);

    // Set up interrupts for encoders
    gpioSetISRFuncEx(ENCODER1_A, RISING_EDGE, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(ENCODER2_A, RISING_EDGE, 0, encoder2_isr, NULL);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_Speed(RPM),Motor2_Speed(RPM),PID_Output,P,I,D\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    double integral1 = 0.0;
    double previous_error1 = 0.0;
    double integral2 = 0.0;
    double previous_error2 = 0.0;

    // Main loop
    while (1) {
        // Read encoder counts
        int current_encoder1_count;
        int current_encoder2_count;

        pthread_mutex_lock(&encoder1_mutex);
        current_encoder1_count = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        current_encoder2_count = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate motor speeds (RPM)
        double motor1_speed = (double)(current_encoder1_count - encoder1_count) * (60000.0 / PWM_FREQUENCY) / SAMPLING_TIME; // Encoder counts per second * 60
        double motor2_speed = (double)(current_encoder2_count - encoder2_count) * (60000.0 / PWM_FREQUENCY) / SAMPLING_TIME;

        // PID calculation
        double pid_output1 = pid_calculate(TARGET_SPEED, motor1_speed, &integral1, &previous_error1);
        double pid_output2 = pid_calculate(TARGET_SPEED, motor2_speed, &integral2, &previous_error2);

        // Motor control
        motor_forward(1, (int)pid_output1);
        motor_forward(2, (int)pid_output2);

        // Data logging
        log_data(motor1_speed, motor2_speed, pid_output1, pid_output1, integral1, previous_error1);

        // Wait for the next sample
        gpioDelay(SAMPLING_TIME * 1000); // Delay in microseconds
    }

    return 0;
}

