#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_ELECTRODECONFIG 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// GPIO pin for relay control
#define RELAY_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_mpr121();
int read_touch_status();
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_relay(0); // Turn off relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initializes the MPR121 sensor
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Configure electrode sensitivity
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) { // Set Electrode Configuration to enable all 12 electrodes
        fprintf(stderr, "Error: Failed to configure MPR121 electrode config\n");
        return -1;
    }

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_L, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to configure MPR121 filter threshold\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_H, 0x05) < 0) {
        fprintf(stderr, "Error: Failed to configure MPR121 filter threshold\n");
        return -1;
    }

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 0x30) < 0) {
            fprintf(stderr, "Error: Failed to configure MPR121 touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to configure MPR121 release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to enable MPR121 run mode\n");
        return -1;
    }

    return 0;
}

