// Structure to hold GPIO pin configurations
typedef struct {
    int valve1_pin;
    int valve2_pin;
} gpio_config_t;

// Global GPIO configuration
gpio_config_t gpio_config = {VALVE1_GPIO, VALVE2_GPIO};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop for the water distribution schedule
    while (program_running) {
        // Activate Valve 1
        activate_valve(gpio_config.valve1_pin, 500);
        log_event("Valve 1 activated for 500ms");
        gpioDelay(5000); // Pause for 5 seconds

        // Activate Valve 2
        activate_valve(gpio_config.valve2_pin, 1000);
        log_event("Valve 2 activated for 1000ms");
        gpioDelay(10000); // Pause for 10 seconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

