int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(gpio_config.valve1_pin, PI_OUTPUT);
    gpioSetMode(gpio_config.valve2_pin, PI_OUTPUT);

    // Ensure valves are initially deactivated
    deactivate_valve(gpio_config.valve1_pin);
    deactivate_valve(gpio_config.valve2_pin);

    return 0;
}

// Function to activate a solenoid valve
void activate_valve(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH to activate the valve
    gpioDelay(duration_ms);  // Keep the valve activated for the specified duration
    gpioWrite(gpio_pin, 0); // Set GPIO LOW to deactivate the valve
}

// Function to deactivate a solenoid valve
void deactivate_valve(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO LOW to deactivate the valve
}

// Function to log an event to the log file
void log_event(const char *event_description) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm);

    fprintf(fp, "%s: %s\n", timestamp, event_description);
    fclose(fp);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Deactivate all valves
    deactivate_valve(gpio_config.valve1_pin);
    deactivate_valve(gpio_config.valve2_pin);

    // Terminate the pigpio library
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0; // Set the flag to exit the main loop
}

