#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define NUM_ELECTRODES 12

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_ELECTRODECONFIG 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_stop();
int mpr121_start();
int mpr121_set_thresholds(uint8_t touch_threshold, uint8_t release_threshold);
int mpr121_set_filter_config(uint8_t filter_config);
int mpr121_set_electrode_config(uint8_t electrode_config);
int mpr121_read_touch_status();
int mpr121_toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// MPR121 Initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set Electrode Configuration to 0x00\n");
        return -1;
    }

    // Configure touch and release thresholds
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (mpr121_set_thresholds(40, 20) < 0) {
            fprintf(stderr, "Error: Failed to set thresholds for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (mpr121_set_filter_config(0x10) < 0) {
        fprintf(stderr, "Error: Failed to set filter configuration\n");
        return -1;
    }

    // Set electrode configuration to enable all 12 electrodes
    if (mpr121_set_electrode_config(0x3F) < 0) {
        fprintf(stderr, "Error: Failed to set electrode configuration\n");
        return -1;
    }

    return 0;
}

// MPR121 Stop Mode function
int mpr121_stop() {
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set Electrode Configuration to 0x00 (stop mode)\n");
        return -1;
    }
    return 0;
}

// MPR121 Start Mode function
int mpr121_start() {
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECONFIG, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set Electrode Configuration to 0x10 (run mode)\n");
        return -1;
    }
    return 0;
}

// MPR121 Set Thresholds function
int mpr121_set_thresholds(uint8_t touch_threshold, uint8_t release_threshold) {
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, touch_threshold) < 0) {
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, release_threshold) < 0) {
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }
    return 0;
}

