#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_motion_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void control_relay(int state);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int pir_pin;
    int relay_pin;
    char *log_file_name;
} Config;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Control the relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Log events to file
void log_event(const char *event_type) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    control_relay(0); // Turn off relay
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            // Motion detected
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            unsigned long current_time = (unsigned long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);

            if (current_time - last_motion_time > RATE_LIMIT_MS) {
                log_event("Motion Detected");
                control_relay(1); // Activate relay
                gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
                control_relay(0); // Deactivate relay
                log_event("Door Unlocked");
                last_motion_time = current_time;
            } else {
                log_event("Rate Limited");
            }
        }

        gpioDelay(50 * 1000); // Delay for 50 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

