#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global flag to signal program termination
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    shutdown_flag = 1;
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes for the motors
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency for the motors
    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    // Set PWM range for the motors
    if (gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a random haptic feedback pattern
int generate_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations, int *num_steps) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate the number of steps for the pattern
    *num_steps = (rand() % 11) + 5; // Random number between 5 and 15

    // Allocate memory for the duty cycles and durations
    *motor1_duty_cycles = (int *)malloc(*num_steps * sizeof(int));
    *motor2_duty_cycles = (int *)malloc(*num_steps * sizeof(int));
    *durations = (int *)malloc(*num_steps * sizeof(int));

    if (*motor1_duty_cycles == NULL || *motor2_duty_cycles == NULL || *durations == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Generate the pattern data
    for (int i = 0; i < *num_steps; i++) {
        // Generate random duty cycles for each motor
        (*motor1_duty_cycles)[i] = (rand() % 256);
        (*motor2_duty_cycles)[i] = (rand() % 256);

        // Generate random durations for each step
        (*durations)[i] = (rand() % 151) + 50; // Random number between 50 and 200
    }

    return 0;
}

// Function to play a haptic feedback pattern
void play_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        // Set the PWM duty cycles for each motor
        gpioPWM(MOTOR1_GPIO, motor1_duty_cycles[i]);
        gpioPWM(MOTOR2_GPIO, motor2_duty_cycles[i]);

        // Delay for the specified duration
        gpioDelay(durations[i] * 1000); // Convert milliseconds to microseconds
    }
}

// Function to stop both motors
void stop_motors() {
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
}

// Function to free allocated memory
void free_memory(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations) {
    if (motor1_duty_cycles != NULL) free(motor1_duty_cycles);
    if (motor2_duty_cycles != NULL) free(motor2_duty_cycles);
    if (durations != NULL) free(durations);
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and set GPIO modes
    if (initialize_gpio() != 0) {
        return 1;
    }

    int *motor1_duty_cycles = NULL;
    int *motor2_duty_cycles = NULL;
    int *durations = NULL;
    int num_steps;

    // Main loop to generate and play random patterns
    while (!shutdown_flag) {
        // Generate a new haptic feedback pattern
        if (generate_pattern(&motor1_duty_cycles, &motor2_duty_cycles, &durations, &num_steps) != 0) {
            fprintf(stderr, "Failed to generate pattern\n");
            break; // Exit loop on error
        }

        // Play the generated pattern
        play_pattern(motor1_duty_cycles, motor2_duty_cycles, durations, num_steps);

        // Free allocated memory
        free_memory(motor1_duty_cycles, motor2_duty_cycles, durations);
        motor1_duty_cycles = NULL;
        motor2_duty_cycles = NULL;
        durations = NULL;

        // Small delay before generating the next pattern
        gpioDelay(100000); // 100ms
    }

    // Stop both motors
    stop_motors();

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

