#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define weight threshold (in kg)
#define WEIGHT_THRESHOLD 10.0

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 500

// Define number of calibration readings
#define NUM_CALIBRATION_READINGS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Structure to hold calibration data
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Function prototypes
int initialize_gpio();
int read_hx711();
double calculate_weight(int raw_value, CalibrationData calibration);
void control_solenoid(double weight);
void log_data(int raw_value, double weight);
CalibrationData load_calibration_data();
void save_calibration_data(CalibrationData calibration);
void calibrate_sensor();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Function to read data from HX711 sensor
int read_hx711() {
    int data = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);

    // Wait for data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_DURATION) {
        fprintf(stderr, "Timeout reading HX711 data\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high duration
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low duration
    }

    // 25th pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value, CalibrationData calibration) {
    return (double)raw_value / calibration.scale_factor + calibration.offset;
}

// Function to control solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    }
}

// Function to log data to file
void log_data(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_value, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to load calibration data from file
CalibrationData load_calibration_data() {
    CalibrationData calibration = {1.0, 0.0};
    char line[256];

    calibration_file = fopen("calibration.txt", "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Calibration file not found, using default values\n");
        return calibration;
    }

    if (fgets(line, sizeof(line), calibration_file) == NULL) {
        fprintf(stderr, "Error reading calibration file, using default values\n");
        fclose(calibration_file);
        return calibration;
    }

    if (sscanf(line, "%lf %lf", &calibration.scale_factor, &calibration.offset) != 2) {
        fprintf(stderr, "Invalid calibration file format, using default values\n");
        calibration.scale_factor = 1.0;
        calibration.offset = 0.0;
    }

    fclose(calibration_file);
    return calibration;
}

// Function to save calibration data to file
void save_calibration_data(CalibrationData calibration) {
    calibration_file = fopen("calibration.txt", "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        return;
    }

    fprintf(calibration_file, "%.6f %.6f", calibration.scale_factor, calibration.offset);
    fclose(calibration_file);
}

// Function to calibrate the sensor
void calibrate_sensor() {
    int i;
    int raw_value;
    double sum = 0.0;

    printf("Calibrating sensor... Please ensure no weight is applied.\n");

    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711 during calibration\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    double offset = sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %.2f\n", offset);

    CalibrationData calibration = load_calibration_data();
    calibration.offset = offset;
    save_calibration_data(calibration);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Load calibration data
    CalibrationData calibration = load_calibration_data();

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Calibrate sensor if needed
    // In a real-world scenario, you might want to add a command-line argument
    // to force calibration.
    // For this example, we'll just calibrate on the first run.
    calibrate_sensor();

    printf("Weight-triggered solenoid lock system started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value, calibration);
            control_solenoid(weight);
            log_data(raw_value, weight);
        } else {
            fprintf(stderr, "Error reading HX711, skipping iteration\n");
        }

        gpioDelay(500); // Read every 500 ms
    }

    // Clean up
    gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

