#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define RAIN_THRESHOLD 3
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define MOTOR_PWM_FREQUENCY 1000
#define MOTOR_PWM_DUTY_CYCLE 150
#define MOTOR_RUN_TIME_SEC 5
#define SENSOR_CHECK_INTERVAL_SEC 60
#define MOTOR_COOLDOWN_SEC 60

// Global variables
static volatile int running = 1;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor(int num_readings);
void control_motor(int direction);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    int value = gpioRead(RAIN_SENSOR_PIN);
    if (value < 0) {
        log_event("Error reading rain sensor");
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce the rain sensor readings
int debounce_rain_sensor(int num_readings) {
    int low_count = 0;
    for (int i = 0; i < num_readings; i++) {
        int reading = read_rain_sensor();
        if (reading < 0) return -1; // Propagate error
        if (reading == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return low_count;
}

// Function to control the motor
void control_motor(int direction) {
    if (direction == 1) { // Close window
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY_CYCLE);
        log_event("Closing window");
        gpioDelay(MOTOR_RUN_TIME_SEC * 1000000); // Run motor for specified time
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Window closed");
    } else { // Stop motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Motor stopped");
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_check_time = 0;
    time_t last_motor_time = 0;

    // Main loop
    while (running) {
        time_t current_time = time(NULL);

        // Check if it's time to check the rain sensor
        if (difftime(current_time, last_check_time) >= SENSOR_CHECK_INTERVAL_SEC) {
            int rain_detected = debounce_rain_sensor(DEBOUNCE_READINGS);
            if (rain_detected < 0) {
                // Error reading sensor, already logged in debounce_rain_sensor
                last_check_time = current_time; // Prevent immediate retry
                gpioDelay(SENSOR_CHECK_INTERVAL_SEC * 1000000); // Delay to avoid spamming logs
                continue;
            }

            if (rain_detected >= RAIN_THRESHOLD) {
                log_event("Rain detected");
                control_motor(1); // Close window
                last_motor_time = current_time;
            }
            last_check_time = current_time;
        }

        // Check if it's time to wait before the next check
        if (difftime(current_time, last_check_time) < SENSOR_CHECK_INTERVAL_SEC) {
            gpioDelay((SENSOR_CHECK_INTERVAL_SEC - difftime(current_time, last_check_time)) * 1000000); // Delay to wait
        }

        // Check if it's time to wait after the motor operation
        if (difftime(current_time, last_motor_time) >= MOTOR_COOLDOWN_SEC) {
            last_check_time = current_time; // Allow immediate retry after cooldown
        }

        gpioDelay(100000); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler is used)
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    return 0;
}

