#define TIMEOUT_US 100000         // 100ms timeout

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
long read_hx711();
float convert_to_grams(long raw_value);
void activate_solenoid(int duration_seconds);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read data from HX711
long read_hx711() {
    long value = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DT) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        log_event("HX711 read timeout");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        value = value << 1;
        if (gpioRead(HX711_DT)) {
            value++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // 25th pulse for gain setting (Channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Sign extend if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Function to convert raw value to grams
float convert_to_grams(long raw_value) {
    // Calibration factor (adjust based on your setup)
    // This is a placeholder; you'll need to calibrate your load cell
    float calibration_factor = 420.0; // Example: raw value of 1g gives 420
    return (float)raw_value / calibration_factor;
}

