void activate_solenoid(int duration_seconds) {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    log_event("Solenoid activated");
    gpioDelay(duration_seconds * 1000); // Delay for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
