#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Calibration file path
#define CALIBRATION_FILE "calibration.txt"

// Log file path
#define LOG_FILE "security.log"

// Weight threshold in kg
#define WEIGHT_THRESHOLD 5.0

// Timeout threshold in microseconds
#define TIMEOUT_THRESHOLD 100000 // 100ms

// Solenoid activation time in seconds
#define SOLENOID_ACTIVATION_TIME 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double calibration_factor = 0.0;

// Function prototypes
int read_hx711();
double calibrate_hx711();
double convert_to_kg(int raw_value, double calibration_factor);
void activate_solenoid();
void log_event(double weight);
void signal_handler(int signal);
int read_calibration_factor();
int write_calibration_factor(double factor);

// Function to read the HX711 value
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for the data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_THRESHOLD) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_THRESHOLD) {
        fprintf(stderr, "Error: HX711 timeout\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calibrate the HX711
double calibrate_hx711() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight\n");
        return -1.0;
    }

    printf("Reading raw value...");
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration\n");
        return -1.0;
    }
    printf("Raw value: %d\n", raw_value);

    return known_weight / (double)raw_value;
}

// Function to convert raw value to kg
double convert_to_kg(int raw_value, double calibration_factor) {
    return (double)raw_value * calibration_factor;
}

// Function to activate the solenoid
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Set HIGH
    gpioDelay(SOLENOID_ACTIVATION_TIME * 1000000); // Wait for 5 seconds
    gpioWrite(SOLENOID_PIN, 0); // Set LOW
}

// Function to log events to a file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return;
    }

    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Unlock solenoid
    gpioWrite(SOLENOID_PIN, 0);

    // Close pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to read calibration factor from file
int read_calibration_factor() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file, using default calibration factor (1.0)\n");
        return -1; // Indicate failure to open file
    }

    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Warning: Could not read calibration factor from file, using default calibration factor (1.0)\n");
        fclose(fp);
        return -1; // Indicate failure to read from file
    }

    fclose(fp);
    printf("Calibration factor read from file: %.2f\n", calibration_factor);
    return 0; // Indicate success
}

// Function to write calibration factor to file
int write_calibration_factor(double factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing\n");
        return -1; // Indicate failure to open file
    }

    if (fprintf(fp, "%lf", factor) < 0) {
        fprintf(stderr, "Error: Could not write calibration factor to file\n");
        fclose(fp);
        return -1; // Indicate failure to write to file
    }

    fclose(fp);
    printf("Calibration factor written to file: %.2f\n", factor);
    return 0; // Indicate success
}

int main() {
    int raw_value;
    double weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially unlocked

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration factor from file
    if (read_calibration_factor() != 0) {
        // If reading fails, calibrate the sensor
        calibration_factor = calibrate_hx711();
        if (calibration_factor < 0) {
            fprintf(stderr, "Error: Calibration failed\n");
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
        if (write_calibration_factor(calibration_factor) != 0) {
            fprintf(stderr, "Warning: Failed to write calibration factor to file\n");
        }
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711 value\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        weight = convert_to_kg(raw_value, calibration_factor);

        printf("Raw Value: %d, Weight: %.2f kg\n", raw_value, weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Activating solenoid.\n");
            activate_solenoid();
            log_event(weight);
        }

        gpioDelay(100000); // Delay 0.1 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

