#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open configuration file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from configuration file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the duration from the line
    char *key = strtok(line, "=");
    char *value_str = strtok(NULL, "=");

    if (key == NULL || value_str == NULL) {
        fprintf(stderr, "Error: Invalid format in configuration file %s\n", filename);
        return -1;
    }

    int duration = atoi(value_str);

    // Validate the duration
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Watering duration out of range (1-3600 seconds) in configuration file %s\n", filename);
        return -1;
    }

    return duration;
}

// Function to activate the watering valve
int activate_valve(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate valve (GPIO %d)\n", gpio_pin);
        return -1;
    }
    printf("Valve activated (GPIO %d)\n", gpio_pin);
    return 0;
}

// Function to deactivate the watering valve
int deactivate_valve(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate valve (GPIO %d)\n", gpio_pin);
        return -1;
    }
    printf("Valve deactivated (GPIO %d)\n", gpio_pin);
    return 0;
}

// Function to perform the watering cycle
int watering_cycle(int gpio_pin, int duration) {
    if (activate_valve(gpio_pin) != 0) {
        return -1;
    }

    // Use nanosleep for interruptible sleep
    struct timespec req, rem;
    req.tv_sec = duration;
    req.tv_nsec = 0;

    if (nanosleep(&req, &rem) != 0) {
        fprintf(stderr, "Error: nanosleep interrupted\n");
        return -1;
    }

    if (deactivate_valve(gpio_pin) != 0) {
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Set pull-down resistor

    // Main loop
    while (!terminate) {
        // Read the watering duration from the configuration file
        int duration = read_watering_duration(CONFIG_FILE);
        if (duration == -1) {
            fprintf(stderr, "Error: Failed to read watering duration, exiting...\n");
            break;
        }

        // Perform the watering cycle
        if (watering_cycle(GPIO_PIN, duration) != 0) {
            fprintf(stderr, "Error: Watering cycle failed, exiting...\n");
            break;
        }

        // Check for termination signal after watering cycle
        if (terminate) {
            break;
        }

        // Wait for 24 hours before the next cycle
        sleep(86400); // 24 * 60 * 60
    }

    // Deactivate the valve before exiting
    deactivate_valve(GPIO_PIN);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

