void print_status(const char *message);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        print_status("Caught SIGINT, cleaning up...");
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Initializes the pigpio library and sets up the GPIO pins.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Reads the state of a button with debouncing.
int read_button(int gpio_pin) {
    int button_state = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay (microseconds)
    return button_state;
}

// Sets the servo pulse width.
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Pulse width out of range (500-2500 us): %d\n", pulse_width);
        return 1; // Indicate failure
    }
    gpioServo(gpio_pin, pulse_width);
    return 0; // Indicate success
}

// Prints a status message to the console.
void print_status(const char *message) {
    printf("%s\n", message);
}

// Cleans up the GPIO pins and terminates the pigpio library.
void cleanup_gpio() {
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    print_status("Door lock control system started.");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (read_button(LOCK_BUTTON_PIN) == 0) {
            if (set_servo_pulse_width(SERVO_PIN, LOCK_PULSE_WIDTH) == 0) {
                print_status("Door locked.");
            }
        }

        // Check for unlock button press
        if (read_button(UNLOCK_BUTTON_PIN) == 0) {
            if (set_servo_pulse_width(SERVO_PIN, UNLOCK_PULSE_WIDTH) == 0) {
                print_status("Door unlocked.");
            }
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting (10ms)
    }

    return 0;
}

