// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse durations in milliseconds
#define MOTOR1_PULSE_DURATION 200
#define MOTOR2_PULSE_DURATION 300

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, stopping motors and exiting...\n", signal);
    program_running = 0;
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to pulse a motor for a specified duration
void pulse_motor(int gpio_pin, int duration_ms) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", gpio_pin);
        return;
    }
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", gpio_pin);
        return;
    }
}

// Function to perform the haptic feedback sequence
void haptic_feedback() {
    pulse_motor(MOTOR1_GPIO, MOTOR1_PULSE_DURATION);
    pulse_motor(MOTOR2_GPIO, MOTOR2_PULSE_DURATION);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        haptic_feedback();
    }

    // Stop motors and terminate pigpio
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);
    gpioTerminate();

    fprintf(stderr, "Haptic feedback system stopped.\n");

    return 0;
}

