#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define ZeroMQ topic
#define ZMQ_TOPIC "SOUND_ALERTS"

// Global variables for cleanup
static volatile int running = 1;
static void *context = NULL;
static void *publisher = NULL;
static void *subscriber = NULL;

// Function prototypes
int initialize_gpio();
int initialize_zmq();
void cleanup();
void signal_handler(int signal);
void publish_sound_event();
void handle_alarm_message(const char *message);

// Structure to hold program configuration
typedef struct {
    int mode; // 0 for sound_sensor, 1 for alarm_node
} program_config_t;

// Function to parse command-line arguments
program_config_t parse_arguments(int argc, char *argv[]) {
    program_config_t config;
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        config.mode = 0;
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        config.mode = 1;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        exit(EXIT_FAILURE);
    }

    return config;
}

int main(int argc, char *argv[]) {
    program_config_t config = parse_arguments(argc, argv);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return EXIT_FAILURE;
    }

    // Initialize ZeroMQ
    if (initialize_zmq() != 0) {
        fprintf(stderr, "Failed to initialize ZeroMQ.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (config.mode == 0) {
        // Sound sensor mode
        printf("Running in sound sensor mode.\n");
        while (running) {
            publish_sound_event();
            gpioDelay(10000); // 10 ms
        }
    } else {
        // Alarm node mode
        printf("Running in alarm node mode.\n");
        while (running) {
            char buffer[256];
            int bytes = zmq_recv(subscriber, buffer, sizeof(buffer) - 1, 0);
            if (bytes > 0) {
                buffer[bytes] = '\0';
                handle_alarm_message(buffer);
            } else {
                // Handle ZeroMQ errors or timeout
                if (errno != EAGAIN && errno != EINTR) {
                    fprintf(stderr, "ZeroMQ receive error: %s\n", zmq_strerror(errno));
                    break;
                }
            }
        }
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

int initialize_zmq() {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context.\n");
        return -1;
    }

    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Failed to create ZeroMQ publisher socket.\n");
        return -1;
    }

    int rc = zmq_bind(publisher, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ publisher socket: %s\n", zmq_strerror(errno));
        return -1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket.\n");
        return -1;
    }

    rc = zmq_connect(subscriber, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to connect ZeroMQ subscriber socket: %s\n", zmq_strerror(errno));
        return -1;
    }

    rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (rc != 0) {
        fprintf(stderr, "Failed to set ZeroMQ subscriber socket option: %s\n", zmq_strerror(errno));
        return -1;
    }

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");

    // Disable alarm LED
    gpioWrite(ALARM_LED_PIN, 0);

    // Close ZeroMQ sockets and context
    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down...\n", signal);
    running = 0;
}

void publish_sound_event() {
    if (gpioRead(SOUND_SENSOR_PIN) == 0) {
        // Sound detected
        zmq_msg_t message;
        zmq_msg_init_size(&message, strlen(ZMQ_TOPIC));
        memcpy(zmq_msg_data(&message), ZMQ_TOPIC, strlen(ZMQ_TOPIC));

        int rc = zmq_msg_send(&message, publisher, ZMQ_DONTWAIT);
        zmq_msg_close(&message);

        if (rc == -1) {
            fprintf(stderr, "Failed to send ZeroMQ message: %s\n", zmq_strerror(errno));
        } else {
            printf("Published sound event.\n");
        }
    }
}

void handle_alarm_message(const char *message) {
    if (strcmp(message, ZMQ_TOPIC) == 0) {
        printf("Received alarm message. Activating alarm.\n");
        gpioWrite(ALARM_LED_PIN, 1); // Turn on alarm LED
        gpioDelay(1000000);          // Wait for 1 second
        gpioWrite(ALARM_LED_PIN, 0); // Turn off alarm LED
        printf("Alarm deactivated.\n");
    }
}

