#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <time.h>

// Configuration
#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define MAX_PULSES 100
#define PULSE_BUFFER_SIZE 100

// NEC Protocol Constants
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_CHECKSUM_BITS 8

// Global Variables
static volatile int pulse_count = 0;
static volatile unsigned int pulse_buffer[PULSE_BUFFER_SIZE];
static volatile unsigned int last_tick = 0;
static struct mosquitto *mosq = NULL;
static int running = 1;

// Function Prototypes
void ir_callback(int gpio, int level, unsigned int tick);
int decode_nec(unsigned int *pulses, int pulse_count, unsigned int *command);
int validate_checksum(unsigned int command);
int publish_mqtt(unsigned int command);
void signal_handler(int sig);
int mqtt_connect_and_loop(void);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Callback function for IR receiver pulses
void ir_callback(int gpio, int level, unsigned int tick) {
    unsigned int pulse_length;

    if (level != PI_OFF && level != PI_ON) return; // Ignore PI_TIMEOUT

    if (tick > last_tick) {
        pulse_length = tick - last_tick;
    } else {
        pulse_length = last_tick - tick; // Handle tick rollover
    }

    last_tick = tick;

    if (pulse_count < MAX_PULSES) {
        pulse_buffer[pulse_count++] = pulse_length;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow!");
        pulse_count = 0; // Reset buffer
    }
}

// Function to decode NEC IR signal
int decode_nec(unsigned int *pulses, int pulse_count, unsigned int *command) {
    if (pulse_count < 34) {
        syslog(LOG_ERR, "Too few pulses received: %d", pulse_count);
        return -1;
    }

    // Verify header
    if (pulses[0] < NEC_HEADER_MARK * 0.8 || pulses[0] > NEC_HEADER_MARK * 1.2 ||
        pulses[1] < NEC_HEADER_SPACE * 0.8 || pulses[1] > NEC_HEADER_SPACE * 1.2) {
        syslog(LOG_ERR, "Invalid NEC header: Mark=%d, Space=%d", pulses[0], pulses[1]);
        return -1;
    }

    unsigned int address = 0;
    unsigned int inv_address = 0;
    unsigned int data = 0;
    unsigned int inv_data = 0;

    // Decode address (8 bits)
    for (int i = 2; i < 10; i++) {
        if (pulses[2 * i] < NEC_BIT_MARK * 0.8 || pulses[2 * i] > NEC_BIT_MARK * 1.2) {
            syslog(LOG_ERR, "Invalid bit mark at pulse %d", 2 * i);
            return -1;
        }
        if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8 && pulses[2 * i + 1] < NEC_ONE_SPACE * 1.2) {
            address = (address << 1) | 1;
            inv_address = (inv_address << 1) | 0;
        } else if (pulses[2 * i + 1] > NEC_ZERO_SPACE * 0.8 && pulses[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
            address = (address << 1) | 0;
            inv_address = (inv_address << 1) | 1;
        } else {
            syslog(LOG_ERR, "Invalid bit space at pulse %d", 2 * i + 1);
            return -1;
        }
    }

    // Decode data (8 bits)
    for (int i = 10; i < 18; i++) {
        if (pulses[2 * i] < NEC_BIT_MARK * 0.8 || pulses[2 * i] > NEC_BIT_MARK * 1.2) {
            syslog(LOG_ERR, "Invalid bit mark at pulse %d", 2 * i);
            return -1;
        }
        if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8 && pulses[2 * i + 1] < NEC_ONE_SPACE * 1.2) {
            data = (data << 1) | 1;
            inv_data = (inv_data << 1) | 0;
        } else if (pulses[2 * i + 1] > NEC_ZERO_SPACE * 0.8 && pulses[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
            data = (data << 1) | 0;
            inv_data = (inv_data << 1) | 1;
        } else {
            syslog(LOG_ERR, "Invalid bit space at pulse %d", 2 * i + 1);
            return -1;
        }
    }

    // Decode checksum (8 bits)
