#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;
int udp_socket = -1;

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float lux;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *device);
int i2c_set_slave_address(int fd, int address);
int i2c_read_word(int fd, uint16_t *data);
float bh1750_read_lux(int fd);
char* format_data(sensor_data_t data);
int udp_init(const char *address, int port);
int udp_send_data(int socket, const char *data);
void signal_handler(int sig);

// I2C initialization function
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, uint16_t *data) {
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }
    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// BH1750 read lux function
float bh1750_read_lux(int fd) {
    uint16_t raw_data;
    if (i2c_read_word(fd, &raw_data) < 0) {
        return NAN; // Indicate error
    }
    return (float)raw_data / 1.2;
}

// Format sensor data into a string
char* format_data(sensor_data_t data) {
    static char buffer[64]; // Static buffer to avoid memory allocation issues
    snprintf(buffer, sizeof(buffer), "%d,%.2f", data.sensor_id, data.lux);
    return buffer;
}

// UDP initialization function
int udp_init(const char *address, int port) {
    int socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket < 0) {
        perror("Error creating UDP socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(address);
    addr.sin_port = htons(port);

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting multicast TTL");
        close(socket);
        return -1;
    }

    return socket;
}

// UDP send data function
int udp_send_data(int socket, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(socket, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP data");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize UDP
    udp_socket = udp_init(MULTICAST_ADDR, MULTICAST_PORT);
    if (udp_socket < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data_string[256] = {0}; // Initialize to zero
        size_t data_string_len = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int sensor_address = sensor_addresses[i];
            if (i2c_set_slave_address(i2c_fd, sensor_address) < 0) {
                fprintf(stderr, "Error setting slave address for sensor %d\n", i + 1);
                continue; // Skip to the next sensor
            }

            float lux = bh1750_read_lux(i2c_fd);
            if (isnan(lux)) {
                fprintf(stderr, "Error reading lux value from sensor %d\n", i + 1);
                continue; // Skip to the next sensor
            }

            sensor_data_t sensor_data = {i + 1, lux};
            char *sensor_data_str = format_data(sensor_data);

            // Append to the data string
            size_t sensor_data_str_len = strlen(sensor_data_str);
            if (data_string_len + sensor_data_str_len + 1 > sizeof(data_string) - 1) {
                fprintf(stderr, "Data string too long, skipping sensor %d\n", i + 1);
                continue; // Skip if the string would overflow
            }

            if (data_string_len > 0) {
                strcat(data_string, ";");
                data_string_len++;
            }
            strcat(data_string, sensor_data_str);
            data_string_len += sensor_data_str_len;
        }

        // Send the data
        if (udp_send_data(udp_socket, data_string) < 0) {
            fprintf(stderr, "Error sending data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    close(udp_socket);

    return 0;
}

