#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_ID 0x00
#define AS7341_ENABLE 0x01
#define AS7341_CFG6 0x06
#define AS7341_STATUS 0x07
#define AS7341_F1DATAH 0x14

// Configuration values
#define AS7341_CONFIG_PON 0x01
#define AS7341_CONFIG_SMUX 0x0F // Enable all channels
#define AS7341_CONFIG_SP_EN 0x02 // Enable spectral measurement

// Lux approximation constants
#define CLEAR_SCALE 0.01
#define CLEAR_OFFSET 0.0
#define NIR_SCALE 0.01
#define NIR_OFFSET 0.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1;
    uint16_t f2;
    uint16_t f3;
    uint16_t f4;
    uint16_t f5;
    uint16_t f6;
    uint16_t f7;
    uint16_t f8;
    uint16_t clear;
    uint16_t nir;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
float calculate_lux(sensor_data_t data);
void log_data(sensor_data_t data, float lux);
void signal_handler(int signal);

// Function to write a byte to a specific register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a specific register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the AS7341 sensor
int initialize_sensor() {
    // Verify sensor ID
    uint8_t id;
    if (read_register(i2c_handle, AS7341_ID, &id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (id != 0x41) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power on
    if (write_register(i2c_handle, AS7341_ENABLE, AS7341_CONFIG_PON) != 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }
    gpioDelay(10); // Wait for power-on

    // Configure SMUX
    if (write_register(i2c_handle, AS7341_CFG6, AS7341_CONFIG_SMUX) != 0) {
        fprintf(stderr, "Error writing to CFG6 register\n");
        return -1;
    }

    // Enable spectral measurement
    if (write_register(i2c_handle, AS7341_ENABLE, AS7341_CONFIG_PON | AS7341_CONFIG_SP_EN) != 0) {
        fprintf(stderr, "Error writing to ENABLE register to enable spectral measurement\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t buffer[20]; // Buffer to hold all channel data

    // Read all channel data in one go
    if (i2cWriteDevice(i2c_handle, (char[]){AS7341_F1DATAH}, 1) != 1) {
        fprintf(stderr, "Error writing register address for channel data\n");
        data.f1 = data.f2 = data.f3 = data.f4 = data.f5 = data.f6 = data.f7 = data.f8 = data.clear = data.nir = 0; // Set to 0 to avoid garbage values
        return data;
    }
    if (i2cReadDevice(i2c_handle, buffer, 20) != 20) {
        fprintf(stderr, "Error reading channel data\n");
        data.f1 = data.f2 = data.f3 = data.f4 = data.f5 = data.f6 = data.f7 = data.f8 = data.clear = data.nir = 0; // Set to 0 to avoid garbage values
        return data;
    }

    // Extract channel data (big-endian)
    data.f1 = (buffer[1] << 8) | buffer[0];
    data.f2 = (buffer[3] << 8) | buffer[2];
    data.f3 = (buffer[5] << 8) | buffer[4];
    data.f4 = (buffer[7] << 8) | buffer[6];
    data.f5 = (buffer[9] << 8) | buffer[8];
    data.f6 = (buffer[11] << 8) | buffer[10];
    data.f7 = (buffer[13] << 8) | buffer[12];
    data.f8 = (buffer[15] << 8) | buffer[14];
    data.clear = (buffer[17] << 8) | buffer[16];
    data.nir = (buffer[19] << 8) | buffer[18];

    return data;
}

// Function to calculate lux value (simplified approximation)
float calculate_lux(sensor_data_t data) {
    float clear_scaled = (float)data.clear * CLEAR_SCALE + CLEAR_OFFSET;
    float nir_scaled = (float)data.nir * NIR_SCALE + NIR_OFFSET;
    return clear_scaled * nir_scaled;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp,
            data.f1, data.f2, data.f3, data.f4, data.f5, data.f6, data.f7, data.f8,
            data.clear, data.nir, lux);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Calculate lux value
        float lux = calculate_lux(data);

        // Log data
        log_data(data, lux);

        // Wait for 5 seconds
        gpioDelay(5000); // pigpioDelay is in milliseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

