#include <unistd.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x1D
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS 10
#define SENSOR_ABSENT_THRESHOLD 0.1 // g
#define BUS_ERROR_THRESHOLD 0.05 // g

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
int i2c_address = DEFAULT_I2C_ADDRESS;
int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
char *filename = DEFAULT_FILENAME;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(int handle, float *x, float *y, float *z);
int log_data(FILE *file, float x, float y, float z);
int log_error(FILE *file, const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} SensorData;

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, float *x, float *y, float *z) {
    char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 6);
        if (result == 6) {
            // Data received successfully
            int16_t raw_x = (buf[0] << 8) | buf[1];
            int16_t raw_y = (buf[2] << 8) | buf[3];
            int16_t raw_z = (buf[4] << 8) | buf[5];

            // Convert to g (adjust scale factor as needed)
            *x = (float)raw_x / 1000.0; // Example scale factor
            *y = (float)raw_y / 1000.0;
            *z = (float)raw_z / 1000.0;

            return 0; // Success
        } else {
            // Error occurred
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            log_error(error_file, "I2C read error");
            retries++;
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
        }
    }

    // All retries failed
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    log_error(error_file, "Failed to read sensor data after multiple retries.");
    return -1; // Failure
}

// Function to log data to CSV file
int log_data(FILE *file, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to CSV file.\n");
        log_error(error_file, "Error writing to CSV file.");
        return -1;
    }
    fflush(file); // Flush to ensure data is written immediately
    return 0;
}

// Function to log errors to file
int log_error(FILE *file, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to error log file.\n");
        return -1;
    }
    fflush(file);
    return 0;
}

