void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to close files and I2C
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                if (sampling_interval <= 0) {
                    fprintf(stderr, "Invalid sampling interval. Using default value (%d seconds).\n", DEFAULT_SAMPLING_INTERVAL);
                    sampling_interval = DEFAULT_SAMPLING_INTERVAL;
                }
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f filename]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file!\n");
        log_error(error_file, "Error opening data file.");
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        fprintf(stderr, "I2C initialization failed!\n");
        log_error(error_file, "I2C initialization failed.");
        fclose(data_file);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    SensorData sensor_data;
    float x_offset = 0.0;
    float y_offset = 0.0;
    float z_offset = 0.0;
    int offset_count = 0;

    printf("Starting data acquisition...\n");

    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Data validation
            if (sensor_data.x > -100.0 && sensor_data.x < 100.0 &&
                sensor_data.y > -100.0 && sensor_data.y < 100.0 &&
                sensor_data.z > -100.0 && sensor_data.z < 100.0) {

                // Calculate offsets
                x_offset += sensor_data.x;
                y_offset += sensor_data.y;
                z_offset += sensor_data.z;
                offset_count++;

                if (offset_count >= 100) {
                    x_offset /= offset_count;
                    y_offset /= offset_count;
                    z_offset /= offset_count;

                    // Apply offsets
                    sensor_data.x -= x_offset;
                    sensor_data.y -= y_offset;
                    sensor_data.z -= z_offset;

                    // Log data
                    if (log_data(data_file, sensor_data.x, sensor_data.y, sensor_data.z) != 0) {
                        fprintf(stderr, "Error logging data.\n");
                    }

                    // Sensor absence detection
                    if (fabs(sensor_data.x) < SENSOR_ABSENT_THRESHOLD &&
                        fabs(sensor_data.y) < SENSOR_ABSENT_THRESHOLD &&
                        fabs(sensor_data.z) < SENSOR_ABSENT_THRESHOLD) {
                        log_error(error_file, "Sensor appears to be absent.");
                    }

                    // Bus error detection
                    if (fabs(sensor_data.x) > BUS_ERROR_THRESHOLD ||
                        fabs(sensor_data.y) > BUS_ERROR_THRESHOLD ||
                        fabs(sensor_data.z) > BUS_ERROR_THRESHOLD) {
                        log_error(error_file, "Bus error detected.");
                    }

                    offset_count = 0;
                    x_offset = 0.0;
                    y_offset = 0.0;
                    z_offset = 0.0;
                }
            } else {
                log_error(error_file, "Invalid sensor data received.");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(sampling_interval * 1000); // Delay in milliseconds
    }

    cleanup();
    return 0;
}

