#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000

int i2c_fd = -1;
int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to configure the BH1750 sensor
int config_bh1750(int fd, uint8_t config_value) {
    uint8_t buf[2];
    buf[0] = 0x00; // Register address
    buf[1] = config_value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the BH1750 sensor
int read_bh1750(int fd, uint16_t *raw_value) {
    uint8_t buf[2];

    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device for read");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *message) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Set TTL for multicast
    int ttl = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(sock);
        return -1;
    }

    if (sendto(sock, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending data");
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (config_bh1750(i2c_fd, CONTINUOUS_HIGH_RES_MODE) < 0) {
        close(i2c_fd);
        return 1;
    }

    uint16_t raw_value;
    float lux_value;
    char lux_str[20];

    while (1) {
        // Read light intensity
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Format as string
            snprintf(lux_str, sizeof(lux_str), "%.2f", lux_value);

            // Send via UDP multicast
            if (send_udp_multicast(lux_str) != 0) {
                fprintf(stderr, "Error sending UDP multicast, retrying...\n");
            }
        } else {
            fprintf(stderr, "Error reading BH1750, retrying...\n");
        }

        sleep(1);
    }

    return 0;
}

