#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define DATA_BITS 8
#define STOP_BITS 1
#define PARITY 0 // 0=None, 1=Odd, 2=Even
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07}
#define MAX_BUFFER_SIZE 2048
#define CSV_FILE "radar_data.csv"

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure for TLV header
typedef struct {
    uint16_t type;
    uint16_t length;
} tlv_header_t;

// Function prototypes
int initialize_uart();
void signal_handler(int signal);
int read_uart_data(char *buffer, int max_size);
int find_magic_word(const char *buffer, int buffer_size, const unsigned char *magic_word, int magic_word_size);
int validate_tlv_payload(const char *buffer, int buffer_size);
int extract_range_velocity(const char *buffer, int buffer_size, float *range, float *velocity);
int write_to_csv(time_t timestamp, int object_index, float range, float velocity);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Read data from UART
int read_uart_data(char *buffer, int max_size) {
    int bytes_read = serRead(uart_handle, buffer, max_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Find magic word in buffer
int find_magic_word(const char *buffer, int buffer_size, const unsigned char *magic_word, int magic_word_size) {
    if (buffer_size < magic_word_size) {
        return -1; // Not enough data to find magic word
    }

    for (int i = 0; i <= buffer_size - magic_word_size; i++) {
        if (memcmp(buffer + i, magic_word, magic_word_size) == 0) {
            return i; // Return the index where the magic word is found
        }
    }
    return -1; // Magic word not found
}

// Validate TLV payload (example: check if type is within expected range)
int validate_tlv_payload(const char *buffer, int buffer_size) {
    if (buffer_size < sizeof(tlv_header_t)) {
        fprintf(stderr, "Error: TLV payload too short\n");
        return -1;
    }

    tlv_header_t *header = (tlv_header_t *)buffer;
    if (header->type < 1 || header->type > 10) { // Example: Validate type
        fprintf(stderr, "Error: Invalid TLV type: %d\n", header->type);
        return -1;
    }

    return 0;
}

// Extract range and velocity from TLV payload (example: assuming specific format)
int extract_range_velocity(const char *buffer, int buffer_size, float *range, float *velocity) {
    // Example: Assuming a specific TLV type and format
    if (buffer_size < 12) { // Example: Assuming type 1 has a payload of 8 bytes (4 for range, 4 for velocity)
        fprintf(stderr, "Error: TLV payload too short for range/velocity\n");
        return -1;
    }

    // Example: Assuming type 1 has a payload of 8 bytes (4 for range, 4 for velocity)
    if (((tlv_header_t *)buffer)->type == 1) {
        memcpy(range, buffer + sizeof(tlv_header_t), sizeof(float));
        memcpy(velocity, buffer + sizeof(tlv_header_t) + sizeof(float), sizeof(float));
        return 0;
    } else {
        fprintf(stderr, "Error: TLV type is not range/velocity type\n");
        return -1;
    }
}

