int write_to_csv(time_t timestamp, int object_index, float range, float velocity) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp_str, object_index, range, velocity);
    fflush(csv_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }

    char buffer[MAX_BUFFER_SIZE];
    int bytes_read;
    int magic_word_index;
    time_t timestamp;
    float range, velocity;
    int object_index = 0; // Assuming object index is incremented by 1 for each object

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        bytes_read = read_uart_data(buffer, MAX_BUFFER_SIZE);
        if (bytes_read > 0) {
            magic_word_index = find_magic_word(buffer, bytes_read, MAGIC_WORD, MAGIC_WORD_SIZE);
            if (magic_word_index != -1) {
                // Process the TLV payload
                if (validate_tlv_payload(buffer + magic_word_index + MAGIC_WORD_SIZE, bytes_read - (magic_word_index + MAGIC_WORD_SIZE)) == 0) {
                    if (extract_range_velocity(buffer + magic_word_index + MAGIC_WORD_SIZE, bytes_read - (magic_word_index + MAGIC_WORD_SIZE), &range, &velocity) == 0) {
                        timestamp = time(NULL);
                        write_to_csv(timestamp, object_index, range, velocity);
                        object_index++; // Increment object index
                    }
                }
            }
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    cleanup();
    return 0;
}

