#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define LINE_BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Structure to hold program state
typedef struct {
    int uart_fd;
    char line_buffer[LINE_BUFFER_SIZE];
    int line_buffer_index;
} ProgramState;

// Function prototypes
int configure_uart(int fd);
int read_uart_data(int fd, char *buffer, int max_len);
int parse_line(const char *line, double *timestamp, double *range);
void log_data(double timestamp, double range);
void signal_handler(int signal);
void close_uart(int fd);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
        program_running = 0;
    }
}

// Function to configure the UART
int configure_uart(int fd) {
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

// Function to read data from the UART
int read_uart_data(int fd, char *buffer, int max_len) {
    fd_set readfds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (ret == -1) {
        perror("select failed");
        return -1;
    } else if (ret == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        return read(fd, buffer, max_len);
    }
}

// Function to parse the line
int parse_line(const char *line, double *timestamp, double *range) {
    char *token;
    char *rest = NULL;

    // Get timestamp
    token = strtok_r((char *)line, ",", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Missing timestamp\n");
        return -1;
    }
    *timestamp = strtod(token, NULL);

    // Get range
    token = strtok_r(NULL, "\n", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Missing range\n");
        return -1;
    }
    *range = strtod(token, NULL);

    return 0;
}

// Function to log the data
void log_data(double timestamp, double range) {
    time_t rawtime = (time_t)timestamp;
    struct tm *timeinfo = localtime(&rawtime);
    char timestamp_str[20];

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

// Function to close the UART
void close_uart(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    ProgramState state = {.uart_fd = -1, .line_buffer_index = 0};
    char read_buffer[256];
    int bytes_read;
    double timestamp, range;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open UART
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return 1;
    }
    state.uart_fd = uart_fd;

    // Configure UART
    if (configure_uart(uart_fd) != 0) {
        close_uart(uart_fd);
        return 1;
    }

    printf("UART initialized. Reading data...\n");

    while (program_running) {
        // Read data from UART
        bytes_read = read_uart_data(uart_fd, read_buffer, sizeof(read_buffer) - 1);
        if (bytes_read > 0) {
            read_buffer[bytes_read] = '\0'; // Null-terminate the buffer

            // Append to line buffer
            for (int i = 0; i < bytes_read; i++) {
                state.line_buffer[state.line_buffer_index++] = read_buffer[i];
                if (read_buffer[i] == '\n' || state.line_buffer_index >= LINE_BUFFER_SIZE - 1) {
                    state.line_buffer[state.line_buffer_index] = '\0'; // Null-terminate the line

                    // Parse the line
                    if (parse_line(state.line_buffer, &timestamp, &range) == 0) {
                        log_data(timestamp, range);
                    } else {
                        fprintf(stderr, "Error parsing line: %s\n", state.line_buffer);
                    }

                    // Reset line buffer index
                    state.line_buffer_index = 0;
                }
            }
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            break;
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Close UART
    close_uart(uart_fd);

    printf("Program finished.\n");
    return 0;
}

