    return 0;
}

// Function to read data from the UART
int read_uart_data(int fd, char *buffer, int max_len) {
    fd_set readfds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (ret == -1) {
        perror("select failed");
        return -1;
    } else if (ret == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        return read(fd, buffer, max_len);
    }
}

// Function to parse the line
int parse_line(const char *line, double *timestamp, double *range) {
    char *token;
    char *rest = NULL;

    // Get timestamp
    token = strtok_r((char *)line, ",", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Missing timestamp\n");
        return -1;
    }
    *timestamp = strtod(token, NULL);

    // Get range
    token = strtok_r(NULL, "\n", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Missing range\n");
        return -1;
    }
    *range = strtod(token, NULL);

    return 0;
}

// Function to log the data
void log_data(double timestamp, double range) {
    time_t rawtime = (time_t)timestamp;
    struct tm *timeinfo = localtime(&rawtime);
    char timestamp_str[20];

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

// Function to close the UART
void close_uart(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    ProgramState state = {.uart_fd = -1, .line_buffer_index = 0};
    char read_buffer[256];
    int bytes_read;
    double timestamp, range;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open UART
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return 1;
    }
    state.uart_fd = uart_fd;

    // Configure UART
    if (configure_uart(uart_fd) != 0) {
        close_uart(uart_fd);
        return 1;
    }

    printf("UART initialized. Reading data...\n");

    while (program_running) {
        // Read data from UART
        bytes_read = read_uart_data(uart_fd, read_buffer, sizeof(read_buffer) - 1);
        if (bytes_read > 0) {
            read_buffer[bytes_read] = '\0'; // Null-terminate the buffer

            // Append to line buffer
            for (int i = 0; i < bytes_read; i++) {
                state.line_buffer[state.line_buffer_index++] = read_buffer[i];
                if (read_buffer[i] == '\n' || state.line_buffer_index >= LINE_BUFFER_SIZE - 1) {
                    state.line_buffer[state.line_buffer_index] = '\0'; // Null-terminate the line

                    // Parse the line
                    if (parse_line(state.line_buffer, &timestamp, &range) == 0) {
                        log_data(timestamp, range);
                    } else {
                        fprintf(stderr, "Error parsing line: %s\n", state.line_buffer);
                    }

                    // Reset line buffer index
                    state.line_buffer_index = 0;
                }
            }
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            break;
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Close UART
    close_uart(uart_fd);

    printf("Program finished.\n");
    return 0;
}

