        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        log_data(left_value, middle_value, right_value);

        if (left_value == 0 && middle_value == 0 && right_value == 0) {
            send_emergency_stop();
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // The following lines will never be reached due to the infinite loop
    serClose(uart_handle);
    gpioTerminate();
    return 0;
